struct ActionRateState {
    uint64_t windowStartMs = 0;
    uint32_t actionsInWindow = 0;
    uint64_t lastActionMs = 0;
};

// ServerAllowAction() is meant as a general-purpose per-player action
// limiter (see its use from ServerValidateShot below and the note near
// Game59's queueAction() that future actions should be gated through
// ServerAllowAction), but a single g_actionRate bucket keyed only on
// playerId means every action kind sharing this call would drain the same 20/sec, 25ms-interval budget.
// Today only SHOOT calls it, so this is latent, but the moment a second
// action type (grenade throw, ability use, item pickup, ...) reuses it
// as intended, that action would silently start starving/being starved by
// SHOOT's own rate consumption instead of getting its own independent cap.
// Keying by (playerId, action kind) keeps each action type's budget
// separate while still sharing the same limiter implementation.
enum class ServerActionKind : uint8_t { GENERIC = 0, SHOOT = 1 };

static uint64_t ServerActionRateKey(int playerId, ServerActionKind kind) {
    return (static_cast<uint64_t>(static_cast<uint32_t>(playerId)) << 8) |
           static_cast<uint8_t>(kind);
}

static std::unordered_map<uint64_t, ActionRateState> g_actionRate;
static constexpr uint32_t MAX_ACTIONS_PER_SECOND = 20;
static constexpr uint64_t MIN_ACTION_INTERVAL_MS = 25;
static constexpr float MAX_SERVER_MOVE_SPEED = 900.0f; // authoritative units/sec
static constexpr uint32_t LAN_INPUT_STALE_MS = 200;
static constexpr uint32_t LAN_INPUT_COMMAND_MAX_DT_MS = 100;
static constexpr float MAX_SHOT_RANGE = 1800.0f;

static bool ServerAllowAction(int playerId, uint64_t nowMs,
                              ServerActionKind kind = ServerActionKind::GENERIC) {
    auto &r = g_actionRate[ServerActionRateKey(playerId, kind)];
    if (r.windowStartMs == 0 || nowMs - r.windowStartMs >= 1000) {
        r.windowStartMs = nowMs;
        r.actionsInWindow = 0;
    }
    if (r.actionsInWindow >= MAX_ACTIONS_PER_SECOND) return false;
    if (r.lastActionMs && nowMs - r.lastActionMs < MIN_ACTION_INTERVAL_MS) return false;
    ++r.actionsInWindow;
    r.lastActionMs = nowMs;
    return true;
}

static bool Game80ConstantTimeEqual(const std::string& a, const std::string& b) {
    if (a.size() != b.size()) return false;
    unsigned char diff = 0;
    for (size_t i = 0; i < a.size(); ++i) {
        diff |= static_cast<unsigned char>(a[i]) ^ static_cast<unsigned char>(b[i]);
    }
    return diff == 0;
}

static bool ServerFinite(float v) {
    return std::isfinite(v);
}

// Validate a client-requested movement delta against the server clock.
// The server should apply the movement itself rather than trusting the
// client's resulting position.
static bool ServerValidateMove(float dx, float dy, float dtSeconds) {
    if (!ServerFinite(dx) || !ServerFinite(dy) || !ServerFinite(dtSeconds)) return false;
    if (dtSeconds <= 0.0f || dtSeconds > 0.25f) return false;
    const float distance = std::sqrt(dx * dx + dy * dy);
    const float allowedDistance = MAX_SERVER_MOVE_SPEED * dtSeconds;
    // Tolerance scales with dt instead of being a flat amount, since a flat
    // add-on is misleading at the call site's actual cadence: this used to
    // be "+ 8.0f" regardless of dtSeconds, which at a ~60Hz tick (dt=1/60,
    // allowedDistance=15.0) was over 50% of the entire per-tick budget on
    // top of the nominal cap - but at dtSeconds near the 0.25s ceiling above
    // (allowedDistance=225.0) the same +8.0f was under 4%. Same constant,
    // wildly different effective looseness depending on how often the
    // caller invokes this. A percentage of the per-tick budget keeps the
    // slack proportionally consistent; the small fixed floor just covers
    // floating-point rounding noise at very small dt.
    const float tolerance = (allowedDistance * 0.10f > 0.1f) ? allowedDistance * 0.10f : 0.1f;
    return distance <= allowedDistance + tolerance;
}

// Validate a shot request using server-owned positions/teams.
// Caller must fetch shooter and target from authoritative game state.
// NOTE: the LAN SHOOT| packet carries a normalized aim direction (dx,dy),
// not a target point, so this range/team check doesn't apply to it as-is -
// that path enforces rate limiting (ServerAllowAction + per-weapon
// cooldownMs, see lan_process_host_line) and validates team/hit legality
// later at bullet-collision time instead. This function is here for a
// caller that has an actual target position (sx,sy)->(tx,ty), e.g. a
// future hitscan/melee path.
static bool ServerValidateShot(float sx, float sy, float tx, float ty,
                               bool sameTeam, uint64_t nowMs, int playerId) {
    if (!ServerAllowAction(playerId, nowMs, ServerActionKind::SHOOT)) return false;
    if (sameTeam) return false; // friendly fire remains disabled
    if (!ServerFinite(sx) || !ServerFinite(sy) ||
        !ServerFinite(tx) || !ServerFinite(ty)) return false;
    const float dx = tx - sx;
    const float dy = ty - sy;
    return (dx * dx + dy * dy) <= MAX_SHOT_RANGE * MAX_SHOT_RANGE;
}

