// ============================================================
// STEP 17.37 - DAY/NIGHT CYCLE
// Integrated with PLAYING and weather rendering.
// ============================================================

enum class TimeOfDayPhase { DAWN, DAY, DUSK, NIGHT };

struct DayNightSystem {
    bool enabled = true;
    float timeOfDayHours = 12.0f;       // 0..24
    float cycleLengthSeconds = 900.0f;  // 15 real minutes = 24 game hours
};

static DayNightSystem g_dayNight;

static float DayNightWrapHours(float h) {
    while (h >= 24.0f) h -= 24.0f;
    while (h < 0.0f) h += 24.0f;
    return h;
}

static TimeOfDayPhase DayNightPhase() {
    const float h = g_dayNight.timeOfDayHours;
    if (h >= 5.5f && h < 7.0f) return TimeOfDayPhase::DAWN;
    if (h >= 7.0f && h < 18.0f) return TimeOfDayPhase::DAY;
    if (h >= 18.0f && h < 19.5f) return TimeOfDayPhase::DUSK;
    return TimeOfDayPhase::NIGHT;
}

static float DayNightNightFactor() {
    const float h = g_dayNight.timeOfDayHours;
    if (h >= 7.0f && h < 18.0f) return 0.0f;
    if (h >= 18.0f && h < 19.5f) return (h - 18.0f) / 1.5f;
    if (h >= 5.5f && h < 7.0f) return 1.0f - (h - 5.5f) / 1.5f;
    return 1.0f;
}

// Call when a map/round starts.
static void DayNightBegin(float startHour = 12.0f) {
    g_dayNight.timeOfDayHours = DayNightWrapHours(startHour);
}

// Call only from the PLAYING update loop.
static void DayNightUpdate(float dtSeconds) {
    if (!g_dayNight.enabled || !std::isfinite(dtSeconds) ||
        dtSeconds <= 0.0f || g_dayNight.cycleLengthSeconds <= 0.0f) return;
    const float hoursPerSecond = 24.0f / g_dayNight.cycleLengthSeconds;
    g_dayNight.timeOfDayHours = DayNightWrapHours(
        g_dayNight.timeOfDayHours + dtSeconds * hoursPerSecond);
}

static float DayNightVisibilityMultiplier() {
    return 1.0f - 0.30f * DayNightNightFactor();
}

// Render after the world/weather and before the HUD.
static void DayNightRenderOverlay(SDL_Renderer* renderer) {
    if (!renderer || !g_dayNight.enabled) return;
    const float night = DayNightNightFactor();
    if (night <= 0.001f) return;

    SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);
    SDL_SetRenderDrawColor(renderer, 12, 18, 40,
                           static_cast<Uint8>(65.0f * night));
    SDL_Rect screen{0, 0, SCREEN_WIDTH, SCREEN_HEIGHT};
    SDL_RenderFillRect(renderer, &screen);
    SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_NONE);
}




