// STEP 17.17 - MATCHMAKING
// Online matchmaking is intentionally kept separate from the LAN transport.
// A backend can later consume this request state without changing the menu/UI.
enum class MatchVisibility { PUBLIC_MATCH, PRIVATE_MATCH };
enum class MatchRegion { AUTO, INDIA, ASIA, EUROPE, NORTH_AMERICA };
enum class MatchmakingStatus { IDLE, SEARCHING, FOUND, CANCELLED, ERROR };

struct MatchmakingRequest {
    MatchVisibility visibility{MatchVisibility::PUBLIC_MATCH};
    MatchRegion region{MatchRegion::AUTO};
    int playerLimit{8};
    MatchmakingStatus status{MatchmakingStatus::IDLE};
    Uint32 searchStartedAt{0};
    std::string privateCode;
    std::string statusMessage{"READY TO MATCH"};
};
MatchmakingRequest matchmaking;

static const char* matchmaking_visibility_name(MatchVisibility v) {
    return v == MatchVisibility::PUBLIC_MATCH ? "PUBLIC" : "PRIVATE";
}
static const char* matchmaking_region_name(MatchRegion r) {
    switch (r) {
        case MatchRegion::INDIA: return "INDIA";
        case MatchRegion::ASIA: return "ASIA";
        case MatchRegion::EUROPE: return "EUROPE";
        case MatchRegion::NORTH_AMERICA: return "NORTH AMERICA";
        default: return "AUTO";
    }
}
static const char* matchmaking_status_name(MatchmakingStatus s) {
    switch (s) {
        case MatchmakingStatus::SEARCHING: return "SEARCHING";
        case MatchmakingStatus::FOUND: return "MATCH FOUND";
        case MatchmakingStatus::CANCELLED: return "CANCELLED";
        case MatchmakingStatus::ERROR: return "ERROR";
        default: return "READY TO MATCH";
    }
}
static void matchmaking_cycle_region() {
    matchmaking.region = static_cast<MatchRegion>((static_cast<int>(matchmaking.region) + 1) % 5);
}
static void matchmaking_cycle_player_limit() {
    // Keep the existing multiplayer capacity invariant: 2..8 players.
    matchmaking.playerLimit = (matchmaking.playerLimit >= 8) ? 2 : matchmaking.playerLimit + 1;
}
static void matchmaking_begin() {
    matchmaking.status = MatchmakingStatus::SEARCHING;
    matchmaking.searchStartedAt = SDL_GetTicks();
    matchmaking.statusMessage = matchmaking.visibility == MatchVisibility::PRIVATE_MATCH
        ? (matchmaking.privateCode.empty() ? "CREATE OR ENTER A PRIVATE CODE" : "SEARCHING PRIVATE ROOM")
        : "SEARCHING FOR PLAYERS";
}
static void matchmaking_cancel() {
    matchmaking.status = MatchmakingStatus::CANCELLED;
    matchmaking.statusMessage = "MATCHMAKING CANCELLED";
}

