// Forward declarations for the vehicle/weapon visual event system. These are
// intentionally available before gameplay code so damage and movement paths can
// trigger visuals without changing the gameplay data model.
struct VehicleParticle {
    float x{0}, y{0};
    float vx{0}, vy{0};
    float life{0};
    bool fire{false};
};
static std::vector<VehicleParticle> vehicleParticles;

static void SpawnVehicleSmoke(float x, float y, bool fire = false) {
    if (vehicleParticles.size() >= 180) return;
    VehicleParticle p;
    p.x = x + static_cast<float>(std::rand() % 17 - 8);
    p.y = y + static_cast<float>(std::rand() % 17 - 8);
    p.vx = static_cast<float>(std::rand() % 21 - 10) * 0.04f;
    p.vy = -(0.35f + static_cast<float>(std::rand() % 16) * 0.035f);
    p.life = fire ? 0.55f : 0.9f;
    p.fire = fire;
    vehicleParticles.push_back(p);
}

static void UpdateVehicleEffects(float dt) {
    for (auto& p : vehicleParticles) {
        p.x += p.vx * 60.0f * dt;
        p.y += p.vy * 60.0f * dt;
        p.vx *= 0.985f;
        p.vy *= 0.985f;
        p.life -= dt;
    }
    vehicleParticles.erase(std::remove_if(vehicleParticles.begin(), vehicleParticles.end(),
        [](const VehicleParticle& p){ return p.life <= 0.0f; }), vehicleParticles.end());
}

static void DrawVehicleEffects(SDL_Renderer* renderer, int cameraX, int cameraY) {
    if (!renderer) return;
    SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);
    for (const auto& p : vehicleParticles) {
        const Uint8 alpha = static_cast<Uint8>(std::clamp(p.life / (p.fire ? 0.55f : 0.9f), 0.0f, 1.0f) * 150.0f);
        SDL_SetRenderDrawColor(renderer, p.fire ? 255 : 135, p.fire ? 105 : 135,
                               p.fire ? 25 : 135, alpha);
        const int size = p.fire ? 7 : 11;
        SDL_Rect r{static_cast<int>(p.x) - cameraX - size/2,
                   static_cast<int>(p.y) - cameraY - size/2, size, size};
        SDL_RenderFillRect(renderer, &r);
    }
    SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_NONE);
}

static void DrawMuzzleFlash(SDL_Renderer* renderer, int x, int y) {
    if (!renderer) return;
    SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);
    SDL_SetRenderDrawColor(renderer, 255, 225, 90, 210);
    SDL_Rect flash{x - 5, y - 5, 10, 10};
    SDL_RenderFillRect(renderer, &flash);
    SDL_SetRenderDrawColor(renderer, 255, 255, 180, 90);
    SDL_Rect glow{x - 11, y - 11, 22, 22};
    SDL_RenderFillRect(renderer, &glow);
    SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_NONE);
}
