void play_gunshot_sound(bool isPlayer, WeaponType wType = WeaponType::PISTOL, bool aiShot = false) {
    if (aiShot) {
        Uint32 now = SDL_GetTicks();
        // One AI firing sound at most every 115 ms.  Projectile spawning is not
        // throttled; only the shared audio retrigger is limited.
        if (now - lastTacticalAISoundAt < 115) return;
        lastTacticalAISoundAt = now;
    }
    SDL_LockAudioDevice(audioDevice);
    float baseFreq = 520.0f;
    if (wType == WeaponType::RIFLE)  baseFreq = 720.0f;
    if (wType == WeaponType::ROCKET) baseFreq = 160.0f;
    if (wType == WeaponType::LASER)  baseFreq = 920.0f;

    currentEffect.frequency = isPlayer ? baseFreq : 280.0f;
    currentEffect.durationSamples = static_cast<int>(44100 * 0.10);
    currentEffect.currentSample = 0;
    currentEffect.volume = isPlayer ? 0.9f : 0.7f;
    currentEffect.isPlayerShot = isPlayer;
    currentEffect.isExplosion = false;
    currentEffect.isBeep = false;
    currentEffect.isGlassShatter = false;
    currentEffect.isCoin = false;
    currentEffect.isVictory = false;
    currentEffect.isFire = false;
    currentEffect.isIce = false;
    currentEffect.isRimScrape = false;
    SDL_UnlockAudioDevice(audioDevice);
    if (isPlayer && wType == WeaponType::FIRE_GUN) play_fire_sound();
    else if (isPlayer && wType == WeaponType::ICE_GUN) play_ice_sound();
}

