// Loads a WAV file and converts it to the engine's audio format (44100Hz,
// S16SYS, mono) so it can be mixed sample-for-sample with the procedural
// effect. Missing/invalid files are handled gracefully - the clip simply
// never plays, matching the optional-asset pattern used for vehicle sprites.
bool load_voice_clip(const char* path, VoiceClip& clip) {
    SDL_AudioSpec wavSpec{};
    Uint8* wavBuffer = nullptr;
    Uint32 wavLength = 0;

    // Android packages files under app/src/main/assets/ inside the APK.
    // SDL's Android backend exposes packaged assets through SDL_RWops, and
    // that backend is already rooted at assets/ - so paths here must be
    // relative to assets/ (e.g. "audio/x.wav"), NOT prefixed with "assets/".
    SDL_RWops* wavFile = SDL_RWFromFile(path, "rb");
    if (!wavFile) {
        std::cerr << "Voice asset unavailable (" << path << "): "
                  << SDL_GetError() << std::endl;
        return false;
    }

    // The '1' tells SDL to close the RWops after decoding.
    if (!SDL_LoadWAV_RW(wavFile, 1, &wavSpec, &wavBuffer, &wavLength)) {
        std::cerr << "Voice asset could not be decoded (" << path << "): "
                  << SDL_GetError() << std::endl;
        return false;
    }

    SDL_AudioCVT cvt;
    int cvtResult = SDL_BuildAudioCVT(&cvt, wavSpec.format, wavSpec.channels, wavSpec.freq,
                                       AUDIO_S16SYS, 1, 44100);
    if (cvtResult < 0) {
        SDL_FreeWAV(wavBuffer);
        return false;
    }

    if (cvtResult == 0) {
        // Already in the target format - copy as-is.
        clip.samples = static_cast<Uint8*>(SDL_malloc(wavLength));
        if (!clip.samples) {
            std::cerr << "Voice clip allocation failed (" << path << ")" << std::endl;
            SDL_FreeWAV(wavBuffer);
            return false;
        }
        std::memcpy(clip.samples, wavBuffer, wavLength);
        clip.lengthSamples = wavLength / sizeof(int16_t);
        SDL_FreeWAV(wavBuffer);
    } else {
        cvt.len = static_cast<int>(wavLength);
        const size_t convertedBytes = static_cast<size_t>(cvt.len) * static_cast<size_t>(cvt.len_mult);
        cvt.buf = static_cast<Uint8*>(SDL_malloc(convertedBytes));
        if (!cvt.buf) {
            std::cerr << "Voice conversion buffer allocation failed (" << path << ")" << std::endl;
            SDL_FreeWAV(wavBuffer);
            return false;
        }
        std::memcpy(cvt.buf, wavBuffer, wavLength);
        SDL_FreeWAV(wavBuffer);
        if (SDL_ConvertAudio(&cvt) != 0) {
            SDL_free(cvt.buf);
            return false;
        }
        clip.samples = cvt.buf;
        clip.lengthSamples = static_cast<Uint32>(cvt.len_cvt) / sizeof(int16_t);
    }

    clip.playhead = 0;
    clip.playing = false;
    return true;
}

// Loads every WAV in kVoiceLineDefs into g_voiceClips. Call once at startup,
// after the audio device is open. Missing/invalid files are handled
// gracefully per-line by load_voice_clip() - that line simply never plays,
// matching the optional-asset pattern used for vehicle sprites.
void load_all_voice_clips() {
    for (const auto& def : kVoiceLineDefs) {
        load_voice_clip(def.path, g_voiceClips[static_cast<size_t>(def.id)]);
    }
}

// Triggers playback of a single voice line. Safe to call for a line whose
// WAV failed to load (or doesn't exist) - it just stays silent. Restarts
// the line from the beginning if it's already mid-playback.
bool play_voice_line(VoiceLine line, float playbackRate = 1.0f) {
    VoiceClip& clip = g_voiceClips[static_cast<size_t>(line)];
    if (!clip.samples || clip.lengthSamples == 0) {
        SDL_Log("Voice line %d is not loaded; command voice will not be played", static_cast<int>(line));
        return false;
    }
    playbackRate = std::clamp(playbackRate, 0.85f, 1.15f);
    SDL_LockAudioDevice(audioDevice);
    clip.playhead = 0.0f;
    clip.playbackRate = playbackRate;
    clip.playing = true;
    SDL_UnlockAudioDevice(audioDevice);
    return true;
}

// Per-bot voice identity. The same WAV recordings are resampled at a slightly
// different rate for each squad member, giving each bot a distinct natural
// pitch without needing separate recordings. Keep the spread subtle so speech
// remains intelligible.
float bot_voice_pitch(int botIndex) {
    static constexpr float kBotVoiceRates[] = { 0.92f, 0.97f, 1.00f, 1.05f, 1.10f };
    if (botIndex < 0 || botIndex >= MAX_BOTS) return 1.0f;
    float rate = bots[botIndex].voicePitch;
    // Preserve deterministic variety for bots created before voicePitch was assigned.
    if (!(rate >= 0.85f && rate <= 1.15f)) {
        constexpr int count = static_cast<int>(sizeof(kBotVoiceRates) / sizeof(kBotVoiceRates[0]));
        rate = kBotVoiceRates[botIndex % count];
    }
    return std::clamp(rate, 0.85f, 1.15f);
}

// Returns the decoded duration of a voice clip in milliseconds. Clips are
// converted to 44.1 kHz mono S16, so lengthSamples maps directly to time.
Uint32 voice_duration_ms(VoiceLine line, float playbackRate = 1.0f) {
    const VoiceClip& clip = g_voiceClips[static_cast<size_t>(line)];
    if (!clip.samples || clip.lengthSamples == 0) return 0;
    playbackRate = std::clamp(playbackRate, 0.85f, 1.15f);
    const double seconds = static_cast<double>(clip.lengthSamples) / (44100.0 * playbackRate);
    return static_cast<Uint32>(std::ceil(seconds * 1000.0));
}

void stop_bot_voice_response() {
    SDL_LockAudioDevice(audioDevice);
    // Bot command responses use only these five voice entries. Stop them so a
    // newer order never leaves an old acknowledgement talking over it.
    constexpr VoiceLine botVoices[] = {
        VoiceLine::BOT_FOLLOW, VoiceLine::BOT_HOLD,
        VoiceLine::BOT_SITE_A, VoiceLine::BOT_SITE_B, VoiceLine::BOT_NO_SIR
    };
    for (VoiceLine line : botVoices) {
        VoiceClip& clip = g_voiceClips[static_cast<size_t>(line)];
        clip.playing = false;
        clip.playhead = 0.0f;
        clip.playbackRate = 1.0f;
    }
    SDL_UnlockAudioDevice(audioDevice);
}

extern GameMode selectedMode;
extern Bomb tacticalBomb;
extern int botDefuserIndex;
extern bool defuseHeld;


// -----------------------------------------------------------------------------
// Squad response queue
// Voice and on-screen text are synchronized. Only one bot responds at a time.
// Uses the existing WAV recordings; no new recordings are required.
// -----------------------------------------------------------------------------
struct QueuedBotResponse {
    int botIndex;
    std::string message;
    VoiceLine voice;
    Uint32 startTime;
};

static std::deque<QueuedBotResponse> botResponseQueue;
static bool botResponsePlaying = false;
static Uint32 botResponseNextTime = 0;

void queue_bot_response(int botIndex,
                        const std::string& message,
                        VoiceLine voice,
                        Uint32 startTime) {
    botResponseQueue.push_back(
        QueuedBotResponse{botIndex, message, voice, startTime}
    );
}

void update_bot_response_queue(Uint32 currentTime) {
    if (botResponsePlaying) {
        if (currentTime < botResponseNextTime) return;
        botResponsePlaying = false;
    }

    while (!botResponseQueue.empty()) {
        if (currentTime < botResponseQueue.front().startTime) return;
        QueuedBotResponse response = botResponseQueue.front();
        botResponseQueue.pop_front();

        if (response.botIndex < 0 || response.botIndex >= activeBotCount ||
            !bots[response.botIndex].active || bots[response.botIndex].hp <= 0) {
            // Dead/invalid bots consume no turn. The next response remains eligible immediately.
            continue;
        }

        for (int bi = 0; bi < activeBotCount; ++bi) {
            bots[bi].replyMessage.clear();
            bots[bi].replyMessageUntil = 0;
        }

        const float voiceRate = bot_voice_pitch(response.botIndex);
        const Uint32 voiceDuration = voice_duration_ms(response.voice, voiceRate);
        const Uint32 displayDuration = voiceDuration > 0 ? voiceDuration : 1200;

        bots[response.botIndex].replyMessage = response.message;
        bots[response.botIndex].replyMessageUntil = currentTime + displayDuration;

        if (voiceDuration > 0) {
            play_voice_line(response.voice, voiceRate);
            botResponsePlaying = true;
            botResponseNextTime = currentTime + voiceDuration;
        } else {
            // Missing audio: keep the visual acknowledgement briefly, but do not
            // reserve a voice turn. The next bot may respond on the next update.
            botResponsePlaying = false;
            botResponseNextTime = currentTime;
        }
        return;
    }
}

// Plays the player's squad-command voice first, then queues the bot
// responses so the two voices do not overlap. The bot command is not issued
// until the player's voice has finished.
void issue_bot_command(BotCommand command, Uint32 currentTime);

struct PendingPlayerCommand {
    bool active = false;
    BotCommand command = BotCommand::NONE;
    Uint32 finishTime = 0;
};

static PendingPlayerCommand pendingPlayerCommand;

void update_pending_player_command(Uint32 currentTime) {
    if (!pendingPlayerCommand.active) return;
    if (currentTime < pendingPlayerCommand.finishTime) return;

    const BotCommand command = pendingPlayerCommand.command;
    pendingPlayerCommand.active = false;
    pendingPlayerCommand.command = BotCommand::NONE;
    pendingPlayerCommand.finishTime = 0;

    issue_bot_command(command, currentTime);
}

void issue_player_command(BotCommand command,
                          VoiceLine playerVoice,
                          Uint32 currentTime) {
    // A new player command replaces any previous command that has not yet
    // finished speaking. This guarantees the bots can never answer an older
    // player command after a newer one is pressed.
    pendingPlayerCommand.active = false;
    pendingPlayerCommand.command = BotCommand::NONE;
    pendingPlayerCommand.finishTime = 0;

    if (!play_voice_line(playerVoice)) {
        // Do not silently let the bots answer when the player's command audio
        // is missing. The SDL log identifies the missing VoiceLine.
        SDL_Log("Player squad command %d cancelled: player voice clip is unavailable",
                static_cast<int>(command));
        return;
    }

    const Uint32 playerVoiceDuration = voice_duration_ms(playerVoice);
    pendingPlayerCommand.active = true;
    pendingPlayerCommand.command = command;
    pendingPlayerCommand.finishTime = currentTime + playerVoiceDuration;
}

void issue_bot_command(BotCommand command, Uint32 currentTime) {
    // New command supersedes all previous bot command acknowledgements.
    for (int bi = 0; bi < activeBotCount; ++bi) {
        bots[bi].replyMessage.clear();
        bots[bi].replyMessageUntil = 0.0;
    }

    currentBotCommand = command;
    if (command == BotCommand::NONE) return;

    // A newer command supersedes the entire previous acknowledgement sequence.
    // Stop the current bot voice as well as pending responses so an old order
    // can never speak after the player has issued a newer one.
    botResponseQueue.clear();
    stop_bot_voice_response();
    botResponsePlaying = false;
    botResponseNextTime = currentTime;
    for (int bi = 0; bi < activeBotCount; ++bi) {
        bots[bi].replyMessage.clear();
        bots[bi].replyMessageUntil = 0;
    }

    // If a bomb is planted, the bot currently designated to defuse it
    // refuses a movement order. Other bots still receive the command.
    const bool bombActive = selectedMode == GameMode::TACTICAL &&
                            tacticalBomb.planted && !tacticalBomb.defused;
    const bool defuserAlive =
        bombActive &&
        botDefuserIndex >= 0 &&
        botDefuserIndex < activeBotCount &&
        bots[botDefuserIndex].active &&
        bots[botDefuserIndex].hp > 0 &&
        !defuseHeld;

    std::string affirmMessage;
    VoiceLine affirmVoice = VoiceLine::BOT_FOLLOW;

    switch (command) {
        case BotCommand::FOLLOW_PLAYER:
            affirmVoice = VoiceLine::BOT_FOLLOW;
            affirmMessage = "ROGER, MOVING WITH YOU!";
            break;

        case BotCommand::HOLD_POSITION:
            affirmVoice = VoiceLine::BOT_HOLD;
            affirmMessage = "OK, SIR!";
            for (int bi = 0; bi < activeBotCount; ++bi) {
                if (!bots[bi].active || bots[bi].hp <= 0) continue;
                if (defuserAlive && bi == botDefuserIndex) continue;
                bots[bi].holdTile = Point{
                    static_cast<int>(bots[bi].x + bots[bi].rect.w / 2) / TILE_SIZE,
                    static_cast<int>(bots[bi].y + bots[bi].rect.h / 2) / TILE_SIZE
                };
                bots[bi].holdTileValid = true;
            }
            break;

        case BotCommand::REACH_SITE_A:
            affirmVoice = VoiceLine::BOT_SITE_A;
            affirmMessage = "ROGER, MOVING TO A!";
            break;

        case BotCommand::REACH_SITE_B:
            affirmVoice = VoiceLine::BOT_SITE_B;
            affirmMessage = "ROGER, MOVING TO B!";
            break;

        case BotCommand::NONE:
            return;
    }

    // Queue the visual response and its voice together. Only the bot whose
    // turn it is gets its response text shown, and the same response's voice
    // is played at the same time.
    // Queue only the response identity. Timing is assigned dynamically by
    // update_bot_response_queue(), so bots that die after this command is issued
    // never reserve time for a turn they cannot perform.
    for (int bi = 0; bi < activeBotCount; ++bi) {
        if (!bots[bi].active || bots[bi].hp <= 0) continue;

        std::string responseText = affirmMessage;
        VoiceLine responseVoice = affirmVoice;

        if (defuserAlive && bi == botDefuserIndex) {
            responseText = "NO, SIR!";
            responseVoice = VoiceLine::BOT_NO_SIR;
        }

        queue_bot_response(bi, responseText, responseVoice, currentTime);
    }
}

