// ============================================================
// STEP 17.36 - WEATHER SYSTEM
// Dynamic, deterministic weather that layers over the streamed world.
// Weather is cosmetic/gameplay-safe: it does not alter authoritative combat.
// ============================================================
enum class WeatherType { CLEAR, CLOUDY, RAIN, STORM, FOG };

struct WeatherState {
    WeatherType type{WeatherType::CLEAR};
    WeatherType target{WeatherType::CLEAR};
    Uint32 changedAt{0};
    Uint32 nextChangeAt{0};
    float intensity{0.0f};
    float targetIntensity{0.0f};
    std::array<SDL_Point, 180> particles{};
    bool initialized{false};
};

static WeatherState g_weather;
static std::mt19937 g_weatherRng{0x1736C0DEu};

static const char* weather_name(WeatherType t) {
    switch (t) {
        case WeatherType::CLOUDY: return "CLOUDY";
        case WeatherType::RAIN:   return "RAIN";
        case WeatherType::STORM:  return "STORM";
        case WeatherType::FOG:    return "FOG";
        default:                  return "CLEAR";
    }
}

static float weather_target_intensity(WeatherType t) {
    switch (t) {
        case WeatherType::CLOUDY: return 0.35f;
        case WeatherType::RAIN:   return 0.72f;
        case WeatherType::STORM:  return 1.0f;
        case WeatherType::FOG:    return 0.78f;
        default:                  return 0.0f;
    }
}

static WeatherType weather_random_type() {
    // Clear/cloudy dominate; severe weather is less frequent.
    std::uniform_int_distribution<int> roll(0, 99);
    int r = roll(g_weatherRng);
    if (r < 35) return WeatherType::CLEAR;
    if (r < 58) return WeatherType::CLOUDY;
    if (r < 82) return WeatherType::RAIN;
    if (r < 94) return WeatherType::FOG;
    return WeatherType::STORM;
}

static void weather_begin(Uint32 now) {
    g_weather.initialized = true;
    g_weather.type = WeatherType::CLEAR;
    g_weather.target = WeatherType::CLEAR;
    g_weather.changedAt = now;
    g_weather.nextChangeAt = now + 22000;
    g_weather.intensity = 0.0f;
    g_weather.targetIntensity = 0.0f;
    std::uniform_int_distribution<int> xDist(0, SCREEN_WIDTH - 1);
    std::uniform_int_distribution<int> yDist(0, SCREEN_HEIGHT - 1);
    for (auto& p : g_weather.particles) p = {xDist(g_weatherRng), yDist(g_weatherRng)};
}

static void weather_update(Uint32 now, float dt) {
    if (!g_weather.initialized) weather_begin(now);

    if (now >= g_weather.nextChangeAt && g_weather.target == g_weather.type) {
        g_weather.target = weather_random_type();
        g_weather.targetIntensity = weather_target_intensity(g_weather.target);
        g_weather.changedAt = now;
        g_weather.nextChangeAt = now + 28000 + (g_weatherRng() % 30000);
    }

    // Smooth transitions prevent a hard visual pop when weather changes.
    const float blend = std::min(1.0f, dt * 0.45f);
    g_weather.intensity += (g_weather.targetIntensity - g_weather.intensity) * blend;
    if (std::fabs(g_weather.intensity - g_weather.targetIntensity) < 0.01f) {
        g_weather.type = g_weather.target;
        g_weather.intensity = g_weather.targetIntensity;
    }

    // Keep rain/storm particles moving in screen space so they remain cheap even
    // on large streamed maps and do not need world-coordinate collision handling.
    if (g_weather.type == WeatherType::RAIN || g_weather.type == WeatherType::STORM ||
        g_weather.target == WeatherType::RAIN || g_weather.target == WeatherType::STORM) {
        const int speed = g_weather.type == WeatherType::STORM ? 900 : 650;
        for (auto& p : g_weather.particles) {
            p.y += static_cast<int>(speed * dt);
            p.x -= static_cast<int>(speed * 0.12f * dt);
            if (p.y >= SCREEN_HEIGHT + 30 || p.x < -20) {
                p.x = static_cast<int>(g_weatherRng() % SCREEN_WIDTH);
                p.y = -static_cast<int>(g_weatherRng() % 120);
            }
        }
    }
}

static void render_weather(SDL_Renderer* renderer, Uint32 now) {
    if (!g_weather.initialized || g_weather.intensity <= 0.01f) return;

    SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);
    const float i = std::clamp(g_weather.intensity, 0.0f, 1.0f);

    // Cloud cover / storm darkening.
    if (g_weather.type == WeatherType::CLOUDY || g_weather.type == WeatherType::RAIN ||
        g_weather.type == WeatherType::STORM) {
        Uint8 alpha = static_cast<Uint8>((g_weather.type == WeatherType::STORM ? 72 : 38) * i);
        SDL_SetRenderDrawColor(renderer, 35, 48, 62, alpha);
        SDL_Rect shade{0, 0, SCREEN_WIDTH, SCREEN_HEIGHT};
        SDL_RenderFillRect(renderer, &shade);
    }

    // Fog is a soft full-screen veil; keeping alpha moderate preserves gameplay readability.
    if (g_weather.type == WeatherType::FOG) {
        Uint8 alpha = static_cast<Uint8>(82 * i);
        SDL_SetRenderDrawColor(renderer, 190, 205, 210, alpha);
        SDL_Rect fog{0, 0, SCREEN_WIDTH, SCREEN_HEIGHT};
        SDL_RenderFillRect(renderer, &fog);
    }

    if (g_weather.type == WeatherType::RAIN || g_weather.type == WeatherType::STORM) {
        const bool storm = g_weather.type == WeatherType::STORM;
        const int count = storm ? 180 : 120;
        const int length = storm ? 22 : 15;
        Uint8 alpha = static_cast<Uint8>((storm ? 145 : 105) * i);
        SDL_SetRenderDrawColor(renderer, 155, 205, 235, alpha);
        for (int n = 0; n < count; ++n) {
            const SDL_Point& p = g_weather.particles[n];
            SDL_RenderDrawLine(renderer, p.x, p.y, p.x - length / 4, p.y + length);
        }
    }

    // Rare lightning flash during storms. Purely visual and deterministic from the clock.
    if (g_weather.type == WeatherType::STORM) {
        Uint32 phase = now % 11000;
        if (phase < 70 || (phase >= 260 && phase < 305)) {
            Uint8 alpha = phase < 70 ? 48 : 24;
            SDL_SetRenderDrawColor(renderer, 225, 240, 255, alpha);
            SDL_Rect flash{0, 0, SCREEN_WIDTH, SCREEN_HEIGHT};
            SDL_RenderFillRect(renderer, &flash);
        }
    }

    SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_NONE);
}


