bool badgeBombDefuserUnlocked = false;
bool badgeLastManStandingUnlocked = false;
bool badgeSharpShooterUnlocked = false;

const int BADGE_BOMB_DEFUSER_TARGET = 10;       // defuse 10 bombs (lifetime)
const int BADGE_LAST_MAN_STANDING_TARGET = 15;  // reach Endless wave 15 in one run
const int BADGE_SHARP_SHOOTER_TARGET = 100;     // 100 kills (lifetime)

struct BadgeUnlockPopup {
    bool active{false};
    std::string title;
    std::string subtitle;
    Uint32 shownAt{0};
};
BadgeUnlockPopup badgePopup;

std::string get_progress_save_path() {
    const char* base = SDL_AndroidGetInternalStoragePath();
    return std::string(base ? base : ".") + "/progress.sav";
}

// Save hardening:
// - Never truncate the live save directly; write a temporary file and atomically
//   replace the old save after a successful flush/close.
// - Authenticate saves with an Android Keystore-backed, non-exportable HMAC key.
// - Never compile the save-MAC secret into the native binary.
// - Keep premium purchase entitlement out of the local save trust boundary:
//   premium flags are restored only by the verified Android billing bridge.

static bool progress_read_all(const std::string& path, std::string& out) {
    constexpr std::streamoff MAX_PROGRESS_FILE_BYTES = 64 * 1024;
    std::ifstream in(path, std::ios::in | std::ios::binary);
    if (!in.is_open()) return false;
    in.seekg(0, std::ios::end);
    const std::streamoff size = in.tellg();
    if (size < 0 || size > MAX_PROGRESS_FILE_BYTES) return false;
    in.seekg(0, std::ios::beg);
    out.resize(static_cast<size_t>(size));
    if (size > 0) in.read(&out[0], size);
    return in.good() || in.eof();
}

// Android Keystore-backed save-MAC API. Implemented below.
// No native/compiled secret fallback is permitted.
static bool game80_compute_save_mac(const std::string& payload,
                                    std::string& outHexMac);
static bool game80_verify_save_mac(const std::string& payload,
                                   const std::string& hexMac);

bool save_progress() {
    const std::string path = get_progress_save_path();
    const std::string tempPath = path + ".tmp";
    std::ofstream out(tempPath, std::ios::out | std::ios::binary | std::ios::trunc);
    if (!out.is_open()) return false;

    std::ostringstream payload;
    payload << "PROGRESS 9\n";
    payload << "LIFETIME_KILLS " << lifetimeKills << "\n";
    for (int wi = 0; wi < static_cast<int>(WeaponType::COUNT); ++wi) {
        payload << "WEAPON_KILLS_" << wi << " " << weaponKills[wi] << "\n";
    }
    payload << "LIFETIME_BOMB_DEFUSES " << lifetimeBombDefuses << "\n";
    payload << "HIGHEST_ENDLESS_WAVE " << highestEndlessWave << "\n";
    payload << "COIN_BALANCE " << coinBalance << "\n";
    // Pending completed-run rewards survive app restarts until the player
    // explicitly taps the reward button to claim them.
    payload << "COIN_REWARD_PENDING " << (coinRewardPending ? 1 : 0) << "\n";
    payload << "COIN_REWARD_SCORE " << coinRewardScoreCoins << "\n";
    payload << "COIN_REWARD_HIGH_BONUS " << coinRewardHighScoreBonus << "\n";
    payload << "LAST_RUN_COIN_REWARD " << lastRunCoinReward << "\n";
    payload << "LAST_CLAIMED_SCORE_REWARD " << lastClaimedScoreRewardCoins << "\n";
    payload << "LAST_CLAIMED_HIGH_SCORE " << lastClaimedHighScoreRewardValue << "\n";
    payload << "WEAPON_RIFLE_UNLOCKED " << (weaponRifleUnlocked ? 1 : 0) << "\n";
    payload << "WEAPON_LASER_UNLOCKED " << (weaponLaserUnlocked ? 1 : 0) << "\n";
    payload << "WEAPON_ROCKET_UNLOCKED " << (weaponRocketUnlocked ? 1 : 0) << "\n";
    payload << "PREMIUM_VECTOR_UNLOCKED " << (premiumVectorReflectUnlocked ? 1 : 0) << "\n";
    payload << "PREMIUM_LASER_UNLOCKED " << (premiumLaserUnlocked ? 1 : 0) << "\n";
    payload << "PREMIUM_FIRE_UNLOCKED " << (premiumFireGunUnlocked ? 1 : 0) << "\n";
    payload << "PREMIUM_ICE_UNLOCKED " << (premiumIceGunUnlocked ? 1 : 0) << "\n";
    payload << "BADGE_BOMB_DEFUSER " << (badgeBombDefuserUnlocked ? 1 : 0) << "\n";
    payload << "BADGE_LAST_MAN_STANDING " << (badgeLastManStandingUnlocked ? 1 : 0) << "\n";    payload << "LAST_MAN_STANDING_RULE_VERSION 2\n";
    payload << "BADGE_SHARP_SHOOTER " << (badgeSharpShooterUnlocked ? 1 : 0) << "\n";
    payload << "TUTORIAL_COMPLETED " << (firstRunTutorialCompleted ? 1 : 0) << "\n";
    const std::string body = payload.str();
    if (body.size() > 60 * 1024) {
        out.close();
        std::remove(tempPath.c_str());
        return false;
    }
    // Authenticate the exact payload with the Android Keystore-backed
    // non-exportable HMAC key. Non-Android builds fail closed.
    std::string saveMac;
    if (!game80_compute_save_mac(body, saveMac)) {
        out.close();
        std::remove(tempPath.c_str());
        return false;
    }
    out.write(body.data(), static_cast<std::streamsize>(body.size()));
    out << "SAVE_MAC " << saveMac << "\n";
    out.flush();
    if (!out.good()) { out.close(); std::remove(tempPath.c_str()); return false; }
    out.close();
    if (!out.good()) { std::remove(tempPath.c_str()); return false; }

    // POSIX rename is atomic when source/destination are on the same filesystem.
    // Android app-internal storage satisfies that requirement here.
    if (std::rename(tempPath.c_str(), path.c_str()) != 0) {
        std::remove(tempPath.c_str());
        return false;
    }
    return true;
}

bool load_progress() {
    const std::string path = get_progress_save_path();
    std::string raw;
    if (!progress_read_all(path, raw)) return false; // first-ever launch - defaults stand

    // Split the authenticated payload from the trailing MAC record. New saves
    // must authenticate before any persisted state is applied. Older PROGRESS
    // versions remain readable for migration, but they are treated as legacy
    // and are rewritten into the hardened format after a successful load.
    std::string payload = raw;
    std::string storedMac;
    const std::string macMarker = "\nSAVE_MAC ";
    const size_t macPos = raw.rfind(macMarker);
    bool authenticated = false;
    if (macPos != std::string::npos) {
        payload = raw.substr(0, macPos + 1);
        storedMac = raw.substr(macPos + macMarker.size());
        while (!storedMac.empty() && (storedMac.back() == '\n' || storedMac.back() == '\r' || storedMac.back() == ' ' || storedMac.back() == '\t'))
            storedMac.pop_back();
        authenticated = game80_verify_save_mac(payload, storedMac);
        if (!authenticated) {
            // A SAVE_MAC record is present but does not verify: this save was
            // written by a hardened build and has since been altered. Do not
            // partially load a tampered save.
            return false;
        }
    }

    std::istringstream in(payload);
    std::string tag; int version;
    if (!(in >> tag >> version) || tag != "PROGRESS" || version < 1 || version > 9) return false;

    // Every save written by a hardened (PROGRESS 9+) build carries a SAVE_MAC
    // record and must authenticate above, or it is rejected as tampered.
    // A save with NO SAVE_MAC record at all is only acceptable as a genuine
    // pre-hardening legacy file - i.e. a version that predates the SAVE_MAC
    // scheme entirely. If a file claims to be PROGRESS 9+ but has no MAC
    // record, that is not a legitimate legacy save (9+ always writes one),
    // so it is treated the same as a failed verification: reject it.
    const bool legacyUnauthenticatedAllowed = (macPos == std::string::npos) && version < 9;
    if (!authenticated && !legacyUnauthenticatedAllowed) return false;
    int v;
    if (!(in >> tag >> lifetimeKills) || tag != "LIFETIME_KILLS") return false;
    if (version >= 6) {
        for (int wi = 0; wi < static_cast<int>(WeaponType::COUNT); ++wi) {
            if (!(in >> tag >> weaponKills[wi]) || tag != "WEAPON_KILLS_" + std::to_string(wi)) return false;
        }
    }
    if (!(in >> tag >> lifetimeBombDefuses) || tag != "LIFETIME_BOMB_DEFUSES") return false;
    if (!(in >> tag >> highestEndlessWave) || tag != "HIGHEST_ENDLESS_WAVE") return false;
    if (version >= 2) {
        if (!(in >> tag >> coinBalance) || tag != "COIN_BALANCE") return false;
        if (version >= 5) {
            if (!(in >> tag >> v) || tag != "COIN_REWARD_PENDING") return false; coinRewardPending = (v != 0);
            if (!(in >> tag >> coinRewardScoreCoins) || tag != "COIN_REWARD_SCORE") return false;
            if (!(in >> tag >> coinRewardHighScoreBonus) || tag != "COIN_REWARD_HIGH_BONUS") return false;
            if (!(in >> tag >> lastRunCoinReward) || tag != "LAST_RUN_COIN_REWARD") return false;
            if (version >= 6) {
                if (!(in >> tag >> lastClaimedScoreRewardCoins) || tag != "LAST_CLAIMED_SCORE_REWARD") return false;
                if (!(in >> tag >> lastClaimedHighScoreRewardValue) || tag != "LAST_CLAIMED_HIGH_SCORE") return false;
            }
            // A restored pending reward is waiting for a manual tap; no old
            // animation state is restored because the animation is only UI.
            coinRewardAnimationActive = false;
            coinRewardAnimationOnMenuEntry = false;
            coinRewardAnimationStartedAt = 0;
            coinRewardDisplayCoins = 0;
            coinRewardDisplayScore = 0;
        }
        if (!(in >> tag >> v) || tag != "WEAPON_RIFLE_UNLOCKED") return false; weaponRifleUnlocked = (v != 0);
        if (!(in >> tag >> v) || tag != "WEAPON_LASER_UNLOCKED") return false; weaponLaserUnlocked = (v != 0);
        if (!(in >> tag >> v) || tag != "WEAPON_ROCKET_UNLOCKED") return false; weaponRocketUnlocked = (v != 0);
    }
    if (version >= 4) {
        // Premium entitlements are intentionally NOT restored from local save
        // data. The Android billing layer must call grant_premium_weapon() only
        // after Google Play verification. The values are consumed solely to
        // maintain file-format compatibility.
        if (!(in >> tag >> v) || tag != "PREMIUM_VECTOR_UNLOCKED") return false;
        if (!(in >> tag >> v) || tag != "PREMIUM_LASER_UNLOCKED") return false;
        if (!(in >> tag >> v) || tag != "PREMIUM_FIRE_UNLOCKED") return false;
        if (!(in >> tag >> v) || tag != "PREMIUM_ICE_UNLOCKED") return false;
        premiumVectorReflectUnlocked = false;
        premiumLaserUnlocked = false;
        premiumFireGunUnlocked = false;
        premiumIceGunUnlocked = false;
    }
    // Badge fields were added in PROGRESS 7. Older save files have no
    // BADGE_* lines at all - reading unconditionally here would leave `v`
    // holding a stale value from whatever field was read last (e.g. a
    // purchased premium weapon), silently marking badges "unlocked" that
    // were never actually earned. Only read them from saves new enough to
    // contain them; older saves simply keep the false defaults and the
    // badges are re-earned naturally as check_badge_unlocks() runs.
    bool lastManStandingRuleV2 = false;
    if (version >= 7) {
        if (!(in >> tag >> v) || tag != "BADGE_BOMB_DEFUSER") return false; badgeBombDefuserUnlocked = (v != 0);
        if (!(in >> tag >> v) || tag != "BADGE_LAST_MAN_STANDING") return false; badgeLastManStandingUnlocked = (v != 0);
        if (!(in >> tag >> v) || tag != "BADGE_SHARP_SHOOTER") return false; badgeSharpShooterUnlocked = (v != 0);
    }
    if (version >= 8) {
        if (!(in >> tag >> v) || tag != "LAST_MAN_STANDING_RULE_VERSION") return false;
        lastManStandingRuleV2 = (v >= 2);
    }
    // Any badge saved by the old wave-only rule is invalid under the corrected
    // rule. It must be earned again by reaching wave 15 without dying.
    if (!lastManStandingRuleV2) {
        badgeLastManStandingUnlocked = false;
    }

    // Old PROGRESS 2 files have no tutorial field. In that case extraction
    // fails and the default false remains, which intentionally shows the new
    // beginner tutorial once.
    if (in >> tag >> v) {
        if (tag != "TUTORIAL_COMPLETED") return false;
        firstRunTutorialCompleted = (v != 0);
        if (in >> tag) return false;
    }

    // Migrate legacy saves to the hardened atomic/MAC format after successful
    // parsing. This also upgrades PROGRESS 8 to PROGRESS 9 automatically.
    if (version < 9) {
        if (!save_progress()) return false;
    }
    return true;
}

void trigger_badge_popup(const std::string& subtitle) {
    badgePopup.active = true;
    badgePopup.title = "BADGE UNLOCKED";
    badgePopup.subtitle = subtitle;
    badgePopup.shownAt = SDL_GetTicks();
}

void check_badge_unlocks() {
    if (!badgeBombDefuserUnlocked && lifetimeBombDefuses >= BADGE_BOMB_DEFUSER_TARGET) {
        badgeBombDefuserUnlocked = true;
        trigger_badge_popup("BOMB DEFUSER");
        save_progress();
    }
    if (!badgeSharpShooterUnlocked && lifetimeKills >= BADGE_SHARP_SHOOTER_TARGET) {
        badgeSharpShooterUnlocked = true;
        trigger_badge_popup("SHARP SHOOTER");
        save_progress();
    }
    if (!badgeLastManStandingUnlocked &&
        highestEndlessWave >= BADGE_LAST_MAN_STANDING_TARGET &&
        !playerDiedThisEndlessRun) {
        badgeLastManStandingUnlocked = true;
        trigger_badge_popup("LAST MAN STANDING");
        save_progress();
    }
}

// --- Tactical round tracking ------------------------------------------------
// A tactical mission is 10 rounds. Bots keep the same roster (names, kills,
// deaths) across all 10 rounds of one mission - only a brand new mission
// (Start Mission from TACTICAL_CONFIG) reshuffles/resets the bot roster.
constexpr int MAX_TACTICAL_ROUNDS = 10;
int currentRound = 1;
std::string playerName = "VETERAN_01";
bool profileEditActive = false;
std::string profileNameInput;
bool showLeaderboardPanel = false; // manual toggle via the HUD button during play
bool showMatchEndLeaderboard = false; // shown after the mission-accomplished screen
bool showMissionAccomplishedScreen = false; // short result screen before the final leaderboard
Uint32 missionAccomplishedAt = 0;

void profile_open_edit_dialog() {
    profileEditActive = true;
    profileNameInput = playerName;
    // Force a fresh OFF->ON edge every time the dialog opens. If the on-screen
    // keyboard was dismissed directly (tap outside the field, back gesture,
    // the keyboard's own dismiss key) without going through Save/Cancel, SDL
    // still considers text input "active" - calling Start again in that state
    // is a no-op on many platforms and the keyboard never reappears. Stopping
    // first guarantees the edge that actually summons it.
    SDL_StopTextInput();
    SDL_StartTextInput();
}

void profile_close_edit_dialog() {
    profileEditActive = false;
    SDL_StopTextInput();
}

int playerMaxHp = 100, playerHp = 100;

// STEP 17.21 - PLAYER CONTROLLER POLISH
// A small, deterministic movement filter keeps keyboard and touch controls
// responsive while removing abrupt starts/stops and diagonal speed exploits.
struct PlayerControllerPolish {
    float velocityX{0.0f};
    float velocityY{0.0f};
    float lastMoveX{0.0f};
    float lastMoveY{1.0f};
    float accelerationPerFrame{0.34f};
    float decelerationPerFrame{0.48f};
    float deadzone{0.08f};
};
PlayerControllerPolish playerController;

static float controller_approach(float current, float target, float amount) {
    if (current < target) return std::min(current + amount, target);
    if (current > target) return std::max(current - amount, target);
    return target;
}

static void controller_build_move_input(const Uint8* keys, float touchX, float touchY,
                                        float& outX, float& outY) {
    outX = touchX; outY = touchY;
    // Keyboard takes part in the same vector rather than overwriting one axis,
    // so W+A and touch diagonals always receive identical normalization.
    if (keys[SDL_SCANCODE_A]) outX -= 1.0f;
    if (keys[SDL_SCANCODE_D]) outX += 1.0f;
    if (keys[SDL_SCANCODE_W]) outY -= 1.0f;
    if (keys[SDL_SCANCODE_S]) outY += 1.0f;
    const float len = std::sqrt(outX*outX + outY*outY);
    if (len > 1.0f) { outX /= len; outY /= len; }
    if (len < playerController.deadzone) { outX = 0.0f; outY = 0.0f; }
}

static void controller_update_velocity(float inputX, float inputY, bool dashing,
                                       float& outVX, float& outVY) {
    if (inputX != 0.0f || inputY != 0.0f) {
        playerController.lastMoveX = inputX;
        playerController.lastMoveY = inputY;
    }
    const float targetX = inputX * WALK_SPEED;
    const float targetY = inputY * WALK_SPEED;
    const float rate = (inputX != 0.0f || inputY != 0.0f)
        ? playerController.accelerationPerFrame * WALK_SPEED
        : playerController.decelerationPerFrame * WALK_SPEED;
    playerController.velocityX = controller_approach(playerController.velocityX, targetX, rate);
    playerController.velocityY = controller_approach(playerController.velocityY, targetY, rate);
    if (dashing) { outVX = 0.0f; outVY = 0.0f; return; }
    outVX = playerController.velocityX;
    outVY = playerController.velocityY;
}

// Weapon state: current + previous, so quick-swap (Q) and the hotbar can both
// reference "what was I just holding" without any extra bookkeeping elsewhere.
struct PlayerWeaponState {
    WeaponType current{WeaponType::PISTOL};
    WeaponType previous{WeaponType::PISTOL};
    // Rifle and Rocket are locked behind the coin shop; premium weapons use the
    // real-money store. Only Pistol starts equipped by default -
    // only Pistol starts equipped. Previously-unlocked weapons (loaded from
    // progress.sav) get re-added to this loadout right after load_progress()
    // runs - see the call site near program start.
    std::array<WeaponType, 8> equipped{{WeaponType::PISTOL}};
    int equippedCount{1};
};
PlayerWeaponState playerWeaponState;
WeaponType& playerWeapon = playerWeaponState.current;
Uint32 weaponSwitchFlashAt = 0;
Uint32 lastPlayerFireAt = 0;
float lastPlayerAimX = 1.0f, lastPlayerAimY = 0.0f;

// Pistol is free. Rifle/Rocket use coins. Vector-Reflect/Laser/Fire Gun/Ice Gun
// are premium RS 20 products. Coin Magnet is always free.
bool is_weapon_locked(WeaponType w) {
    if (TEST_UNLOCK_ALL_WEAPONS) return false;
    if (w == WeaponType::RIFLE)  return !weaponRifleUnlocked;
    if (w == WeaponType::ROCKET) return !weaponRocketUnlocked;
    if (w == WeaponType::VECTOR_REFLECT) return !premiumVectorReflectUnlocked;
    if (w == WeaponType::LASER) return !premiumLaserUnlocked;
    if (w == WeaponType::FIRE_GUN) return !premiumFireGunUnlocked;
    if (w == WeaponType::ICE_GUN) return !premiumIceGunUnlocked;
    if (w == WeaponType::WIND_GUN) return false;
    if (w == WeaponType::COIN_MAGNET) return false;
    return false;
}

// Host-authoritative weapon entitlement check used by the live LAN server.
// Never trust the weapon id supplied by a remote client as proof of ownership.
// During TEST_UNLOCK_ALL_WEAPONS development builds this intentionally allows
// every weapon, so multiplayer testing keeps working exactly as before. When
// test mode is disabled, the host's loaded/verified unlock state is the
// authority for which weapons may be fired over the network.
static bool server_weapon_authorized(WeaponType w) {
    if (static_cast<int>(w) < 0 || static_cast<int>(w) >= static_cast<int>(WeaponType::COUNT))
        return false;
    if (TEST_UNLOCK_ALL_WEAPONS) return true;
    return !is_weapon_locked(w);
}

int weapon_unlock_cost(WeaponType w) {
    if (w == WeaponType::RIFLE)  return WEAPON_COST_RIFLE;
    if (w == WeaponType::LASER)  return WEAPON_COST_LASER;
    if (w == WeaponType::ROCKET) return WEAPON_COST_ROCKET;
    if (w == WeaponType::VECTOR_REFLECT || w == WeaponType::LASER ||
        w == WeaponType::FIRE_GUN || w == WeaponType::ICE_GUN) return PREMIUM_PRICE_RS;
    return 0;
}

// Attempts to spend coinBalance to unlock a weapon (save_progress() is
// defined earlier in the file). Returns true on success (and saves progress
// right away so a purchase is never lost to a crash or force-quit). No-op
// if already unlocked or the balance is short.
bool try_unlock_weapon(WeaponType w) {
    if (!is_weapon_locked(w)) return false;
    if (w == WeaponType::VECTOR_REFLECT || w == WeaponType::LASER ||
        w == WeaponType::FIRE_GUN || w == WeaponType::ICE_GUN) {
        request_premium_purchase(w);
        return false;
    }
    int cost = weapon_unlock_cost(w);
    if (coinBalance < cost) return false;
    coinBalance -= cost;
    if (w == WeaponType::RIFLE)  weaponRifleUnlocked = true;
    if (w == WeaponType::ROCKET) weaponRocketUnlocked = true;
    save_progress();
    return true;
}

bool is_weapon_equipped(WeaponType w) {
    for (int i = 0; i < playerWeaponState.equippedCount; ++i)
        if (playerWeaponState.equipped[i] == w) return true;
    return false;
}

void refresh_weapon_radial();

WeaponType cycle_weapon(WeaponType w, int dir) {
    if (playerWeaponState.equippedCount <= 0) return WeaponType::PISTOL;
    int currentIndex = 0;
    for (int i = 0; i < playerWeaponState.equippedCount; ++i) {
        if (playerWeaponState.equipped[i] == w) { currentIndex = i; break; }
    }
    int next = (currentIndex + dir + playerWeaponState.equippedCount) % playerWeaponState.equippedCount;
    return playerWeaponState.equipped[next];
}

void set_player_weapon(WeaponType newWeapon, Uint32 currentTime,
                        VoiceLine voiceLine = VoiceLine::WEAPON_SWITCH) {
    if (!is_weapon_equipped(newWeapon) || newWeapon == playerWeaponState.current) return;
    playerWeaponState.previous = playerWeaponState.current;
    playerWeaponState.current = newWeapon;
    weaponSwitchFlashAt = currentTime;
    play_voice_line(voiceLine);
}

void toggle_weapon_loadout(WeaponType w, Uint32 currentTime) {
    for (int i = 0; i < playerWeaponState.equippedCount; ++i) {
        if (playerWeaponState.equipped[i] == w) {
            if (playerWeaponState.equippedCount <= 1) return;
            for (int j = i; j < playerWeaponState.equippedCount - 1; ++j)
                playerWeaponState.equipped[j] = playerWeaponState.equipped[j + 1];
            --playerWeaponState.equippedCount;
            if (!is_weapon_equipped(playerWeaponState.current))
                playerWeaponState.current = playerWeaponState.equipped[0];
            refresh_weapon_radial();
            weaponSwitchFlashAt = currentTime;
            return;
        }
    }
    if (playerWeaponState.equippedCount >= 4) return;
    playerWeaponState.equipped[playerWeaponState.equippedCount++] = w;
    refresh_weapon_radial();
}

// Electric Shield: pistol-only special ability. While active, blocks all incoming damage
// (direct bullets + rocket splash) and instantly destroys any enemy that touches the player.
constexpr Uint32 SHIELD_DURATION_MS = 3000; // how long the shield stays up once activated
constexpr Uint32 SHIELD_COOLDOWN_MS = 5000; // cooldown after it drops before it can be used again
bool playerShieldActive = false;
Uint32 playerShieldActivatedAt = 0;
Uint32 playerShieldReadyAt = 0; // shield can be (re)activated once currentTime >= this

// Dash/dodge-roll I-Frames - global (not just a main() local) so damage-applying
// helpers like trigger_explosion() can also respect it.
bool playerIsInvulnerable = false;

void try_activate_shield(Uint32 currentTime) {
    if (playerWeapon != WeaponType::PISTOL) return; // pistol-exclusive
    if (playerShieldActive) return;                 // already up
    if (currentTime < playerShieldReadyAt) return;   // still on cooldown
    playerShieldActive = true;
    playerShieldActivatedAt = currentTime;
    play_voice_line(VoiceLine::SHIELD_ACTIVATE);
}

int score = 0;
int highScore = 0;
int runStartHighScore = 0;

int activeEnemyCount = 1;
Bomb tacticalBomb{};
int botDefuserIndex = -1; // Sentinel assigned to the current planted bomb

std::array<Bullet, MAX_BULLETS> bullets{};
std::array<Explosion, MAX_EXPLOSIONS> explosions{};
std::array<FireImpact, 48> fireImpacts{}; // headroom for wall-of-fire casts (FIRE_WALL_SEGMENTS each)
std::array<GlassShatter, 32> glassShatters{};
std::array<HealthPack, MAX_HEALTH_PACKS> healthPacks{};
std::array<Coin, MAX_COINS> coins{};
std::array<Enemy, MAX_ENEMIES> enemies{};
std::array<LaserBeam, 16> laserBeams{}; // pool - each shot gets its own slot instead of
                                         // clobbering one shared beam when player and enemy
                                         // lasers fire close together

// --- Leaderboard --------------------------------------------------------
struct LBEntry {
    std::string name;
    int kills{0};
    int deaths{0};
    int bombDefuses{0};
    int bombPlants{0};
    int scoreValue{0};
    bool isPlayer{false};
    Team team{Team::GREEN_DEFUSER};
};

std::vector<LBEntry> build_leaderboard() {
    std::vector<LBEntry> rows;

    // Sentinel section: the player is always first in this faction's roster,
    // followed by the allied Sentinel bots.
    rows.push_back({playerName, playerKills, playerDeaths, playerBombDefuses, 0, score, true, Team::GREEN_DEFUSER});
    for (int i = 0; i < activeBotCount; ++i) {
        const Bot& bot = bots[i];
        if (bot.name.empty()) continue;
        rows.push_back({bot.name, bot.kills, bot.deaths, bot.bombDefuses, 0, bot.kills * 10 + bot.bombDefuses * 100, false, Team::GREEN_DEFUSER});
    }

    // Raider section.
    for (int i = 0; i < activeEnemyCount; ++i) {
        const Enemy& enemy = enemies[i];
        if (enemy.name.empty()) continue;
        rows.push_back({enemy.name, enemy.kills, enemy.deaths, 0, enemy.bombPlants, enemy.kills * 10 + enemy.bombPlants * 100, false, Team::RED_BOMBER});
    }
    return rows;
}

// Shared leaderboard panel - Sentinel section is always shown first, followed
// by the Raider section. Each faction is sorted independently by score.
void render_leaderboard_panel(SDL_Renderer* renderer, const SDL_Rect& requestedBox, const std::string& title) {
    SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);

    // The game uses a fixed 2000x1200 logical canvas, but the physical Android
    // surface can be much smaller and/or portrait.  Build the panel from the
    // renderer's real output size so the table stays compact and legible after
    // SDL's logical-size scaling.
    int outputW = SCREEN_WIDTH;
    int outputH = SCREEN_HEIGHT;
    SDL_GetRendererOutputSize(renderer, &outputW, &outputH);

    const float physicalScale = std::min(
        static_cast<float>(outputW) / static_cast<float>(SCREEN_WIDTH),
        static_cast<float>(outputH) / static_cast<float>(SCREEN_HEIGHT));

    // Keep a generous panel on tablets/desktop, but make it narrower on phones.
    // The table never relies on hard-coded X positions that can fall outside
    // the panel.
    const bool compact = physicalScale < 0.75f || outputW < 1100 || outputH < 700;
    const int panelW = compact ? 1660 : 1740;
    const int panelH = compact ? 1030 : 1060;
    const int panelX = (SCREEN_WIDTH - panelW) / 2;
    const int panelY = std::max(55, (SCREEN_HEIGHT - panelH) / 2);
    const SDL_Rect box{panelX, panelY, panelW, panelH};

    // Use a larger logical font on small physical screens.  At phone-scale
    // rendering this keeps the glyphs comfortably tappable/readable.
    const int titleScale = compact ? 3 : 3;
    const int textScale = compact ? 3 : 2;
    const int smallScale = compact ? 2 : 2;

    // Dark translucent overlay.
    SDL_SetRenderDrawColor(renderer, 0, 0, 0, 175);
    SDL_Rect fullScreen{0, 0, SCREEN_WIDTH, SCREEN_HEIGHT};
    SDL_RenderFillRect(renderer, &fullScreen);

    // Main panel.
    SDL_SetRenderDrawColor(renderer, 18, 22, 30, 252);
    SDL_RenderFillRect(renderer, &box);
    SDL_SetRenderDrawColor(renderer, 235, 235, 240, 255);
    draw_rect_outline(renderer, box, 3);

    draw_text(renderer, title,
              centered_text_x(title, titleScale, box.x, box.w),
              box.y + 22, titleScale, {100, 220, 255, 255});

    std::vector<LBEntry> rows = build_leaderboard();
    std::vector<LBEntry> sentinels;
    std::vector<LBEntry> raiders;
    for (const LBEntry& row : rows) {
        if (row.team == Team::GREEN_DEFUSER) sentinels.push_back(row);
        else raiders.push_back(row);
    }

    auto sortByScore = [](const LBEntry& a, const LBEntry& b) {
        return a.scoreValue > b.scoreValue;
    };
    if (sentinels.size() > 1) std::sort(sentinels.begin() + 1, sentinels.end(), sortByScore);
    std::sort(raiders.begin(), raiders.end(), sortByScore);

    // Responsive column grid.  Names get the largest share; numeric columns
    // are fixed-width so values never collide with one another.
    const int innerX = box.x + (compact ? 22 : 28);
    const int innerW = box.w - (compact ? 44 : 56);
    const int scoreW = compact ? 190 : 205;
    const int actionW = compact ? 210 : 225;
    const int statW = compact ? 155 : 165;
    const int nameW = innerW - scoreW - actionW - statW - statW;

    const int nameX   = innerX;
    const int killsX  = nameX + nameW;
    const int deathsX = killsX + statW;
    const int actionX = deathsX + statW;
    const int scoreX  = actionX + actionW;

    const SDL_Color columnColor{205, 205, 215, 255};
    const int headerH = compact ? 48 : 44;
    const int rowH = compact ? 68 : 60;
    const int sectionH = compact ? 54 : 50;
    const int gapBetweenTeams = compact ? 18 : 24;

    int y = box.y + (compact ? 88 : 92);

    auto drawTeamBar = [&](const char* label, SDL_Color accent) {
        SDL_SetRenderDrawColor(renderer, 34, 38, 46, 255);
        SDL_Rect bar{innerX, y, innerW, sectionH};
        SDL_RenderFillRect(renderer, &bar);
        draw_text(renderer, label, innerX + 12, y + (sectionH - 14) / 2,
                  smallScale, accent);
        y += sectionH;
    };

    auto drawHeader = [&](const char* actionLabel) {
        SDL_SetRenderDrawColor(renderer, 10, 13, 18, 230);
        SDL_Rect header{innerX, y, innerW, headerH};
        SDL_RenderFillRect(renderer, &header);

        const int textY = y + (headerH - 14) / 2;
        draw_text(renderer, "NAME",   nameX + 8,   textY, smallScale, columnColor);
        draw_text(renderer, "KILLS",  killsX + 8,  textY, smallScale, columnColor);
        draw_text(renderer, "DEATHS", deathsX + 8, textY, smallScale, columnColor);
        draw_text(renderer, actionLabel, actionX + 8, textY, smallScale, columnColor);
        draw_text(renderer, "SCORE", scoreX + 8, textY, smallScale, columnColor);
        y += headerH;
    };

    auto drawEntry = [&](const LBEntry& row, bool sentinel) {
        const SDL_Color textColor = sentinel
            ? SDL_Color{60, 245, 100, 255}
            : SDL_Color{255, 85, 85, 255};

        if (row.isPlayer) {
            SDL_SetRenderDrawColor(renderer, 45, 70, 100, 210);
        } else {
            SDL_SetRenderDrawColor(renderer, 24, 28, 36, 200);
        }

        SDL_Rect rowRect{innerX, y, innerW, rowH};
        SDL_RenderFillRect(renderer, &rowRect);

        std::string name = row.name;
        // Fit the callsign to the actual name column instead of truncating at a
        // fixed character count that only worked for the old desktop geometry.
        const int maxNameChars = std::max(4, nameW / (6 * textScale));
        if (static_cast<int>(name.size()) > maxNameChars) {
            name.resize(static_cast<size_t>(maxNameChars));
        }

        const int textY = y + (rowH - 7 * textScale) / 2;
        draw_text(renderer, name, nameX + 8, textY, textScale, textColor);
        draw_text(renderer, std::to_string(row.kills), killsX + 8, textY, textScale, textColor);
        draw_text(renderer, std::to_string(row.deaths), deathsX + 8, textY, textScale, textColor);

        if (sentinel) {
            draw_text(renderer, std::to_string(row.bombDefuses), actionX + 8, textY, textScale, textColor);
        } else {
            draw_text(renderer, std::to_string(row.bombPlants), actionX + 8, textY, textScale, textColor);
        }

        draw_text(renderer, std::to_string(row.scoreValue), scoreX + 8, textY, textScale, textColor);
        y += rowH;
    };

    // Draw both factions using the same responsive grid.  Eight total players
    // therefore remain readable without horizontal overflow or overlapping
    // columns on small phone screens.
    drawTeamBar("SENTINELS", {60, 245, 90, 255});
    drawHeader("DEFUSED");
    for (const LBEntry& row : sentinels) {
        if (y + rowH > box.y + box.h - sectionH - headerH - rowH) break;
        drawEntry(row, true);
    }

    y += gapBetweenTeams;

    drawTeamBar("RAIDERS", {255, 85, 85, 255});
    drawHeader("PLANTED");
    for (const LBEntry& row : raiders) {
        if (y + rowH > box.y + box.h - 10) break;
        drawEntry(row, false);
    }

    // requestedBox is retained in the API so existing callers do not need to
    // change; the responsive panel intentionally supersedes its old fixed size.
    (void)requestedBox;
}

// Small live tactical map shown during gameplay. It deliberately displays ONLY
// the map layout and the player's current position/direction; no enemies, bots,
// bomb carrier, bomb, health packs, or other tactical information are revealed.
void render_live_minimap(SDL_Renderer* renderer, const SDL_Rect& box, float playerWorldX, float playerWorldY, float dirX, float dirY) {
    // Blueprint-style tactical map: technical, clean, and readable rather than
    // a solid green minimap.  The live map intentionally reveals only layout
    // plus the player's current position/direction.
    SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);

    SDL_SetRenderDrawColor(renderer, 5, 12, 24, 245);
    SDL_RenderFillRect(renderer, &box);
    SDL_SetRenderDrawColor(renderer, 45, 135, 190, 255);
    draw_rect_outline(renderer, box, 2);

    const int headerH = 28;
    const int pad = 10;
    const int mapX = box.x + pad;
    const int mapY = box.y + headerH + pad;
    const int mapW = box.w - pad * 2;
    const int mapH = box.h - headerH - pad * 2;

    // Technical header.
    draw_text(renderer, "LIVE MAP // BLUEPRINT", box.x + 12, box.y + 7, 1,
              {100, 205, 255, 255});
    SDL_SetRenderDrawColor(renderer, 35, 100, 145, 180);
    SDL_RenderDrawLine(renderer, box.x + 10, box.y + headerH,
                       box.x + box.w - 10, box.y + headerH);

    // Preserve map aspect ratio and center small custom maps inside the preview.
    float scaleX = static_cast<float>(mapW) / std::max(1, currentMapCols);
    float scaleY = static_cast<float>(mapH) / std::max(1, currentMapRows);
    float scale = std::min(scaleX, scaleY);
    const float sx = scale;
    const float sy = scale;
    const int drawW = static_cast<int>(currentMapCols * sx);
    const int drawH = static_cast<int>(currentMapRows * sy);
    const int drawX = mapX + (mapW - drawW) / 2;
    const int drawY = mapY + (mapH - drawH) / 2;

    // Blueprint grid.
    SDL_SetRenderDrawColor(renderer, 20, 70, 105, 95);
    for (int c = 0; c <= currentMapCols; ++c) {
        int x = drawX + static_cast<int>(c * sx);
        SDL_RenderDrawLine(renderer, x, mapY, x, mapY + mapH);
    }
    for (int r = 0; r <= currentMapRows; ++r) {
        int y = drawY + static_cast<int>(r * sy);
        SDL_RenderDrawLine(renderer, mapX, y, mapX + mapW, y);
    }

    // Draw floor/walls as technical blueprint geometry.
    for (int r = 0; r < currentMapRows; ++r) {
        for (int c = 0; c < currentMapCols; ++c) {
            int tile = gameMap[r][c];
            bool walkable = (tile == 0 || tile == 8 || tile == 9 || tile == 10 || tile == 11);
            int x0 = drawX + static_cast<int>(c * sx);
            int y0 = drawY + static_cast<int>(r * sy);
            int x1 = drawX + static_cast<int>((c + 1) * sx);
            int y1 = drawY + static_cast<int>((r + 1) * sy);
            SDL_Rect cell{x0, y0, std::max(1, x1 - x0), std::max(1, y1 - y0)};

            if (walkable) {
                SDL_SetRenderDrawColor(renderer, 8, 35, 58, 150);
                SDL_RenderFillRect(renderer, &cell);
            } else {
                SDL_SetRenderDrawColor(renderer, 11, 24, 38, 245);
                SDL_RenderFillRect(renderer, &cell);
                SDL_SetRenderDrawColor(renderer, 55, 155, 205, 210);
                draw_rect_outline(renderer, cell, 1);
            }
        }
    }

    // Highlight the map boundary like a technical drafting frame.
    SDL_SetRenderDrawColor(renderer, 70, 175, 225, 210);
    SDL_RenderDrawLine(renderer, mapX, mapY, mapX + mapW, mapY);
    SDL_RenderDrawLine(renderer, mapX, mapY + mapH, mapX + mapW, mapY + mapH);
    SDL_RenderDrawLine(renderer, mapX, mapY, mapX, mapY + mapH);
    SDL_RenderDrawLine(renderer, mapX + mapW, mapY, mapX + mapW, mapY + mapH);

    float worldCx = playerWorldX + 30.0f;
    float worldCy = playerWorldY + 30.0f;
    float mx = mapX + (worldCx / std::max(1.0f, currentMapCols * static_cast<float>(TILE_SIZE))) * mapW;
    float my = mapY + (worldCy / std::max(1.0f, currentMapRows * static_cast<float>(TILE_SIZE))) * mapH;

    // Player marker: cyan drafting arrow with a small centre dot.
    float dx = dirX, dy = dirY;
    if (std::abs(dx) < 0.01f && std::abs(dy) < 0.01f) { dx = 0.0f; dy = -1.0f; }
    float len = std::sqrt(dx * dx + dy * dy);
    if (len > 0.001f) { dx /= len; dy /= len; }
    float px = -dy, py = dx;
    const float tipLen = 14.0f, baseLen = 7.0f, halfBase = 6.0f;
    SDL_Point tip{static_cast<int>(mx + dx * tipLen), static_cast<int>(my + dy * tipLen)};
    SDL_Point left{static_cast<int>(mx - dx * baseLen + px * halfBase), static_cast<int>(my - dy * baseLen + py * halfBase)};
    SDL_Point right{static_cast<int>(mx - dx * baseLen - px * halfBase), static_cast<int>(my - dy * baseLen - py * halfBase)};
    SDL_SetRenderDrawColor(renderer, 120, 235, 255, 255);
    SDL_RenderDrawLine(renderer, tip.x, tip.y, left.x, left.y);
    SDL_RenderDrawLine(renderer, left.x, left.y, right.x, right.y);
    SDL_RenderDrawLine(renderer, right.x, right.y, tip.x, tip.y);
    SDL_RenderDrawLine(renderer, static_cast<int>(mx), static_cast<int>(my), tip.x, tip.y);
    SDL_Rect centre{static_cast<int>(mx) - 2, static_cast<int>(my) - 2, 5, 5};
    SDL_RenderFillRect(renderer, &centre);

    // Small drafting labels for orientation.
    draw_text(renderer, "N", box.x + box.w - 25, box.y + 7, 1, {110, 220, 255, 255});
                                     
draw_text(renderer, current_play_map_name(), box.x + 12, box.y + box.h - 15, 1,

              {80, 160, 200, 220});
}

bool save_map_to_file(const std::string& filename) {
    std::ofstream outFile(filename, std::ios::out | std::ios::trunc);
    if (!outFile.is_open()) return false;
    outFile << "FORMAT 2\n";
    outFile << "SIZE " << editorMapCols << " " << editorMapRows << "\n";
    // Space-separate tile values so multi-digit tiles such as GLASS (10)
    // cannot be loaded back as WALL (1) followed by FLOOR (0).
    for (int r = 0; r < editorMapRows; ++r) {
        for (int c = 0; c < editorMapCols; ++c) {
            if (c) outFile << ' ';
            outFile << gameMap[r][c];
        }
        outFile << "\n";
    }

    // Saved editor vehicles section.
    outFile << "VEHICLES " << savedMapVehicles.size() << "\n";
    for (const auto& v : savedMapVehicles) {
        outFile << v.type << " " << v.x << " " << v.y << " " << v.rotation << "\n";
    }

    outFile.flush();
    bool ok = outFile.good();
    outFile.close();
    return ok;
}

bool load_map_from_file(const std::string& filename) {
    std::ifstream inFile(filename);
    if (!inFile.is_open()) return false;

    for (int r = 0; r < ROWS; ++r)
        for (int c = 0; c < COLS; ++c)
            gameMap[r][c] = 0;

    std::string line;
    int r = 0;
    int loadedCols = COLS, loadedRows = ROWS;

    if (std::getline(inFile, line)) {
        std::istringstream header(line);
        std::string tag;
        int w = 0, h = 0;
        if (line == "FORMAT 2") {
            // New format: the next line contains SIZE and all rows are whitespace-separated.
            if (std::getline(inFile, line)) {
                std::istringstream sizeHeader(line);
                if (sizeHeader >> tag >> w >> h && tag == "SIZE") {
                    loadedCols = std::clamp(w, 20, COLS);
                    loadedRows = std::clamp(h, 15, ROWS);
                }
            }
        } else if ((header >> tag >> w >> h) && tag == "SIZE") {
            // Version-1 map: SIZE followed by one-character-per-tile rows.
            loadedCols = std::clamp(w, 20, COLS);
            loadedRows = std::clamp(h, 15, ROWS);
        } else {
            for (int c = 0; c < loadedCols && c < static_cast<int>(line.size()); ++c)
                if (std::isdigit(static_cast<unsigned char>(line[c]))) gameMap[0][c] = line[c] - '0';
            r = 1;
        }
    }

    savedMapVehicles.clear();

    while (std::getline(inFile, line) && r < loadedRows) {
        if (line.rfind("VEHICLES ", 0) == 0) {
            int count = 0;
            std::istringstream vs(line);
            std::string tag;
            vs >> tag >> count;
            for (int i = 0; i < count && std::getline(inFile, line); ++i) {
                SavedMapVehicle v;
                std::istringstream item(line);
                if (item >> v.type >> v.x >> v.y >> v.rotation)
                    savedMapVehicles.push_back(v);
            }
            continue;
        }

        std::istringstream rowStream(line);
        std::vector<int> values;
        int value = 0;
        while (rowStream >> value) values.push_back(value);

        if (!values.empty()) {
            // New format: whitespace-separated tile IDs, including 10 = GLASS.
            for (int c = 0; c < loadedCols && c < static_cast<int>(values.size()); ++c)
                gameMap[r][c] = values[c];
        } else {
            // Backward compatibility with old maps containing one digit per tile.
            for (int c = 0; c < loadedCols && c < static_cast<int>(line.size()); ++c)
                if (std::isdigit(static_cast<unsigned char>(line[c]))) gameMap[r][c] = line[c] - '0';
        }
        ++r;
    }
    inFile.close();

    currentMapCols = editorMapCols = loadedCols;
    currentMapRows = editorMapRows = loadedRows;

    for (int c = 0; c < currentMapCols; ++c) {
        gameMap[0][c] = 1;
        gameMap[currentMapRows - 1][c] = 1;
    }
    for (int rr = 0; rr < currentMapRows; ++rr) {
        gameMap[rr][0] = 1;
        gameMap[rr][currentMapCols - 1] = 1;
    }
    return r > 0;
}

void scan_bombsites() {
    bombSiteA = {-1, -1};
    bombSiteB = {-1, -1};
    bombSiteAValid = bombSiteBValid = false;
    for (int r = 0; r < currentMapRows; ++r) {
        for (int c = 0; c < currentMapCols; ++c) {
            if (gameMap[r][c] == 8 && !bombSiteAValid) {
                bombSiteA = {c, r};
                bombSiteAValid = true;
            } else if (gameMap[r][c] == 9 && !bombSiteBValid) {
                bombSiteB = {c, r};
                bombSiteBValid = true;
            }
        }
    }
}

Point nearest_free_tile(Point p) {
    auto ok = [](int x, int y) {
        return x > 0 && x < currentMapCols - 1 && y > 0 && y < currentMapRows - 1 &&
               (gameMap[y][x] == 0 || gameMap[y][x] == 8 || gameMap[y][x] == 9 || gameMap[y][x] == 10);
    };
    if (ok(p.x, p.y)) return p;
    for (int rad = 1; rad < std::max(currentMapCols, currentMapRows); ++rad) {
        for (int dy = -rad; dy <= rad; ++dy) {
            for (int dx = -rad; dx <= rad; ++dx) {
                if (std::max(std::abs(dx), std::abs(dy)) != rad) continue;
                if (ok(p.x + dx, p.y + dy)) return {p.x + dx, p.y + dy};
            }
        }
    }
    return {1, 1};
}

void reset_editor_map_size(int w, int h) {
    editorMapCols = std::clamp(w, 20, COLS);
    editorMapRows = std::clamp(h, 15, ROWS);
    currentMapCols = editorMapCols;
    currentMapRows = editorMapRows;
    for (int r = 0; r < ROWS; ++r)
        for (int c = 0; c < COLS; ++c)
            gameMap[r][c] = 0;
    for (int c = 0; c < editorMapCols; ++c) {
        gameMap[0][c] = 1;
        gameMap[editorMapRows - 1][c] = 1;
    }
    for (int r = 0; r < editorMapRows; ++r) {
        gameMap[r][0] = 1;
        gameMap[r][editorMapCols - 1] = 1;
    }
    cameraX = cameraY = 0;
    editorZoom = 1.0f;
    scan_bombsites();
}

bool is_glass_tile(int c, int r) {
    return c >= 0 && c < currentMapCols && r >= 0 && r < currentMapRows && gameMap[r][c] == 10;
}

bool rect_hits_glass(const SDL_Rect& rect, int* hitCol = nullptr, int* hitRow = nullptr) {
    int startCol = std::max(0, rect.x / TILE_SIZE);
    int endCol = std::min(currentMapCols - 1, (rect.x + rect.w - 1) / TILE_SIZE);
    int startRow = std::max(0, rect.y / TILE_SIZE);
    int endRow = std::min(currentMapRows - 1, (rect.y + rect.h - 1) / TILE_SIZE);
    for (int r = startRow; r <= endRow; ++r) {
        for (int c = startCol; c <= endCol; ++c) {
            if (is_glass_tile(c, r)) {
                if (hitCol) *hitCol = c;
                if (hitRow) *hitRow = r;
                return true;
            }
        }
    }
    return false;
}

bool check_wall_collision(SDL_Rect rect) {
    int startCol = rect.x / TILE_SIZE;
    int endCol = (rect.x + rect.w - 1) / TILE_SIZE;
    int startRow = rect.y / TILE_SIZE;
    int endRow = (rect.y + rect.h - 1) / TILE_SIZE;

    for (int r = startRow; r <= endRow; ++r) {
        for (int c = startCol; c <= endCol; ++c) {
            // STRICT BOUNDARY: If outside the array, it's an instant collision
            if (r < 0 || r >= currentMapRows || c < 0 || c >= currentMapCols) {
                return true; 
            }
            // Solid walls block movement. Glass (10) is now also solid to movement -
            // it must be shot open first; once shattered the tile becomes 0 (floor)
            // and this check naturally stops blocking it. Bombsite tags (8/9) stay walkable.
            if (gameMap[r][c] == 1 || gameMap[r][c] == 10) {
                return true;
            }
        }
    }
    return false;
}

// FIRE GUN: spawns a wall of overlapping fire patches trailing back along
// the shot's incoming flight path from the impact point, using the existing
// FireImpact pool. This borrows the flamethrower's own technique for laying
// down a wall - space overlapping patches out along the direction of travel
// with a little perpendicular wobble so the line reads as organic ground
// fire rather than a straight ruler-line - just applied all at once, since
// a Fire Gun shot is a single long-range bolt rather than a held spray.
// Anyone who walks through the line is caught by the normal per-tick
// FireImpact ignition check.
void spawn_fire_wall(float originX, float originY, float dirX, float dirY, Uint32 currentTime) {
    float len = std::sqrt(dirX * dirX + dirY * dirY);
    float dx = len > 0.01f ? dirX / len : 1.0f;
    float dy = len > 0.01f ? dirY / len : 0.0f;
    float px = -dy, py = dx;

    for (int seg = 0; seg < FIRE_WALL_SEGMENTS; ++seg) {
        // Walk backward from the impact point along the bullet's incoming
        // path - the same "step outward and place a patch" idea the
        // flamethrower uses while spraying, just resolved instantly here.
        float back = static_cast<float>(seg) * FIRE_WALL_SPACING;
        float seed = static_cast<float>(seg) * 12.9898f + originX * 0.013f + originY * 0.017f;
        float wobble = std::sin(seed * 4.7f) * 20.0f;
        float sx = originX - dx * back + px * wobble;
        float sy = originY - dy * back + py * wobble;
        for (auto& fi : fireImpacts) {
            if (!fi.active) {
                fi.x = sx;
                fi.y = sy;
                fi.radius = FIRE_WALL_SEGMENT_RADIUS * (0.85f + 0.3f * std::fmod(std::fabs(seed), 1.0f));
                fi.spawnTime = currentTime;
                fi.duration = FIRE_WALL_DURATION_MS;
                fi.active = true;
                break;
            }
        }
    }
}

// Returns whether a full-size enemy can actually occupy a tile.  The old
// pathfinder treated every non-wall tile as walkable, but a 60x60 enemy can
// overlap a wall even when its tile itself is open.  That was the main cause
// of enemies getting pinned against corners and then appearing unresponsive.
bool ai_tile_walkable(int c, int r) {
    if (c < 1 || c >= currentMapCols - 1 || r < 1 || r >= currentMapRows - 1) return false;
    if (!(gameMap[r][c] == 0 || gameMap[r][c] == 8 || gameMap[r][c] == 9)) return false;
    SDL_Rect probe{c * TILE_SIZE + 5, r * TILE_SIZE + 5, 60, 60};
    return !check_wall_collision(probe);
}

// A 60x60 actor is wider than one 50px tile, so a custom spawn or a
// collision correction can occasionally leave a Raider overlapping a wall.
// Recover it to the nearest tile that can contain the complete hitbox before
// pathing continues; otherwise the normal blocked-movement logic can keep it
// pressed against the same wall forever.
void recover_enemy_from_wall(Enemy& enemy) {
    if (!enemy.active || !check_wall_collision(enemy.rect)) return;

    const int startC = static_cast<int>(enemy.x + enemy.rect.w / 2) / TILE_SIZE;
    const int startR = static_cast<int>(enemy.y + enemy.rect.h / 2) / TILE_SIZE;
    for (int radius = 1; radius <= 8; ++radius) {
        for (int r = startR - radius; r <= startR + radius; ++r) {
            for (int c = startC - radius; c <= startC + radius; ++c) {
                if (!ai_tile_walkable(c, r)) continue;
                enemy.x = c * TILE_SIZE + 5.0f;
                enemy.y = r * TILE_SIZE + 5.0f;
                enemy.rect.x = static_cast<int>(enemy.x);
                enemy.rect.y = static_cast<int>(enemy.y);
                enemy.lastPathCalc = 0;
                return;
            }
        }
    }
}

Point get_next_ai_step(Point start, Point target) {
    start.x = std::clamp(start.x, 1, currentMapCols - 2);
    start.y = std::clamp(start.y, 1, currentMapRows - 2);
    target.x = std::clamp(target.x, 1, currentMapCols - 2);
    target.y = std::clamp(target.y, 1, currentMapRows - 2);
    if (start.x == target.x && start.y == target.y) return start;

    Point parent[ROWS][COLS];
    bool visited[ROWS][COLS] = {{false}};
    std::vector<Point> queue;
    size_t head = 0;

    queue.push_back(start);
    visited[start.y][start.x] = true;

    const int dx[] = {0, 0, -1, 1};
    const int dy[] = {-1, 1, 0, 0};
    bool found = false;

    while (head < queue.size()) {
        Point curr = queue[head++];
        if (curr.x == target.x && curr.y == target.y) { found = true; break; }

        for (int i = 0; i < 4; ++i) {
            int nx = curr.x + dx[i], ny = curr.y + dy[i];
            if (nx < 1 || nx >= currentMapCols - 1 || ny < 1 || ny >= currentMapRows - 1) continue;
            if (visited[ny][nx] || !ai_tile_walkable(nx, ny)) continue;
            visited[ny][nx] = true;
            parent[ny][nx] = curr;
            queue.push_back(Point{nx, ny});
        }
    }

    if (!found) {
        // If the exact target is temporarily unreachable, pick the best
        // walkable neighbour instead of repeatedly pushing into the same wall.
        Point best = start;
        int bestDist = 0x7fffffff;
        for (int i = 0; i < 4; ++i) {
            int nx = start.x + dx[i], ny = start.y + dy[i];
            if (!ai_tile_walkable(nx, ny)) continue;
            int d = std::abs(nx - target.x) + std::abs(ny - target.y);
            if (d < bestDist) { bestDist = d; best = Point{nx, ny}; }
        }
        return best;
    }

    // Walk the parent chain backwards until we reach the first step.
    Point curr = target;
    while (!(parent[curr.y][curr.x].x == start.x && parent[curr.y][curr.x].y == start.y)) {
        curr = parent[curr.y][curr.x];
        if (curr.x == start.x && curr.y == start.y) break;
    }
    return curr;
}
// ownerIsPlayerTeam/ownerIndex identify who lit the fuse on this blast, so a
// kill from splash damage gets credited the same way a direct hit does:
//   ownerIsPlayerTeam == true,  ownerIndex == -1   -> player
//   ownerIsPlayerTeam == true,  ownerIndex >= 0     -> that bots[] slot
//   ownerIsPlayerTeam == false, ownerIndex >= 0     -> that enemies[] slot
//   ownerIndex == -2                                 -> no attribution (e.g. the bomb fuse)
void trigger_explosion(float blastX, float blastY, float radius, int baseDamage, SDL_Rect& player, int& pHp,
                        bool ownerIsPlayerTeam = true, int ownerIndex = -2, WeaponType sourceWeapon = WeaponType::COUNT) {
    // Always allocate an explosion slot.  During rapid rocket fire it is possible
    // for all MAX_EXPLOSIONS slots to still be active; silently dropping the new
    // effect makes a direct rocket hit appear to have no blast.  Prefer an inactive
    // slot, otherwise recycle the oldest active effect.
    Explosion* slot = nullptr;
    for (auto& exp : explosions) {
        if (!exp.active) {
            slot = &exp;
            break;
        }
    }
    if (!slot) {
        slot = &explosions[0];
        for (auto& exp : explosions) {
            if (exp.spawnTime < slot->spawnTime) slot = &exp;
        }
    }
    slot->x = blastX;
    slot->y = blastY;
    slot->maxRadius = radius;
    slot->spawnTime = SDL_GetTicks();
    slot->duration = 360;
    slot->active = true;

    auto apply_splash = [&](const SDL_Rect& target, int& targetHp) {
        float cx = target.x + target.w / 2.0f;
        float cy = target.y + target.h / 2.0f;
        float dist = std::sqrt((cx - blastX) * (cx - blastX) + (cy - blastY) * (cy - blastY));
        if (dist <= radius) {
            float factor = 1.0f - (dist / radius);
            int scaledBaseDamage = baseDamage + (currentLevel * 5);
            int damage = std::max(20, static_cast<int>(scaledBaseDamage * factor));
            targetHp -= damage;
        }
    };

    auto credit_kill = [&]() {
        if (ownerIndex == -2) return; // unattributed blast (bomb fuse, etc.)
        if (ownerIsPlayerTeam) {
            if (ownerIndex >= 0 && ownerIndex < activeBotCount) bots[ownerIndex].kills++;
            else { playerKills++; lifetimeKills++; if (sourceWeapon != WeaponType::COUNT) ++weaponKills[static_cast<int>(sourceWeapon)]; check_badge_unlocks(); }
        } else if (ownerIndex >= 0 && ownerIndex < activeEnemyCount) {
            enemies[ownerIndex].kills++;
        }
    };

    if (pHp > 0 && !playerShieldActive && !playerIsInvulnerable) {
        int hpBefore = pHp;
        apply_splash(player, pHp);
        if (pHp < hpBefore && defuseHeld) { defuseHeld = false; defuseStartTime = 0; }
        if (hpBefore > 0 && pHp <= 0) {
            playerDeaths++;
            credit_kill();
        }
    }
    for (auto& enemy : enemies) {
        if (enemy.active && enemy.hp > 0) {
            apply_splash(enemy.rect, enemy.hp);
            if (enemy.hp <= 0) {
                enemy.active = false;
                enemy.deaths = 1;
                score += 10;
                highScore = std::max(highScore, score);
                if (ownerIsPlayerTeam) credit_kill(); // only player-team splash scores a Raider kill
            }
        }
    }
    for (int bi = 0; bi < activeBotCount; ++bi) {
        Bot& bot = bots[bi];
        if (!ownerIsPlayerTeam && bot.active && bot.hp > 0) { // only a Raider's blast can splash a friendly bot
            apply_splash(bot.rect, bot.hp);
            if (bot.hp <= 0) {
                bot.active = false;
                bot.deaths++;
                credit_kill();
            }
        }
    }
    play_explosion_sound();
}

void fire_laser(float startX, float startY, float dirX, float dirY, bool isPlayer, const SDL_Rect* playerHitbox = nullptr, EnemyType shooterType = EnemyType::RED, int ownerBotIndex = -1) {
    // Laser is hitscan and supports all 8 aiming directions.
    // Normalize the direction so diagonal lasers travel at the same effective speed.
    float len = std::sqrt(dirX * dirX + dirY * dirY);
    if (len < 0.0001f) return;
    if (isPlayer) {
        lastPlayerFireAt = SDL_GetTicks();
        lastPlayerAimX = dirX / len;
        lastPlayerAimY = dirY / len;
    }
    dirX /= len;
    dirY /= len;
    const float stepX = dirX * 12.0f;
    const float stepY = dirY * 12.0f;

    SDL_Rect beamCheck = { static_cast<int>(startX), static_cast<int>(startY), 4, 4 };
    std::vector<Enemy*> hitEnemies; // dedup so a wide enemy isn't hit multiple times as the beam steps through it

    while (beamCheck.x > 0 && beamCheck.x < currentMapCols * TILE_SIZE && beamCheck.y > 0 && beamCheck.y < currentMapRows * TILE_SIZE) {
        beamCheck.x += static_cast<int>(stepX);
        beamCheck.y += static_cast<int>(stepY);

        // Glass now blocks like a wall (see check_wall_collision), so the beam must
        // shatter it here first - same as bullets do - or every laser would stop dead
        // at the first pane instead of blasting through it.
        int glassCol = -1, glassRow = -1;
        if (rect_hits_glass(beamCheck, &glassCol, &glassRow)) {
            gameMap[glassRow][glassCol] = 0;
            for (auto& gs : glassShatters) {
                if (!gs.active) {
                    gs.x = glassCol * TILE_SIZE + TILE_SIZE / 2.0f;
                    gs.y = glassRow * TILE_SIZE + TILE_SIZE / 2.0f;
                    gs.spawnTime = SDL_GetTicks();
                    gs.duration = 420;
                    gs.active = true;
                    break;
                }
            }
            play_glass_shatter_sound();
        }

        if (check_wall_collision(beamCheck)) break;

        if (isPlayer) {
            // Pierces through every enemy in its path rather than stopping at the first one -
            // it's drawn as a continuous beam, so it should hit like one. Each enemy it
            // touches dies instantly - the laser one-shots everything in its line, not
            // just the first target.
            for (auto& enemy : enemies) {
                if (enemy.active && enemy.hp > 0 && SDL_HasIntersection(&beamCheck, &enemy.rect)) {
                    if (std::find(hitEnemies.begin(), hitEnemies.end(), &enemy) != hitEnemies.end()) continue;
                    hitEnemies.push_back(&enemy);

                    enemy.hp -= WEAPON_PROPS[static_cast<int>(WeaponType::LASER)].damage;
                    if (enemy.hp <= 0) {
                        enemy.active = false;
                        enemy.deaths = 1;
                        score += 10;
                        // Attribute the kill the same way bullet hits do: to the
                        // firing bot if this beam came from one, otherwise the player.
                        if (ownerBotIndex >= 0 && ownerBotIndex < activeBotCount) {
                            bots[ownerBotIndex].kills++;
                        } else {
                            playerKills++;
                            lifetimeKills++;
                            ++weaponKills[static_cast<int>(WeaponType::LASER)];
                            check_badge_unlocks();
                        }
                    }
                    highScore = std::max(highScore, score);
                }
            }
        } else if (playerHitbox && SDL_HasIntersection(&beamCheck, playerHitbox)) {
            if (!playerShieldActive && !playerIsInvulnerable) {
                playerHp -= WEAPON_PROPS[static_cast<int>(WeaponType::LASER)].damage;
                highScore = std::max(highScore, score);
                if (playerHp <= 0) {
                    if (selectedMode == GameMode::ENDLESS) playerDiedThisEndlessRun = true;
                    currentGameState = GameState::GAME_OVER;
                    playerDeaths++;
                    // This beam's shooter is the Raider at ownerBotIndex (repurposed
                    // as the enemy roster index for enemy-fired shots).
                    if (ownerBotIndex >= 0 && ownerBotIndex < activeEnemyCount) {
                        enemies[ownerBotIndex].kills++;
                    }
                }
                if (defuseHeld) { defuseHeld = false; defuseStartTime = 0; }
            }
            break; // there's only one player - beam stops once it lands
        }
    }

    for (auto& beam : laserBeams) {
        if (!beam.active) {
            beam.start = { static_cast<int>(startX), static_cast<int>(startY) };
            beam.end = { beamCheck.x, beamCheck.y };
            beam.spawnTime = SDL_GetTicks();
            beam.duration = 100;
            // Beam color identifies the shooter: player laser is green, RED enemy
            // laser is red, PINK enemy laser is pink.
            if (isPlayer) {
                beam.color = SDL_Color{60, 220, 120, 255};
            } else if (shooterType == EnemyType::PINK) {
                beam.color = SDL_Color{255, 105, 180, 255};
            } else {
                beam.color = SDL_Color{220, 60, 60, 255};
            }
            beam.isPlayerShot = isPlayer;
            beam.active = true;
            break;
        }
    }

    play_gunshot_sound(isPlayer, WeaponType::LASER, (!isPlayer || ownerBotIndex >= 0));
}

void spawn_cardinal_bullet(float startX, float startY, Direction dir, bool isPlayer, WeaponType wType, const SDL_Rect* playerHitbox = nullptr, EnemyType shooterType = EnemyType::RED, int ownerBotIndex = -1) {
    if (wType == WeaponType::LASER) {
        float dx = 0.0f, dy = 0.0f;
        if (dir == Direction::DIR_UP)    dy = -1.0f;
        if (dir == Direction::DIR_DOWN)  dy =  1.0f;
        if (dir == Direction::DIR_LEFT)  dx = -1.0f;
        if (dir == Direction::DIR_RIGHT) dx =  1.0f;
        fire_laser(startX, startY, dx, dy, isPlayer, playerHitbox, shooterType, ownerBotIndex);
        return;
    }

    const auto& props = WEAPON_PROPS[static_cast<int>(wType)];
    float speed = props.speed;
    int sz = (wType == WeaponType::ROCKET) ? 16 : ((wType == WeaponType::ICE_GUN) ? 26 : ((wType == WeaponType::FIRE_GUN || wType == WeaponType::WIND_GUN) ? 14 : 8));

    for (auto& b : bullets) {
        if (!b.active) {
            b.x = startX; b.y = startY;
            b.isPlayerBullet = isPlayer;
            b.ownerBotIndex = ownerBotIndex;
            b.dir = dir; b.type = wType; b.bounceCount = 0;

            switch (dir) {
                case Direction::DIR_UP:    b.vx = 0.0f; b.vy = -speed; b.rect.w = sz; b.rect.h = sz * 2; break;
                case Direction::DIR_DOWN:  b.vx = 0.0f; b.vy =  speed; b.rect.w = sz; b.rect.h = sz * 2; break;
                case Direction::DIR_LEFT:  b.vx = -speed; b.vy = 0.0f; b.rect.w = sz * 2; b.rect.h = sz; break;
                case Direction::DIR_RIGHT: b.vx =  speed; b.vy = 0.0f; b.rect.w = sz * 2; b.rect.h = sz; break;
            }

            b.rect.x = static_cast<int>(b.x) - b.rect.w / 2;
            b.rect.y = static_cast<int>(b.y) - b.rect.h / 2;
            b.active = true;
            break;
        }
    }
    play_gunshot_sound(isPlayer, wType, (!isPlayer || ownerBotIndex >= 0));
}

// Spawns a bullet along an arbitrary (possibly diagonal) normalized direction vector.
// Both axes are scaled by the same weapon speed scalar so diagonal shots travel at the
// exact same magnitude as cardinal shots (no ~41% diagonal speed-up from unnormalized dx,dy).
void spawn_vector_bullet(float startX, float startY, float dirX, float dirY, bool isPlayer, WeaponType wType, const SDL_Rect* playerHitbox = nullptr, EnemyType shooterType = EnemyType::RED, int ownerBotIndex = -1) {
    if (wType == WeaponType::COIN_MAGNET) return;
    if (wType == WeaponType::LASER) {
        // Laser follows the complete aim vector, including all four diagonals.
        fire_laser(startX, startY, dirX, dirY, isPlayer, playerHitbox, shooterType, ownerBotIndex);
        return;
    }

    float len = std::sqrt(dirX * dirX + dirY * dirY);
    if (len < 0.0001f) return;
    float nx = dirX / len, ny = dirY / len; // (x̂, ŷ) = (dx, dy) / sqrt(dx² + dy²)

    const auto& props = WEAPON_PROPS[static_cast<int>(wType)];
    float speed = props.speed;
    int sz = (wType == WeaponType::ROCKET) ? 16 : ((wType == WeaponType::ICE_GUN) ? 26 : ((wType == WeaponType::FIRE_GUN || wType == WeaponType::WIND_GUN) ? 14 : 8));

    bool isCardinal = (std::abs(nx) < 0.001f || std::abs(ny) < 0.001f);

    for (auto& b : bullets) {
        if (!b.active) {
            b.x = startX; b.y = startY;
            b.isPlayerBullet = isPlayer;
            b.ownerBotIndex = ownerBotIndex;
            b.type = wType;
            b.bounceCount = 0;
            b.vx = nx * speed;
            b.vy = ny * speed;
            b.diagonal = !isCardinal;

            if (isCardinal) {
                b.dir = (std::abs(nx) > std::abs(ny)) ? ((nx > 0) ? Direction::DIR_RIGHT : Direction::DIR_LEFT)
                                                       : ((ny > 0) ? Direction::DIR_DOWN : Direction::DIR_UP);
                if (b.dir == Direction::DIR_UP || b.dir == Direction::DIR_DOWN) { b.rect.w = sz; b.rect.h = sz * 2; }
                else                                                            { b.rect.w = sz * 2; b.rect.h = sz; }
            } else {
                // Diagonal bolt: square footprint so it reads correctly moving at 45 degrees.
                b.rect.w = static_cast<int>(sz * 1.5f);
                b.rect.h = static_cast<int>(sz * 1.5f);
            }

            b.rect.x = static_cast<int>(b.x) - b.rect.w / 2;
            b.rect.y = static_cast<int>(b.y) - b.rect.h / 2;
            b.active = true;
            break;
        }
    }
    play_gunshot_sound(isPlayer, wType, (!isPlayer || ownerBotIndex >= 0));
}

static float tactical_difficulty_multiplier() {
    if (selectedMode != GameMode::TACTICAL) return 1.0f;
    switch (tacticalEnemyDifficulty) {
        case EnemyDifficulty::EASY:   return 0.90f;
        case EnemyDifficulty::HARD:   return 1.0f;
        case EnemyDifficulty::EXPERT: return 1.0f;
        default: return 1.0f;
    }
}

static float tactical_enemy_speed(bool alert) {
    if (selectedMode != GameMode::TACTICAL) return alert ? AI_SPEED_ALERT : AI_SPEED_NORMAL;
    if (tacticalEnemyDifficulty == EnemyDifficulty::EASY)
        return alert ? AI_SPEED_EASY_ALERT : AI_SPEED_EASY;
    if (tacticalEnemyDifficulty == EnemyDifficulty::NORMAL)
        return alert ? AI_SPEED_ALERT : AI_SPEED_NORMAL;
    float base = (tacticalEnemyDifficulty == EnemyDifficulty::EXPERT) ? AI_SPEED_EXPERT : AI_SPEED_HARD;
    return alert ? base + 1.5f : base;
}

static Uint32 tactical_enemy_shoot_multiplier(bool alert) {
    if (selectedMode != GameMode::TACTICAL) return alert ? 1U : 2U;
    if (tacticalEnemyDifficulty == EnemyDifficulty::EASY) return alert ? 3U : 4U;
    if (tacticalEnemyDifficulty == EnemyDifficulty::EXPERT) return alert ? 1U : 1U;
    if (tacticalEnemyDifficulty == EnemyDifficulty::HARD) return alert ? 1U : 1U;
    return alert ? 2U : 3U;
}

static float tactical_enemy_damage_multiplier() {
    if (selectedMode != GameMode::TACTICAL) return 1.0f;
    if (tacticalEnemyDifficulty == EnemyDifficulty::EASY) return 0.90f;
    if (tacticalEnemyDifficulty == EnemyDifficulty::EXPERT) return 1.20f;
    if (tacticalEnemyDifficulty == EnemyDifficulty::HARD) return 1.10f;
    return 1.0f;
}

// --- Bot (ally Sentinel) stat tiers ------------------------------------
// Bots inherit whichever tier the player picked for enemy difficulty in
// TACTICAL_CONFIG - Easy/Normal/Hard/Expert bots mirror the selected tier
// for damage/fire-rate, but movement speed is intentionally NOT tiered:
// allied bots always move at exactly WALK_SPEED (the player's own speed)
// regardless of difficulty, so they never feel slower or faster than the
// player in any mode. Hostile enemies (tactical_enemy_speed(), a separate
// function) still use the tiered AI_SPEED_* constants and are unaffected
// by this - only the player's own squad is pinned to WALK_SPEED here.
static float bot_speed(EnemyDifficulty /*tier*/) {
    return WALK_SPEED;
}
static Uint32 bot_shoot_multiplier(EnemyDifficulty tier) {
    switch (tier) {
        case EnemyDifficulty::EASY:   return 4U;
        case EnemyDifficulty::EXPERT: return 1U;
        case EnemyDifficulty::HARD:   return 1U;
        default:                      return 2U;
    }
}
static float bot_damage_multiplier(EnemyDifficulty tier) {
    switch (tier) {
        case EnemyDifficulty::EASY:   return 0.90f;
        case EnemyDifficulty::EXPERT: return 1.20f;
        case EnemyDifficulty::HARD:   return 1.10f;
        default:                      return 1.0f;
    }
}

void spawn_single_enemy(Enemy& enemy, int index) {
    std::array<Point, 8> spawnPoints = {
        Point{92, 3}, Point{92, 54}, Point{3, 54}, Point{50, 3},
        Point{25, 28}, Point{75, 18}, Point{18, 45}, Point{78, 45}
    };
    Point sp = spawnPoints[index % spawnPoints.size()];
    
    enemy.x = sp.x * TILE_SIZE + 5;
    enemy.y = sp.y * TILE_SIZE + 5;
    enemy.rect.x = static_cast<int>(enemy.x);
    enemy.rect.y = static_cast<int>(enemy.y);
    enemy.maxHp = static_cast<int>((60 + (currentLevel * 5)) * tactical_difficulty_multiplier());
    enemy.hp = enemy.maxHp;
    enemy.team = Team::RED_BOMBER;

    int wChoice = index % 5;
    if (wChoice == 0)      enemy.weaponType = WeaponType::PISTOL;
    else if (wChoice == 1) enemy.weaponType = WeaponType::RIFLE;
    else if (wChoice == 2) enemy.weaponType = WeaponType::ROCKET;
    else if (wChoice == 3) enemy.weaponType = WeaponType::LASER;
    else                   enemy.weaponType = WeaponType::VECTOR_REFLECT;

    // Every third spawn is a Pink Enemy variant - can shoot cardinal OR diagonal.
    enemy.enemyType = (index % 3 == 2) ? EnemyType::PINK : EnemyType::RED;

    enemy.name = RAIDER_NAME_POOL[index % RAIDER_NAME_POOL.size()];
    enemy.kills = 0;
    enemy.deaths = 0;
    enemy.lastShootTime = SDL_GetTicks();
    enemy.lastPathCalc = 0;
    enemy.lastGlassBreakTime = 0;

    enemy.active = true;
}

// Places an enemy at a specific world tile (used for enemy markers painted in the map editor).
void spawn_enemy_at_tile(Enemy& enemy, int index, int tileCol, int tileRow, EnemyType type) {
    enemy.x = tileCol * TILE_SIZE + 5;
    enemy.y = tileRow * TILE_SIZE + 5;
    enemy.rect.x = static_cast<int>(enemy.x);
    enemy.rect.y = static_cast<int>(enemy.y);
    enemy.maxHp = static_cast<int>((60 + (currentLevel * 5)) * tactical_difficulty_multiplier());
    enemy.hp = enemy.maxHp;
    enemy.team = Team::RED_BOMBER;
    enemy.enemyType = type;

    int wChoice = index % 5;
    if (wChoice == 0)      enemy.weaponType = WeaponType::PISTOL;
    else if (wChoice == 1) enemy.weaponType = WeaponType::RIFLE;
    else if (wChoice == 2) enemy.weaponType = WeaponType::ROCKET;
    else if (wChoice == 3) enemy.weaponType = WeaponType::LASER;
    else                   enemy.weaponType = WeaponType::VECTOR_REFLECT;

    enemy.name = RAIDER_NAME_POOL[index % RAIDER_NAME_POOL.size()];
    enemy.kills = 0;
    enemy.deaths = 0;
    enemy.lastShootTime = SDL_GetTicks();
    enemy.lastPathCalc = 0;
    enemy.lastGlassBreakTime = 0;

    enemy.active = true;
}

// Ally bot spawn - places a Sentinel-team bot near the player's spawn area,
// gives it a random callsign from the pool (no repeats within a match), and
// a weapon/tier matching the selected tactical difficulty.
void spawn_bots(int count, EnemyDifficulty tier, Point playerSpawnTile, bool keepRoster = false) {
    // Snapshot the outgoing roster before it gets wiped below - when keepRoster
    // is set (advancing to the next round of the same 10-round mission instead
    // of starting a brand new one) each slot's name/kills/deaths carry over
    // instead of being reshuffled/reset.
    std::array<Bot, MAX_BOTS> priorBots = bots;

    std::vector<int> nameOrder(BOT_NAME_POOL.size());
    for (size_t i = 0; i < nameOrder.size(); ++i) nameOrder[i] = static_cast<int>(i);
    for (size_t i = nameOrder.size(); i > 1; --i)
        std::swap(nameOrder[i - 1], nameOrder[static_cast<size_t>(std::rand()) % i]);

    // Spread bots in a ring around the player's spawn so they don't all stack
    // on one tile and instantly collide with each other.
    for (auto& bot : bots) bot = Bot{};
    activeBotCount = std::clamp(count, 0, MAX_BOTS);
    for (int i = 0; i < activeBotCount; ++i) {
        Bot& bot = bots[i];
        float angle = (2.0f * static_cast<float>(M_PI) * i) / std::max(1, activeBotCount);
        int ring = 2 + (i / 8); // wider rings once more than 8 bots need spreading
        Point spawnTile = nearest_free_tile({
            playerSpawnTile.x + static_cast<int>(std::cos(angle) * ring),
            playerSpawnTile.y + static_cast<int>(std::sin(angle) * ring)
        });
        bot.x = spawnTile.x * TILE_SIZE + 5;
        bot.y = spawnTile.y * TILE_SIZE + 5;
        bot.rect.x = static_cast<int>(bot.x);
        bot.rect.y = static_cast<int>(bot.y);
        bot.tier = tier;
        bot.maxHp = static_cast<int>(70 * bot_damage_multiplier(tier)); // sturdier tier fights harder, so give it a bit more HP too
        bot.hp = bot.maxHp;

        bool reuse = keepRoster && !priorBots[i].name.empty();
        bot.name = reuse ? priorBots[i].name : BOT_NAME_POOL[nameOrder[i % nameOrder.size()]];

        // Keep voice identity attached to the squad slot/roster across rounds.
        // New bots receive a deterministic profile; returning bots keep theirs.
        if (reuse && priorBots[i].voicePitch >= 0.85f && priorBots[i].voicePitch <= 1.15f) {
            bot.voicePitch = priorBots[i].voicePitch;
        } else {
            static constexpr float kVoiceProfiles[] = { 0.92f, 0.97f, 1.00f, 1.05f, 1.10f };
            constexpr int kVoiceProfileCount = static_cast<int>(sizeof(kVoiceProfiles) / sizeof(kVoiceProfiles[0]));
            bot.voicePitch = kVoiceProfiles[i % kVoiceProfileCount];
        }

        int wChoice = i % 4; // bots skip VECTOR_REFLECT - reflect bounces are unpredictable for AI aim
        WeaponType freshWeapon = (wChoice == 0) ? WeaponType::PISTOL
                                : (wChoice == 1) ? WeaponType::RIFLE
                                : (wChoice == 2) ? WeaponType::ROCKET
                                                  : WeaponType::LASER;
        bot.weaponType = reuse ? priorBots[i].weaponType : freshWeapon;
        bot.kills = reuse ? priorBots[i].kills : 0;
        bot.deaths = reuse ? priorBots[i].deaths : 0;
        bot.bombDefuses = reuse ? priorBots[i].bombDefuses : 0;
        bot.defusingBomb = false;
        bot.defuseStartTime = 0;

        // lastShootTime defaults to 0 (Bot{} above), but currentTime is
        // SDL_GetTicks() since app start, not since spawn - so "currentTime -
        // lastShootTime" was always huge on a fresh bot, satisfying the fire
        // cooldown check instantly and letting bots open fire the moment they
        // got a target, with no initial cooldown. Stamp it with the real spawn
        // time instead, same as Enemy::lastShootTime already does at spawn.
        bot.lastShootTime = SDL_GetTicks();

        // Golden-angle spread (~137.5 deg apart) so every bot claims a different
        // stand-off point around whatever it's engaging, plus a randomized pace
        // so squadmates visibly move independently instead of in lockstep.
        bot.flankAngle = std::fmod(i * 2.399963f, 2.0f * static_cast<float>(M_PI));
        bot.speedJitter = 0.85f + 0.3f * (static_cast<float>(std::rand()) / static_cast<float>(RAND_MAX));

        bot.active = true;
    }
}

// Signature was missing entirely in the original source (a bare `return`
// floated here with no enclosing function) - restored based on its call
// site usage: usable(c, r) below calls it with a tile column/row and
// expects a walkable/free-tile bool back.
bool health_pack_tile_is_free(int col, int row) {
    return col > 0 && col < currentMapCols - 1 && row > 0 && row < currentMapRows - 1 && (gameMap[row][col] == 0 || gameMap[row][col] == 8 || gameMap[row][col] == 9);
}

Point find_health_pack_tile(Point preferred, const std::vector<Point>& alreadyUsed) {
    auto usable = [&](int c, int r) {
        if (!health_pack_tile_is_free(c, r)) return false;
        for (const Point& used : alreadyUsed) {
            if (used.x == c && used.y == r) return false;
        }
        return true;
    };

    if (usable(preferred.x, preferred.y)) return preferred;

    const int maxRadius = std::max(currentMapCols, currentMapRows);
    for (int radius = 1; radius < maxRadius; ++radius) {
        for (int dy = -radius; dy <= radius; ++dy) {
            for (int dx = -radius; dx <= radius; ++dx) {
                if (std::max(std::abs(dx), std::abs(dy)) != radius) continue;
                const int c = preferred.x + dx;
                const int r = preferred.y + dy;
                if (usable(c, r)) return Point{c, r};
            }
        }
    }
    return Point{-1, -1};
}

void generate_ai_map() {
    // Custom dimensions are opt-in via the tick in the size dialog. Off (the
    // default) always uses the full 100x60 world, matching prior behavior.
    int cols = aiMapCustomDimensions ? std::clamp(aiMapCols, 30, COLS) : COLS;
    int rows = aiMapCustomDimensions ? std::clamp(aiMapRows, 20, ROWS) : ROWS;
    currentMapCols = editorMapCols = cols;
    currentMapRows = editorMapRows = rows;
    for (int r = 0; r < ROWS; ++r)
        for (int c = 0; c < COLS; ++c)
            gameMap[r][c] = 0;

    for (int c = 0; c < currentMapCols; ++c) {
        gameMap[0][c] = 1;
        gameMap[currentMapRows - 1][c] = 1;
    }
    for (int r = 0; r < currentMapRows; ++r) {
        gameMap[r][0] = 1;
        gameMap[r][currentMapCols - 1] = 1;
    }

    // Procedural AI map: varied cover with open routes between the two sites.
    // Spawn area/lengths scale with map size instead of assuming the fixed
    // 100x60 world, so smaller/larger custom dimensions still generate
    // sensible, in-bounds cover.
    for (int i = 0; i < 20; ++i) {
        int x = 6 + std::rand() % std::max(1, currentMapCols - 12);
        int y = 4 + std::rand() % std::max(1, currentMapRows - 8);
        bool horizontal = (std::rand() % 2) == 0;
        int len = 4 + std::rand() % 9;
        for (int j = 0; j < len; ++j) {
            int c = horizontal ? x + j : x;
            int r = horizontal ? y : y + j;
            if (c > 1 && c < currentMapCols - 2 && r > 1 && r < currentMapRows - 2)
                gameMap[r][c] = 1;
        }
    }

    // Guaranteed open player start area (clamped so it never exceeds a
    // small custom map's bounds).
    int startRowEnd = std::min(8, currentMapRows - 3);
    int startColEnd = std::min(10, currentMapCols - 3);
    for (int r = 2; r <= startRowEnd; ++r)
        for (int c = 2; c <= startColEnd; ++c)
            gameMap[r][c] = 0;

    // Bomb sites scaled to the same relative position they held on the
    // original 100x60 layout (78% across, 20%/77% down), then clamped so
    // the site and its clearing radius always stay in-bounds.
    bombSiteA = { std::clamp(currentMapCols * 78 / 100, 4, currentMapCols - 5),
                  std::clamp(currentMapRows * 12 / 60,  4, currentMapRows - 5) };
    bombSiteB = { std::clamp(currentMapCols * 78 / 100, 4, currentMapCols - 5),
                  std::clamp(currentMapRows * 46 / 60,  4, currentMapRows - 5) };
    for (Point site : {bombSiteA, bombSiteB}) {
        for (int r = site.y - 2; r <= site.y + 2; ++r)
            for (int c = site.x - 2; c <= site.x + 2; ++c)
                if (r > 0 && r < currentMapRows - 1 && c > 0 && c < currentMapCols - 1)
                    gameMap[r][c] = 0;
    }
    gameMap[bombSiteA.y][bombSiteA.x] = 8;
    gameMap[bombSiteB.y][bombSiteB.x] = 9;
    bombSiteAValid = bombSiteBValid = true;

    // Open a central lane so either site is reachable, spanning the full
    // width (minus a 2-tile margin) at the map's vertical midpoint. Skips
    // over either bomb site's marker column on the rare custom-dimension
    // combo where the lane row lands exactly on a site's row.
    int laneRow = currentMapRows / 2;
    for (int c = 2; c < currentMapCols - 2; ++c) {
        if ((laneRow == bombSiteA.y && c == bombSiteA.x) ||
            (laneRow == bombSiteB.y && c == bombSiteB.x)) continue;
        gameMap[laneRow][c] = 0;
    }
}

// Converts the completed run's score into persistent coins exactly once.
// Map pickups remain the primary coin source; this is only a balanced bonus
// granted when the final run ends, then manually claimed by the player.
void award_completed_run_coins(Uint32 now) {
    // Called when a FINAL run ends. The reward is earned here but remains
    // pending until the player manually taps the reward button.
    // Persisting the pending state prevents the reward from disappearing if
    // the app is closed before the player claims it.
    (void)now;
    if (completedRunRewardIssued) return;
    completedRunRewardIssued = true;

    // Performance rewards: every score point earns one coin.
    const int scoreCoins = std::max(0, score);
    const bool newHigh = score > runStartHighScore;
    // A new personal best is a major achievement.
    const int highBonus = newHigh ? 500 : 0;
    const int total = scoreCoins + highBonus;
    if (total <= 0) return;

    // Start a completely fresh reward state for this run.
    coinRewardScoreCoins = scoreCoins;
    coinRewardHighScoreBonus = highBonus;
    lastRunCoinReward = total;
    coinRewardPending = true;
    coinRewardAnimationActive = false;
    coinRewardAnimationOnMenuEntry = false;
    coinRewardAnimationStartedAt = 0;
    coinRewardDisplayCoins = 0;
    coinRewardDisplayScore = 0;

    // Do NOT add coins yet. The player explicitly claims the earned reward
    // with a tap. Save the pending reward immediately so it survives restart.
    progressSavePending = true;
    save_progress();
}

void activate_coin_reward_animation(Uint32 now, bool fromHighScoreButton = false) {
    // If a completed-run reward is already pending, keep the original manual
    // claim behaviour: either profile button claims that one pending reward.
    if (coinRewardPending) {
        if (coinRewardAnimationActive) return;
        const int total = coinRewardScoreCoins + coinRewardHighScoreBonus;
        if (total <= 0) {
            coinRewardPending = false;
            lastRunCoinReward = 0;
            progressSavePending = true;
            save_progress();
            return;
        }
        coinBalance += total;
        coinRewardPending = false;
        coinRewardAnimationOnMenuEntry = false;
        coinRewardAnimationStartedAt = now;
        coinRewardAnimationActive = true;
        coinRewardDisplayCoins = 0;
        coinRewardDisplayScore = 0;
        lastClaimedScoreRewardCoins = std::max(lastClaimedScoreRewardCoins,
                                               coinRewardScoreCoins);
        if (coinRewardHighScoreBonus > 0)
            lastClaimedHighScoreRewardValue = std::max(lastClaimedHighScoreRewardValue, highScore);
        progressSavePending = true;
        save_progress();
        return;
    }

    if (coinRewardAnimationActive) return;

    // Manual SCORE button: pays out every available +1 score milestone in a
    // single tap. Example: score 60 gives 60 claimable milestones, so one
    // tap on SCORE collects all 60 coins.
    int scoreCoinsAvailable = std::max(0, score) - lastClaimedScoreRewardCoins;
    // Manual HIGH SCORE button: award the 500-coin personal-best bonus once for
    // each higher high-score value.
    int highBonusAvailable = (!fromHighScoreButton) ? 0 :
        ((highScore > lastClaimedHighScoreRewardValue && highScore > 0) ? 500 : 0);

    if (!fromHighScoreButton) {
        if (scoreCoinsAvailable <= 0) return;
    } else {
        if (highBonusAvailable <= 0) return;
    }

    // SCORE pays out every available coin in one tap. HIGH SCORE remains a
    // separate one-time +100 bonus for each new personal-best value.
    coinRewardScoreCoins = !fromHighScoreButton ? scoreCoinsAvailable : 0;
    coinRewardHighScoreBonus = fromHighScoreButton ? highBonusAvailable : 0;
    lastRunCoinReward = coinRewardScoreCoins + coinRewardHighScoreBonus;

    if (coinRewardScoreCoins <= 0 && coinRewardHighScoreBonus <= 0) return;

    coinBalance += lastRunCoinReward;
    if (coinRewardScoreCoins > 0) {
        // Consume every available +1 score milestone on this tap.
        lastClaimedScoreRewardCoins += coinRewardScoreCoins;
    }
    if (coinRewardHighScoreBonus > 0) {
        lastClaimedHighScoreRewardValue = highScore;
    }

    coinRewardAnimationOnMenuEntry = false;
    coinRewardAnimationStartedAt = now;
    coinRewardAnimationActive = true;
    coinRewardDisplayCoins = 0;
    coinRewardDisplayScore = 0;
    progressSavePending = true;
    save_progress();
}

void init_game_arena(bool keepRoster = false)
{
    highScore = std::max(highScore, score);
    if (!keepRoster) runStartHighScore = highScore;
    if (!keepRoster) {
        // Brand new mission: full reset, including round count and the bot roster.
        completedRunRewardIssued = false;
        coinRewardPending = false;
        coinRewardAnimationActive = false;
        coinRewardAnimationOnMenuEntry = false;
        coinRewardAnimationStartedAt = 0;
        coinRewardDisplayCoins = 0;
        coinRewardDisplayScore = 0;
        score = 0;
        // Score-based coin reward tracking is per-run: without this reset,
        // a reward claimed in a previous run (e.g. 170 coins) permanently
        // blocks the same score milestone from ever paying out again.
        lastClaimedScoreRewardCoins = 0;
        playerKills = 0;
        playerDeaths = 0;
        playerBombDefuses = 0;
        currentRound = 1;
    }
    currentLevel = 1;
    playerShieldActive = false;
    playerShieldReadyAt = 0;
    activeEnemyCount = (selectedMode == GameMode::ENDLESS) ? 4 : std::min(customTacticalEnemies, MAX_ENEMIES);
    playerHp = playerMaxHp;
    showLeaderboardPanel = false;
    showMatchEndLeaderboard = false;
    showMissionAccomplishedScreen = false;
    missionAccomplishedAt = 0;

    tacticalBomb.planted = false;
    tacticalBomb.defused = false;
    botDefuserIndex = -1;
    tacticalBomb.x = 0; tacticalBomb.y = 0; tacticalBomb.rect = {0,0,35,35};
    defuseHeld = false;
    defuseStartTime = 0;
    lastFuseBeepTime = 0;
    lastTacticalAISoundAt = 0;

    bool customMapLoaded = false;
    if (useCustomMap) customMapLoaded = load_map_from_file(mapFilePath);

    if (!customMapLoaded && !aiGeneratedMapActive) {
        for (int r = 0; r < ROWS; ++r) {
            for (int c = 0; c < COLS; ++c) {
                if (r == 0 || r == ROWS - 1 || c == 0 || c == COLS - 1) gameMap[r][c] = 1;
                else gameMap[r][c] = 0;
            }
        }
        // A few starter structures spread across the large world.
        for (int r = 5; r <= 15; ++r) { gameMap[r][12] = 1; gameMap[r][35] = 1; gameMap[r][70] = 1; }
        for (int r = 35; r <= 48; ++r) { gameMap[r][20] = 1; gameMap[r][55] = 1; gameMap[r][82] = 1; }
        for (int c = 20; c <= 40; ++c) { gameMap[20][c] = 1; gameMap[42][c] = 1; }
        for (int c = 62; c <= 90; ++c) { gameMap[27][c] = 1; }
    }

    scan_bombsites();
    if (!bombSiteAValid) {
        bombSiteA = nearest_free_tile({std::max(8, currentMapCols - 22), std::max(6, currentMapRows / 4)});
        bombSiteAValid = true;
        gameMap[bombSiteA.y][bombSiteA.x] = 8;
    }
    if (!bombSiteBValid) {
        bombSiteB = nearest_free_tile({std::max(8, currentMapCols - 22), std::max(8, (currentMapRows * 3) / 4)});
        bombSiteBValid = true;
        gameMap[bombSiteB.y][bombSiteB.x] = 9;
    }
    // The carrier chooses one of the two sites for this round; both A and B are valid.
    if (bombSiteAValid && bombSiteBValid)
        selectedBombSite = (std::rand() % 2 == 0) ? bombSiteA : bombSiteB;
    else if (bombSiteAValid) selectedBombSite = bombSiteA;
    else selectedBombSite = bombSiteB;

    tacticalBomb.x = selectedBombSite.x * TILE_SIZE + 8;
    tacticalBomb.y = selectedBombSite.y * TILE_SIZE + 8;
    tacticalBomb.rect = {static_cast<int>(tacticalBomb.x), static_cast<int>(tacticalBomb.y), 35, 35};

    for (auto& b : bullets) b.active = false;
    for (auto& exp : explosions) exp.active = false;
    for (auto& fi : fireImpacts) fi.active = false;
    for (auto& gs : glassShatters) gs.active = false;
    for (auto& beam : laserBeams) beam.active = false;
    for (auto& enemy : enemies) enemy.active = false;

    // Enemy spawn tiles painted in the editor (6 = red spawn, 7 = pink spawn) take
    // priority over the default spawn-point list when a custom map supplies any.
    // Important: gameMap is the same array the editor reads/writes, so we only
    // read spawn markers here - never clear them back to floor. Clearing them
    // used to wipe out the player's placed spawns the moment they tested the
    // map, so reopening the editor (without reloading from disk) showed empty
    // spawn points even though nothing was actually lost from the saved file.
    std::vector<Point> customRedSpawns, customPinkSpawns;
    customPlayerSpawnValid = false;
    customPlayerSpawn = {-1, -1};
    if (customMapLoaded) {
        for (int r = 0; r < ROWS; ++r) {
            for (int c = 0; c < COLS; ++c) {
                if (gameMap[r][c] == 6) { customRedSpawns.push_back({c, r}); }
                else if (gameMap[r][c] == 7) { customPinkSpawns.push_back({c, r}); }
                else if (gameMap[r][c] == 11) {
                    // Only one player spawn is meaningful - first one found wins.
                    if (!customPlayerSpawnValid) { customPlayerSpawn = {c, r}; customPlayerSpawnValid = true; }
                }
            }
        }
    }

    if (!customRedSpawns.empty() || !customPinkSpawns.empty()) {
        std::vector<Point> allSpawns = customRedSpawns;
        allSpawns.insert(allSpawns.end(), customPinkSpawns.begin(), customPinkSpawns.end());
        activeEnemyCount = std::min(static_cast<int>(allSpawns.size()), MAX_ENEMIES);
        for (int i = 0; i < activeEnemyCount; ++i) {
            EnemyType t = (i < static_cast<int>(customRedSpawns.size())) ? EnemyType::RED : EnemyType::PINK;
            spawn_enemy_at_tile(enemies[i], i, allSpawns[i].x, allSpawns[i].y, t);
        }
    } else {
        for (int i = 0; i < activeEnemyCount; ++i) {
            spawn_single_enemy(enemies[i], i);
        }
    }

    // Ally Sentinel bots spawn in a ring around wherever the player will start.
    // ENDLESS mode has no difficulty selector, so bots default to NORMAL tier there.
    {
        Point playerSpawnTile = customPlayerSpawnValid ? customPlayerSpawn : Point{5, 5};
        EnemyDifficulty botTier = (selectedMode == GameMode::TACTICAL) ? tacticalEnemyDifficulty : EnemyDifficulty::NORMAL;
        spawn_bots(customBotCount, botTier, playerSpawnTile, keepRoster);
    }

    const std::array<Point, 8> preferredPackLocations = {
        Point{8, 8}, Point{92, 8}, Point{8, 52}, Point{92, 52},
        Point{30, 10}, Point{70, 10}, Point{30, 48}, Point{70, 48}
    };

    // Never place a health pack inside a colored editor block or wall.
    std::vector<Point> usedPackTiles;
    usedPackTiles.reserve(MAX_HEALTH_PACKS);
    for (int i = 0; i < MAX_HEALTH_PACKS; ++i) {
        Point packTile = find_health_pack_tile(preferredPackLocations[i], usedPackTiles);
        if (packTile.x < 0) {
            healthPacks[i].active = false;
            continue;
        }
        usedPackTiles.push_back(packTile);
        healthPacks[i].r = packTile.y;
        healthPacks[i].c = packTile.x;
        healthPacks[i].active = true;
        healthPacks[i].rect = { packTile.x * TILE_SIZE + 10, packTile.y * TILE_SIZE + 10, 30, 30 };
    }

    // Coins: spawn as many small groups as the map can fit. Keeping pickups
    // within a couple of tiles of a shared anchor makes them feel intentional
    // to collect instead of looking like sparse random noise. Endless mode
    // still does not spawn coins.
    for (auto& coin : coins) coin.active = false;
    if (selectedMode == GameMode::TACTICAL) {
        std::vector<Point> usedCoinTiles = usedPackTiles; // don't stack a coin on a health pack
        std::vector<Point> coinClusterAnchors;
        constexpr int COINS_PER_CLUSTER = 6;
        // Coins should never land on (or crowd right up against) a bomb site -
        // keeps the plant/defuse marker clear instead of a pickup sitting on it.
        auto near_bomb_site = [&](int c, int r) {
            auto within = [&](const Point& site, bool valid) {
                return valid && std::abs(c - site.x) <= 1 && std::abs(r - site.y) <= 1;
            };
            return within(bombSiteA, bombSiteAValid) || within(bombSiteB, bombSiteBValid);
        };
        coinClusterAnchors.reserve((MAX_COINS + COINS_PER_CLUSTER - 1) / COINS_PER_CLUSTER);
        for (int i = 0; i < MAX_COINS; ++i) {
            Point coinTile{-1, -1};
            if (i % COINS_PER_CLUSTER == 0 || coinClusterAnchors.empty()) {
                // Pick a fresh walkable anchor for every group.
                for (int attempt = 0; attempt < 80; ++attempt) {
                    int c = 2 + std::rand() % std::max(1, currentMapCols - 4);
                    int r = 2 + std::rand() % std::max(1, currentMapRows - 4);
                    if (health_pack_tile_is_free(c, r) && !near_bomb_site(c, r)) {
                        coinClusterAnchors.push_back({c, r});
                        break;
                    }
                }
            }
            if (coinClusterAnchors.empty()) {
                coins[i].active = false;
                continue;
            }
            const Point anchor = coinClusterAnchors.back();
            for (int attempt = 0; attempt < 80; ++attempt) {
                int c = std::clamp(anchor.x + (std::rand() % 5) - 2, 1, currentMapCols - 2);
                int r = std::clamp(anchor.y + (std::rand() % 5) - 2, 1, currentMapRows - 2);
                bool clash = false;
                for (const Point& used : usedCoinTiles) {
                    if (used.x == c && used.y == r) { clash = true; break; }
                }
                if (!clash && health_pack_tile_is_free(c, r) && !near_bomb_site(c, r)) { coinTile = {c, r}; break; }
            }
            if (coinTile.x < 0) { coins[i].active = false; continue; }
            usedCoinTiles.push_back(coinTile);
            coins[i].r = coinTile.y;
            coins[i].c = coinTile.x;
            coins[i].active = true;
            coins[i].rect = { coinTile.x * TILE_SIZE + 17, coinTile.y * TILE_SIZE + 17, 16, 16 };
        }
    }
    
        // --- Add this to the end of init_game_arena() ---
    
    // Force unbreakable visual outer walls for the map array
    for (int r = 0; r < ROWS; ++r) {
        gameMap[r][0] = 1;               // Left wall
        gameMap[r][COLS - 1] = 1;        // Right wall
    }
    for (int c = 0; c < COLS; ++c) {
        gameMap[0][c] = 1;               // Top wall
        gameMap[ROWS - 1][c] = 1;        // Bottom wall
    }
} // End of init_game_arena()

// Counts enemies currently alive, used to scale the bomb fuse at plant time.
int count_active_enemies() {
    int n = 0;
    for (int i = 0; i < activeEnemyCount; ++i) {
        if (enemies[i].active && enemies[i].hp > 0) ++n;
    }
    return n;
}

// Bomb plant trigger: fuse length scales with how many enemies are still
// alive at the moment of planting - a bigger surviving squad buys the
// defenders (well, the bombers) more time.
//   timer = 15.0 + max(0, enemyCount - 3) * 3.5      (seconds)
void trigger_bomb_plant(Bomb& bomb, Uint32 currentTime, int planterIndex = -1) {
    int enemyCount = count_active_enemies();
    float fuseSeconds = 15.0f + static_cast<float>(std::max(0, enemyCount - 3)) * 3.5f;
    bomb.fuseDuration = static_cast<Uint32>(fuseSeconds * 1000.0f);
    bomb.planted = true;
    bomb.plantTime = currentTime;
    if (planterIndex >= 0 && planterIndex < activeEnemyCount) {
        enemies[planterIndex].bombPlants++;
    }
    botDefuserIndex = -1;
    for (int bi = 0; bi < activeBotCount; ++bi) {
        bots[bi].defusingBomb = false;
        bots[bi].defuseStartTime = 0;
    }
}


