// ============================================================
// STEP 17.39 - VEHICLES
// Drivable ground vehicles with enter/exit, acceleration, braking, steering,
// oriented collision, player collision, health, multiplayer authority and
// destruction effects. Vehicles intentionally have NO fuel system.
// ============================================================

enum class VehicleDamageState { PRISTINE, LIGHT, HEAVY, CRITICAL, DESTROYED };

struct VehicleEntity {
    bool active = false;
    bool occupied = false;
    VehicleType type = VehicleType::CAR;
    float x = 0.0f;
    float y = 0.0f;
    float vx = 0.0f;
    float vy = 0.0f;
    // Angle is measured from the vehicle's forward axis. angle == 0 points up.
    float angle = 0.0f;
    float health = 100.0f;
    float maxHealth = 100.0f;
    float maxSpeed = 520.0f;
    float reverseSpeed = 190.0f;
    float acceleration = 760.0f;
    float braking = 980.0f;
    float turnRate = 2.8f;
    float traction = 7.0f;
    float mass = 1.0f;
    float skidTimer = 0.0f;
    // Visual wheel rotation in radians; front wheels also steer with the vehicle.
    float wheelSpin = 0.0f;
    // Per-wheel visual/traction state. Order: FL, FR, RL, RR.
    std::array<float,4> wheelSpinIndividual{};
    std::array<float,4> wheelSteer{};
    std::array<float,4> wheelSlip{};
    std::array<bool,4> wheelLocked{};
    // Per-corner suspension response. Order: FL, FR, RL, RR.
    std::array<float,4> suspensionOffset{};
    std::array<float,4> suspensionVelocity{};
    std::array<float,4> wheelLoad{};
    // Individual tire durability: 100 = healthy, <= 0 = punctured/deflated.
    std::array<float,4> wheelHealth{{100.0f,100.0f,100.0f,100.0f}};
    std::array<bool,4> wheelDeflated{};
    std::array<float,4> wheelDamageFlash{};
    float yawRate = 0.0f;
    float brakeEffect = 0.0f; // 0..1, rises during hard braking
    float wheelWobble = 0.0f;  // visible body oscillation from a punctured tire
    float wheelPull = 0.0f;    // signed lateral pull; + = vehicle local right
    // Ambient vehicles are AI-driven when not occupied by a player.
    bool aiControlled = false;
    float aiTargetX = 0.0f;
    float aiTargetY = 0.0f;
    float aiRetargetTimer = 0.0f;
    float rimScrapeTimer = 0.0f;
    float rimScrapeIntensity = 0.0f;
    int driverId = -1;
    bool explosionPending = false;
    SDL_Rect rect{0,0,90,54};
};

// Forward declaration: defined later alongside VehicleRender, but needed
// earlier by VehicleUpdateTireEffects for damage-based smoke.
static VehicleDamageState VehicleGetDamageState(const VehicleEntity& v);

// Shared vehicle state used by the tire-effects subsystem.
static constexpr int MAX_VEHICLE_TRACKED = 8;
static constexpr int MAX_AMBIENT_VEHICLES = 8;
static std::array<VehicleEntity, MAX_AMBIENT_VEHICLES> g_vehicles{};
static std::array<std::array<SDL_FPoint,2>, MAX_VEHICLE_TRACKED> g_vehicleLastTirePoints{};
static std::array<bool, MAX_VEHICLE_TRACKED> g_vehicleLastTireValid{};
static bool g_vehicleEnterLatch = false;
static int g_activeVehicle = -1;
static Uint32 g_lastVehicleDamageAt[MAX_AMBIENT_VEHICLES]{};
static Uint32 g_lastVehicleImpactAt[MAX_AMBIENT_VEHICLES]{};


// ============================================================
// Vehicle tire effects: persistent skid marks + animated tire smoke.
// These are visual-only and are intentionally not network-synchronized.
// ============================================================
struct VehicleSkidMark {
    bool active = false;
    float x = 0.0f, y = 0.0f;
    float angle = 0.0f;
    float length = 0.0f;
    float width = 0.0f;
    float age = 0.0f;
    float life = 7.0f;
};

struct VehicleSparkParticle {
    bool active = false;
    float x = 0.0f, y = 0.0f;
    float vx = 0.0f, vy = 0.0f;
    float age = 0.0f;
    float life = 0.22f;
    float size = 1.5f;
    bool damagedRim = false;
};

struct VehicleSmokeParticle {
    bool active = false;
    float x = 0.0f, y = 0.0f;
    float vx = 0.0f, vy = 0.0f;
    float size = 4.0f;
    float age = 0.0f;
    float life = 0.55f;
    bool damageSmoke = false; // true = sooty engine smoke, false = tire smoke
};

// Continuous ground dust kicked up behind a moving vehicle, distinct from
// the drift/brake tire smoke above: lighter, sandier, spawns any time the
// vehicle is moving (not just sliding), matching the reference sheet's
// "DRIVING (DUST)" / "OFF-ROAD DUST" in-game examples.
struct VehicleDustParticle {
    bool active = false;
    float x = 0.0f, y = 0.0f;
    float vx = 0.0f, vy = 0.0f;
    float size = 3.0f;
    float age = 0.0f;
    float life = 0.6f;
};

static constexpr int MAX_VEHICLE_SKID_MARKS = 420;
static constexpr int MAX_VEHICLE_SMOKE_PARTICLES = 180;
static constexpr int MAX_VEHICLE_SPARK_PARTICLES = 120;
static constexpr int MAX_VEHICLE_DUST_PARTICLES = 220;
static std::array<VehicleSkidMark, MAX_VEHICLE_SKID_MARKS> g_vehicleSkidMarks{};
static std::array<VehicleSparkParticle, MAX_VEHICLE_SPARK_PARTICLES> g_vehicleSparkParticles{};
static std::array<VehicleSmokeParticle, MAX_VEHICLE_SMOKE_PARTICLES> g_vehicleSmokeParticles{};
static std::array<VehicleDustParticle, MAX_VEHICLE_DUST_PARTICLES> g_vehicleDustParticles{};
static int g_vehicleSkidWrite = 0;
static int g_vehicleSmokeWrite = 0;
static int g_vehicleSparkWrite = 0;
static int g_vehicleDustWrite = 0;
static std::array<float, MAX_AMBIENT_VEHICLES> g_vehicleDustAccumulator{};
static std::array<float, MAX_AMBIENT_VEHICLES> g_vehicleDamageSmokeAccumulator{};

static void VehicleClearTireEffects() {
    g_vehicleSkidMarks = {};
    g_vehicleSmokeParticles = {};
    g_vehicleSparkParticles = {};
    g_vehicleDustParticles = {};
    g_vehicleSkidWrite = 0;
    g_vehicleSmokeWrite = 0;
    g_vehicleSparkWrite = 0;
    g_vehicleDustWrite = 0;
    g_vehicleDustAccumulator = {};
    g_vehicleDamageSmokeAccumulator = {};
    g_vehicleLastTirePoints = {};
    g_vehicleLastTireValid = {};
}

static void VehicleSpawnSkidMark(float x, float y, float angle, float length, float width) {
    VehicleSkidMark& m = g_vehicleSkidMarks[g_vehicleSkidWrite++ % MAX_VEHICLE_SKID_MARKS];
    m.active = true;
    m.x = x; m.y = y; m.angle = angle;
    m.length = length; m.width = width;
    m.age = 0.0f; m.life = 6.0f + static_cast<float>(std::rand() % 180) / 100.0f;
}

static void VehicleSpawnTireSmoke(float x, float y, float speed, float intensity) {
    const int count = intensity > 1.35f ? 2 : 1;
    for (int n = 0; n < count; ++n) {
        VehicleSmokeParticle& p = g_vehicleSmokeParticles[g_vehicleSmokeWrite++ % MAX_VEHICLE_SMOKE_PARTICLES];
        const float a = static_cast<float>(std::rand() % 628) / 100.0f;
        const float spread = 8.0f + static_cast<float>(std::rand() % 12);
        p.active = true;
        p.x = x + std::cos(a) * spread * 0.18f;
        p.y = y + std::sin(a) * spread * 0.18f;
        p.vx = std::cos(a) * (10.0f + speed * 0.035f);
        p.vy = std::sin(a) * (10.0f + speed * 0.035f) - 12.0f;
        p.size = 3.0f + static_cast<float>(std::rand() % 30) / 10.0f;
        p.age = 0.0f;
        p.life = 0.38f + static_cast<float>(std::rand() % 35) / 100.0f;
    }
}


static void VehicleSpawnDamageSmoke(float x, float y, float intensity) {
    const int count = intensity > 1.5f ? 2 : 1;
    for (int n = 0; n < count; ++n) {
        VehicleSmokeParticle& p = g_vehicleSmokeParticles[g_vehicleSmokeWrite++ % MAX_VEHICLE_SMOKE_PARTICLES];
        const float a = static_cast<float>(std::rand() % 628) / 100.0f;
        const float spread = 3.0f + static_cast<float>(std::rand() % 6);
        p.active = true;
        p.damageSmoke = true;
        p.x = x + std::cos(a) * spread * 0.2f;
        p.y = y + std::sin(a) * spread * 0.2f;
        p.vx = std::cos(a) * 5.0f;
        p.vy = std::sin(a) * 5.0f - (16.0f + intensity * 8.0f); // rises steadily
        p.size = 3.5f + static_cast<float>(std::rand() % 30) / 10.0f + intensity * 2.0f;
        p.age = 0.0f;
        p.life = 0.9f + static_cast<float>(std::rand() % 40) / 100.0f;
    }
}

static void VehicleSpawnGroundDust(float x, float y, float dirX, float dirY, float speed, float intensity) {
    const int count = intensity > 1.4f ? 2 : 1;
    for (int n = 0; n < count; ++n) {
        VehicleDustParticle& p = g_vehicleDustParticles[g_vehicleDustWrite++ % MAX_VEHICLE_DUST_PARTICLES];
        const float jitter = static_cast<float>(std::rand() % 100 - 50) / 100.0f;
        const float spread = 4.0f + static_cast<float>(std::rand() % 8);
        p.active = true;
        p.x = x - dirX * spread * 0.4f + jitter * 6.0f;
        p.y = y - dirY * spread * 0.4f + jitter * 6.0f;
        // Puffs drift slightly backward (opposite of travel) and settle outward.
        p.vx = -dirX * (8.0f + speed * 0.05f) + jitter * 10.0f;
        p.vy = -dirY * (8.0f + speed * 0.05f) + jitter * 10.0f;
        p.size = 2.5f + static_cast<float>(std::rand() % 20) / 10.0f + intensity * 1.5f;
        p.age = 0.0f;
        p.life = 0.45f + static_cast<float>(std::rand() % 30) / 100.0f;
    }
}

static void VehicleSpawnDriftSparks(float x, float y, float speed, float intensity) {
    const int count = std::clamp(1 + static_cast<int>(intensity * 2.0f), 1, 5);
    for (int n = 0; n < count; ++n) {
        VehicleSparkParticle& p = g_vehicleSparkParticles[g_vehicleSparkWrite++ % MAX_VEHICLE_SPARK_PARTICLES];
        const float a = static_cast<float>(std::rand() % 628) / 100.0f;
        const float force = 35.0f + static_cast<float>(std::rand() % 70) + speed * 0.12f;
        p.active = true;
        p.x = x; p.y = y;
        p.vx = std::cos(a) * force;
        p.vy = std::sin(a) * force;
        p.age = 0.0f;
        p.life = 0.14f + static_cast<float>(std::rand() % 16) / 100.0f;
        p.size = 1.0f + static_cast<float>(std::rand() % 12) / 10.0f;
        p.damagedRim = false;
    }
}

static void VehicleSpawnDamagedRimSparks(float x, float y, float speed, float intensity) {
    const int count = std::clamp(1 + static_cast<int>(intensity * 2.5f), 1, 6);
    for (int n = 0; n < count; ++n) {
        VehicleSparkParticle& p = g_vehicleSparkParticles[g_vehicleSparkWrite++ % MAX_VEHICLE_SPARK_PARTICLES];
        const float a = static_cast<float>(std::rand() % 628) / 100.0f;
        const float force = 28.0f + static_cast<float>(std::rand() % 85) + speed * 0.16f;
        p.active = true;
        p.x = x; p.y = y;
        p.vx = std::cos(a) * force;
        p.vy = std::sin(a) * force - 18.0f;
        p.age = 0.0f;
        p.life = 0.10f + static_cast<float>(std::rand() % 18) / 100.0f;
        p.size = 1.0f + static_cast<float>(std::rand() % 14) / 10.0f;
        p.damagedRim = true;
    }
}

static void VehicleUpdateTireEffects(float dtSeconds) {
    dtSeconds = std::clamp(dtSeconds, 0.0f, 0.10f);

    for (auto& m : g_vehicleSkidMarks) {
        if (!m.active) continue;
        m.age += dtSeconds;
        if (m.age >= m.life) m.active = false;
    }
    for (auto& sp : g_vehicleSparkParticles) {
        if (!sp.active) continue;
        sp.age += dtSeconds;
        if (sp.age >= sp.life) { sp.active = false; continue; }
        sp.x += sp.vx * dtSeconds;
        sp.y += sp.vy * dtSeconds;
        sp.vx *= std::exp(-4.8f * dtSeconds);
        sp.vy *= std::exp(-4.8f * dtSeconds);
    }
    for (auto& p : g_vehicleSmokeParticles) {
        if (!p.active) continue;
        p.age += dtSeconds;
        if (p.age >= p.life) { p.active = false; continue; }
        p.x += p.vx * dtSeconds;
        p.y += p.vy * dtSeconds;
        p.vx *= std::exp(-2.2f * dtSeconds);
        p.vy *= std::exp(-2.2f * dtSeconds);
        p.size += 8.0f * dtSeconds;
    }
    for (auto& p : g_vehicleDustParticles) {
        if (!p.active) continue;
        p.age += dtSeconds;
        if (p.age >= p.life) { p.active = false; continue; }
        p.x += p.vx * dtSeconds;
        p.y += p.vy * dtSeconds;
        p.vx *= std::exp(-1.8f * dtSeconds);
        p.vy *= std::exp(-1.8f * dtSeconds);
        p.size += 5.5f * dtSeconds;
    }

    // Persistent engine damage smoke — independent of movement, so a
    // heavily damaged vehicle keeps smoking even when stopped.
    for (int vehicleIndex = 0; vehicleIndex < MAX_AMBIENT_VEHICLES; ++vehicleIndex) {
        auto& v = g_vehicles[vehicleIndex];
        if (!v.active || v.health <= 0.0f) continue;
        const VehicleDamageState ds = VehicleGetDamageState(v);
        if (ds < VehicleDamageState::HEAVY) continue;

        const float smokeRate = ds == VehicleDamageState::CRITICAL ? 0.10f : 0.22f;
        g_vehicleDamageSmokeAccumulator[vehicleIndex] += dtSeconds;
        if (g_vehicleDamageSmokeAccumulator[vehicleIndex] >= smokeRate) {
            g_vehicleDamageSmokeAccumulator[vehicleIndex] = 0.0f;
            const float c = std::cos(v.angle), s = std::sin(v.angle);
            const float cx = v.x + v.rect.w * 0.5f;
            const float cy = v.y + v.rect.h * 0.5f;
            const float hoodY = -v.rect.h * 0.30f; // engine bay, toward the front
            const float smokeX = cx + hoodY * -s;
            const float smokeY = cy + hoodY * c;
            const float intensity = ds == VehicleDamageState::CRITICAL ? 1.8f : 0.9f;
            VehicleSpawnDamageSmoke(smokeX, smokeY, intensity);
        }
    }

    for (int vehicleIndex = 0; vehicleIndex < MAX_AMBIENT_VEHICLES; ++vehicleIndex) {
        auto& v = g_vehicles[vehicleIndex];
        if (!v.active || v.health <= 0.0f) continue;
        const float speed = std::hypot(v.vx, v.vy);
        if (speed < 35.0f) { g_vehicleLastTireValid[vehicleIndex] = false; continue; }

        const float c = std::cos(v.angle), s = std::sin(v.angle);
        const float fx = s, fy = -c;
        const float cx = v.x + v.rect.w * 0.5f;
        const float cy = v.y + v.rect.h * 0.5f;

        // Continuous ground dust while simply driving (any direction/speed
        // above the threshold), separate from the drift/brake-only smoke
        // below. Throttled per-vehicle so it scales with speed but doesn't
        // flood the particle pool.
        {
            const float dustRate = std::clamp(0.16f - speed * 0.00016f, 0.035f, 0.16f);
            g_vehicleDustAccumulator[vehicleIndex] += dtSeconds;
            if (g_vehicleDustAccumulator[vehicleIndex] >= dustRate) {
                g_vehicleDustAccumulator[vehicleIndex] = 0.0f;
                const float rearYd = v.rect.h * 0.42f;
                const float dustX = cx - rearYd * s; // rear-center, opposite of facing
                const float dustY = cy + rearYd * c;
                const float dirX = s, dirY = -c; // forward-facing unit vector
                const float intensity = std::clamp(speed / 260.0f, 0.25f, 1.6f);
                VehicleSpawnGroundDust(dustX, dustY, dirX, dirY, speed, intensity);
            }
        }

        const float lateral = v.vx * (-c) + v.vy * (-s);
        const float longitudinal = v.vx * fx + v.vy * fy;
        const float slide = std::fabs(lateral);
        const float oppositeInput = (longitudinal > 0.0f && v.brakeEffect > 0.05f) ? 1.0f : 0.0f;
        const bool drifting = slide > 58.0f && speed > 95.0f;
        const bool hardBraking = v.brakeEffect > 0.35f && speed > 95.0f && std::fabs(longitudinal) > 55.0f;
        if (!drifting && !hardBraking) { g_vehicleLastTireValid[vehicleIndex] = false; continue; }

        const float rearY = v.rect.h * 0.30f;
        const float sideX = v.rect.w * 0.34f;
        const float distance = speed * dtSeconds;
        const float trackAngle = std::atan2(v.vy, v.vx);
        const float markWidth = std::max(3.0f, v.rect.w * 0.045f);

        for (int sideIndex = 0; sideIndex < 2; ++sideIndex) {
            const float side = sideIndex == 0 ? -1.0f : 1.0f;
            const float wx = cx + side * sideX * c - rearY * s;
            const float wy = cy + side * sideX * s + rearY * c;

            // Connect each new tire contact point to its previous point. This
            // produces naturally curved tracks while the vehicle rotates/drifts.
            if (g_vehicleLastTireValid[vehicleIndex]) {
                const SDL_FPoint prev = g_vehicleLastTirePoints[vehicleIndex][sideIndex];
                const float dx = wx - prev.x, dy = wy - prev.y;
                const float segLen = std::hypot(dx, dy);
                if (segLen > 0.8f) {
                    const float mx = (wx + prev.x) * 0.5f;
                    const float my = (wy + prev.y) * 0.5f;
                    VehicleSpawnSkidMark(mx, my, std::atan2(dy, dx),
                        std::clamp(segLen + 2.0f, 5.0f, 24.0f), markWidth * (hardBraking ? 1.15f : 1.0f));
                }
            } else {
                VehicleSpawnSkidMark(wx, wy, trackAngle, std::clamp(distance, 5.0f, 18.0f), markWidth);
            }
            g_vehicleLastTirePoints[vehicleIndex][sideIndex] = SDL_FPoint{wx, wy};

            const float smokeIntensity = hardBraking
                ? std::clamp(0.75f + v.brakeEffect * 1.8f, 0.75f, 2.8f)
                : std::clamp(slide / 100.0f, 0.55f, 2.2f);
            if ((drifting || hardBraking) && (std::rand() % (hardBraking ? 2 : 3) == 0))
                VehicleSpawnTireSmoke(wx, wy, speed, smokeIntensity);

            if (drifting && std::rand() % 2 == 0)
                VehicleSpawnDriftSparks(wx, wy, speed, std::clamp(slide / 100.0f, 0.5f, 2.0f));
        }

        // A punctured tire exposes the metal rim. At speed, the damaged rim
        // scrapes the road and throws short bursts of sparks; this is separate
        // from normal drift sparks so a damaged wheel remains visibly obvious
        // even when the vehicle is traveling straight.
        const float wheelHalfX = v.rect.w * 0.34f;
        const float wheelHalfY = v.rect.h * 0.30f;
        const float wheelLX[4] = {-wheelHalfX, wheelHalfX, -wheelHalfX, wheelHalfX};
        const float wheelLY[4] = {-wheelHalfY, -wheelHalfY, wheelHalfY, wheelHalfY};
        for (int wi = 0; wi < 4; ++wi) {
            if (!v.wheelDeflated[wi] || speed < 45.0f) continue;
            const float wx = cx + wheelLX[wi] * c - wheelLY[wi] * s;
            const float wy = cy + wheelLX[wi] * s + wheelLY[wi] * c;
            const float intensity = std::clamp(0.45f + speed / 240.0f + v.wheelSlip[wi] * 0.65f, 0.45f, 2.8f);
            if (std::rand() % 3 != 0)
                VehicleSpawnDamagedRimSparks(wx, wy, speed, intensity);
        }
        // Progressive rim-scrape audio. Only the locally controlled vehicle
        // should produce this sound; throttle it so the shared procedural audio
        // channel is not retriggered every frame.
        bool anyFlat = false;
        float scrapeIntensity = 0.0f;
        for(int wi=0;wi<4;++wi) if(v.wheelDeflated[wi]) {
            anyFlat = true;
            scrapeIntensity = std::max(scrapeIntensity, std::clamp(0.35f + speed/180.0f + v.wheelSlip[wi]*0.7f,0.35f,2.0f));
        }
        if(anyFlat && speed > 48.0f && v.occupied && g_activeVehicle == vehicleIndex){
            v.rimScrapeTimer -= dtSeconds;
            v.rimScrapeIntensity += (scrapeIntensity - v.rimScrapeIntensity) * std::clamp(dtSeconds*4.0f,0.0f,1.0f);
            if(v.rimScrapeTimer <= 0.0f){
                play_rim_scrape_sound(v.rimScrapeIntensity);
                v.rimScrapeTimer = std::clamp(0.22f - v.rimScrapeIntensity*0.045f,0.10f,0.22f);
            }
        } else {
            v.rimScrapeTimer = 0.0f;
            v.rimScrapeIntensity = std::max(0.0f, v.rimScrapeIntensity - dtSeconds*2.5f);
        }
        g_vehicleLastTireValid[vehicleIndex] = true;
        (void)oppositeInput;
    }

}

static void VehicleRenderTireEffects(SDL_Renderer* renderer, float cameraX, float cameraY) {
    if (!renderer) return;
    SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);

    // Skid marks fade from fresh dark rubber to a transparent grey-brown.
    for (const auto& m : g_vehicleSkidMarks) {
        if (!m.active) continue;
        const float fade = std::clamp(1.0f - m.age / std::max(0.01f, m.life), 0.0f, 1.0f);
        const float c = std::cos(m.angle), s = std::sin(m.angle);
        const float hx = std::cos(m.angle) * m.length * 0.5f;
        const float hy = std::sin(m.angle) * m.length * 0.5f;
        const int x1 = static_cast<int>(std::lround(m.x - hx - cameraX));
        const int y1 = static_cast<int>(std::lround(m.y - hy - cameraY));
        const int x2 = static_cast<int>(std::lround(m.x + hx - cameraX));
        const int y2 = static_cast<int>(std::lround(m.y + hy - cameraY));
        const Uint8 alpha = static_cast<Uint8>(std::clamp(95.0f * fade, 0.0f, 95.0f));
        SDL_SetRenderDrawColor(renderer, 30, 28, 25, alpha);
        SDL_RenderDrawLine(renderer, x1, y1, x2, y2);
        SDL_SetRenderDrawColor(renderer, 18, 18, 17, static_cast<Uint8>(alpha * 0.55f));
        const int ox = static_cast<int>(std::lround(-s * m.width));
        const int oy = static_cast<int>(std::lround(c * m.width));
        SDL_RenderDrawLine(renderer, x1 + ox, y1 + oy, x2 + ox, y2 + oy);
        (void)c;
    }

    // Sandy dust puffs from ordinary driving — lighter and more transparent
    // than the drift/brake tire smoke below.
    for (const auto& p : g_vehicleDustParticles) {
        if (!p.active) continue;
        const float t = std::clamp(p.age / std::max(0.01f, p.life), 0.0f, 1.0f);
        const float fade = 1.0f - t;
        const int r = std::max(2, static_cast<int>(std::lround(p.size)));
        const Uint8 alpha = static_cast<Uint8>(std::clamp(70.0f * fade, 0.0f, 70.0f));
        SDL_SetRenderDrawColor(renderer, 176, 154, 108, alpha);
        SDL_Rect rr{static_cast<int>(std::lround(p.x - cameraX)) - r,
                    static_cast<int>(std::lround(p.y - cameraY)) - r,
                    r * 2, r * 2};
        SDL_RenderFillRect(renderer, &rr);
    }

    // Small puffs rise and expand from sliding tires (grey) or a damaged
    // engine (darker, sootier — matches the reference sheet's HEAVY/CRITICAL
    // damage smoke plume).
    for (const auto& p : g_vehicleSmokeParticles) {
        if (!p.active) continue;
        const float t = std::clamp(p.age / std::max(0.01f, p.life), 0.0f, 1.0f);
        const float fade = 1.0f - t;
        const int r = std::max(2, static_cast<int>(std::lround(p.size)));
        const Uint8 alpha = static_cast<Uint8>(std::clamp((p.damageSmoke ? 150.0f : 105.0f) * fade, 0.0f, 150.0f));
        if (p.damageSmoke) {
            SDL_SetRenderDrawColor(renderer, 40, 38, 36, alpha);
        } else {
            SDL_SetRenderDrawColor(renderer, 108, 108, 104, alpha);
        }
        SDL_Rect rr{static_cast<int>(std::lround(p.x - cameraX)) - r,
                    static_cast<int>(std::lround(p.y - cameraY)) - r,
                    r * 2, r * 2};
        SDL_RenderFillRect(renderer, &rr);
        if (r > 4) {
            if (p.damageSmoke) {
                SDL_SetRenderDrawColor(renderer, 65, 62, 58, static_cast<Uint8>(alpha * 0.5f));
            } else {
                SDL_SetRenderDrawColor(renderer, 145, 145, 140, static_cast<Uint8>(alpha * 0.45f));
            }
            SDL_Rect inner{rr.x + r / 2, rr.y + r / 2, r, r};
            SDL_RenderFillRect(renderer, &inner);
        }
    }

    // Hot orange/yellow sparks appear only during lateral tire slip.
    for (const auto& sp : g_vehicleSparkParticles) {
        if (!sp.active) continue;
        const float t = std::clamp(sp.age / std::max(0.01f, sp.life), 0.0f, 1.0f);
        const Uint8 alpha = static_cast<Uint8>(std::clamp(235.0f * (1.0f - t), 0.0f, 235.0f));
        const int x = static_cast<int>(std::lround(sp.x - cameraX));
        const int y = static_cast<int>(std::lround(sp.y - cameraY));
        const int len = std::max(2, static_cast<int>(std::lround(sp.size * 2.5f)));
        if (sp.damagedRim) {
            // Damaged-rim sparks are hotter/whiter than normal tire-slip sparks.
            SDL_SetRenderDrawColor(renderer, 255, 225, 135, alpha);
            SDL_RenderDrawLine(renderer, x, y, x + static_cast<int>(std::lround(sp.vx * 0.045f * len)),
                               y + static_cast<int>(std::lround(sp.vy * 0.045f * len)));
            SDL_SetRenderDrawColor(renderer, 255, 250, 220, alpha);
            SDL_RenderDrawPoint(renderer, x, y);
        } else {
            SDL_SetRenderDrawColor(renderer, 255, 190, 70, alpha);
            SDL_RenderDrawLine(renderer, x, y, x + static_cast<int>(std::lround(sp.vx * 0.035f * len)),
                               y + static_cast<int>(std::lround(sp.vy * 0.035f * len)));
            SDL_SetRenderDrawColor(renderer, 255, 235, 155, alpha);
            SDL_RenderDrawPoint(renderer, x, y);
        }
    }
    SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_NONE);
}

static VehicleDamageState VehicleGetDamageState(const VehicleEntity& v) {
    if (!v.active || v.health <= 0.0f) return VehicleDamageState::DESTROYED;
    const float ratio = v.maxHealth > 0.0f ? v.health / v.maxHealth : 0.0f;
    if (ratio <= 0.25f) return VehicleDamageState::CRITICAL;
    if (ratio <= 0.50f) return VehicleDamageState::HEAVY;
    if (ratio <= 0.80f) return VehicleDamageState::LIGHT;
    return VehicleDamageState::PRISTINE;
}

static void VehicleRender(SDL_Renderer* renderer, const VehicleEntity& v, float cameraX, float cameraY) {
    if (!renderer || !v.active) return;

    // V16 PIXEL-ART VEHICLE RENDERER
    // The supplied concept sheet is treated as the visual specification:
    // chunky top-down silhouettes, stepped highlights, dark pixel outlines,
    // readable glass/wheels, type-specific body panels, lights and damage.
    const float speed = std::hypot(v.vx, v.vy);
    const float now = static_cast<float>(SDL_GetTicks()) * 0.001f;
    const float wobble = v.wheelWobble * std::sin(now * (7.0f + std::min(7.0f, speed * 0.02f))) * 0.014f;
    const float suspensionBodyBob = (v.suspensionOffset[0] + v.suspensionOffset[1] +
                                     v.suspensionOffset[2] + v.suspensionOffset[3]) * 0.028f;
    const float cx = v.x + v.rect.w * 0.5f - cameraX;
    const float cy = v.y + v.rect.h * 0.5f - cameraY + suspensionBodyBob;
    const float a = v.angle + wobble;
    const float c = std::cos(a), s = std::sin(a);

    auto P = [&](float x, float y) -> SDL_Point {
        return SDL_Point{static_cast<int>(std::lround(cx + x*c - y*s)),
                         static_cast<int>(std::lround(cy + x*s + y*c))};
    };
    auto poly = [&](std::initializer_list<std::pair<float,float>> pts, SDL_Color col, bool outline=false) {
        std::vector<SDL_Point> p; p.reserve(pts.size()+1);
        for (auto q:pts) p.push_back(P(q.first,q.second));
        if (p.size()<2) return;
        if (outline) {
            p.push_back(p.front());
            SDL_SetRenderDrawColor(renderer,col.r,col.g,col.b,col.a);
            SDL_RenderDrawLines(renderer,p.data(),static_cast<int>(p.size()));
            return;
        }
        int minY=p[0].y,maxY=p[0].y;
        for(auto q:p){minY=std::min(minY,q.y);maxY=std::max(maxY,q.y);}
        SDL_SetRenderDrawColor(renderer,col.r,col.g,col.b,col.a);
        for(int yy=minY;yy<=maxY;++yy){
            std::vector<int> xs;
            for(size_t i=0,j=p.size()-1;i<p.size();j=i++){
                const auto &a1=p[i],&a2=p[j];
                if((a1.y>yy)!=(a2.y>yy)){
                    const float den=float(a2.y-a1.y);
                    if(std::fabs(den)>0.001f) xs.push_back(int(std::lround(a1.x+(a2.x-a1.x)*float(yy-a1.y)/den)));
                }
            }
            std::sort(xs.begin(),xs.end());
            for(size_t i=0;i+1<xs.size();i+=2) SDL_RenderDrawLine(renderer,xs[i],yy,xs[i+1],yy);
        }
    };
    auto rect = [&](float x,float y,float w,float h,SDL_Color col) {
        poly({{x-w*.5f,y-h*.5f},{x+w*.5f,y-h*.5f},{x+w*.5f,y+h*.5f},{x-w*.5f,y+h*.5f}},col);
    };
    auto line = [&](float x1,float y1,float x2,float y2,SDL_Color col) {
        const SDL_Point a1=P(x1,y1),a2=P(x2,y2);
        SDL_SetRenderDrawColor(renderer,col.r,col.g,col.b,col.a); SDL_RenderDrawLine(renderer,a1.x,a1.y,a2.x,a2.y);
    };
    auto px = [&](float x,float y,int w,int h,SDL_Color col) { rect(x,y,float(w),float(h),col); };
    auto circle = [&](float x,float y,float r,SDL_Color col) {
        const SDL_Point q=P(x,y);
        SDL_SetRenderDrawColor(renderer,col.r,col.g,col.b,col.a);
        const int ir=std::max(1,int(std::lround(r)));
        for(int yy=-ir;yy<=ir;++yy){
            const int span=int(std::sqrt(std::max(0.0f,r*r-float(yy*yy))));
            SDL_RenderDrawLine(renderer,q.x-span,q.y+yy,q.x+span,q.y+yy);
        }
    };

    const float W=v.rect.w*0.94f, H=v.rect.h*0.94f;
    const VehicleDamageState ds=VehicleGetDamageState(v);
    const bool damaged=ds>=VehicleDamageState::HEAVY;
    const bool critical=ds==VehicleDamageState::CRITICAL;
    const float night=DayNightNightFactor();

    SDL_Color body,dark,deep,mid,bright,glass,metal,head,tail;
    if(v.type==VehicleType::TRUCK){
        body={78,91,42,255}; dark={25,29,23,255}; deep={38,44,29,255}; mid={106,116,54,255};
        bright={145,151,76,255}; glass={28,44,44,255}; metal={139,137,103,255};
        head={255,224,143,255}; tail={230,56,42,255};
    } else if(v.type==VehicleType::BUGGY){
        body={18,105,158,255}; dark={17,24,28,255}; deep={24,52,64,255}; mid={33,137,188,255};
        bright={70,176,218,255}; glass={26,53,61,220}; metal={123,130,124,255};
        head={255,237,167,255}; tail={235,57,43,255};
    } else {
        body={167,34,31,255}; dark={31,20,21,255}; deep={79,25,24,255}; mid={201,50,43,255};
        bright={231,78,67,255}; glass={23,42,50,255}; metal={155,158,151,255};
        head={255,241,177,255}; tail={242,53,43,255};
    }

    SDL_SetRenderDrawBlendMode(renderer,SDL_BLENDMODE_BLEND);

    // Pixel-art ground shadow: hard inner shadow + softer offset fringe.
    poly({{-W*.57f,-H*.42f},{W*.57f,-H*.42f},{W*.61f,H*.47f},{-W*.61f,H*.47f}}, {0,0,0,105});
    poly({{-W*.49f,-H*.38f},{W*.49f,-H*.38f},{W*.54f,H*.42f},{-W*.54f,H*.42f}}, {7,8,8,75});

    // Headlight cones are intentionally stepped/polygonal like the reference sheet.
    if(night>0.04f){
        const Uint8 ba=static_cast<Uint8>(std::clamp(20.0f+65.0f*night,20.0f,85.0f));
        poly({{-W*.34f,-H*.43f},{-W*.08f,-H*.43f},{-W*.17f,-H*1.04f},{-W*.55f,-H*1.04f}}, {255,240,185,ba});
        poly({{ W*.08f,-H*.43f},{ W*.34f,-H*.43f},{ W*.55f,-H*1.04f},{ W*.17f,-H*1.04f}}, {255,240,185,ba});
    }

    // Wheels first: thick pixel tyre, rim, spokes, lock band and flat-tire sidewall.
    const float tireX=W*.47f;
    const float tireY=H*(v.type==VehicleType::TRUCK ? .32f : .30f);
    const float tireW=v.type==VehicleType::BUGGY?W*.25f:W*.19f;
    const float tireH=v.type==VehicleType::BUGGY?H*.23f:H*.17f;
    auto wheelP=[&](float wx,float wy,float wa,float x,float y)->SDL_Point{
        const float cw=std::cos(wa),sw=std::sin(wa);
        return P(wx+x*cw-y*sw,wy+x*sw+y*cw);
    };
    auto wheel=[&](float wx,float wy,int wi){
        wy+=v.suspensionOffset[wi];
        const float wa=v.wheelSteer[wi];
        const bool flat=v.wheelDeflated[wi];
        const float hw=tireW*.5f,hh=tireH*.5f;
        auto q=[&](float x,float y){return wheelP(wx,wy,wa,x,y);};
        SDL_Point corners[5]={q(-hw,-hh),q(hw,-hh),q(hw,hh),q(-hw,hh),q(-hw,-hh)};
        SDL_SetRenderDrawColor(renderer,12,13,13,255); SDL_RenderDrawLines(renderer,corners,5);
        // Blocky tyre tread.
        SDL_SetRenderDrawColor(renderer,flat?42:48,flat?38:48,flat?34:45,255);
        SDL_Point cp=q(0,0); const int rr=std::max(3,int(std::min(hw,hh)*.78f));
        for(int yy=-rr;yy<=rr;++yy){int sp=int(std::sqrt(std::max(0.0f,float(rr*rr-yy*yy))));SDL_RenderDrawLine(renderer,cp.x-sp,cp.y+yy,cp.x+sp,cp.y+yy);}
        if(!flat){
            for(int t=-2;t<=2;++t) line(wx+std::cos(wa)*(-hw*.7f)+std::sin(wa)*t,wy+std::sin(wa)*(-hw*.7f)-std::cos(wa)*t,
                                      wx+std::cos(wa)*(hw*.7f)+std::sin(wa)*t,wy+std::sin(wa)*(hw*.7f)-std::cos(wa)*t,{75,75,70,190});
        }
        circle(wx,wy,std::max(2.8f,std::min(hw,hh)*.58f),flat?SDL_Color{104,73,48,255}:SDL_Color{151,153,146,255});
        circle(wx,wy,std::max(1.6f,std::min(hw,hh)*.22f),{43,45,43,255});
        const float spin=v.wheelSpinIndividual[wi];
        for(int sp=0;sp<4;++sp){
            const float th=spin+sp*float(M_PI*.5); const float r=std::min(hw,hh)*.52f;
            const SDL_Point a1=q(std::cos(th)*r*.22f,std::sin(th)*r*.22f);
            const SDL_Point a2=q(std::cos(th)*r*.86f,std::sin(th)*r*.86f);
            SDL_SetRenderDrawColor(renderer,210,211,201,220); SDL_RenderDrawLine(renderer,a1.x,a1.y,a2.x,a2.y);
        }
        if(v.wheelLocked[wi]){SDL_Point a1=q(-hw*.7f,0),a2=q(hw*.7f,0);SDL_SetRenderDrawColor(renderer,25,24,23,255);SDL_RenderDrawLine(renderer,a1.x,a1.y,a2.x,a2.y);}
        if(flat){
            // Exposed hot rim.
            circle(wx,wy,std::min(hw,hh)*.40f,{116,76,43,255});
            px(wx,wy,3,3,{238,169,71,235});
        }
        if(v.wheelDamageFlash[wi]>0){px(wx,wy,4,4,{255,148,45,static_cast<Uint8>(220*v.wheelDamageFlash[wi])});}
    };
    wheel(-tireX,-tireY,0); wheel(tireX,-tireY,1); wheel(-tireX,tireY,2); wheel(tireX,tireY,3);

    // --- SPORT CAR ---
    if(v.type==VehicleType::CAR){
        // Shadowed outer shell / fenders.
        poly({{0,-H*.53f},{W*.25f,-H*.49f},{W*.38f,-H*.34f},{W*.44f,-H*.06f},{W*.42f,H*.30f},
              {W*.28f,H*.48f},{W*.14f,H*.52f},{-W*.14f,H*.52f},{-W*.28f,H*.48f},{-W*.42f,H*.30f},
              {-W*.44f,-H*.06f},{-W*.38f,-H*.34f},{-W*.25f,-H*.49f}},dark);
        poly({{0,-H*.50f},{W*.23f,-H*.45f},{W*.34f,-H*.29f},{W*.39f,-H*.03f},{W*.37f,H*.29f},
              {W*.24f,H*.44f},{W*.12f,H*.48f},{-W*.12f,H*.48f},{-W*.24f,H*.44f},{-W*.37f,H*.29f},
              {-W*.39f,-H*.03f},{-W*.34f,-H*.29f},{-W*.23f,-H*.45f}},body);
        // Pixel-step fender highlights.
        poly({{-W*.31f,-H*.36f},{-W*.20f,-H*.43f},{-W*.15f,-H*.24f},{-W*.25f,-H*.20f}},mid);
        poly({{W*.31f,-H*.36f},{W*.20f,-H*.43f},{W*.15f,-H*.24f},{W*.25f,-H*.20f}},mid);
        poly({{-W*.33f,H*.22f},{-W*.22f,H*.38f},{-W*.12f,H*.45f},{-W*.18f,H*.20f}},mid);
        poly({{W*.33f,H*.22f},{W*.22f,H*.38f},{W*.12f,H*.45f},{W*.18f,H*.20f}},mid);
        // Cabin / windshield.
        poly({{-W*.24f,-H*.17f},{W*.24f,-H*.17f},{W*.20f,H*.18f},{-W*.20f,H*.18f}},glass);
        poly({{-W*.24f,-H*.17f},{W*.24f,-H*.17f},{W*.20f,H*.18f},{-W*.20f,H*.18f}},deep,true);
        line(-W*.20f,0,W*.20f,0,{91,109,112,220});
        line(-W*.18f,-H*.13f,-W*.12f,H*.12f,{95,119,124,145});
        line(W*.18f,-H*.13f,W*.12f,H*.12f,{95,119,124,145});
        // Iconic twin white racing stripes with a tiny pixel break at glass.
        rect(-W*.095f,-H*.04f,W*.055f,H*.88f,{242,240,221,255});
        rect( W*.095f,-H*.04f,W*.055f,H*.88f,{242,240,221,255});
        rect(-W*.095f,H*.01f,W*.055f,H*.12f,{207,206,191,255});
        rect( W*.095f,H*.01f,W*.055f,H*.12f,{207,206,191,255});
        // Mirrors / handles / side skirts.
        px(-W*.48f,-H*.17f,7,5,dark); px(W*.48f,-H*.17f,7,5,dark);
        px(-W*.49f,-H*.17f,4,3,bright); px(W*.49f,-H*.17f,4,3,bright);
        rect(-W*.36f,H*.12f,4,3,{244,100,75,190}); rect(W*.36f,H*.12f,4,3,{244,100,75,190});
        line(-W*.35f,H*.33f,-W*.22f,H*.40f,deep); line(W*.35f,H*.33f,W*.22f,H*.40f,deep);
        // Front grille and rear diffuser pixels.
        rect(0,-H*.48f,W*.42f,4,dark); rect(0,H*.47f,W*.40f,5,dark);
        for(int i=-2;i<=2;++i) px(i*5,-H*.475f,2,2,metal);
    }
    // --- TRUCK ---
    else if(v.type==VehicleType::TRUCK){
        // Heavy square chassis and protruding fenders.
        poly({{-W*.42f,-H*.51f},{W*.42f,-H*.51f},{W*.47f,-H*.36f},{W*.47f,H*.48f},
              {W*.38f,H*.51f},{-W*.38f,H*.51f},{-W*.47f,H*.48f},{-W*.47f,-H*.36f}},dark);
        poly({{-W*.37f,-H*.48f},{W*.37f,-H*.48f},{W*.41f,-H*.34f},{W*.41f,H*.46f},
              {-W*.41f,H*.46f},{-W*.41f,-H*.34f}},body);
        // Cab front.
        poly({{-W*.32f,-H*.45f},{W*.32f,-H*.45f},{W*.35f,-H*.15f},{-W*.35f,-H*.15f}},mid);
        poly({{-W*.28f,-H*.41f},{W*.28f,-H*.41f},{W*.27f,-H*.24f},{-W*.27f,-H*.24f}},glass);
        line(-W*.27f,-H*.33f,W*.27f,-H*.33f,metal); line(0,-H*.42f,0,-H*.25f,deep);
        // Cargo bed: raised rails, inner floor and tailgate planks.
        poly({{-W*.34f,-H*.07f},{W*.34f,-H*.07f},{W*.35f,H*.42f},{-W*.35f,H*.42f}},deep);
        poly({{-W*.29f,-H*.02f},{W*.29f,-H*.02f},{W*.30f,H*.37f},{-W*.30f,H*.37f}}, {61,69,41,255});
        for(int i=0;i<5;++i){const float yy=-H*.01f+i*H*.075f;line(-W*.28f,yy,W*.28f,yy,mid);}
        line(-W*.31f,-H*.06f,-W*.31f,H*.41f,bright); line(W*.31f,-H*.06f,W*.31f,H*.41f,bright);
        line(-W*.37f,H*.43f,W*.37f,H*.43f,metal);
        // Cab step, mirrors, bumper and grille.
        px(-W*.49f,-H*.24f,7,5,dark);px(W*.49f,-H*.24f,7,5,dark);
        px(-W*.50f,-H*.24f,4,3,bright);px(W*.50f,-H*.24f,4,3,bright);
        rect(0,-H*.49f,W*.62f,6,dark);
        for(int i=-2;i<=2;++i)px(i*7,-H*.475f,3,3,metal);
        for(int i=-1;i<=1;++i)circle(i*W*.22f,-H*.45f,2.5f,head);
        // Tailgate latch and rear lights.
        px(-W*.22f,H*.45f,5,3,tail);px(W*.22f,H*.45f,5,3,tail);px(0,H*.45f,4,3,metal);
    }
    // --- BUGGY ---
    else {
        // Open frame, long-travel suspension and exposed cockpit.
        poly({{0,-H*.47f},{W*.23f,-H*.39f},{W*.31f,H*.35f},{0,H*.48f},{-W*.31f,H*.35f},{-W*.23f,-H*.39f}},dark);
        poly({{0,-H*.43f},{W*.19f,-H*.34f},{W*.25f,H*.31f},{0,H*.43f},{-W*.25f,H*.31f},{-W*.19f,-H*.34f}},body);
        // Front blue nose panel.
        poly({{-W*.18f,-H*.43f},{W*.18f,-H*.43f},{W*.16f,-H*.22f},{-W*.16f,-H*.22f}},bright);
        line(-W*.12f,-H*.39f,0,-H*.22f,{112,197,226,210}); line(W*.12f,-H*.39f,0,-H*.22f,{112,197,226,210});
        // Seat/cockpit and floor.
        poly({{-W*.18f,-H*.15f},{W*.18f,-H*.15f},{W*.21f,H*.18f},{-W*.21f,H*.18f}},deep);
        rect(0,H*.07f,W*.20f,H*.18f,{22,31,34,255});
        // Roll cage, cross-bracing and side bars.
        line(-W*.25f,-H*.35f,-W*.18f,H*.34f,metal); line(W*.25f,-H*.35f,W*.18f,H*.34f,metal);
        line(-W*.22f,-H*.24f,W*.22f,-H*.24f,bright); line(-W*.18f,H*.27f,W*.18f,H*.27f,bright);
        line(-W*.19f,-H*.30f,W*.19f,H*.29f,metal); line(W*.19f,-H*.30f,-W*.19f,H*.29f,deep);
        // Suspension arms.
        line(-W*.30f,-H*.31f,-W*.43f,-H*.30f,metal); line(W*.30f,-H*.31f,W*.43f,-H*.30f,metal);
        line(-W*.30f,H*.31f,-W*.43f,H*.30f,metal); line(W*.30f,H*.31f,W*.43f,H*.30f,metal);
        // Rear spare tyre and hub.
        circle(0,H*.43f,W*.105f,{30,31,30,255}); circle(0,H*.43f,W*.060f,{112,115,108,255});
        line(-W*.065f,H*.43f,W*.065f,H*.43f,metal); line(0,H*.37f,0,H*.49f,metal);
        // Blue center stripe.
        rect(0,H*.02f,W*.045f,H*.48f,{34,137,188,235});
    }

    // Shared pixel lights and small highlights.
    rect(-W*.25f,-H*.465f,W*.13f,5,head); rect(W*.25f,-H*.465f,W*.13f,5,head);
    rect(-W*.25f,H*.465f,W*.15f,5,tail); rect(W*.25f,H*.465f,W*.15f,5,tail);
    // Lamp bloom is a few bright pixels, not a smooth glow.
    if(night>0.04f){px(-W*.25f,-H*.466f,5,5,{255,250,204,static_cast<Uint8>(190*night)});px(W*.25f,-H*.466f,5,5,{255,250,204,static_cast<Uint8>(190*night)});}
    // Body highlight strips and door/panel seams.
    line(-W*.34f,-H*.40f,-W*.27f,H*.36f,{255,255,255,55});
    line(W*.34f,-H*.40f,W*.27f,H*.36f,{255,255,255,38});
    line(-W*.37f,H*.02f,-W*.29f,H*.02f,metal); line(W*.37f,H*.02f,W*.29f,H*.02f,metal);

    // ============================================================
    // PREMIUM PIXEL-ART FINISH
    // Extra layered highlights, glass reflections, trim, wheel arches,
    // brake lamps and speed accents make the vehicles read more clearly
    // at a glance without changing gameplay or collision geometry.
    // ============================================================
    const float visualSpeed = std::min(1.0f, speed / std::max(1.0f, v.maxSpeed));

    // Dark wheel-arch cutouts and painted fender lips.
    const float archY = v.type == VehicleType::TRUCK ? H*.31f : H*.29f;
    const float archX = W*.47f;
    const float archW = v.type == VehicleType::BUGGY ? W*.145f : W*.12f;
    for (int side = -1; side <= 1; side += 2) {
        poly({{side*(archX-archW),-archY-H*.08f},{side*(archX+archW),-archY-H*.08f},
              {side*(archX+archW),-archY+H*.09f},{side*(archX-archW),-archY+H*.09f}}, dark);
        poly({{side*(archX-archW),archY-H*.08f},{side*(archX+archW),archY-H*.08f},
              {side*(archX+archW),archY+H*.09f},{side*(archX-archW),archY+H*.09f}}, dark);
    }

    // Metallic side belt / rocker strip.
    line(-W*.34f, -H*.01f, -W*.25f, -H*.01f, bright);
    line( W*.34f, -H*.01f,  W*.25f, -H*.01f, bright);
    line(-W*.31f, H*.31f, -W*.18f, H*.36f, {18,20,20,190});
    line( W*.31f, H*.31f,  W*.18f, H*.36f, {18,20,20,190});

    // Windshield reflection: stepped diagonal pixels instead of a flat pane.
    if (v.type != VehicleType::BUGGY) {
        poly({{-W*.18f,-H*.14f},{-W*.11f,-H*.14f},{-W*.02f,H*.14f},{-W*.08f,H*.14f}}, {190,225,228,75});
        poly({{ W*.04f,-H*.14f},{ W*.10f,-H*.14f},{ W*.18f,H*.10f},{ W*.12f,H*.10f}}, {210,238,240,52});
        line(-W*.15f,-H*.11f,-W*.09f,-H*.01f,{235,250,248,110});
    }

    // Front bumper and grille depth.
    rect(0,-H*.485f,W*.50f,5,{14,17,17,230});
    rect(0,-H*.477f,W*.32f,2,{92,98,92,230});
    for (int i=-3;i<=3;++i) {
        px(i*6,-H*.47f,2,3,{196,198,184,170});
    }

    // Headlamp inner housings + crisp highlight pixels.
    for (int side=-1; side<=1; side+=2) {
        rect(side*W*.25f,-H*.455f,W*.12f,7,{34,35,31,255});
        rect(side*W*.25f,-H*.455f,W*.085f,4,head);
        px(side*W*.27f,-H*.457f,3,3,{255,255,235,255});
    }

    // Rear lamp clusters and center brake strip.
    for (int side=-1; side<=1; side+=2) {
        rect(side*W*.28f,H*.455f,W*.105f,6,{57,17,18,255});
        rect(side*W*.28f,H*.455f,W*.075f,3,tail);
    }
    if (v.brakeEffect > 0.08f || visualSpeed > 0.72f) {
        rect(0,H*.46f,W*.16f,3,{255,74,55,static_cast<Uint8>(120+100*v.brakeEffect)});
    }

    // Vehicle-specific center emblem / stripe badge.
    if (v.type == VehicleType::CAR) {
        rect(0,H*.31f,W*.10f,4,{245,244,228,210});
        px(0,H*.31f,4,4,{255,255,255,235});
    } else if (v.type == VehicleType::TRUCK) {
        rect(0,H*.18f,W*.22f,3,{188,193,135,150});
        for(int i=-2;i<=2;++i) px(i*7,H*.18f,2,2,{221,224,180,180});
    } else {
        rect(0,H*.30f,W*.13f,3,{102,201,235,190});
    }

    // Speed shimmer: a few tiny pixel streaks behind the vehicle at high speed.
    if (visualSpeed > 0.62f) {
        const Uint8 alpha = static_cast<Uint8>(35.0f + 75.0f*visualSpeed);
        const float streak = 10.0f + 24.0f*visualSpeed;
        line(-W*.24f,H*.49f,-W*.24f,H*.49f+streak,{220,224,210,alpha});
        line( W*.24f,H*.49f, W*.24f,H*.49f+streak,{220,224,210,alpha});
    }

    // Local driver marker: a small green cockpit glow, visible only while occupied.
    if (v.driverId >= 0 && v.driverId == lanNetwork.localPlayerId) {
        const float gy = v.type == VehicleType::TRUCK ? -H*.02f : 0.0f;
        rect(0,gy,10,6,{24,205,82,230});
        px(0,gy,4,3,{135,255,155,255});
    }

    // Damage states become increasingly pixel-noisy, matching the concept sheet.
    if(ds>=VehicleDamageState::LIGHT){
        line(-W*.30f,-H*.08f,-W*.06f,H*.05f,{48,43,40,230});
        line(W*.11f,-H*.25f,W*.30f,-H*.08f,{48,43,40,230});
        px(-W*.20f,H*.17f,6,2,{226,208,177,150}); px(W*.23f,H*.22f,5,2,{226,208,177,120});
    }
    if(damaged){
        line(-W*.16f,H*.20f,W*.17f,H*.31f,{35,33,30,240});
        line(W*.02f,-H*.04f,W*.26f,H*.09f,{38,35,31,220});
        px(-W*.29f,-H*.20f,5,3,{54,50,45,210}); px(W*.30f,H*.08f,4,3,{54,50,45,200});
    }
    if(critical){
        for(int i=0;i<6;++i){
            const float dx=(float)((i*37)%17-8),dy=(float)((i*23)%19-9);
            px(dx,H*.08f+dy,2+(i%2),2,{46,42,38,140});
        }
        circle(0,-H*.31f,4.5f,{40,38,35,130});
    }

    // Green driver indicator: when this vehicle is occupied by the local
    // driver, keep a clearly visible green block inside the cockpit. This is
    // intentionally a block/square rather than a tiny dot so it remains
    // readable at normal gameplay zoom and matches the reference sheet's
    // "OCCUPIED / Driver indicator (Green)" treatment.
    if(v.occupied && g_activeVehicle >= 0 && &v == &g_vehicles[g_activeVehicle]){
        rect(0,-H*.02f,11.0f,11.0f,{35,205,78,255});
        rect(0,-H*.02f,6.0f,6.0f,{120,255,155,255});
        SDL_SetRenderDrawColor(renderer,18,70,30,255);
        SDL_Point outline[5]={P(-6,-H*.02f-6),P(6,-H*.02f-6),P(6,-H*.02f+6),P(-6,-H*.02f+6),P(-6,-H*.02f-6)};
        SDL_RenderDrawLines(renderer,outline,5);
    }

    SDL_SetRenderDrawBlendMode(renderer,SDL_BLENDMODE_NONE);
}

struct VehiclePoint { float x, y; };

static std::array<VehiclePoint,4> VehicleCorners(const VehicleEntity& v,float x,float y){
    const float cx=x+v.rect.w*.5f,cy=y+v.rect.h*.5f,hx=v.rect.w*.5f,hy=v.rect.h*.5f;
    const float c=std::cos(v.angle),s=std::sin(v.angle);
    const std::array<VehiclePoint,4> local={{{-hx,-hy},{hx,-hy},{hx,hy},{-hx,hy}}};
    std::array<VehiclePoint,4> out{};
    for(int i=0;i<4;++i) out[i]={cx+local[i].x*c-local[i].y*s,cy+local[i].x*s+local[i].y*c};
    return out;
}

static bool VehiclePolygonIntersectsRect(const std::array<VehiclePoint,4>& poly,const SDL_Rect& r){
    const std::array<VehiclePoint,4> box={{{(float)r.x,(float)r.y},{(float)(r.x+r.w),(float)r.y},{(float)(r.x+r.w),(float)(r.y+r.h)},{(float)r.x,(float)(r.y+r.h)}}};
    auto overlap=[&](const std::array<VehiclePoint,4>& A,const std::array<VehiclePoint,4>& B,float ax,float ay){
        float amin=std::numeric_limits<float>::max(),amax=-amin,bmin=amin,bmax=-amin;
        for(int i=0;i<4;++i){float pa=A[i].x*ax+A[i].y*ay,pb=B[i].x*ax+B[i].y*ay;amin=std::min(amin,pa);amax=std::max(amax,pa);bmin=std::min(bmin,pb);bmax=std::max(bmax,pb);}
        return !(amax<bmin||bmax<amin);
    };
    const float axes[4][2]={{-(poly[1].y-poly[0].y),poly[1].x-poly[0].x},{-(poly[3].y-poly[0].y),poly[3].x-poly[0].x},{-(box[1].y-box[0].y),box[1].x-box[0].x},{-(box[3].y-box[0].y),box[3].x-box[0].x}};
    for(const auto& ax:axes) if(!overlap(poly,box,ax[0],ax[1])) return false;
    return true;
}

static bool VehicleOBBIntersectsVehicle(const VehicleEntity& a,float ax,float ay,const VehicleEntity& b,float bx,float by){
    const auto A=VehicleCorners(a,ax,ay),B=VehicleCorners(b,bx,by);
    auto overlap=[](const std::array<VehiclePoint,4>& P,const std::array<VehiclePoint,4>& Q,float x,float y){
        float pmin=std::numeric_limits<float>::max(),pmax=-pmin,qmin=pmin,qmax=-pmin;
        for(int i=0;i<4;++i){float p=P[i].x*x+P[i].y*y,q=Q[i].x*x+Q[i].y*y;pmin=std::min(pmin,p);pmax=std::max(pmax,p);qmin=std::min(qmin,q);qmax=std::max(qmax,q);}
        return !(pmax<qmin||qmax<pmin);
    };
    const float axes[4][2]={{-(A[1].y-A[0].y),A[1].x-A[0].x},{-(A[3].y-A[0].y),A[3].x-A[0].x},{-(B[1].y-B[0].y),B[1].x-B[0].x},{-(B[3].y-B[0].y),B[3].x-B[0].x}};
    for(const auto& ax:axes) if(!overlap(A,B,ax[0],ax[1])) return false;
    return true;
}

static bool VehicleCanOccupyMap(const VehicleEntity& v,float x,float y){
    const auto corners=VehicleCorners(v,x,y);
    float minX=corners[0].x,maxX=corners[0].x,minY=corners[0].y,maxY=corners[0].y;
    for(const auto& p:corners){minX=std::min(minX,p.x);maxX=std::max(maxX,p.x);minY=std::min(minY,p.y);maxY=std::max(maxY,p.y);}
    if(minX<0||minY<0||maxX>currentMapCols*TILE_SIZE||maxY>currentMapRows*TILE_SIZE) return false;
    const int sc=std::max(0,(int)std::floor(minX/TILE_SIZE)-1),ec=std::min(currentMapCols-1,(int)std::floor(maxX/TILE_SIZE)+1);
    const int sr=std::max(0,(int)std::floor(minY/TILE_SIZE)-1),er=std::min(currentMapRows-1,(int)std::floor(maxY/TILE_SIZE)+1);
    for(int r=sr;r<=er;++r) for(int c=sc;c<=ec;++c) if(gameMap[r][c]==1||gameMap[r][c]==10){SDL_Rect tile{c*TILE_SIZE,r*TILE_SIZE,TILE_SIZE,TILE_SIZE};if(VehiclePolygonIntersectsRect(corners,tile)) return false;}
    return true;
}

static void VehicleReset(){
    g_vehicles={};g_activeVehicle=-1;g_vehicleEnterLatch=false;VehicleClearTireEffects();
    std::fill(std::begin(g_lastVehicleDamageAt),std::end(g_lastVehicleDamageAt),0);
    std::fill(std::begin(g_lastVehicleImpactAt),std::end(g_lastVehicleImpactAt),0);
}

static void VehicleConfigure(VehicleEntity& v,VehicleType type,float x,float y){
    v=VehicleEntity{};v.active=true;v.type=type;v.x=x;v.y=y;v.aiControlled=true;
    // Larger world-space vehicle bodies: substantially easier to see on phones.
    v.rect={static_cast<int>(x),static_cast<int>(y),86,144};
    if(type==VehicleType::TRUCK){v.rect.w=100;v.rect.h=190;v.maxSpeed=680;v.reverseSpeed=300;v.acceleration=1450;v.braking=1250;v.turnRate=2.1f;v.traction=6.0f;v.mass=2.2f;v.health=v.maxHealth=160;}
    else if(type==VehicleType::BUGGY){v.rect.w=76;v.rect.h=124;v.maxSpeed=980;v.reverseSpeed=380;v.acceleration=1750;v.braking=1400;v.turnRate=3.5f;v.traction=8.5f;v.mass=.75f;v.health=v.maxHealth=80;}
    else {v.maxSpeed=850;v.reverseSpeed=330;v.acceleration=1550;v.braking=1250;v.turnRate=2.9f;v.traction=7.5f;v.mass=1.0f;v.health=v.maxHealth=100;}
}

static void VehicleSpawnSize(VehicleType type,int& w,int& h){w=86;h=144;if(type==VehicleType::TRUCK){w=100;h=190;}else if(type==VehicleType::BUGGY){w=76;h=124;}}
static bool VehicleCanSpawnAt(float x,float y,int w,int h){VehicleEntity probe;probe.rect={0,0,w,h};return VehicleCanOccupyMap(probe,x,y);}


static void VehicleSpawnSavedMapVehicles(){
    if(!useCustomMap) return;

    // Avoid duplicating vehicles every frame/map update.
    for(const auto& v : g_vehicles) if(v.active) return;

    int slot = 0;
    for(const auto& saved : savedMapVehicles){
        if(slot >= MAX_AMBIENT_VEHICLES) break;

        VehicleType type = VehicleType::CAR;
        if(saved.type == 1) type = VehicleType::TRUCK;
        else if(saved.type == 2) type = VehicleType::BUGGY;

        VehicleConfigure(g_vehicles[slot], type, saved.x, saved.y);
        g_vehicles[slot].angle = saved.rotation;
        slot++;
    }
}

static void VehicleEnsureMapVehicles(){
    // Custom maps use editor-placed vehicles saved with the map file.
    // Do not create random ambient vehicles on custom maps.
    if(useCustomMap) return;

    for(const auto& v:g_vehicles) if(v.active) return;
    const float cx=currentMapCols*TILE_SIZE*.5f,cy=currentMapRows*TILE_SIZE*.5f;
    // Place ambient traffic well away from the map center/player start.
    // The AI subsequently retargets each vehicle to another remote point.
    const float candidates[][2]={{cx-700,cy-420},{cx+650,cy-380},{cx-620,cy+460},{cx+700,cy+430}};
    const VehicleType types[]={VehicleType::CAR,VehicleType::BUGGY,VehicleType::TRUCK,VehicleType::CAR};
    for(int i=0;i<4;++i){int w,h;VehicleSpawnSize(types[i],w,h);if(VehicleCanSpawnAt(candidates[i][0],candidates[i][1],w,h))VehicleConfigure(g_vehicles[i],types[i],candidates[i][0],candidates[i][1]);}
}

static bool VehicleIntersectsOther(const VehicleEntity& candidate,float x,float y,int ignoreIndex){
    for(int i=0;i<MAX_AMBIENT_VEHICLES;++i) if(i!=ignoreIndex&&g_vehicles[i].active&&VehicleOBBIntersectsVehicle(candidate,x,y,g_vehicles[i],g_vehicles[i].x,g_vehicles[i].y)) return true;
    return false;
}

static int VehicleCollisionIndex(const VehicleEntity& candidate,float x,float y,int ignoreIndex){
    for(int i=0;i<MAX_AMBIENT_VEHICLES;++i) if(i!=ignoreIndex&&g_vehicles[i].active&&VehicleOBBIntersectsVehicle(candidate,x,y,g_vehicles[i],g_vehicles[i].x,g_vehicles[i].y)) return i;
    return -1;
}

static int VehicleFindNearbyPlayer(float px,float py){
    const float enterDistance=105.0f;int best=-1;float bestDist2=enterDistance*enterDistance;
    for(int i=0;i<MAX_AMBIENT_VEHICLES;++i){const auto& v=g_vehicles[i];if(!v.active||v.occupied||v.health<=0)continue;const float cx=v.x+v.rect.w*.5f,cy=v.y+v.rect.h*.5f,dx=px-cx,dy=py-cy,d2=dx*dx+dy*dy;if(d2<bestDist2){bestDist2=d2;best=i;}}
    return best;
}

static bool VehicleFindExitPosition(const VehicleEntity& v,SDL_Rect player,SDL_Rect& out){
    const float c=std::cos(v.angle),s=std::sin(v.angle);
    const float offsets[][2]={{v.rect.w*.5f+player.w*.70f,0},{-v.rect.w*.5f-player.w*.70f,0},{0,v.rect.h*.5f+player.h*.70f},{0,-v.rect.h*.5f-player.h*.70f}};
    for(const auto& o:offsets){
        const float wx=v.x+v.rect.w*.5f+o[0]*c-o[1]*s,wy=v.y+v.rect.h*.5f+o[0]*s+o[1]*c;
        SDL_Rect p=player;p.x=(int)std::lround(wx-p.w*.5f);p.y=(int)std::lround(wy-p.h*.5f);
        if(!check_wall_collision(p)&&p.x>=0&&p.y>=0&&p.x+p.w<=currentMapCols*TILE_SIZE&&p.y+p.h<=currentMapRows*TILE_SIZE){out=p;return true;}
    }
    return false;
}

static bool VehicleExitPlayer(float& playerPosX,float& playerPosY,SDL_Rect& player){
    if(g_activeVehicle<0||g_activeVehicle>=MAX_AMBIENT_VEHICLES)return false;
    VehicleEntity& v=g_vehicles[g_activeVehicle];if(!v.active||!v.occupied)return false;
    SDL_Rect probe=player;if(!VehicleFindExitPosition(v,player,probe))return false;
    player=probe;playerPosX=(float)probe.x;playerPosY=(float)probe.y;v.occupied=false;v.driverId=-1;g_activeVehicle=-1;return true;
}

static void VehicleEnterPlayer(float px,float py,int localPlayerId=0){
    if(g_activeVehicle>=0)return;const int idx=VehicleFindNearbyPlayer(px,py);if(idx<0)return;
    g_vehicles[idx].occupied=true;g_vehicles[idx].driverId=localPlayerId;g_activeVehicle=idx;
}

static void VehicleMarkForExplosion(VehicleEntity& v){if(v.health<=0){v.health=0;v.vx=v.vy=0;v.explosionPending=true;}}

static void VehicleApplyExplosion(VehicleEntity& v,float& playerPosX,float& playerPosY,SDL_Rect& player,int& playerHp,Uint32 now){
    if(!v.active)return;
    const float bx=v.x+v.rect.w*.5f,by=v.y+v.rect.h*.5f,radius=v.type==VehicleType::TRUCK?190.0f:150.0f;
    const bool wasDriver=g_activeVehicle>=0&&g_activeVehicle<MAX_AMBIENT_VEHICLES&& &v == &g_vehicles[g_activeVehicle];
    if(wasDriver) VehicleExitPlayer(playerPosX,playerPosY,player);
    trigger_explosion(bx,by,radius,v.type==VehicleType::TRUCK?70:55,player,playerHp,false,-2,WeaponType::ROCKET);
    v.active=false;v.occupied=false;v.driverId=-1;v.explosionPending=false;
    if(wasDriver){g_activeVehicle=-1;playerIsInvulnerable=false;}
    playerPosX=(float)player.x;playerPosY=(float)player.y;(void)now;
}

static void VehicleDamagePlayerRect(const VehicleEntity& v,const SDL_Rect& target,int& hp,Uint32 now,int idx){
    if(hp<=0||idx<0||idx>=MAX_AMBIENT_VEHICLES||now-g_lastVehicleDamageAt[idx]<250)return;
    const auto poly=VehicleCorners(v,v.x,v.y);if(!VehiclePolygonIntersectsRect(poly,target))return;
    const float speed=std::hypot(v.vx,v.vy);if(speed<90)return;
    const int damage=std::clamp((int)std::lround(speed*.10f),8,45);hp=std::max(0,hp-damage);g_lastVehicleDamageAt[idx]=now;
}

static int VehicleIndexForDriver(int playerId){for(int i=0;i<MAX_AMBIENT_VEHICLES;++i)if(g_vehicles[i].active&&g_vehicles[i].occupied&&g_vehicles[i].driverId==playerId)return i;return -1;}

// Definition for the forward declaration near lan_remove_peer. Frees a
// vehicle a disconnecting driver was occupying so it isn't permanently
// soft-locked once its driverId no longer corresponds to any live peer.
static void VehicleReleaseDriverIfAny(int playerId){
    const int idx=VehicleIndexForDriver(playerId);
    if(idx<0)return;
    g_vehicles[idx].occupied=false;
    g_vehicles[idx].driverId=-1;
    if(g_activeVehicle==idx)g_activeVehicle=-1;
}

static void VehicleHostProcessRemoteActions(){
    if(!lanNetwork.hosting)return;
    for(auto& peer:lanNetwork.peers) if(peer.vehicleEnterRequested){
        peer.vehicleEnterRequested=false;const int current=VehicleIndexForDriver(peer.playerId);
        if(current>=0){
            VehicleEntity& v=g_vehicles[current];
            v.occupied=false;v.driverId=-1;
            // Find a clear exit point the same way the local player does
            // (VehicleExitPlayer) instead of leaving the remote player's
            // authoritative position glued to wherever the vehicle stopped -
            // otherwise they can end up stuck inside the vehicle's collision
            // box or embedded in a wall the vehicle parked against.
            for(auto& rp:lanNetwork.remotePlayers) if(rp.id==peer.playerId){
                SDL_Rect playerRect{(int)std::lround(rp.x),(int)std::lround(rp.y),60,60};
                SDL_Rect exitRect;
                if(VehicleFindExitPosition(v,playerRect,exitRect)){
                    rp.x=(float)exitRect.x;rp.y=(float)exitRect.y;
                }
                break;
            }
        }
        else for(const auto& rp:lanNetwork.remotePlayers) if(rp.id==peer.playerId&&!rp.dead){const int idx=VehicleFindNearbyPlayer(rp.x+30.0f,rp.y+30.0f);if(idx>=0){g_vehicles[idx].occupied=true;g_vehicles[idx].driverId=peer.playerId;}break;}
    }
}

static int VehicleNearestWheelFromWorldPoint(const VehicleEntity& v,float px,float py){
    const float c=std::cos(v.angle), s=std::sin(v.angle);
    const float dx=px-(v.x+v.rect.w*.5f), dy=py-(v.y+v.rect.h*.5f);
    // Transform world point into vehicle-local coordinates. Forward is local -Y.
    const float lx=dx*c+dy*s;
    const float ly=-dx*s+dy*c;
    const float halfX=v.rect.w*.34f, halfY=v.rect.h*.30f;
    const float wx[4]={-halfX,halfX,-halfX,halfX};
    const float wy[4]={-halfY,-halfY,halfY,halfY};
    int best=0; float bestD=1e30f;
    for(int i=0;i<4;++i){ const float ax=lx-wx[i], ay=ly-wy[i]; const float d=ax*ax+ay*ay; if(d<bestD){bestD=d;best=i;} }
    return best;
}

static void VehicleDamageWheel(VehicleEntity& v,int wheelIndex,float damage){
    if(wheelIndex<0||wheelIndex>=4||damage<=0.0f)return;
    v.wheelHealth[wheelIndex]=std::max(0.0f,v.wheelHealth[wheelIndex]-damage);
    v.wheelDamageFlash[wheelIndex]=1.0f;
    if(v.wheelHealth[wheelIndex]<=0.0f){
        v.wheelDeflated[wheelIndex]=true;
        v.wheelLocked[wheelIndex]=true;
    }
}

static void VehicleUpdateWheelDamage(VehicleEntity& v,float dtSeconds){
    for(int i=0;i<4;++i){
        v.wheelDamageFlash[i]=std::max(0.0f,v.wheelDamageFlash[i]-dtSeconds*4.5f);
        v.wheelDeflated[i]=v.wheelHealth[i]<=0.0f;
    }
}

static void VehicleApplyImpactWheelDamage(VehicleEntity& v,float impactSpeed,float localX,float localY){
    if(impactSpeed<180.0f)return;
    const float halfX=v.rect.w*.34f, halfY=v.rect.h*.30f;
    int nearest=0; float best=1e30f;
    const float wx[4]={-halfX,halfX,-halfX,halfX};
    const float wy[4]={-halfY,-halfY,halfY,halfY};
    for(int i=0;i<4;++i){float dx=localX-wx[i],dy=localY-wy[i],d=dx*dx+dy*dy;if(d<best){best=d;nearest=i;}}
    VehicleDamageWheel(v,nearest,std::clamp((impactSpeed-140.0f)*0.16f,5.0f,35.0f));
}

static void VehicleApplyImpactDamage(VehicleEntity& a,int bIndex,float impactSpeed,Uint32 now){
    if(impactSpeed<120||now-g_lastVehicleImpactAt[bIndex]<120)return;
    VehicleEntity& b=g_vehicles[bIndex];
    const int total=std::clamp((int)std::lround((impactSpeed-80.0f)*.055f),3,32);
    const int aDamage=std::max(2,(int)std::lround(total*(b.mass/(a.mass+b.mass))));
    const int bDamage=std::max(2,total-aDamage+2);
    a.health=std::max(0.0f,a.health-(float)aDamage);b.health=std::max(0.0f,b.health-(float)bDamage);
    const float acx=a.x+a.rect.w*.5f, acy=a.y+a.rect.h*.5f;
    const float bcx=b.x+b.rect.w*.5f, bcy=b.y+b.rect.h*.5f;
    const float adx=bcx-acx, ady=bcy-acy;
    const float ac=std::cos(a.angle), as=std::sin(a.angle);
    const float aLocalX=adx*ac+ady*as, aLocalY=-adx*as+ady*ac;
    const float bc=std::cos(b.angle), bs=std::sin(b.angle);
    const float bLocalX=-adx*bc-ady*bs, bLocalY=adx*bs-ady*bc;
    VehicleApplyImpactWheelDamage(a,impactSpeed,aLocalX,aLocalY);
    VehicleApplyImpactWheelDamage(b,impactSpeed,bLocalX,bLocalY);
    g_lastVehicleImpactAt[bIndex]=now;
    VehicleMarkForExplosion(a);VehicleMarkForExplosion(b);
}

static bool VehicleDriveStep(VehicleEntity& v,float forward,float steering,float dtSeconds,int index,Uint32 now){
    forward=std::clamp(forward,-1.0f,1.0f);steering=std::clamp(steering,-1.0f,1.0f);
    const float oldSpeed=std::hypot(v.vx,v.vy);
    const float c0=std::cos(v.angle), s0=std::sin(v.angle);
    const float fx0=s0, fy0=-c0;
    const float longitudinalInput = v.vx*fx0 + v.vy*fy0;
    // Pressing the opposite direction while moving forward is a hard brake,
    // not an instant switch to reverse.
    const bool brakingInput = std::fabs(longitudinalInput) > 45.0f &&
                               ((longitudinalInput > 0.0f && forward < -0.05f) ||
                                (longitudinalInput < 0.0f && forward > 0.05f));
    const float brakeTarget = brakingInput ? std::clamp(std::fabs(forward), 0.0f, 1.0f) : 0.0f;
    v.brakeEffect += (brakeTarget - v.brakeEffect) * std::clamp(dtSeconds*10.0f,0.0f,1.0f);
    const float c=std::cos(v.angle),s=std::sin(v.angle);
    // Force-based four-wheel model. Forward is local -Y; right is local +X.
    const float fx=s, fy=-c;
    const float rx=c, ry=s;
    const float speed0=std::hypot(v.vx,v.vy);
    const float bodyLong=v.vx*fx+v.vy*fy;
    const float bodyLat=v.vx*rx+v.vy*ry;

    // Vehicle-specific handling: the buggy is agile, the truck is heavily damped,
    // and the sport car has a stronger rear-drive character.
    float tireGrip=1.0f, lateralGrip=1.0f, coastDrag=0.55f, driveBias=0.72f;
    if(v.type==VehicleType::TRUCK){ tireGrip=0.82f; lateralGrip=0.78f; coastDrag=0.82f; driveBias=0.86f; }
    else if(v.type==VehicleType::BUGGY){ tireGrip=1.08f; lateralGrip=0.96f; coastDrag=0.42f; driveBias=0.62f; }

    const float geomHalfX=v.rect.w*0.34f, geomHalfY=v.rect.h*0.30f;
    const float wheelX[4]={-geomHalfX,geomHalfX,-geomHalfX,geomHalfX};
    const float wheelY[4]={-geomHalfY,-geomHalfY,geomHalfY,geomHalfY};
    const float steerBase=steering*(v.type==VehicleType::TRUCK?0.40f:(v.type==VehicleType::BUGGY?0.52f:0.48f));
    const float wheelBase=std::max(20.0f,geomHalfY*2.0f);

    // Compute axle load transfer from acceleration/braking and cornering.
    const float brakeTargetForce=brakingInput?std::clamp(std::fabs(forward),0.0f,1.0f):0.0f;
    const float longitudinalLoad=std::clamp((-bodyLong/650.0f),-0.55f,0.55f);
    const float lateralLoad=std::clamp((bodyLat/650.0f),-0.45f,0.45f);
    float totalWorldFx=0.0f,totalWorldFy=0.0f,totalTorque=0.0f;
    const float yawForSlip=v.yawRate;

    for(int wi=0;wi<4;++wi){
        const bool front=wi<2;
        const bool left=(wi==0||wi==2);
        const bool flat=v.wheelDeflated[wi];
        const float ack=front?(left?0.94f:1.06f):0.0f;
        float wa=v.angle+(front?steerBase*ack:0.0f);
        if(flat&&front) wa=v.angle+(wa-v.angle)*0.28f;

        const float localX=wheelX[wi], localY=wheelY[wi];
        const float worldRX=localX*c-localY*s, worldRY=localX*s+localY*c;
        const float contactVx=v.vx-yawForSlip*worldRY;
        const float contactVy=v.vy+yawForSlip*worldRX;
        const float wfX=std::sin(wa), wfY=-std::cos(wa);
        const float wrX=std::cos(wa), wrY=std::sin(wa);
        const float longV=contactVx*wfX+contactVy*wfY;
        const float latV=contactVx*wrX+contactVy*wrY;

        float load=0.25f;
        load += front ? -longitudinalLoad*0.16f : longitudinalLoad*0.16f;
        load += left ? -lateralLoad*0.10f : lateralLoad*0.10f;
        load=std::clamp(load,0.10f,0.42f);
        v.wheelLoad[wi]=load*4.0f;

        const float healthGrip=flat?0.16f:std::clamp(v.wheelHealth[wi]/100.0f,0.35f,1.0f);
        const float axleGrip=(front?1.0f:0.96f)*tireGrip*healthGrip;
        const float sideGrip=lateralGrip*healthGrip;

        // Desired longitudinal force comes from the engine/brakes, while the tire
        // model resists wheel slip. This prevents instant direction changes.
        float desiredLong=forward*v.acceleration;
        if(forward<0.0f && !brakingInput) desiredLong*=0.55f;
        if(brakingInput) desiredLong=-std::copysign(v.braking*brakeTargetForce,std::fabs(longV)>1.0f?longV:(bodyLong==0?1.0f:bodyLong));
        if(front) desiredLong*=1.0f-driveBias; else desiredLong*=driveBias;
        if(v.type==VehicleType::TRUCK && forward>0.0f) desiredLong*=0.92f;

        const float slipLong=(desiredLong-longV*7.5f)*axleGrip;
        const float slipLat=-latV*sideGrip*8.5f;
        const float combined=std::hypot(slipLong,slipLat);
        const float frictionLimit=std::max(30.0f,520.0f*load*axleGrip);
        const float scale=combined>frictionLimit?frictionLimit/combined:1.0f;
        const float forceLong=slipLong*scale;
        const float forceLat=slipLat*scale;
        totalWorldFx+=wfX*forceLong+wrX*forceLat;
        totalWorldFy+=wfY*forceLong+wrY*forceLat;
        totalTorque+=worldRX*(wfY*forceLong+wrY*forceLat)-worldRY*(wfX*forceLong+wrX*forceLat);
        v.wheelSlip[wi]=std::clamp((std::fabs(latV)/75.0f+std::fabs(longV-desiredLong/7.5f)/120.0f)/std::max(0.18f,healthGrip),0.0f,2.5f);
    }

    // Aerodynamic drag and rolling resistance grow with speed.
    const float dragForce=(coastDrag*0.75f + 0.0009f*speed0*speed0);
    const float dragWorldX=(-bodyLong*fx-bodyLat*rx)*dragForce/(speed0+1.0f);
    const float dragWorldY=(-bodyLong*fy-bodyLat*ry)*dragForce/(speed0+1.0f);
    totalWorldFx += dragWorldX;
    totalWorldFy += dragWorldY;
    const float invMass=1.0f/std::max(0.35f,v.mass);
    v.vx += totalWorldFx*invMass*dtSeconds;
    v.vy += totalWorldFy*invMass*dtSeconds;

    // Weight/inertia-aware yaw response. Larger trucks rotate more slowly.
    const float yawInertia=std::max(0.8f,v.mass*wheelBase*wheelBase*0.55f);
    v.yawRate += (totalTorque/yawInertia)*dtSeconds;
    const float yawDamping=(v.type==VehicleType::TRUCK?2.8f:2.1f);
    v.yawRate *= std::exp(-yawDamping*dtSeconds);
    const float speedForSteer=std::hypot(v.vx,v.vy);
    const float steeringAuthority=std::clamp(speedForSteer/110.0f,0.0f,1.0f);
    if(std::fabs(steering)>0.01f) v.yawRate += steering*v.turnRate*(0.18f+0.82f*steeringAuthority)*dtSeconds;
    v.angle += v.yawRate*dtSeconds;

    float speed=std::hypot(v.vx,v.vy);
    // Soft speed limiter rather than a hard clamp.
    if(speed>v.maxSpeed){
        const float excess=speed-v.maxSpeed;
        const float scale=std::max(0.0f,1.0f-excess*0.0025f*dtSeconds);
        v.vx*=scale;v.vy*=scale;speed=std::hypot(v.vx,v.vy);
    }

    // Low-speed reverse steering naturally follows the current travel direction.
    if(speed<35.0f && std::fabs(steering)>0.01f) v.angle += steering*(bodyLong<0?-1.0f:1.0f)*0.55f*dtSeconds;
    const float angleBeforeSteering = v.angle - v.yawRate*dtSeconds;

    const float nx=v.x+v.vx*dtSeconds,ny=v.y+v.vy*dtSeconds;
    bool hit=false;
    if(VehicleCanOccupyMap(v,nx,v.y)) v.x=nx;
    else {hit=true;const float impact=std::fabs(v.vx);v.vx*=-.28f;v.health-=std::clamp(impact*.045f,2.0f,28.0f); VehicleVisual_OnDamage(v.x, v.y, (int)v.health);}
    if(VehicleCanOccupyMap(v,v.x,ny)) v.y=ny;
    else {hit=true;const float impact=std::fabs(v.vy);v.vy*=-.28f;v.health-=std::clamp(impact*.045f,2.0f,28.0f);}

    const int other=VehicleCollisionIndex(v,v.x,v.y,index);
    if(other>=0){
        hit=true;const float impact=std::max(oldSpeed,speed);VehicleApplyImpactDamage(v,other,impact,now);
        const float dx=(v.x+v.rect.w*.5f)-(g_vehicles[other].x+g_vehicles[other].rect.w*.5f);
        const float dy=(v.y+v.rect.h*.5f)-(g_vehicles[other].y+g_vehicles[other].rect.h*.5f);
        const float d=std::hypot(dx,dy);if(d>0.01f){v.x+=dx/d*std::min(8.0f,impact*dtSeconds*.25f);v.y+=dy/d*std::min(8.0f,impact*dtSeconds*.25f);}
        v.vx*=-.22f;v.vy*=-.22f;
    }

    const float lateral=v.vx*(-c)+v.vy*(-s); // velocity across the body
    // Individual wheel kinematics: each tire sees a slightly different velocity
    // because of steering and the vehicle's yaw rate. This lets the front tires
    // steer independently and lets each tire lock/slip independently under load.
    float yawDelta = v.angle - angleBeforeSteering;
    while(yawDelta > static_cast<float>(M_PI)) yawDelta -= static_cast<float>(2.0*M_PI);
    while(yawDelta < -static_cast<float>(M_PI)) yawDelta += static_cast<float>(2.0*M_PI);
    v.yawRate = dtSeconds > 0.0001f ? yawDelta/dtSeconds : 0.0f;

    const float effectHalfX=v.rect.w*0.34f, effectHalfY=v.rect.h*0.30f;
    const float effectWheelX[4]={-effectHalfX,effectHalfX,-effectHalfX,effectHalfX};
    const float effectWheelY[4]={-effectHalfY,-effectHalfY,effectHalfY,effectHalfY};
    const float steerAngle=steering*0.48f;
    const float visualWheelRadius=std::max(6.0f,v.rect.h*0.14f);
    const bool strongBrake = brakingInput && oldSpeed > 85.0f;
    for(int wi=0;wi<4;++wi){
        const bool front=wi<2;
        const bool left=(wi==0 || wi==2);
        const bool flat=v.wheelDeflated[wi];
        // Inside/outside front tires steer slightly differently, while a
        // damaged front corner loses steering authority asymmetrically.
        const float ackermann = front ? (left ? 0.94f : 1.06f) : 0.0f;
        float cornerSteer = front ? steerAngle*ackermann : 0.0f;
        if(flat && front) cornerSteer *= 0.28f;
        v.wheelSteer[wi]=cornerSteer;
        const float wa=v.angle+v.wheelSteer[wi];
        // Contact-point velocity = body velocity + angular velocity x offset.
        const float rx=effectWheelX[wi]*c-effectWheelY[wi]*s;
        const float ry=effectWheelX[wi]*s+effectWheelY[wi]*c;
        const float contactVx=v.vx-v.yawRate*ry;
        const float contactVy=v.vy+v.yawRate*rx;
        const float wheelLong=contactVx*std::sin(wa)+contactVy*(-std::cos(wa));
        const float wheelLat=contactVx*(-std::cos(wa))+contactVy*(-std::sin(wa));
        const float absLong=std::fabs(wheelLong), absLat=std::fabs(wheelLat);
        // Each corner has its own effective grip. Front tires primarily affect
        // steering; rear tires primarily affect traction and yaw stability.
        const float baseGrip = front ? 1.0f : 0.92f;
        const float damageGrip = flat ? 0.18f : 1.0f;
        const float cornerGrip = baseGrip * damageGrip;
        v.wheelLoad[wi] = std::clamp(0.72f + (strongBrake ? (front ? 0.30f : 0.18f) : 0.0f)
                                     + (std::fabs(steering) > 0.25f && front ? 0.10f : 0.0f), 0.35f, 1.35f);
        v.wheelSlip[wi]=std::clamp((absLat/90.0f + (strongBrake ? std::max(0.0f,(absLong-45.0f)/180.0f) : 0.0f))
                                   / std::max(0.18f,cornerGrip) * v.wheelLoad[wi],0.0f,2.0f);
        const float lockThreshold = flat ? 35.0f : (front ? 70.0f : 62.0f);
        v.wheelLocked[wi]=strongBrake && absLong>lockThreshold && absLat < std::max(60.0f,absLong*0.9f) && !flat;
        if(v.wheelLocked[wi]){
            // Locked tire: stop its visible rotation, but keep vehicle motion.
            v.wheelSpinIndividual[wi] *= std::exp(-18.0f*dtSeconds);
        }else{
            v.wheelSpinIndividual[wi] += (wheelLong*dtSeconds)/visualWheelRadius;
        }
        if(std::fabs(v.wheelSpinIndividual[wi])>1000.0f)
            v.wheelSpinIndividual[wi]=std::fmod(v.wheelSpinIndividual[wi],static_cast<float>(2.0*M_PI));
    }
    // A deflated tire loses grip and each corner now affects handling differently.
    VehicleUpdateWheelDamage(v,dtSeconds);
    int flatCount=0;
    float pullTarget=0.0f;
    float yawBias=0.0f;
    float gripLoss=0.0f;
    for(int wi=0;wi<4;++wi){
        const bool flat=v.wheelDeflated[wi];
        if(!flat) continue;
        ++flatCount;
        const float sideSign=(wi==0||wi==2)?-1.0f:1.0f;
        // FL/FR are strongest because they sit on the steering axle. Rear flats
        // mainly create drag and a smaller yaw bias.
        const float axleWeight=wi<2?1.0f:0.62f;
        const float cornerWeight=(wi==0||wi==3)?1.0f:0.94f;
        pullTarget += sideSign*axleWeight*cornerWeight*0.115f;
        yawBias += sideSign*(wi<2?0.090f:0.045f);
        gripLoss += wi<2?0.19f:0.14f;
    }
    if(flatCount==0){
        v.wheelPull += (0.0f-v.wheelPull)*std::clamp(dtSeconds*5.0f,0.0f,1.0f);
        v.wheelWobble += (0.0f-v.wheelWobble)*std::clamp(dtSeconds*5.0f,0.0f,1.0f);
    } else {
        pullTarget=std::clamp(pullTarget,-0.38f,0.38f);
        v.wheelPull += (pullTarget-v.wheelPull)*std::clamp(dtSeconds*4.5f,0.0f,1.0f);
        const float flatSeverity=std::clamp(flatCount*0.38f+std::fabs(v.wheelPull),0.0f,1.0f);
        v.wheelWobble += ((0.8f+flatSeverity*2.2f)*std::min(1.0f,speed/150.0f)-v.wheelWobble)*std::clamp(dtSeconds*5.5f,0.0f,1.0f);
        // Front-left/right failures yaw more strongly; rear failures mostly add
        // drag. The player can counter-steer because this is not a teleport.
        v.angle += (v.wheelPull*(0.48f+0.82f*std::min(1.0f,speed/220.0f)) + yawBias*0.32f)*dtSeconds;
        const float grip=std::max(0.32f,1.0f-gripLoss);
        v.vx*=1.0f-std::clamp((1.0f-grip)*dtSeconds*0.95f,0.0f,0.22f);
        v.vy*=1.0f-std::clamp((1.0f-grip)*dtSeconds*0.95f,0.0f,0.22f);
        // A single rear flat produces a little extra drag on that side, while a
        // front flat reduces steering authority only on the affected corner.
        const float sideDrag=std::fabs(v.wheelPull)*speed*0.055f;
        const float dragDirX=-std::sin(v.angle)*v.wheelPull;
        const float dragDirY= std::cos(v.angle)*v.wheelPull;
        v.vx += dragDirX*sideDrag*dtSeconds;
        v.vy += dragDirY*sideDrag*dtSeconds;
    }

    // Per-corner suspension: braking loads the front axle, acceleration loads the
    // rear axle, and a flat corner drops farther and bounces with a slower spring.
    const float accelLoad=std::max(0.0f,forward);
    const float brakeLoad=v.brakeEffect;
    for(int wi=0;wi<4;++wi){
        const bool front=wi<2;
        const bool flat=v.wheelDeflated[wi];
        const float load=front ? (0.45f+0.85f*brakeLoad) : (0.45f+0.65f*accelLoad);
        const float targetDrop=flat ? (7.0f+3.5f*std::min(1.0f,speed/180.0f)) : load*1.35f;
        const float spring=flat?7.0f:11.5f;
        const float damping=flat?4.2f:5.8f;
        const float target=targetDrop + std::sin(static_cast<float>(SDL_GetTicks())*0.02f + wi*1.7f)*load*0.7f;
        v.suspensionVelocity[wi] += (target-v.suspensionOffset[wi])*spring*dtSeconds;
        v.suspensionVelocity[wi] *= std::exp(-damping*dtSeconds);
        v.suspensionOffset[wi] += v.suspensionVelocity[wi]*dtSeconds;
        v.suspensionOffset[wi]=std::clamp(v.suspensionOffset[wi],-2.0f,flat?13.0f:5.0f);
    }
    v.wheelSpin = (v.wheelSpinIndividual[0]+v.wheelSpinIndividual[1]+v.wheelSpinIndividual[2]+v.wheelSpinIndividual[3])*0.25f;
    v.skidTimer=(std::fabs(lateral)>75.0f|| (hit&&speed>130.0f))?0.18f:std::max(0.0f,v.skidTimer-dtSeconds);
    v.rect.x=(int)std::lround(v.x);v.rect.y=(int)std::lround(v.y);
    VehicleMarkForExplosion(v);
    return hit;
}

static int VehicleProjectileDamage(WeaponType type) {
    const int base = WEAPON_PROPS[static_cast<int>(type)].damage;
    switch(type) {
        case WeaponType::ROCKET:    return std::max(35, static_cast<int>(std::lround(base * 1.45f)));
        case WeaponType::LASER:     return std::max(12, static_cast<int>(std::lround(base * 0.90f)));
        case WeaponType::VECTOR_REFLECT: return std::max(10, static_cast<int>(std::lround(base * 0.85f)));
        case WeaponType::FIRE_GUN:  return std::max(10, static_cast<int>(std::lround(base * 0.80f)));
        case WeaponType::ICE_GUN:   return std::max(8, static_cast<int>(std::lround(base * 0.70f)));
        default:                    return std::max(6, static_cast<int>(std::lround(base * 0.65f)));
    }
}

static int VehicleProjectileHitIndex(const SDL_Rect& projectileRect) {
    for (int i = 0; i < MAX_AMBIENT_VEHICLES; ++i) {
        const auto& v = g_vehicles[i];
        if (!v.active || v.health <= 0.0f) continue;
        if (VehiclePolygonIntersectsRect(VehicleCorners(v, v.x, v.y), projectileRect)) return i;
    }
    return -1;
}

static void VehicleApplyProjectileDamage(VehicleEntity& v, WeaponType type, Uint32 now, float hitX, float hitY) {
    if (!v.active || v.health <= 0.0f) return;
    const int damage = VehicleProjectileDamage(type);
    const int hitWheel=VehicleNearestWheelFromWorldPoint(v,hitX,hitY);
    const float wheelDamage=(type==WeaponType::ROCKET?34.0f:(type==WeaponType::LASER?14.0f:8.0f));
    VehicleDamageWheel(v,hitWheel,wheelDamage);
    TriggerVehicleCombatFeedback(hitX, hitY, static_cast<int>(v.health), hitX - v.x, hitY - v.y);
    v.health = std::max(0.0f, v.health - static_cast<float>(damage));
    if (type == WeaponType::FIRE_GUN && v.health > 0.0f)
        v.health = std::max(0.0f, v.health - 2.0f); // small heat/burn penalty
    if (v.health <= 0.0f) VehicleMarkForExplosion(v);
    VehicleVisual_OnDamage(v.x + v.rect.w*0.5f, v.y + v.rect.h*0.5f, static_cast<int>(v.health));
    (void)now;
}

static void VehicleUpdateRemoteDrivers(float dtSeconds,Uint32 now){
    if(!lanNetwork.hosting)return;
    VehicleHostProcessRemoteActions();
    for(int index=0;index<MAX_AMBIENT_VEHICLES;++index){
        auto& v=g_vehicles[index];if(!v.active||!v.occupied||v.driverId<=1)continue;
        float forward=0,steering=0;
        bool absoluteDirection=false;
        float directionAngle=0.0f;
        for(const auto& peer:lanNetwork.peers)if(peer.playerId==v.driverId){
            forward=peer.vehicleForward;steering=peer.vehicleSteering;
            absoluteDirection=peer.vehicleAbsoluteDirection;directionAngle=peer.vehicleDirectionAngle;break;
        }
        if(absoluteDirection) v.angle=directionAngle;
        VehicleDriveStep(v,forward,steering,dtSeconds,index,now);
        for(auto& rp:lanNetwork.remotePlayers)if(rp.id==v.driverId){rp.x=v.x+(v.rect.w-60)*.5f;rp.y=v.y+(v.rect.h-60)*.5f;break;}
    }
}

static void VehicleHostResolveDestroyed(float& localX,float& localY,SDL_Rect& player,int& localHp,Uint32 now){
    if(!lanNetwork.hosting)return;
    for(int i=0;i<MAX_AMBIENT_VEHICLES;++i){
        auto& v=g_vehicles[i];if(!v.active||!v.explosionPending)continue;
        const float bx=v.x+v.rect.w*.5f,by=v.y+v.rect.h*.5f,radius=v.type==VehicleType::TRUCK?190.0f:150.0f;
        const int base=v.type==VehicleType::TRUCK?70:55;
        for(auto& rp:lanNetwork.remotePlayers)if(rp.hp>0){const float d=std::hypot(rp.x+30.0f-bx,rp.y+30.0f-by);if(d<=radius){const int dmg=std::max(10,(int)std::lround(base*(1.0f-d/radius)));rp.hp=std::max(0,rp.hp-dmg);rp.dead=rp.hp<=0;}}
        const float pd=std::hypot(localX+player.w*.5f-bx,localY+player.h*.5f-by);if(localHp>0&&pd<=radius&&!playerIsInvulnerable){const int dmg=std::max(10,(int)std::lround(base*(1.0f-pd/radius)));localHp=std::max(0,localHp-dmg);}
        for(auto& exp:explosions)if(!exp.active){exp.x=bx;exp.y=by;exp.maxRadius=radius;exp.spawnTime=now;exp.duration=360;exp.active=true;break;}
        play_explosion_sound();v.active=false;v.occupied=false;v.driverId=-1;v.explosionPending=false;if(g_activeVehicle==i)g_activeVehicle=-1;
    }
}

static void VehicleBroadcastState(Uint32 now){
    if(!lanNetwork.hosting||now-lanNetwork.lastVehicleSnapshotAt<50)return;lanNetwork.lastVehicleSnapshotAt=now;
    std::string msg="VSTATE|"+std::to_string(lanNetwork.serverTick)+"|";bool first=true;
    for(int i=0;i<MAX_AMBIENT_VEHICLES;++i){const auto& v=g_vehicles[i];if(!v.active)continue;if(!first)msg+=';';first=false;
        msg+=std::to_string(i)+"|"+std::to_string((int)v.type)+"|"+std::to_string(v.x)+"|"+std::to_string(v.y)+"|"+std::to_string(v.vx)+"|"+std::to_string(v.vy)+"|"+std::to_string(v.angle)+"|"+std::to_string(v.health)+"|"+std::to_string(v.occupied?1:0)+"|"+std::to_string(v.driverId);}
    lan_broadcast_line(msg);
}

static bool VehicleNetworkFinite(float x){return std::isfinite(x)&&std::fabs(x)<10000000.0f;}

static void VehicleApplyNetworkState(const std::string& records){
    std::array<bool,MAX_AMBIENT_VEHICLES> seen{};std::stringstream rs(records);std::string rec;
    while(std::getline(rs,rec,';')){
        std::stringstream ps(rec);std::string si,st,sx,sy,svx,svy,sa,shp,so,sd;
        if(!std::getline(ps,si,'|')||!std::getline(ps,st,'|')||!std::getline(ps,sx,'|')||!std::getline(ps,sy,'|')||!std::getline(ps,svx,'|')||!std::getline(ps,svy,'|')||!std::getline(ps,sa,'|')||!std::getline(ps,shp,'|')||!std::getline(ps,so,'|')||!std::getline(ps,sd,'|'))continue;
        try{
            const int i=std::stoi(si);if(i<0||i>=MAX_AMBIENT_VEHICLES)continue;auto& v=g_vehicles[i];const int type=std::clamp(std::stoi(st),0,2);
            const float nx=std::stof(sx),ny=std::stof(sy),nvx=std::stof(svx),nvy=std::stof(svy),na=std::stof(sa),nh=std::stof(shp);
            if(!VehicleNetworkFinite(nx)||!VehicleNetworkFinite(ny)||!VehicleNetworkFinite(nvx)||!VehicleNetworkFinite(nvy)||!VehicleNetworkFinite(na)||!VehicleNetworkFinite(nh))continue;
            v.active=true;v.type=(VehicleType)type;v.x=nx;v.y=ny;v.vx=nvx;v.vy=nvy;v.angle=na;v.health=std::clamp(nh,0.0f,300.0f);VehicleSpawnSize(v.type,v.rect.w,v.rect.h);v.maxHealth=v.type==VehicleType::TRUCK?160.0f:v.type==VehicleType::BUGGY?80.0f:100.0f;v.rect.x=(int)std::lround(v.x);v.rect.y=(int)std::lround(v.y);v.occupied=std::stoi(so)!=0;v.driverId=std::stoi(sd);seen[i]=true;if(v.driverId==lanNetwork.localPlayerId)g_activeVehicle=i;
        }catch(...){ }
    }
    for(int i=0;i<MAX_AMBIENT_VEHICLES;++i)if(!seen[i]){if(g_activeVehicle==i)g_activeVehicle=-1;g_vehicles[i].active=false;g_vehicles[i].occupied=false;g_vehicles[i].driverId=-1;}
}

static void VehicleHostApplyRemotePlayerCollisions(Uint32 now){
    if(!lanNetwork.hosting)return;
    for(int i=0;i<MAX_AMBIENT_VEHICLES;++i){const auto& v=g_vehicles[i];if(!v.active)continue;for(auto& rp:lanNetwork.remotePlayers){if(rp.hp<=0||rp.dead||rp.id==v.driverId)continue;SDL_Rect target{(int)rp.x,(int)rp.y,60,60};const int before=rp.hp;VehicleDamagePlayerRect(v,target,rp.hp,now,i);if(rp.hp<before){rp.dead=rp.hp<=0;if(rp.hp<=0)rp.deaths++;}}}
}

// Arrow-key driving is intentionally arcade-style and supports all 8 directions.
// A single arrow selects a cardinal direction; two arrows held together select the
// corresponding diagonal. The vehicle faces the selected direction and accelerates
// there, so RIGHT/LEFT/DOWN are movement directions too (not only steering).
static bool VehicleGetArrow8Direction(const Uint8* keyboard,float& dx,float& dy){
    // The explicit event flags are the primary source. SDL_GetKeyboardState is
    // also checked as a fallback, so arrow input works whether SDL delivered a
    // normal key event this frame or only updated its keyboard state.
    // Support BOTH physical arrow keys and the large on-screen 8-way D-pad.
    // The D-pad state was previously only used by shooting, so tapping the
    // visible arrows did not reach vehicle movement at all.
    const bool up = g_vehicleKeyUp || (keyboard && keyboard[SDL_SCANCODE_UP]) ||
                    dpadUpPressed || dpadUpLeftPressed || dpadUpRightPressed;
    const bool down = g_vehicleKeyDown || (keyboard && keyboard[SDL_SCANCODE_DOWN]) ||
                      dpadDownPressed || dpadDownLeftPressed || dpadDownRightPressed;
    const bool left = g_vehicleKeyLeft || (keyboard && keyboard[SDL_SCANCODE_LEFT]) ||
                      dpadLeftPressed || dpadUpLeftPressed || dpadDownLeftPressed;
    const bool right = g_vehicleKeyRight || (keyboard && keyboard[SDL_SCANCODE_RIGHT]) ||
                       dpadRightPressed || dpadUpRightPressed || dpadDownRightPressed;

    dx=(right?1.0f:0.0f)-(left?1.0f:0.0f);
    dy=(down?1.0f:0.0f)-(up?1.0f:0.0f);
    if(std::fabs(dx)<0.01f && std::fabs(dy)<0.01f) return false;
    const float len=std::hypot(dx,dy);
    if(len>0.001f){dx/=len;dy/=len;}
    return true;
}

static void VehicleUpdateAmbientAI(float dtSeconds, float playerX, float playerY, Uint32 now){
    if(useCustomMap) return;
    static Uint32 seed = 0x51A17E57u;
    auto rnd=[&](){ seed ^= seed<<13; seed ^= seed>>17; seed ^= seed<<5; return (seed & 0xFFFFu)/65535.0f; };
    for(int i=0;i<MAX_AMBIENT_VEHICLES;++i){
        auto& v=g_vehicles[i];
        if(!v.active || !v.aiControlled || v.occupied || v.health<=0.0f) continue;
        v.aiRetargetTimer-=dtSeconds;
        const float dx=v.aiTargetX-(v.x+v.rect.w*0.5f);
        const float dy=v.aiTargetY-(v.y+v.rect.h*0.5f);
        if(v.aiRetargetTimer<=0.0f || std::hypot(dx,dy)<180.0f){
            // Keep AI traffic well away from the player and choose another safe-ish
            // point around the map. The map collision step remains authoritative.
            const float angle=rnd()*6.2831853f;
            const float dist=650.0f+rnd()*850.0f;
            v.aiTargetX=std::clamp(playerX+std::cos(angle)*dist, 120.0f, currentMapCols*TILE_SIZE-120.0f);
            v.aiTargetY=std::clamp(playerY+std::sin(angle)*dist, 120.0f, currentMapRows*TILE_SIZE-120.0f);
            v.aiRetargetTimer=4.0f+rnd()*5.0f;
        }
        const float targetAngle=std::atan2(dy,dx)-static_cast<float>(M_PI)*0.5f;
        float turn=targetAngle-v.angle;
        while(turn>static_cast<float>(M_PI)) turn-=static_cast<float>(2*M_PI);
        while(turn<-static_cast<float>(M_PI)) turn+=static_cast<float>(2*M_PI);
        const float steering=std::clamp(turn/(0.9f+std::fabs(turn)), -1.0f, 1.0f);
        const float distanceToPlayer=std::hypot(playerX-(v.x+v.rect.w*.5f),playerY-(v.y+v.rect.h*.5f));
        const float forward=(distanceToPlayer<500.0f)?0.15f:1.0f;
        VehicleDriveStep(v,forward,steering,dtSeconds,i,now);
    }
}

static void VehicleUpdate(float dtSeconds,const Uint8* keyboard,float touchMoveX,float touchMoveY,bool touchInteract,
                           float& playerPosX,float& playerPosY,SDL_Rect& player,int& playerHp,int localPlayerId=0){
    if(!std::isfinite(dtSeconds)||dtSeconds<=0)return;dtSeconds=std::min(dtSeconds,.10f);VehicleSpawnSavedMapVehicles();VehicleEnsureMapVehicles();VehicleUpdateTireEffects(dtSeconds);
    const bool enterPressed=(keyboard&&keyboard[SDL_SCANCODE_E])||touchInteract;
    if(enterPressed&&!g_vehicleEnterLatch){
        if(lanNetwork.connected&&!lanNetwork.hosting){lan_send_line(lanNetwork.clientSocket,std::string("VEHINPUT|0|0|")+(g_activeVehicle>=0?"2":"1")+"|"+std::to_string(++lanNetwork.localVehInputSeq));}
        else if(g_activeVehicle>=0) VehicleExitPlayer(playerPosX,playerPosY,player);
        else VehicleEnterPlayer(playerPosX,playerPosY,localPlayerId);
    }
    g_vehicleEnterLatch=enterPressed;

    if(lanNetwork.connected&&!lanNetwork.hosting){
        float f=0,s=0;
        float arrowDx=0.0f,arrowDy=0.0f;
        const bool arrow8=VehicleGetArrow8Direction(keyboard,arrowDx,arrowDy);
        if(arrow8){
            // Network input remains compact: forward=1, steering carries the
            // requested 8-way heading as a normalized angle in [-1,1].
            f=1.0f;
            s=std::atan2(arrowDx,-arrowDy)/static_cast<float>(M_PI);
        }else if(keyboard){
            if(keyboard[SDL_SCANCODE_W]) f+=1;
            if(keyboard[SDL_SCANCODE_S]) f-=1;
            if(keyboard[SDL_SCANCODE_D]) s+=1;
            if(keyboard[SDL_SCANCODE_A]) s-=1;
        }
        // On touch devices the left movement joystick becomes the vehicle
        // throttle/steering control while occupied: vertical = throttle,
        // horizontal = steering. Values are normalized by the main loop.
        // Combine dock + arrows so both can be used simultaneously.
        if(std::fabs(touchMoveX)>0.01f||std::fabs(touchMoveY)>0.01f){
            if(arrow8){
                arrowDx += touchMoveX;
                arrowDy += touchMoveY;
                const float l=std::hypot(arrowDx,arrowDy);
                if(l>0.01f){ arrowDx/=l; arrowDy/=l; }
                f=1.0f;
                s=0.0f;
            } else {
                f += -touchMoveY;
                s += touchMoveX;
            }
        }
        f=std::clamp(f,-1.0f,1.0f);
        s=std::clamp(s,-1.0f,1.0f);
        const Uint32 now=SDL_GetTicks();
        if(g_activeVehicle>=0&&now-lanNetwork.lastVehicleInputSentAt>=50){
            lanNetwork.lastVehicleInputSentAt=now;
            if(arrow8) lan_send_line(lanNetwork.clientSocket,"VEHINPUT|"+std::to_string(f)+"|0|0|"+std::to_string(++lanNetwork.localVehInputSeq)+"|"+std::to_string(lanNetwork.localGameplayGeneration)+"|"+std::to_string(std::atan2(arrowDx,-arrowDy)));
            else lan_send_line(lanNetwork.clientSocket,"VEHINPUT|"+std::to_string(f)+"|"+std::to_string(s)+"|0|"+std::to_string(++lanNetwork.localVehInputSeq)+"|"+std::to_string(lanNetwork.localGameplayGeneration));
        }
        if(g_activeVehicle>=0&&g_activeVehicle<MAX_AMBIENT_VEHICLES){const auto& v=g_vehicles[g_activeVehicle];playerPosX=v.x+(v.rect.w-player.w)*.5f;playerPosY=v.y+(v.rect.h-player.h)*.5f;player.x=(int)std::lround(playerPosX);player.y=(int)std::lround(playerPosY);}return;
    }

    const Uint32 now=SDL_GetTicks();
    if(g_activeVehicle>=0&&g_activeVehicle<MAX_AMBIENT_VEHICLES){
        VehicleEntity& v=g_vehicles[g_activeVehicle];if(!v.active||!v.occupied){g_activeVehicle=-1;return;}
        float f=0,s=0;
        float arrowDx=0.0f,arrowDy=0.0f;
        const bool arrow8=VehicleGetArrow8Direction(keyboard,arrowDx,arrowDy);
        if(arrow8){
            // Eight-way arcade driving: one arrow gives a cardinal heading and
            // two held arrows give a normalized diagonal heading. The vehicle
            // immediately drives toward that world direction; arrow keys do not
            // depend on the WASD steering path.
            v.angle=std::atan2(arrowDx,-arrowDy);
            f=1.0f;
            s=0.0f;
        }else if(keyboard){
            if(keyboard[SDL_SCANCODE_W]) f+=1;
            if(keyboard[SDL_SCANCODE_S]) f-=1;
            if(keyboard[SDL_SCANCODE_D]) s+=1;
            if(keyboard[SDL_SCANCODE_A]) s-=1;
        }
        // On touch devices the left movement joystick becomes the vehicle
        // throttle/steering control while occupied: vertical = throttle,
        // horizontal = steering. Values are normalized by the main loop.
        // Combine the touch dock and arrow controls instead of letting one cancel
        // the other.  The dock contributes a world-direction vector, while arrows
        // contribute another world-direction vector.  Both can be held at once.
        float inputX = arrow8 ? arrowDx : 0.0f;
        float inputY = arrow8 ? arrowDy : 0.0f;
        if(std::fabs(touchMoveX)>0.01f || std::fabs(touchMoveY)>0.01f){
            // Dock: X is right, Y is down. Convert to the same world vector used
            // by the 8-way arrows.
            inputX += touchMoveX;
            inputY += touchMoveY;
        }
        const float inputLen = std::hypot(inputX,inputY);
        if(inputLen > 0.01f){
            inputX /= std::max(1.0f,inputLen);
            inputY /= std::max(1.0f,inputLen);
            v.angle = std::atan2(inputX,-inputY);
            // Full throttle for any active combined direction.
            f = 1.0f;
            s = 0.0f;
        } else if(keyboard){
            if(keyboard[SDL_SCANCODE_W]) f+=1;
            if(keyboard[SDL_SCANCODE_S]) f-=1;
            if(keyboard[SDL_SCANCODE_D]) s+=1;
            if(keyboard[SDL_SCANCODE_A]) s-=1;
        }
        f=std::clamp(f,-1.0f,1.0f);
        s=std::clamp(s,-1.0f,1.0f);
        VehicleDriveStep(v,f,s,dtSeconds,g_activeVehicle,now);

        // Arrow/dock driving gets a responsive arcade velocity assist.  The
        // previous tire-force model could take too long to build speed from a
        // digital button, making the vehicle feel slow even with a high maxSpeed.
        if(inputLen > 0.01f){
            const float targetSpeed = v.maxSpeed;
            const float targetVX = inputX * targetSpeed;
            const float targetVY = inputY * targetSpeed;
            const float response = 1.0f - std::exp(-dtSeconds * 7.5f);
            v.vx += (targetVX - v.vx) * response;
            v.vy += (targetVY - v.vy) * response;
        }
        playerPosX=v.x+(v.rect.w-player.w)*.5f;playerPosY=v.y+(v.rect.h-player.h)*.5f;player.x=(int)std::lround(playerPosX);player.y=(int)std::lround(playerPosY);
        VehicleVisual_OnDrive(v.x + v.rect.w*0.5f, v.y + v.rect.h*0.75f, std::hypot(v.vx, v.vy));
        if(v.explosionPending)VehicleApplyExplosion(v,playerPosX,playerPosY,player,playerHp,now);
    }
    VehicleUpdateAmbientAI(dtSeconds, playerPosX + player.w*0.5f, playerPosY + player.h*0.5f, now);
    if(lanNetwork.hosting)VehicleUpdateRemoteDrivers(dtSeconds,now);

    for(int i=0;i<MAX_AMBIENT_VEHICLES;++i){auto& v=g_vehicles[i];if(!v.active||(v.occupied&&v.driverId==localPlayerId))continue;if(!lanNetwork.hosting&&lanNetwork.connected)continue;VehicleDamagePlayerRect(v,player,playerHp,now,i);}
    if(lanNetwork.hosting)VehicleBroadcastState(now);
}

static void VehicleEndForMap() {
    VehicleReset();
    vehicleParticles.clear();
    vehicleTracers.clear();
}



// ===== CONSOLIDATED VEHICLE VISUAL SYSTEM =====
// One implementation only: sprite assets are optional; the built-in pixel vehicle
// renderer remains the fallback, so the game still runs without external assets.
static SDL_Texture* g_carVehicleTexture = nullptr;
static SDL_Texture* g_truckVehicleTexture = nullptr;
static SDL_Texture* g_buggyVehicleTexture = nullptr;

// Draw textures without assuming the device is landscape. SDL's logical
// renderer coordinates are always SCREEN_WIDTH x SCREEN_HEIGHT; SDL scales
// the result to the current Android display orientation.
static SDL_Rect FitTexture(SDL_Texture* texture, int cx, int cy, int maxW, int maxH) {
    SDL_Rect r{cx - maxW / 2, cy - maxH / 2, maxW, maxH};
    if (!texture) return r;

    int tw = 0, th = 0;
    if (SDL_QueryTexture(texture, nullptr, nullptr, &tw, &th) == 0 && tw > 0 && th > 0) {
        const float scale = std::min(static_cast<float>(maxW) / tw,
                                     static_cast<float>(maxH) / th);
        r.w = std::max(1, static_cast<int>(tw * scale));
        r.h = std::max(1, static_cast<int>(th * scale));
        r.x = cx - r.w / 2;
        r.y = cy - r.h / 2;
    }
    return r;
}

static SDL_Texture* LoadVehicleTexture(SDL_Renderer* renderer, const char* path) {
    if (!renderer || !path) return nullptr;
    SDL_Surface* surface = IMG_Load(path);
    if (!surface) return nullptr;
    SDL_Texture* tex = SDL_CreateTextureFromSurface(renderer, surface);
    SDL_FreeSurface(surface);
    return tex;
}

static SDL_Texture* VehicleTextureFor(VehicleType type) {
    switch (type) {
        case VehicleType::TRUCK: return g_truckVehicleTexture;
        case VehicleType::BUGGY: return g_buggyVehicleTexture;
        default:                 return g_carVehicleTexture;
    }
}

// Lightweight readability overlay drawn on top of the sprite texture:
// night headlight/taillight glow, damage smudges, and the occupied
// driver indicator. Mirrors the equivalent cues in VehicleRender()
// without redrawing the full pixel-art body.
static void VehicleRenderTextureOverlay(SDL_Renderer* renderer, const VehicleEntity& v,
                                        float cameraX, float cameraY) {
    const float cx = v.x + v.rect.w * 0.5f - cameraX;
    const float cy = v.y + v.rect.h * 0.5f - cameraY;
    const float a = v.angle;
    const float c = std::cos(a), s = std::sin(a);
    auto P = [&](float x, float y) -> SDL_Point {
        return SDL_Point{static_cast<int>(std::lround(cx + x*c - y*s)),
                         static_cast<int>(std::lround(cy + x*s + y*c))};
    };
    const float W = v.rect.w * 0.94f, H = v.rect.h * 0.94f;
    const VehicleDamageState ds = VehicleGetDamageState(v);
    const float night = DayNightNightFactor();

    SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);

    // Headlight glow bloom at night (texture already has painted lamps).
    if (night > 0.04f) {
        for (int side = -1; side <= 1; side += 2) {
            SDL_Point pt = P(side * W * 0.25f, -H * 0.47f);
            SDL_SetRenderDrawColor(renderer, 255, 250, 204, static_cast<Uint8>(150 * night));
            SDL_Rect glow{pt.x - 3, pt.y - 3, 6, 6};
            SDL_RenderFillRect(renderer, &glow);
        }
    }

    // Damage visuals layered over the sprite, progressing across the four
    // states like the reference sheet (scratches -> dents+cracked glass ->
    // scorch marks+heavier cracks). A per-vehicle seed keeps the pattern
    // stable frame-to-frame instead of flickering, while varying between
    // vehicles so they don't all show identical damage in the same spots.
    const std::ptrdiff_t vSlot = &v - &g_vehicles[0];
    auto seeded = [&](int salt) -> float {
        uint32_t h = static_cast<uint32_t>(vSlot) * 2654435761u + static_cast<uint32_t>(salt) * 40503u + 12345u;
        h ^= h >> 13; h *= 2654435761u; h ^= h >> 16;
        return static_cast<float>(h % 1000) / 1000.0f; // 0..1
    };

    if (ds >= VehicleDamageState::LIGHT) {
        // A few scuff scratches, position/length jittered per vehicle.
        for (int i = 0; i < 3; ++i) {
            const float jx = (seeded(i * 3 + 1) - 0.5f) * W * 0.5f;
            const float jy = (seeded(i * 3 + 2) - 0.5f) * H * 0.6f;
            const float len = 0.10f + seeded(i * 3 + 3) * 0.12f;
            SDL_Point p1 = P(jx, jy);
            SDL_Point p2 = P(jx + W * len, jy + H * len * 0.4f);
            SDL_SetRenderDrawColor(renderer, 210, 205, 195, 90);
            SDL_RenderDrawLine(renderer, p1.x, p1.y, p2.x, p2.y);
        }
        // Small dirt specks.
        for (int i = 0; i < 3; ++i) {
            const float dx = (seeded(i + 20) - 0.5f) * W * 0.7f;
            const float dy = (seeded(i + 30) - 0.5f) * H * 0.7f;
            SDL_Point p = P(dx, dy);
            SDL_SetRenderDrawColor(renderer, 90, 78, 60, 90);
            SDL_Rect pr{p.x - 1, p.y - 1, 2, 2};
            SDL_RenderFillRect(renderer, &pr);
        }
    }

    if (ds >= VehicleDamageState::HEAVY) {
        // Dark dent blotches.
        for (int i = 0; i < 3; ++i) {
            const float dx = (seeded(i + 40) - 0.5f) * W * 0.6f;
            const float dy = (seeded(i + 50) - 0.5f) * H * 0.7f;
            const int r = 3 + static_cast<int>(seeded(i + 60) * 3.0f);
            SDL_Point p = P(dx, dy);
            SDL_SetRenderDrawColor(renderer, 32, 30, 27, 150);
            SDL_Rect pr{p.x - r, p.y - r, r * 2, r * 2};
            SDL_RenderFillRect(renderer, &pr);
        }
        // Cracked windshield: a few connecting fracture lines near the glass.
        SDL_Point g0 = P(0.0f, -H * 0.08f);
        for (int i = 0; i < 3; ++i) {
            const float ang = seeded(i + 70) * 6.2831853f;
            const float len = W * (0.10f + seeded(i + 80) * 0.08f);
            SDL_Point g1 = P(std::cos(ang) * len, -H * 0.08f + std::sin(ang) * len);
            SDL_SetRenderDrawColor(renderer, 210, 220, 222, 130);
            SDL_RenderDrawLine(renderer, g0.x, g0.y, g1.x, g1.y);
        }
    }

    if (ds == VehicleDamageState::CRITICAL) {
        // Blackened scorch patches, larger and darker than the dents above.
        for (int i = 0; i < 4; ++i) {
            const float dx = (seeded(i + 90) - 0.5f) * W * 0.65f;
            const float dy = (seeded(i + 100) - 0.5f) * H * 0.75f;
            const int r = 5 + static_cast<int>(seeded(i + 110) * 5.0f);
            SDL_Point p = P(dx, dy);
            SDL_SetRenderDrawColor(renderer, 18, 16, 15, 160);
            SDL_Rect pr{p.x - r, p.y - r, r * 2, r * 2};
            SDL_RenderFillRect(renderer, &pr);
        }
        // Pulsing ember glow under the damaged hood, subtle and slow.
        const float pulse = 0.5f + 0.5f * std::sin(static_cast<float>(SDL_GetTicks()) * 0.006f);
        SDL_Point hood = P(0.0f, -H * 0.30f);
        SDL_SetRenderDrawColor(renderer, 255, 110, 40, static_cast<Uint8>(70.0f + 70.0f * pulse));
        SDL_Rect ember{hood.x - 3, hood.y - 3, 6, 6};
        SDL_RenderFillRect(renderer, &ember);
    }

    // Occupied driver indicator: keep the reference sheet's green block.
    if (v.occupied && g_activeVehicle >= 0 && &v == &g_vehicles[g_activeVehicle]) {
        SDL_Point o = P(0, -H*.02f);
        SDL_SetRenderDrawColor(renderer, 35, 205, 78, 255);
        SDL_Rect outer{o.x-5, o.y-5, 11, 11};
        SDL_RenderFillRect(renderer, &outer);
        SDL_SetRenderDrawColor(renderer, 120, 255, 155, 255);
        SDL_Rect inner{o.x-3, o.y-3, 6, 6};
        SDL_RenderFillRect(renderer, &inner);
    }

    SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_NONE);
}

static void DrawVehicleSpriteLayer(SDL_Renderer* renderer, SDL_Texture* texture,
                                   const VehicleEntity& v, float cameraX, float cameraY) {
    if (!renderer || !texture || !v.active) return;
    SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);
    SDL_SetRenderDrawColor(renderer, 0, 0, 0, 90);
    SDL_Rect shadow{static_cast<int>(v.x-cameraX+4), static_cast<int>(v.y-cameraY+7),
                     static_cast<int>(v.rect.w*0.96f), static_cast<int>(v.rect.h*0.96f)};
    SDL_RenderFillRect(renderer, &shadow);
    SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_NONE);

    SDL_Rect dst{static_cast<int>(v.x-cameraX), static_cast<int>(v.y-cameraY), v.rect.w, v.rect.h};
    // VehicleEntity angle 0 points up; SDL's 0-degree texture orientation points right.
    const double degrees = -(static_cast<double>(v.angle) * 180.0 / M_PI) + 90.0;
    SDL_RenderCopyEx(renderer, texture, nullptr, &dst, degrees, nullptr, SDL_FLIP_NONE);
    VehicleRenderTextureOverlay(renderer, v, cameraX, cameraY);
}



int main(int /*argc*/, char* /*argv*/[]) {
    std::srand(static_cast<unsigned int>(std::time(nullptr)));

    // Allow Android to follow the device's physical orientation. Keep this
    // before SDL_Init so SDL's Android activity can request all orientations.
#if defined(__ANDROID__)
    SDL_SetHint(SDL_HINT_ORIENTATIONS,
                "LandscapeLeft LandscapeRight Portrait PortraitUpsideDown");
    SDL_SetHint(SDL_HINT_ANDROID_TRAP_BACK_BUTTON, "0");
#endif

    // On touch platforms SDL by default synthesizes a mouse event for every
    // finger event (and vice versa), so a single tap could fire both
    // SDL_FINGERDOWN and SDL_MOUSEBUTTONDOWN for the same touch. Every place
    // in this file that checks "MOUSEBUTTONDOWN || FINGERDOWN" would then run
    // twice per tap - e.g. the enemy-count '+' button jumping 1 -> 3 instead
    // of 1 -> 2. Disable the cross-synthesis so each physical tap is exactly
    // one event. Must be set before SDL_Init.
    SDL_SetHint(SDL_HINT_MOUSE_TOUCH_EVENTS, "0");
    SDL_SetHint(SDL_HINT_TOUCH_MOUSE_EVENTS, "0");

    // Batch consecutive draw calls (fills/lines/points of the same type) into
    // a single GPU submission instead of one draw call each. This is off by
    // default on some builds and is the single biggest lever for busy scenes
    // (many enemies/bullets/particles each issuing their own small fills and
    // lines) on Android GPUs, which are far more sensitive to draw-call count
    // than desktop GPUs are. Must be set before the renderer is created.
    SDL_SetHint(SDL_HINT_RENDER_BATCHING, "1");

    // Android-safe SDL startup. Video is mandatory; audio is optional.
    // IMPORTANT: never let an audio driver failure terminate the application.
    if (SDL_Init(SDL_INIT_VIDEO) != 0) {
        std::cerr << "SDL video initialization failed: " << SDL_GetError() << std::endl;
        return 1;
    }

    // Audio is initialized separately so a device/audio-policy failure cannot
    // tear down the already-working Android video subsystem.
    if (SDL_InitSubSystem(SDL_INIT_AUDIO) != 0) {
        audioDevice = 0;
        std::cerr << "SDL audio unavailable (continuing silently): " << SDL_GetError() << std::endl;
    }

    const int imgFlags = IMG_INIT_PNG | IMG_INIT_JPG;
    if ((IMG_Init(imgFlags) & imgFlags) != imgFlags) {
        // Images are optional at startup; continue rather than exiting.
    }

    if (char* prefPath = SDL_GetPrefPath("TacticalShooterEngine", "SaveData")) {
        mapFilePath = std::string(prefPath) + "custom_map.txt";
        SDL_free(prefPath);
    }
    ensure_portrait_directory();

    audioSpec.freq = 44100;
    audioSpec.format = AUDIO_S16SYS;
    audioSpec.channels = 1;
    audioSpec.samples = 1024;
    audioSpec.callback = audio_callback;

    // Opening audio is optional. On Android, another app/device audio policy
    // can reject the device; in that case keep audioDevice == 0 and continue.
    if (SDL_WasInit(SDL_INIT_AUDIO) != 0) {
        audioDevice = SDL_OpenAudioDevice(nullptr, 0, &audioSpec, nullptr, 0);
        if (audioDevice != 0) {
            SDL_PauseAudioDevice(audioDevice, 0);
        }
    }

    // SDL Android owns the real native surface. Do not request desktop-only
    // window behaviour; SHOWN/FULLSCREEN is safe for phones and tablets.
    Uint32 windowFlags = SDL_WINDOW_SHOWN;
#if defined(__ANDROID__)
    windowFlags |= SDL_WINDOW_FULLSCREEN;
#endif
    SDL_Window* window = SDL_CreateWindow(
        "Tactical Shooter Engine",
        SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
        SCREEN_WIDTH, SCREEN_HEIGHT, windowFlags);

    if (!window) {
        if (audioDevice != 0) SDL_CloseAudioDevice(audioDevice);
        IMG_Quit();
        SDL_Quit();
        return 1;
    }

    // Prefer hardware rendering, but fall back to software rendering on
    // Android devices whose GPU/driver rejects the accelerated renderer.
    SDL_Renderer* renderer = nullptr;
#if defined(__ANDROID__)
    // Try accelerated rendering first, then software. The explicit fallback
    // prevents an Android GPU/driver that rejects acceleration from closing
    // the application at startup.
    renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED | SDL_RENDERER_PRESENTVSYNC);
    if (!renderer) renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
#else
    renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
#endif
    if (!renderer) renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_SOFTWARE);

    if (!renderer) {
        SDL_DestroyWindow(window);
        if (audioDevice != 0) SDL_CloseAudioDevice(audioDevice);
        IMG_Quit();
        SDL_Quit();
        return 1;
    }
    // Optional external vehicle sprites. The built-in renderer remains the fallback.
    g_carVehicleTexture   = LoadVehicleTexture(renderer, "vehicles/car.png");
    g_truckVehicleTexture = LoadVehicleTexture(renderer, "vehicles/truck.png");
    g_buggyVehicleTexture = LoadVehicleTexture(renderer, "vehicles/buggy.png");

    // Optional spoken voice lines for squad commands and player-action
    // callouts (weapon switch, quick-swap, shield). Missing files are fine -
    // every action still works, its line just stays silent.
    load_all_voice_clips();

    // Use a fixed 2000x1200 game coordinate system while allowing SDL to
    // scale it to whatever portrait/landscape display the phone provides.
    // Do not force the physical window to 2000x1200.
    SDL_RenderSetLogicalSize(renderer, SCREEN_WIDTH, SCREEN_HEIGHT);
    SDL_RenderSetIntegerScale(renderer, SDL_FALSE);

    // Let SDL expose the real drawable size. This is useful on phones with
    // notches, high-density displays and unusual aspect ratios.
    int drawableW = 0;
    int drawableH = 0;
    SDL_GetRendererOutputSize(renderer, &drawableW, &drawableH);
    if (drawableW > 0 && drawableH > 0) {
        SDL_RenderSetViewport(renderer, nullptr);
    }

    lan_init_network();
    refresh_weapon_radial();
    refresh_map_list();

    float playerPosX = 5 * TILE_SIZE + 10, playerPosY = 5 * TILE_SIZE + 10;
    SDL_Rect player = { static_cast<int>(playerPosX), static_cast<int>(playerPosY), 60, 60 };

    SDL_Rect dockBase = {0, 0, 200, 200}, dockHandle = {0, 0, 60, 60};
    int dockCenterX = 0, dockCenterY = 0;
    bool isTouchingDock = false;
    float moveVecX = 0.0f, moveVecY = 0.0f;
    float joystickMagnitude = 0.0f; // 0..1, how far the stick is deflected from center

    // --- Long-press joystick dodge roll + double-tap arrow dash: shared dash state ---
    float joystickHoldTimer = 0.0f;
    bool isDashing = false;
    float dashDirX = 0.0f, dashDirY = 0.0f;
    float dashDurationSetting = DOUBLE_TAP_DASH_DURATION;
    Uint32 dashStartedAt = 0;
    float dashCooldown = 0.0f;      // seconds remaining before another dash/roll can trigger
    bool canShoot = true;           // disabled while dashing
    Uint32 lastDashTriggeredAt = 0; // drives the post-roll tint flash
    // Simple afterimage ghost trail: last few player positions while dashing.
    struct GhostFrame { float x, y; Uint32 t; };
    std::array<GhostFrame, 6> dashGhosts{};
    int dashGhostCount = 0;
    Uint32 lastGhostSpawnAt = 0;

    // Double-tap arrow key detection (UP, DOWN, LEFT, RIGHT), independent of the
    // held-key shooting logic below - a quick double press bursts a dash instead.
    Uint32 lastArrowTapTime[4] = {0, 0, 0, 0}; // 0=UP,1=DOWN,2=LEFT,3=RIGHT

    // Touch d-pad: tracks which finger pressed each button so a finger dragging off
    // the button (or lifting elsewhere) still releases it correctly instead of
    // leaving the direction "stuck" pressed - fixes the sticky arrow-key touch bug.
    // Eight-way pad finger IDs are declared with the pad state above.

    load_progress(); // restore lifetime progress and first-run tutorial state

    // TEMPORARY TEST MODE: unlock every weapon after loading the save.
    // This does not change the real purchase rules in is_weapon_locked();
    // simply switch TEST_UNLOCK_ALL_WEAPONS to false to restore normal locks.
    if (TEST_UNLOCK_ALL_WEAPONS) {
        weaponRifleUnlocked = true;
        weaponRocketUnlocked = true;
        premiumVectorReflectUnlocked = true;
        premiumLaserUnlocked = true;
        premiumFireGunUnlocked = true;
        premiumIceGunUnlocked = true;
        coinMagnetOwned = true;
    }

    // The tutorial is shown only when the saved tutorial-completed flag is false.
    // Existing PROGRESS 2 saves intentionally fall into this path once.
    // Do not show the tutorial automatically in the background. It opens only when the Help button is pressed.
    bool showFirstRunTutorial = false;

    // Re-add previously unlocked weapons, but never exceed the four-slot
    // Blender-style pie-menu loadout.
    if (weaponRifleUnlocked && !is_weapon_equipped(WeaponType::RIFLE) && playerWeaponState.equippedCount < 4)
        playerWeaponState.equipped[playerWeaponState.equippedCount++] = WeaponType::RIFLE;
    if (weaponRocketUnlocked && !is_weapon_equipped(WeaponType::ROCKET) && playerWeaponState.equippedCount < 4)
        playerWeaponState.equipped[playerWeaponState.equippedCount++] = WeaponType::ROCKET;
    if (premiumVectorReflectUnlocked && !is_weapon_equipped(WeaponType::VECTOR_REFLECT) && playerWeaponState.equippedCount < 4)
        playerWeaponState.equipped[playerWeaponState.equippedCount++] = WeaponType::VECTOR_REFLECT;
    if (premiumLaserUnlocked && !is_weapon_equipped(WeaponType::LASER) && playerWeaponState.equippedCount < 4)
        playerWeaponState.equipped[playerWeaponState.equippedCount++] = WeaponType::LASER;
    if (premiumFireGunUnlocked && !is_weapon_equipped(WeaponType::FIRE_GUN) && playerWeaponState.equippedCount < 4)
        playerWeaponState.equipped[playerWeaponState.equippedCount++] = WeaponType::FIRE_GUN;
    if (premiumIceGunUnlocked && !is_weapon_equipped(WeaponType::ICE_GUN) && playerWeaponState.equippedCount < 4)
        playerWeaponState.equipped[playerWeaponState.equippedCount++] = WeaponType::ICE_GUN;
    if (TEST_UNLOCK_ALL_WEAPONS && !is_weapon_equipped(WeaponType::WIND_GUN) && playerWeaponState.equippedCount < 4)
        playerWeaponState.equipped[playerWeaponState.equippedCount++] = WeaponType::WIND_GUN;
    if (TEST_UNLOCK_ALL_WEAPONS && !is_weapon_equipped(WeaponType::COIN_MAGNET) && playerWeaponState.equippedCount < 4)
        playerWeaponState.equipped[playerWeaponState.equippedCount++] = WeaponType::COIN_MAGNET;

    // The radial/Blender-style pie menu was refreshed before load_progress()
    // and before the unlocked weapons were rebuilt into the equipped array.
    // That left the game state showing weapons as EQUIPPED in the weapon menu
    // while the in-game pie menu still contained its old PISTOL-only slots.
    // Rebuild the four visible radial slots after the final loadout is known.
    refresh_weapon_radial();

    bool running = true;
    Uint32 lastShootTime = 0;
    Uint32 lastFrameTime = SDL_GetTicks();
    weather_begin(lastFrameTime);
    SDL_Event event;

    while (running) {
        lan_network_poll(SDL_GetTicks());
        Uint32 currentTime = SDL_GetTicks();
        update_pending_player_command(currentTime);
        update_bot_response_queue(currentTime);
        
        float deltaTime = static_cast<float>(currentTime - lastFrameTime) / 1000.0f;
        if (deltaTime > 0.1f) deltaTime = 0.1f; // clamp huge frame hitches (e.g. window drag)
        lastFrameTime = currentTime;
        UpdateVehicleEffects(deltaTime);
        UpdateVehicleDestructionEffects(deltaTime);
        UpdateVisualTracers(deltaTime);

        // Flush accumulated coin pickups in one small write rather than
        // blocking the render thread once for every coin in a cluster.
        if (progressSavePending &&
            (lastProgressSaveAt == 0 || currentTime - lastProgressSaveAt >= 1000)) {
            if (save_progress()) progressSavePending = false;
            lastProgressSaveAt = currentTime;
        }

        // Always tick down the coin-conversion animation here, not just while
        // the profile panel happens to be on screen. render_player_profile()
        // only runs while the player is viewing MODE_SELECTION, so if the
        // timeout lived only there, navigating away mid-animation left
        // coinRewardAnimationActive stuck true forever - which then silently
        // blocked award_completed_run_coins() (it bails out whenever
        // coinRewardAnimationActive is true) from ever granting coins again.
        if (coinRewardAnimationActive &&
            currentTime - coinRewardAnimationStartedAt >= 4200) {
            coinRewardAnimationActive = false;
            coinRewardDisplayCoins = coinRewardScoreCoins + coinRewardHighScoreBonus;
            coinRewardDisplayScore = score;
            // The previous reward is completely finished. A later completed
            // run is now free to create a fresh pending reward.
        }

#if defined(__ANDROID__)
        // Pick up any image the player selected via Android's system photo
        // picker since last frame (MainActivity.java hands it over via JNI).
        android_poll_picked_portrait(renderer);
#endif


        // Match-result sequence: GAME_WON first shows the Mission Accomplished
        // screen, then automatically opens the final leaderboard. GAME_OVER keeps
        // the existing immediate-results behaviour.
        static GameState prevGameStateForLB = GameState::MODE_SELECTION;
        if (prevGameStateForLB != currentGameState) {
            if (currentGameState == GameState::GAME_OVER) {
                playerLosses++;
                showMissionAccomplishedScreen = false;
                showMatchEndLeaderboard = true;
                const bool finalRun = (selectedMode == GameMode::ENDLESS) || (currentRound >= MAX_TACTICAL_ROUNDS);
                if (finalRun) award_completed_run_coins(currentTime);
            } else if (currentGameState == GameState::GAME_WON) {
                playerWins++;
                showMissionAccomplishedScreen = true;
                missionAccomplishedAt = currentTime;
                showMatchEndLeaderboard = false;
                play_victory_sound();
                const bool finalRun = (selectedMode == GameMode::ENDLESS) || (currentRound >= MAX_TACTICAL_ROUNDS);
                if (finalRun) award_completed_run_coins(currentTime);
            }
        }
        if (currentGameState == GameState::GAME_WON && showMissionAccomplishedScreen &&
            currentTime - missionAccomplishedAt >= 1800) {
            showMissionAccomplishedScreen = false;
            showMatchEndLeaderboard = true;
        }
        prevGameStateForLB = currentGameState;

        while (SDL_PollEvent(&event)) {
            // Keep an explicit arrow-key state for vehicle driving. This is
            // intentionally handled before the state-specific input branches
            // so menu/dialog code cannot swallow the vehicle key state.
            if (event.type == SDL_KEYDOWN && !event.key.repeat) {
                // Use SDL scancodes here instead of only key symbols. Scancodes
                // are layout-independent and are reliable for physical arrow
                // keys on desktop keyboards and Android hardware keyboards.
                switch (event.key.keysym.sym) {
                    case SDLK_UP:    g_vehicleKeyUp = true; break;
                    case SDLK_DOWN:  g_vehicleKeyDown = true; break;
                    case SDLK_LEFT:  g_vehicleKeyLeft = true; break;
                    case SDLK_RIGHT: g_vehicleKeyRight = true; break;
                    default:
                        // Some Android/physical-keyboard SDL builds report the
                        // arrow key symbol correctly but leave scancode UNKNOWN.
                        switch (event.key.keysym.scancode) {
                            case SDL_SCANCODE_UP:    g_vehicleKeyUp = true; break;
                            case SDL_SCANCODE_DOWN:  g_vehicleKeyDown = true; break;
                            case SDL_SCANCODE_LEFT:  g_vehicleKeyLeft = true; break;
                            case SDL_SCANCODE_RIGHT: g_vehicleKeyRight = true; break;
                            default: break;
                        }
                        break;
                }
            } else if (event.type == SDL_KEYUP) {
                switch (event.key.keysym.sym) {
                    case SDLK_UP:    g_vehicleKeyUp = false; break;
                    case SDLK_DOWN:  g_vehicleKeyDown = false; break;
                    case SDLK_LEFT:  g_vehicleKeyLeft = false; break;
                    case SDLK_RIGHT: g_vehicleKeyRight = false; break;
                    default:
                        switch (event.key.keysym.scancode) {
                            case SDL_SCANCODE_UP:    g_vehicleKeyUp = false; break;
                            case SDL_SCANCODE_DOWN:  g_vehicleKeyDown = false; break;
                            case SDL_SCANCODE_LEFT:  g_vehicleKeyLeft = false; break;
                            case SDL_SCANCODE_RIGHT: g_vehicleKeyRight = false; break;
                            default: break;
                        }
                        break;
                }
            } else if (event.type == SDL_WINDOWEVENT &&
                       event.window.event == SDL_WINDOWEVENT_FOCUS_LOST) {
                g_vehicleKeyUp = g_vehicleKeyDown = false;
                g_vehicleKeyLeft = g_vehicleKeyRight = false;
            }

            if (event.type == SDL_QUIT) {
                running = false;
                continue;
            }

            // First-run tutorial owns all input while visible. This prevents
            // taps from leaking into the real menu underneath, while the GOT IT
            // button itself remains fully clickable on mouse and Android touch.
            if (showFirstRunTutorial) {
                bool activate = false;
                if (event.type == SDL_KEYDOWN &&
                    (event.key.keysym.sym == SDLK_RETURN ||
                     event.key.keysym.sym == SDLK_KP_ENTER ||
                     event.key.keysym.sym == SDLK_SPACE)) {
                    activate = true;
                } else if (event.type == SDL_MOUSEBUTTONDOWN) {
                    SDL_Point p = mouse_to_logical(renderer, event.button.x, event.button.y);
                    SDL_Rect gotIt{SCREEN_WIDTH / 2 - 230, 75 + 1030 - 88, 460, 58};
                    activate = SDL_PointInRect(&p, &gotIt) != SDL_FALSE;
                } else if (event.type == SDL_FINGERDOWN) {
                    SDL_Point p{static_cast<int>(event.tfinger.x * SCREEN_WIDTH),
                                static_cast<int>(event.tfinger.y * SCREEN_HEIGHT)};
                    SDL_Rect gotIt{SCREEN_WIDTH / 2 - 230, 75 + 1030 - 88, 460, 58};
                    activate = SDL_PointInRect(&p, &gotIt) != SDL_FALSE;
                }

                if (activate) {
                    firstRunTutorialCompleted = true;
                    showFirstRunTutorial = false;
                    save_progress();
                }
                continue;
            }

            if (currentGameState == GameState::TACTICAL_CONFIG) {
                if (event.type == SDL_KEYDOWN && event.key.keysym.sym == SDLK_ESCAPE) {
                    currentGameState = GameState::MODE_SELECTION;
                    continue;
                }
                if (event.type == SDL_MOUSEBUTTONDOWN || event.type == SDL_FINGERDOWN) {
                    int clickX = (event.type == SDL_MOUSEBUTTONDOWN) ? mouse_to_logical(renderer, event.button.x, event.button.y).x : static_cast<int>(event.tfinger.x * SCREEN_WIDTH);
                    int clickY = (event.type == SDL_MOUSEBUTTONDOWN) ? mouse_to_logical(renderer, event.button.x, event.button.y).y : static_cast<int>(event.tfinger.y * SCREEN_HEIGHT);
                    SDL_Point pt = { clickX, clickY };

                    if (SDL_PointInRect(&pt, &btnBackToMenu)) {
                        currentGameState = GameState::MODE_SELECTION;
                    } else if (SDL_PointInRect(&pt, &btnDecEnemies)) {
                        customTacticalEnemies = std::max(0, customTacticalEnemies - 1);
                    } else if (SDL_PointInRect(&pt, &btnIncEnemies)) {
                        customTacticalEnemies = std::min(MAX_ENEMIES, customTacticalEnemies + 1);
                    } else if (SDL_PointInRect(&pt, &btnDiffEasy)) {
                        tacticalEnemyDifficulty = EnemyDifficulty::EASY;
                        tacticalDifficultyChosen = true;
                    } else if (SDL_PointInRect(&pt, &btnDiffNormal)) {
                        tacticalEnemyDifficulty = EnemyDifficulty::NORMAL;
                        tacticalDifficultyChosen = true;
                    } else if (SDL_PointInRect(&pt, &btnDiffHard)) {
                        tacticalEnemyDifficulty = EnemyDifficulty::HARD;
                        tacticalDifficultyChosen = true;
                    } else if (SDL_PointInRect(&pt, &btnDiffExpert)) {
                        tacticalEnemyDifficulty = EnemyDifficulty::EXPERT;
                        tacticalDifficultyChosen = true;
                    } else if (SDL_PointInRect(&pt, &btnDecBots)) {
                        customBotCount = std::max(0, customBotCount - 1);
                    } else if (SDL_PointInRect(&pt, &btnIncBots)) {
                        customBotCount = std::min(MAX_BOTS, customBotCount + 1);
                    } else if (SDL_PointInRect(&pt, &btnStartTac)) {
                        // Difficulty is mandatory. EASY is preselected, so the
                        // button is immediately usable; NORMAL/HARD/EXPERT replace
                        // the default when the player taps one of them.
                        if (!tacticalDifficultyChosen) {
                            tacticalEnemyDifficulty = EnemyDifficulty::EASY;
                            tacticalDifficultyChosen = true;
                        }
                        selectedMode = GameMode::TACTICAL;
                        if (aiGeneratedMapActive) generate_ai_map();
                        init_game_arena();
                        if (customPlayerSpawnValid) {
                            playerPosX = customPlayerSpawn.x * TILE_SIZE + 10;
                            playerPosY = customPlayerSpawn.y * TILE_SIZE + 10;
                        } else {
                            playerPosX = 5 * TILE_SIZE + 10;
                            playerPosY = 5 * TILE_SIZE + 10;
                        }
                        player.x = static_cast<int>(playerPosX); player.y = static_cast<int>(playerPosY);
                        currentGameState = GameState::PLAYING;
                    }
                }
                continue;
            }
            
              
                
                    if (event.type == SDL_KEYDOWN && event.key.keysym.sym == SDLK_e &&
                        !profileEditActive && !editorShowSaveDialog) {
                // Guarded against both text-entry dialogs: without this, typing the
                // letter "e" into the profile name field (or a map filename) would
                // fire this global hotkey mid-keystroke and yank the game into/out
                // of the Map Editor instead of typing an "E".
                currentGameState = (currentGameState == GameState::MAP_EDITOR) ? GameState::MODE_SELECTION : GameState::MAP_EDITOR;
            }

            if (currentGameState == GameState::MAP_EDITOR) {
                // Save-as dialog box: asks for a filename before writing to disk. While
                // open, it swallows all editor input so taps/keys can't leak through to
                // the grid or palette underneath.
                if (editorShowSizeDialog) {
                    if (event.type == SDL_KEYDOWN && event.key.keysym.sym == SDLK_ESCAPE) {
                        editorShowSizeDialog = false;
                    } else if (event.type == SDL_MOUSEBUTTONDOWN || event.type == SDL_FINGERDOWN) {
                        int cx = (event.type == SDL_MOUSEBUTTONDOWN) ? mouse_to_logical(renderer,event.button.x,event.button.y).x : static_cast<int>(event.tfinger.x*SCREEN_WIDTH);
                        int cy = (event.type == SDL_MOUSEBUTTONDOWN) ? mouse_to_logical(renderer,event.button.x,event.button.y).y : static_cast<int>(event.tfinger.y*SCREEN_HEIGHT);
                        SDL_Point pt{cx,cy};
                        if (SDL_PointInRect(&pt,&editorSizeWidthMinus)) editorMapCols=std::max(20,editorMapCols-1);
                        else if (SDL_PointInRect(&pt,&editorSizeWidthPlus)) editorMapCols=std::min(COLS,editorMapCols+1);
                        else if (SDL_PointInRect(&pt,&editorSizeHeightMinus)) editorMapRows=std::max(15,editorMapRows-1);
                        else if (SDL_PointInRect(&pt,&editorSizeHeightPlus)) editorMapRows=std::min(ROWS,editorMapRows+1);
                        else if (SDL_PointInRect(&pt,&editorSizeApply)) { reset_editor_map_size(editorMapCols,editorMapRows); editor_set_status("SIZE SET",currentTime); editorShowSizeDialog=false; }
                        else if (SDL_PointInRect(&pt,&editorSizeCancel)) editorShowSizeDialog=false;
                    }
                    continue;
                }

                if (editorShowSaveDialog) {
                    if (event.type == SDL_TEXTINPUT) {
                        if (editorFilenameInput.size() < 40) editorFilenameInput += event.text.text;
                    } else if (event.type == SDL_KEYDOWN) {
                        if (event.key.keysym.sym == SDLK_BACKSPACE && !editorFilenameInput.empty()) {
                            editorFilenameInput.pop_back();
                        } else if (event.key.keysym.sym == SDLK_RETURN || event.key.keysym.sym == SDLK_KP_ENTER) {
                            std::string name = sanitize_map_name(editorFilenameInput);
                            std::string path = map_directory() + name + ".txt";
                            if (save_map_to_file(path)) {
                                mapFilePath = path;
                                useCustomMap = true;
                                refresh_map_list();
                                editor_set_status("SAVED " + name + ".txt", currentTime);
                            } else {
                                editor_set_status("SAVE FAILED", currentTime);
                            }
                            editor_close_save_dialog();
                        } else if (event.key.keysym.sym == SDLK_ESCAPE) {
                            editor_close_save_dialog();
                        }
                    } else if (event.type == SDL_MOUSEBUTTONDOWN || event.type == SDL_FINGERDOWN) {
                        int cx = (event.type == SDL_MOUSEBUTTONDOWN) ? mouse_to_logical(renderer, event.button.x, event.button.y).x : static_cast<int>(event.tfinger.x * SCREEN_WIDTH);
                        int cy = (event.type == SDL_MOUSEBUTTONDOWN) ? mouse_to_logical(renderer, event.button.x, event.button.y).y : static_cast<int>(event.tfinger.y * SCREEN_HEIGHT);
                        SDL_Point pt{cx, cy};
                        if (SDL_PointInRect(&pt, &editorDialogSave)) {
                            std::string name = sanitize_map_name(editorFilenameInput);
                            std::string path = map_directory() + name + ".txt";
                            if (save_map_to_file(path)) {
                                mapFilePath = path;
                                useCustomMap = true;
                                refresh_map_list();
                                editor_set_status("SAVED " + name + ".txt", currentTime);
                            } else {
                                editor_set_status("SAVE FAILED", currentTime);
                            }
                            editor_close_save_dialog();
                        } else if (SDL_PointInRect(&pt, &editorDialogCancel)) {
                            editor_close_save_dialog();
                        } else if (SDL_PointInRect(&pt, &editorDialogField)) {
                            // Re-summon the keyboard if the OS dismissed it without
                            // closing the dialog - same forced-edge trick as opening.
                            SDL_StopTextInput();
                            SDL_StartTextInput();
                        }
                    }
                    continue;
                }

                if (editorShowLoadDialog) {
                    if (event.type == SDL_MOUSEBUTTONDOWN || event.type == SDL_FINGERDOWN) {
                        int cx = (event.type == SDL_MOUSEBUTTONDOWN) ? mouse_to_logical(renderer, event.button.x, event.button.y).x : static_cast<int>(event.tfinger.x * SCREEN_WIDTH);
                        int cy = (event.type == SDL_MOUSEBUTTONDOWN) ? mouse_to_logical(renderer, event.button.x, event.button.y).y : static_cast<int>(event.tfinger.y * SCREEN_HEIGHT);
                        SDL_Point pt{cx, cy};
                        const int boxX = SCREEN_WIDTH / 2 - 360;
                        const int boxY = 130;
                        const int rowH = 70;
                        const int maxRows = std::min(8, static_cast<int>(availableMapFiles.size()));
                        for (int i = 0; i < maxRows; ++i) {
                            SDL_Rect row{boxX + 25, boxY + 90 + i * rowH, 670, rowH - 8};
                            SDL_Rect del{row.x + row.w - 125, row.y + 6, 112, row.h - 12};
                            if (SDL_PointInRect(&pt, &del)) {
                                std::string name = availableMapFiles[i];
                                if (delete_map_file_by_index(i)) editor_set_status("DELETED " + name, currentTime);
                                else editor_set_status("DELETE FAILED", currentTime);
                                editorShowLoadDialog = true;
                                break;
                            }
                            if (SDL_PointInRect(&pt, &row)) {
                                if (select_map_file_by_index(i)) {
                                    load_map_from_file(mapFilePath);
                                    editor_set_status("LOADED " + map_basename(mapFilePath), currentTime);
                                }
                                editorShowLoadDialog = false;
                                break;
                            }
                        }
                        SDL_Rect cancel{boxX + 25, boxY + 800 - 65, 670, 45};
                        if (SDL_PointInRect(&pt, &cancel)) editorShowLoadDialog = false;
                    } else if (event.type == SDL_KEYDOWN && event.key.keysym.sym == SDLK_ESCAPE) {
                        editorShowLoadDialog = false;
                    }
                    continue;
                }

                if (event.type == SDL_MOUSEBUTTONDOWN) {
                    SDL_Point mp = mouse_to_logical(renderer, event.button.x, event.button.y);
                    int x = mp.x, y = mp.y;
                    SDL_Point pt{x, y};
                    bool handled = false;
                    if (SDL_PointInRect(&pt, &btnBackToMenu)) {
                        currentGameState = GameState::MODE_SELECTION;
                        editorShowSaveDialog = false;
                        editorShowLoadDialog = false;
                        editorShowSizeDialog = false;
                        handled = true;
                    } else if (SDL_PointInRect(&pt, &editorSaveButton)) {
                        editor_open_save_dialog();
                        handled = true;
                    } else if (SDL_PointInRect(&pt, &editorOverwriteButton)) {
                        if (!mapFilePath.empty() && save_map_to_file(mapFilePath)) {
                            refresh_map_list();
                            useCustomMap = true;
                            editor_set_status("SAVED " + map_basename(mapFilePath), currentTime);
                        } else {
                            editor_set_status("NO MAP TO OVERWRITE - USE SAVE AS", currentTime);
                        }
                        handled = true;
                    } else if (SDL_PointInRect(&pt, &editorLoadButton)) {
                        refresh_map_list();
                        editorShowLoadDialog = true;
                        handled = true;
                    } else if (SDL_PointInRect(&pt, &editorSizeButton)) {
                        editorShowSizeDialog = true;
                        handled = true;
                    } else if (SDL_PointInRect(&pt, &editorEraseButton)) {
                        editorEraseMode = !editorEraseMode;
                        handled = true;
                    } else if (SDL_PointInRect(&pt, &editorExitButton)) {
                        currentGameState = GameState::MODE_SELECTION;
                        handled = true;
                    } else if (SDL_PointInRect(&pt, &editorZoomOutButton)) {
                        editor_set_zoom(editorZoom - EDITOR_ZOOM_STEP);
                        handled = true;
                    } else if (SDL_PointInRect(&pt, &editorZoomInButton)) {
                        editor_set_zoom(editorZoom + EDITOR_ZOOM_STEP);
                        handled = true;
                    } else {
                        for (const auto& opt : editorPalette) {
                            if (SDL_PointInRect(&pt, &opt.rect)) {
                                editorSelectedTile = opt.value;
                                editorEraseMode = false;
                                handled = true;
                                break;
                            }
                        }
                    }
                    if (!handled) {
                        // Right-click is always a quick erase, regardless of the selected brush.
                        editor_apply_tile(x, y, event.button.button == SDL_BUTTON_RIGHT);
                    }
                }

                // Mouse wheel doubles as a zoom control on desktop.
                if (event.type == SDL_MOUSEWHEEL) {
                    int dir = (event.wheel.y > 0) ? 1 : (event.wheel.y < 0 ? -1 : 0);
                    if (dir != 0) editor_set_zoom(editorZoom + dir * EDITOR_ZOOM_STEP);
                }

                if (event.type == SDL_FINGERDOWN) {
                    int x = static_cast<int>(event.tfinger.x * SCREEN_WIDTH);
                    int y = static_cast<int>(event.tfinger.y * SCREEN_HEIGHT);
                    SDL_Point pt{x,y};
                    bool handled = false;

                    if (SDL_PointInRect(&pt, &btnBackToMenu)) {
                        currentGameState = GameState::MODE_SELECTION;
                        editorShowSaveDialog = false;
                        editorShowLoadDialog = false;
                        editorShowSizeDialog = false;
                        handled = true;
                    } else if (SDL_PointInRect(&pt, &editorSaveButton)) {
                        editor_open_save_dialog();
                        handled = true;
                    } else if (SDL_PointInRect(&pt, &editorOverwriteButton)) {
                        if (!mapFilePath.empty() && save_map_to_file(mapFilePath)) {
                            refresh_map_list();
                            useCustomMap = true;
                            editor_set_status("SAVED " + map_basename(mapFilePath), currentTime);
                        } else {
                            editor_set_status("NO MAP TO OVERWRITE - USE SAVE AS", currentTime);
                        }
                        handled = true;
                    } else if (SDL_PointInRect(&pt, &editorLoadButton)) {
                        refresh_map_list();
                        editorShowLoadDialog = true;
                        handled = true;
                    } else if (SDL_PointInRect(&pt, &editorSizeButton)) {
                        editorShowSizeDialog = true;
                        handled = true;
                    } else if (SDL_PointInRect(&pt, &editorEraseButton)) {
                        editorEraseMode = !editorEraseMode;
                        handled = true;
                    } else if (SDL_PointInRect(&pt, &editorExitButton)) {
                        currentGameState = GameState::MODE_SELECTION;
                        handled = true;
                    } else if (SDL_PointInRect(&pt, &editorZoomOutButton)) {
                        editor_set_zoom(editorZoom - EDITOR_ZOOM_STEP);
                        handled = true;
                    } else if (SDL_PointInRect(&pt, &editorZoomInButton)) {
                        editor_set_zoom(editorZoom + EDITOR_ZOOM_STEP);
                        handled = true;
                    } else {
                        for (const auto& opt : editorPalette) {
                            if (SDL_PointInRect(&pt, &opt.rect)) {
                                editorSelectedTile = opt.value;
                                editorEraseMode = false;
                                handled = true;
                                break;
                            }
                        }
                    }

                    if (!handled && y >= EDITOR_PANEL_BOTTOM) {
                        if (!editorTouchActive) {
                            // First finger on the grid: starts panning / tapping-to-paint.
                            editorTouchActive = true;
                            editorFingerId = event.tfinger.fingerId;
                            editorLastTouchX = x;
                            editorLastTouchY = y;
                            editorTouch1X = x;
                            editorTouch1Y = y;
                            editorDragged = false;
                        } else if (editorFingerId2 == -1 && event.tfinger.fingerId != editorFingerId) {
                            // Second finger lands while the first is already down on the
                            // grid: begin a pinch-to-zoom gesture instead of panning.
                            editorFingerId2 = event.tfinger.fingerId;
                            editorTouch2X = x;
                            editorTouch2Y = y;
                            float ddx = static_cast<float>(editorTouch1X - editorTouch2X);
                            float ddy = static_cast<float>(editorTouch1Y - editorTouch2Y);
                            editorPinchStartDist = std::sqrt(ddx * ddx + ddy * ddy);
                            editorPinchStartZoom = editorZoom;
                            editorPinching = editorPinchStartDist > 1.0f;
                            editorDragged = true; // suppress a tile paint when fingers lift
                        }
                    }
                }

                if (event.type == SDL_FINGERMOTION && editorTouchActive &&
                    (event.tfinger.fingerId == editorFingerId || event.tfinger.fingerId == editorFingerId2)) {
                    int x = static_cast<int>(event.tfinger.x * SCREEN_WIDTH);
                    int y = static_cast<int>(event.tfinger.y * SCREEN_HEIGHT);

                    if (event.tfinger.fingerId == editorFingerId) { editorTouch1X = x; editorTouch1Y = y; }
                    else { editorTouch2X = x; editorTouch2Y = y; }

                    if (editorPinching) {
                        float ddx = static_cast<float>(editorTouch1X - editorTouch2X);
                        float ddy = static_cast<float>(editorTouch1Y - editorTouch2Y);
                        float dist = std::sqrt(ddx * ddx + ddy * ddy);
                        if (editorPinchStartDist > 1.0f) {
                            editor_set_zoom(editorPinchStartZoom * (dist / editorPinchStartDist));
                        }
                    } else if (event.tfinger.fingerId == editorFingerId) {
                        int dx = x - editorLastTouchX;
                        int dy = y - editorLastTouchY;
                        if (std::abs(dx) + std::abs(dy) > 3) {
                            editorDragged = true;
                            int maxX = std::max(0, static_cast<int>(editorMapCols * TILE_SIZE - SCREEN_WIDTH / editorZoom));
                            int maxY = std::max(0, static_cast<int>(editorMapRows * TILE_SIZE - SCREEN_HEIGHT / editorZoom));
                            cameraX = std::clamp(cameraX - static_cast<int>(dx / editorZoom), 0, maxX);
                            cameraY = std::clamp(cameraY - static_cast<int>(dy / editorZoom), 0, maxY);
                            editorLastTouchX = x;
                            editorLastTouchY = y;
                        }
                    }
                }

                if (event.type == SDL_FINGERUP && (event.tfinger.fingerId == editorFingerId || event.tfinger.fingerId == editorFingerId2)) {
                    int x = static_cast<int>(event.tfinger.x * SCREEN_WIDTH);
                    int y = static_cast<int>(event.tfinger.y * SCREEN_HEIGHT);

                    if (event.tfinger.fingerId == editorFingerId2) {
                        // Second finger lifted: end the pinch but keep panning with
                        // whichever finger is still down.
                        editorFingerId2 = -1;
                        editorPinching = false;
                        editorLastTouchX = editorTouch1X;
                        editorLastTouchY = editorTouch1Y;
                    } else {
                        if (!editorDragged) editor_apply_tile(x, y, false);
                        editorTouchActive = false;
                        editorFingerId = -1;
                        // If a second finger was still down, it can't keep panning alone;
                        // clear it too so the next touch starts a clean gesture.
                        editorFingerId2 = -1;
                        editorPinching = false;
                    }
                }

                if (event.type == SDL_KEYDOWN) {
                    if (event.key.keysym.sym == SDLK_s) editor_open_save_dialog();
                    if (event.key.keysym.sym == SDLK_l) {
                        refresh_map_list();
                        editor_set_status(load_map_from_file(mapFilePath) ? ("LOADED " + map_basename(mapFilePath)) : "NO SAVED MAP FOUND", currentTime);
                    }
                }
                continue;
            }

            if (currentGameState == GameState::WEAPON_MENU) {
                if (event.type == SDL_KEYDOWN && event.key.keysym.sym == SDLK_ESCAPE) {
                    currentGameState = GameState::MODE_SELECTION;
                    continue;
                }
                if (event.type == SDL_MOUSEBUTTONDOWN || event.type == SDL_FINGERDOWN) {
                    int clickX = (event.type == SDL_MOUSEBUTTONDOWN) ? mouse_to_logical(renderer, event.button.x, event.button.y).x : static_cast<int>(event.tfinger.x * SCREEN_WIDTH);
                    int clickY = (event.type == SDL_MOUSEBUTTONDOWN) ? mouse_to_logical(renderer, event.button.x, event.button.y).y : static_cast<int>(event.tfinger.y * SCREEN_HEIGHT);
                    const WeaponType types[] = {WeaponType::PISTOL,WeaponType::RIFLE,WeaponType::ROCKET,WeaponType::LASER,WeaponType::VECTOR_REFLECT,WeaponType::FIRE_GUN,WeaponType::ICE_GUN,WeaponType::WIND_GUN,WeaponType::COIN_MAGNET};
                    for (int i=0;i<9;++i) {
                        int col = i % 2, row = i / 2;
                        SDL_Rect b{70 + col * 950, 175 + row * 150, 880, 125};
                        SDL_Point pt{clickX,clickY};
                        if (SDL_PointInRect(&pt,&b)) {
                            if (is_weapon_locked(types[i])) {
                                try_unlock_weapon(types[i]); // premium => payment request, legacy => coin unlock
                            } else {
                                toggle_weapon_loadout(types[i], currentTime);
                            }
                            break;
                        }
                    }
                    SDL_Point pt{clickX,clickY};
                    // The weapon screen draws its BACK button using weaponMenuBack.
                    // Previously input was checking btnBackToMenu (the other screen's
                    // top-right button), so the visible weapon-menu BACK button could
                    // not actually be activated on touch or mouse.
                    if (SDL_PointInRect(&pt, &weaponMenuBack) ||
                        SDL_PointInRect(&pt, &btnBackToMenu)) {
                        currentGameState = GameState::MODE_SELECTION;
                        mapDropdownOpen = false;
                        portraitPickerOpen = false;
                    }
                }
                continue;
            }

            if (currentGameState == GameState::MULTIPLAYER_WIFI) {
                if (event.type == SDL_TEXTINPUT && multiplayerView == MultiplayerView::MATCHMAKING &&
                    matchmaking.visibility == MatchVisibility::PRIVATE_MATCH) {
                    if (matchmaking.privateCode.size() < 16) matchmaking.privateCode += event.text.text;
                } else if (event.type == SDL_KEYDOWN && multiplayerView == MultiplayerView::MATCHMAKING &&
                           matchmaking.visibility == MatchVisibility::PRIVATE_MATCH && event.key.keysym.sym == SDLK_BACKSPACE) {
                    if (!matchmaking.privateCode.empty()) matchmaking.privateCode.pop_back();
                } else if (event.type == SDL_TEXTINPUT && multiplayerView == MultiplayerView::LAN_JOIN) {
                    if (lanNetwork.editingJoinFingerprint) {
                        if (lanNetwork.manualTlsFingerprint.size() < 64) {
                            for (char c : std::string(event.text.text)) {
                                if (std::isxdigit(static_cast<unsigned char>(c)) &&
                                    lanNetwork.manualTlsFingerprint.size() < 64) {
                                    lanNetwork.manualTlsFingerprint +=
                                        static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
                                }
                            }
                        }
                    } else {
                        if (lanNetwork.joinIp.size() < 48) lanNetwork.joinIp += event.text.text;
                        lanNetwork.manualJoinInput = true;
#if GAME80_LAN_TLS_AVAILABLE
                        lanNetwork.expectedTlsServerFingerprint.clear();
                        lanNetwork.tlsFingerprintUserApproved = false;
#endif
                    }
                } else if (event.type == SDL_KEYDOWN && multiplayerView == MultiplayerView::LAN_JOIN && event.key.keysym.sym == SDLK_BACKSPACE) {
                    if (lanNetwork.editingJoinFingerprint) {
                        if (!lanNetwork.manualTlsFingerprint.empty()) lanNetwork.manualTlsFingerprint.pop_back();
                    } else if (!lanNetwork.joinIp.empty()) {
                        lanNetwork.joinIp.pop_back();
                        lanNetwork.manualJoinInput = true;
#if GAME80_LAN_TLS_AVAILABLE
                        lanNetwork.expectedTlsServerFingerprint.clear();
                        lanNetwork.tlsFingerprintUserApproved = false;
#endif
                    }
                } else if (event.type == SDL_KEYDOWN && event.key.keysym.sym == SDLK_ESCAPE) {
                    SDL_StopTextInput();
                    lan_stop();
                    currentGameState = GameState::MODE_SELECTION;
                } else if (event.type == SDL_MOUSEBUTTONDOWN || event.type == SDL_FINGERDOWN) {
                    int cx = (event.type == SDL_MOUSEBUTTONDOWN)
                        ? mouse_to_logical(renderer, event.button.x, event.button.y).x
                        : static_cast<int>(event.tfinger.x * SCREEN_WIDTH);
                    int cy = (event.type == SDL_MOUSEBUTTONDOWN)
                        ? mouse_to_logical(renderer, event.button.x, event.button.y).y
                        : static_cast<int>(event.tfinger.y * SCREEN_HEIGHT);
                    SDL_Point pt{cx, cy};
#if GAME80_LAN_TLS_AVAILABLE
                    if (multiplayerView == MultiplayerView::LAN_JOIN &&
                        lanNetwork.status == "VERIFY HOST FINGERPRINT" &&
                        !lanNetwork.discoveredTlsServerFingerprint.empty()) {
                        if (SDL_PointInRect(&pt, &btnLanTlsTrust)) {
                            lanNetwork.expectedTlsServerFingerprint = lanNetwork.discoveredTlsServerFingerprint;
                            lanNetwork.tlsFingerprintUserApproved = true;
                            lanNetwork.manualJoinInput = false;
                            lanNetwork.status = "CONNECTING TO " + lanNetwork.joinIp + "...";
                            lan_start_join(lanNetwork.joinIp);
                        } else if (SDL_PointInRect(&pt, &btnLanTlsCancel)) {
                            lanNetwork.status = "HOST FINGERPRINT NOT TRUSTED";
                            lanNetwork.expectedTlsServerFingerprint.clear();
                            lanNetwork.tlsFingerprintUserApproved = false;
                        }
                        continue;
                    }
#endif
                    if (SDL_PointInRect(&pt, &btnWifiBack)) {
                        SDL_StopTextInput();
                        lan_stop();
                        if (multiplayerView != MultiplayerView::HOME) multiplayerView = MultiplayerView::HOME;
                        else currentGameState = GameState::MODE_SELECTION;
                    } else if (multiplayerView == MultiplayerView::HOME && SDL_PointInRect(&pt, &btnWifiHost)) {
                        if (lan_start_host()) {
                            multiplayerView = MultiplayerView::LAN_HOST;
                            lan_broadcast_lobby();
                        } else {
                            multiplayerView = MultiplayerView::LAN_HOST;
                        }
                    } else if (multiplayerView == MultiplayerView::HOME && SDL_PointInRect(&pt, &btnWifiJoin)) {
                        lan_stop();
                        lanNetwork.manualJoinInput = false;
                        lanNetwork.manualTlsFingerprint.clear();
                        lanNetwork.editingJoinFingerprint = false;
#if GAME80_LAN_TLS_AVAILABLE
                        lanNetwork.discoveredTlsServerFingerprint.clear();
                        lanNetwork.expectedTlsServerFingerprint.clear();
                        lanNetwork.tlsFingerprintUserApproved = false;
#endif
                        lan_start_join("");
                        multiplayerView = MultiplayerView::LAN_JOIN;
                    } else if (multiplayerView == MultiplayerView::HOME && SDL_PointInRect(&pt, &btnWifiOnline)) {
                        lan_stop();
                        matchmaking.status = MatchmakingStatus::IDLE;
                        matchmaking.statusMessage = "READY TO MATCH";
                        multiplayerView = MultiplayerView::MATCHMAKING;
                    } else if (multiplayerView == MultiplayerView::MATCHMAKING && SDL_PointInRect(&pt, &btnMatchVisibility)) {
                        matchmaking.visibility = matchmaking.visibility == MatchVisibility::PUBLIC_MATCH
                            ? MatchVisibility::PRIVATE_MATCH : MatchVisibility::PUBLIC_MATCH;
                    } else if (multiplayerView == MultiplayerView::MATCHMAKING && SDL_PointInRect(&pt, &btnMatchRegion)) {
                        matchmaking_cycle_region();
                    } else if (multiplayerView == MultiplayerView::MATCHMAKING && SDL_PointInRect(&pt, &btnMatchPlayers)) {
                        matchmaking_cycle_player_limit();
                    } else if (multiplayerView == MultiplayerView::MATCHMAKING && SDL_PointInRect(&pt, &btnMatchCode)) {
                        if (matchmaking.visibility == MatchVisibility::PRIVATE_MATCH) SDL_StartTextInput();
                    } else if (multiplayerView == MultiplayerView::MATCHMAKING && SDL_PointInRect(&pt, &btnMatchSearch)) {
                        if (matchmaking.status == MatchmakingStatus::SEARCHING) matchmaking_cancel();
                        else matchmaking_begin();
                    } else if (multiplayerView == MultiplayerView::LAN_HOST && SDL_PointInRect(&pt, &btnLanTeam)) {
                        if (!lanNetwork.hosting || !lanMatchStarted) {
                            lanNetwork.localTeam = (lanNetwork.localTeam == Team::GREEN_DEFUSER) ? Team::RED_BOMBER : Team::GREEN_DEFUSER;
                            if (lanNetwork.hosting) lan_broadcast_lobby();
                        }
                    } else if (multiplayerView == MultiplayerView::LAN_HOST && SDL_PointInRect(&pt, &btnLanStart)) {
                        if (lanNetwork.hosting && !lanMatchStarted) {
                            lan_start_match_host();
                            if (lanMatchStarted) currentGameState = GameState::PLAYING;
                        }
                    } else if (multiplayerView == MultiplayerView::LAN_JOIN && SDL_PointInRect(&pt, &btnLanTeam)) {
                        if (lanNetwork.connected && !lanMatchStarted) {
                            lanNetwork.localTeam = (lanNetwork.localTeam == Team::GREEN_DEFUSER) ? Team::RED_BOMBER : Team::GREEN_DEFUSER;
                            lan_send_line(lanNetwork.clientSocket, std::string("TEAM|") + lan_team_code(lanNetwork.localTeam));
                            lan_send_line(lanNetwork.clientSocket, "HELLO|" + lan_safe_name(playerName) + "|" + lan_team_code(lanNetwork.localTeam));
                        }
                    } else if (multiplayerView == MultiplayerView::LAN_JOIN && SDL_PointInRect(&pt, &btnLanStart)) {
                        if (!lanNetwork.connected) {
                            if (lanNetwork.joinIp.empty()) {
                                lanNetwork.joinIp = lanNetwork.discoveredIp;
                                lanNetwork.manualJoinInput = false;
                            }
#if GAME80_LAN_TLS_AVAILABLE
                            if (!lanNetwork.manualJoinInput && !lanNetwork.discoveredTlsServerFingerprint.empty() &&
                                lanNetwork.expectedTlsServerFingerprint.empty()) {
                                // First-time auto-discovered host: show the claimed
                                // fingerprint and require an explicit user decision.
                                lanNetwork.status = "VERIFY HOST FINGERPRINT";
                            } else {
                                lan_start_join(lanNetwork.joinIp);
                            }
#else
                            lan_start_join(lanNetwork.joinIp);
#endif
                        } else {
                            lan_toggle_local_ready();
                        }
                    } else if (multiplayerView == MultiplayerView::LAN_JOIN && SDL_PointInRect(&pt, &btnWifiIpField)) {
                        lanNetwork.editingJoinFingerprint = false;
                        SDL_StartTextInput();
                    } else if (multiplayerView == MultiplayerView::LAN_JOIN && SDL_PointInRect(&pt, &btnWifiFingerprintField)) {
                        lanNetwork.editingJoinFingerprint = true;
                        SDL_StartTextInput();
                    }
                }
            }

            if (currentGameState == GameState::MODE_SELECTION) {
                // Profile name edit dialog swallows all menu input while open, same
                // pattern as the map editor's save-as dialog.
                if (profileEditActive) {
                    if (event.type == SDL_TEXTINPUT) {
                        if (profileNameInput.size() < 16) profileNameInput += event.text.text;
                    } else if (event.type == SDL_KEYDOWN) {
                        if (event.key.keysym.sym == SDLK_BACKSPACE && !profileNameInput.empty()) {
                            profileNameInput.pop_back();
                        } else if (event.key.keysym.sym == SDLK_RETURN || event.key.keysym.sym == SDLK_KP_ENTER) {
                            if (!profileNameInput.empty()) playerName = profileNameInput;
                            profile_close_edit_dialog();
                        } else if (event.key.keysym.sym == SDLK_ESCAPE) {
                            profile_close_edit_dialog();
                        }
                    } else if (event.type == SDL_MOUSEBUTTONDOWN || event.type == SDL_FINGERDOWN) {
                        int cx = (event.type == SDL_MOUSEBUTTONDOWN) ? mouse_to_logical(renderer, event.button.x, event.button.y).x : static_cast<int>(event.tfinger.x * SCREEN_WIDTH);
                        int cy = (event.type == SDL_MOUSEBUTTONDOWN) ? mouse_to_logical(renderer, event.button.x, event.button.y).y : static_cast<int>(event.tfinger.y * SCREEN_HEIGHT);
                        SDL_Point pt{cx, cy};
                        if (SDL_PointInRect(&pt, &profileDialogSave)) {
                            if (!profileNameInput.empty()) playerName = profileNameInput;
                            profile_close_edit_dialog();
                        } else if (SDL_PointInRect(&pt, &profileDialogCancel)) {
                            profile_close_edit_dialog();
                        } else if (SDL_PointInRect(&pt, &profileDialogField)) {
                            // Re-summon the keyboard if the OS dismissed it without
                            // closing our dialog - same forced-edge trick as opening.
                            SDL_StopTextInput();
                            SDL_StartTextInput();
                        }
                    }
                    continue;
                }

                // Portrait picker swallows menu input while open, same pattern
                // as the profile name dialog above.
                if (portraitPickerOpen) {
                    if (event.type == SDL_MOUSEBUTTONDOWN || event.type == SDL_FINGERDOWN) {
                        int cx = (event.type == SDL_MOUSEBUTTONDOWN) ? mouse_to_logical(renderer, event.button.x, event.button.y).x : static_cast<int>(event.tfinger.x * SCREEN_WIDTH);
                        int cy = (event.type == SDL_MOUSEBUTTONDOWN) ? mouse_to_logical(renderer, event.button.x, event.button.y).y : static_cast<int>(event.tfinger.y * SCREEN_HEIGHT);
                        SDL_Point pt{cx, cy};
                        int rowIdx = portrait_picker_row_at(cx, cy);
                        if (rowIdx >= 0) {
                            select_portrait_file_by_index(renderer, rowIdx);
                        } else if (!SDL_PointInRect(&pt, &portraitPickerBox) && !SDL_PointInRect(&pt, &btnProfileImage)) {
                            portraitPickerOpen = false;
                        }
                    }
                    continue;
                }

                // AI map size dialog swallows all menu input while open, same
                // pattern as the map editor's own size dialog.
                if (aiMapShowSizeDialog) {
                    if (event.type == SDL_KEYDOWN && event.key.keysym.sym == SDLK_ESCAPE) {
                        aiMapShowSizeDialog = false;
                    } else if (event.type == SDL_MOUSEBUTTONDOWN || event.type == SDL_FINGERDOWN) {
                        int cx = (event.type == SDL_MOUSEBUTTONDOWN) ? mouse_to_logical(renderer, event.button.x, event.button.y).x : static_cast<int>(event.tfinger.x * SCREEN_WIDTH);
                        int cy = (event.type == SDL_MOUSEBUTTONDOWN) ? mouse_to_logical(renderer, event.button.x, event.button.y).y : static_cast<int>(event.tfinger.y * SCREEN_HEIGHT);
                        SDL_Point pt{cx, cy};
                        if (SDL_PointInRect(&pt, &aiMapSizeTickBox)) {
                            aiMapCustomDimensions = !aiMapCustomDimensions;
                        } else if (aiMapCustomDimensions && SDL_PointInRect(&pt, &aiMapSizeWidthMinus)) {
                            aiMapCols = std::max(30, aiMapCols - 1);
                        } else if (aiMapCustomDimensions && SDL_PointInRect(&pt, &aiMapSizeWidthPlus)) {
                            aiMapCols = std::min(COLS, aiMapCols + 1);
                        } else if (aiMapCustomDimensions && SDL_PointInRect(&pt, &aiMapSizeHeightMinus)) {
                            aiMapRows = std::max(20, aiMapRows - 1);
                        } else if (aiMapCustomDimensions && SDL_PointInRect(&pt, &aiMapSizeHeightPlus)) {
                            aiMapRows = std::min(ROWS, aiMapRows + 1);
                        } else if (SDL_PointInRect(&pt, &aiMapSizeApply)) {
                            aiMapShowSizeDialog = false;
                        } else if (SDL_PointInRect(&pt, &aiMapSizeCancel)) {
                            aiMapShowSizeDialog = false;
                        }
                    }
                    continue;
                }

                if (mapDropdownOpen && (event.type == SDL_MOUSEMOTION || event.type == SDL_FINGERMOTION)) {
                    int moveX = (event.type == SDL_MOUSEMOTION) ? mouse_to_logical(renderer, event.motion.x, event.motion.y).x : static_cast<int>(event.tfinger.x * SCREEN_WIDTH);
                    int moveY = (event.type == SDL_MOUSEMOTION) ? mouse_to_logical(renderer, event.motion.x, event.motion.y).y : static_cast<int>(event.tfinger.y * SCREEN_HEIGHT);
                    hoveredMapIndex = map_index_at_menu_point(moveX, moveY);
                }
                if (event.type == SDL_MOUSEBUTTONDOWN || event.type == SDL_FINGERDOWN) {
                    int clickX = (event.type == SDL_MOUSEBUTTONDOWN) ? mouse_to_logical(renderer, event.button.x, event.button.y).x : static_cast<int>(event.tfinger.x * SCREEN_WIDTH);
                    int clickY = (event.type == SDL_MOUSEBUTTONDOWN) ? mouse_to_logical(renderer, event.button.x, event.button.y).y : static_cast<int>(event.tfinger.y * SCREEN_HEIGHT);
                    SDL_Point pt = { clickX, clickY };

                    if (SDL_PointInRect(&pt, &btnMultiplayerWifi)) {
                        multiplayerView = MultiplayerView::HOME;
                        currentGameState = GameState::MULTIPLAYER_WIFI;
                    } else if (SDL_PointInRect(&pt, &btnMainMenuHelp)) {
                        // The same guide serves both first-time players and
                        // returning players who want a quick refresher.
                        showFirstRunTutorial = true;
                    } else if (SDL_PointInRect(&pt, &btnMainMenuExit)) {
                        running = false;
                    } else {
                        // Keep input geometry identical to the profile rendering geometry.
                        const SDL_Rect rewardStats{68, 535, 525, 112};
                        const SDL_Rect profileScoreClick{rewardStats.x + 4, rewardStats.y + 4, 250, 44};
                        const SDL_Rect profileHighScoreClick{rewardStats.x + 260, rewardStats.y + 4, 261, 44};
                        if (SDL_PointInRect(&pt, &profileScoreClick)) {
                            // SCORE is independently tappable. A score of 100 pays 10 coins.
                            activate_coin_reward_animation(currentTime, false);
                            continue;
                        } else if (SDL_PointInRect(&pt, &profileHighScoreClick)) {
                            // HIGH SCORE is independently tappable for the +100 achievement.
                            activate_coin_reward_animation(currentTime, true);
                            continue;
                        } else if (SDL_PointInRect(&pt, &btnProfileImage)) {
#if defined(__ANDROID__)
                        android_open_image_picker();
#else
                        refresh_portrait_list();
                        portraitPickerOpen = true;
#endif
                    } else if (SDL_PointInRect(&pt, &btnProfileName)) {
                        profile_open_edit_dialog();
                    } else if (SDL_PointInRect(&pt, &btnTacticalMode)) {
                        // Always enter Tactical with EASY selected as the safe/default
                        // difficulty. The player may then change it to NORMAL, HARD or
                        // EXPERT before starting the mission.
                        tacticalEnemyDifficulty = EnemyDifficulty::EASY;
                        tacticalDifficultyChosen = true;
                        currentGameState = GameState::TACTICAL_CONFIG;
                    } else if (SDL_PointInRect(&pt, &btnInfinityMode)) {
                        selectedMode = GameMode::ENDLESS;
                        playerDiedThisEndlessRun = false;
                        aiGeneratedMapActive = false;
                        init_game_arena();
                        if (customPlayerSpawnValid) {
                            playerPosX = customPlayerSpawn.x * TILE_SIZE + 10;
                            playerPosY = customPlayerSpawn.y * TILE_SIZE + 10;
                        } else {
                            playerPosX = 5 * TILE_SIZE + 10;
                            playerPosY = 5 * TILE_SIZE + 10;
                        }
                        player.x = static_cast<int>(playerPosX); player.y = static_cast<int>(playerPosY);
                        currentGameState = GameState::PLAYING;
                    } else if (SDL_PointInRect(&pt, &btnMapEditor)) {
                        refresh_map_list();
                        aiGeneratedMapActive = false;
                        currentGameState = GameState::MAP_EDITOR;
                    } else if (SDL_PointInRect(&pt, &btnMapSelect)) {
                        refresh_map_list();
                        mapDropdownOpen = !mapDropdownOpen;
                        hoveredMapIndex = -1;
                    } else if (mapDropdownOpen) {
                        // The open dropdown is drawn on top of (and overlaps) the buttons
                        // below it - USE SELECTED MAP, AI GENERATED MAP, DODGE + ROLL, and
                        // WEAPON MENU all sit underneath its row area. It must claim taps
                        // in its own bounds before those buttons get a chance to, or a tap
                        // on a map row falls through and hits whatever button is behind it
                        // instead of selecting the map.
                        const int rowH = 52;
                        const int shownRows = std::min(7, static_cast<int>(availableMapFiles.size()));
                        SDL_Rect listBox{btnMapSelect.x, btnMapSelect.y + btnMapSelect.h + 8,
                                         btnMapSelect.w, std::max(rowH, shownRows * rowH)};
                        if (!availableMapFiles.empty() && SDL_PointInRect(&pt, &listBox)) {
                            const int idx = (pt.y - listBox.y) / rowH;
                            if (idx >= 0 && idx < shownRows) {
                                select_map_file_by_index(idx);
                                mapDropdownOpen = false;
                                hoveredMapIndex = -1;
                            }
                        } else {
                            mapDropdownOpen = false;
                            hoveredMapIndex = -1;
                        }
                    } else if (SDL_PointInRect(&pt, &btnAIMapSize)) {
                        // MAP SIZE is now a separate button beside AI GENERATED MAP, so its
                        // hitbox no longer overlaps the AI-map action.
                        aiMapShowSizeDialog = true;
                    } else if (SDL_PointInRect(&pt, &btnAIGenerated)) {
                        // Mandatory whenever no custom map is selected - AI-generated
                        // maps always carry both bombsites, so it can't be unticked on
                        // its own. Tapping the main AI-map row switches back to it from
                        // a custom map.
                        useCustomMap = false;
                        aiGeneratedMapActive = true;
                        generate_ai_map();
                    } else if (SDL_PointInRect(&pt, &btnDodgeRoll)) {
                        dodgeRollEnabled = !dodgeRollEnabled;
                        if (!dodgeRollEnabled) {
                            isDashing = false;
                            playerIsInvulnerable = false;
                            canShoot = true;
                        }
                    } else if (SDL_PointInRect(&pt, &btnWeaponMenu)) {
                        currentGameState = GameState::WEAPON_MENU;
                    } else if (SDL_PointInRect(&pt, &btnUseCustomMap)) {
                        // Toggling custom map off has nothing else to fall back on but
                        // the AI-generated (2 bombsites) map, so that tick re-activates
                        // automatically rather than leaving neither source selected.
                        if (selectedMapIndex >= 0) {
                            useCustomMap = !useCustomMap;
                            aiGeneratedMapActive = !useCustomMap;
                        }
                    }
                }
                    }
                continue;
            }

            if (event.type == SDL_KEYDOWN && currentGameState == GameState::PLAYING) {
                if (event.key.keysym.sym == SDLK_n) {
                    Game59NetTogglePanel();
                    continue;
                }
                if (event.key.keysym.sym >= SDLK_1 && event.key.keysym.sym <= SDLK_4) {
                    int slot = event.key.keysym.sym - SDLK_1;
                    if (slot < playerWeaponState.equippedCount) set_player_weapon(playerWeaponState.equipped[slot], currentTime);
                }
                // Squad commands:
                // 5 = Follow
                // 6 = Hold position
                // 8 = Reach Bombsite A
                // 9 = Reach Bombsite B
                //
                // Player speaks first, then the bots answer.
                if (event.key.keysym.sym == SDLK_5) {
                    issue_player_command(
                        BotCommand::FOLLOW_PLAYER,
                        VoiceLine::PLAYER_FOLLOW,
                        currentTime
                    );
                }

                if (event.key.keysym.sym == SDLK_6) {
                    issue_player_command(
                        BotCommand::HOLD_POSITION,
                        VoiceLine::PLAYER_HOLD,
                        currentTime
                    );
                }

                if (event.key.keysym.sym == SDLK_8) {
                    issue_player_command(
                        BotCommand::REACH_SITE_A,
                        VoiceLine::PLAYER_SITE_A,
                        currentTime
                    );
                }

                if (event.key.keysym.sym == SDLK_9) {
                    issue_player_command(
                        BotCommand::REACH_SITE_B,
                        VoiceLine::PLAYER_SITE_B,
                        currentTime
                    );
                }
                // Quick-swap: hop back to whatever was equipped before the current weapon.
                if (event.key.keysym.sym == SDLK_q) set_player_weapon(playerWeaponState.previous, currentTime, VoiceLine::QUICK_SWAP);
                // Shield moved off Q (now quick-swap) onto F.
                if (event.key.keysym.sym == SDLK_f) try_activate_shield(currentTime);

                // Optional double-tap arrow key dash: two presses of the SAME arrow key within
                // DOUBLE_TAP_WINDOW triggers a dash in that cardinal direction (or a
                // diagonal if an adjacent arrow is also currently held). event.key.repeat
                // guards against a held key auto-repeating into a false double-tap.
                if (dodgeRollEnabled && event.key.repeat == 0 && dashCooldown <= 0.0f && !isDashing) {
                    int arrowIdx = -1;
                    float tapDirX = 0.0f, tapDirY = 0.0f;
                    if (event.key.keysym.sym == SDLK_UP)    { arrowIdx = 0; tapDirY = -1.0f; }
                    if (event.key.keysym.sym == SDLK_DOWN)  { arrowIdx = 1; tapDirY =  1.0f; }
                    if (event.key.keysym.sym == SDLK_LEFT)  { arrowIdx = 2; tapDirX = -1.0f; }
                    if (event.key.keysym.sym == SDLK_RIGHT) { arrowIdx = 3; tapDirX =  1.0f; }

                    if (arrowIdx >= 0) {
                        float sinceLastTap = static_cast<float>(currentTime - lastArrowTapTime[arrowIdx]) / 1000.0f;
                        if (lastArrowTapTime[arrowIdx] != 0 && sinceLastTap <= DOUBLE_TAP_WINDOW) {
                            // Combine an adjacent held direction key for a diagonal dash.
                            const Uint8* dashState = SDL_GetKeyboardState(nullptr);
                            if (arrowIdx == 0 || arrowIdx == 1) { // vertical tap - check held horizontal
                                if (dashState[SDL_SCANCODE_LEFT])  tapDirX = -1.0f;
                                if (dashState[SDL_SCANCODE_RIGHT]) tapDirX =  1.0f;
                            } else { // horizontal tap - check held vertical
                                if (dashState[SDL_SCANCODE_UP])   tapDirY = -1.0f;
                                if (dashState[SDL_SCANCODE_DOWN]) tapDirY =  1.0f;
                            }
                            float len = std::sqrt(tapDirX * tapDirX + tapDirY * tapDirY);
                            if (len > 0.0001f) {
                                dashDirX = tapDirX / len; dashDirY = tapDirY / len;
                                dashDurationSetting = DOUBLE_TAP_DASH_DURATION;
                                isDashing = true; playerIsInvulnerable = true; canShoot = false;
                                dashStartedAt = currentTime; lastDashTriggeredAt = currentTime;
                                dashGhostCount = 0; lastGhostSpawnAt = 0;
                            }
                            lastArrowTapTime[arrowIdx] = 0; // consume - avoid chaining into a triple-tap
                        } else {
                            lastArrowTapTime[arrowIdx] = currentTime;
                        }
                    }
                }
            }

            if (event.type == SDL_MOUSEWHEEL && currentGameState == GameState::PLAYING) {
                int dir = (event.wheel.y > 0) ? 1 : (event.wheel.y < 0 ? -1 : 0);
                if (dir != 0) set_player_weapon(cycle_weapon(playerWeapon, dir), currentTime);
            }

            if ((currentGameState == GameState::GAME_OVER || currentGameState == GameState::GAME_WON) && 
                (event.type == SDL_MOUSEBUTTONDOWN || event.type == SDL_FINGERDOWN)) {
                // A TACTICAL mission is 10 rounds regardless of whether each round
                // is won or lost - dying doesn't end the mission early, it just
                // costs that round. Same bot roster (names/kills/deaths) carries
                // over round to round. Only clearing/losing round 10 (or an
                // ENDLESS run) returns to the menu, and resets the round count.
                bool continueNextRound = selectedMode == GameMode::TACTICAL &&
                                          currentRound < MAX_TACTICAL_ROUNDS;

                showMatchEndLeaderboard = false;
                showLeaderboardPanel = false;
                playerPosX = 5 * TILE_SIZE + 10; playerPosY = 5 * TILE_SIZE + 10;
                player.x = static_cast<int>(playerPosX); player.y = static_cast<int>(playerPosY);
                isTouchingDock = false;
                moveFingerId = -1;
                joystickMagnitude = 0.0f; joystickHoldTimer = 0.0f;
                isDashing = false; dashCooldown = 0.0f; canShoot = true; playerIsInvulnerable = false;
                dpadUpPressed = dpadDownPressed = dpadLeftPressed = dpadRightPressed = false;
                dpadUpLeftPressed = dpadUpRightPressed = dpadDownLeftPressed = dpadDownRightPressed = false;
                for (auto& id : padFingerId) id = -1;
                weaponSwipeActive = false; weaponSwipeFingerId = -1;

                if (continueNextRound) {
                    currentRound++;
                    if (aiGeneratedMapActive) generate_ai_map();
                    init_game_arena(true); // keepRoster: same bots, same names/tallies
                    if (customPlayerSpawnValid) {
                        playerPosX = customPlayerSpawn.x * TILE_SIZE + 10;
                        playerPosY = customPlayerSpawn.y * TILE_SIZE + 10;
                    }
                    player.x = static_cast<int>(playerPosX); player.y = static_cast<int>(playerPosY);
                    currentGameState = GameState::PLAYING;
                } else {
                    // Final result -> profile. Ensure the reward exists even if a
                    // state transition was missed during the result sequence.
                    if ((selectedMode == GameMode::ENDLESS || currentRound >= MAX_TACTICAL_ROUNDS) &&
                        !completedRunRewardIssued) {
                        award_completed_run_coins(currentTime);
                    }
                    currentGameState = GameState::MODE_SELECTION;
                }
            }

            if (currentGameState == GameState::PLAYING) {
                if (g_game59NetTestPanelOpen &&
                    (event.type == SDL_FINGERDOWN || event.type == SDL_FINGERMOTION || event.type == SDL_FINGERUP)) {
                    const int tx = static_cast<int>(event.tfinger.x * SCREEN_WIDTH);
                    const int ty = static_cast<int>(event.tfinger.y * SCREEN_HEIGHT);
                    const bool down = event.type == SDL_FINGERDOWN;
                    const bool up = event.type == SDL_FINGERUP;
                    if (Game59NetworkTestHandlePoint(tx, ty, down, up)) continue;
                }
                if (g_game59NetTestPanelOpen && event.type == SDL_MOUSEBUTTONDOWN) {
                    SDL_Point p = mouse_to_logical(renderer, event.button.x, event.button.y);
                    if (Game59NetworkTestHandlePoint(p.x, p.y, true)) continue;
                }
                if (g_game59NetTestPanelOpen && event.type == SDL_MOUSEMOTION) {
                    SDL_Point p = mouse_to_logical(renderer, event.motion.x, event.motion.y);
                    if (Game59NetworkTestHandlePoint(p.x, p.y, false)) continue;
                }
                if (g_game59NetTestPanelOpen && event.type == SDL_MOUSEBUTTONUP) {
                    SDL_Point p = mouse_to_logical(renderer, event.button.x, event.button.y);
                    if (Game59NetworkTestHandlePoint(p.x, p.y, false, true)) continue;
                }
                if (event.type == SDL_FINGERDOWN) {
                    float nx = event.tfinger.x, ny = event.tfinger.y;
                    SDL_Point backPt{static_cast<int>(nx * SCREEN_WIDTH), static_cast<int>(ny * SCREEN_HEIGHT)};
                    if (SDL_PointInRect(&backPt, &btnPlayingBack)) {
                        currentGameState = GameState::MODE_SELECTION;
                        mapDropdownOpen = false;
                        moveFingerId = -1;
                        isTouchingDock = false;
                        joystickMagnitude = 0.0f;
                        defuseHeld = false;
                        defuseStartTime = 0;
                        continue;
                    }
                    if (SDL_PointInRect(&backPt, &btnLeaderboard)) {
                        showLeaderboardPanel = !showLeaderboardPanel;
                        continue;
                    }
                    if ((lanNetwork.hosting || lanNetwork.connected || lanNetwork.joining)) {
                        const int netBoxW = std::min(360, SCREEN_WIDTH - 24);
                        const int netBoxX = SCREEN_WIDTH - netBoxW - 12;
                        SDL_Rect netBtn{netBoxX + netBoxW - 118, 78 + 66, 108, 22};
                        if (SDL_PointInRect(&backPt, &netBtn)) {
                            Game59NetTogglePanel();
                            continue;
                        }
                    }
                    float touchX = nx * SCREEN_WIDTH, touchY = ny * SCREEN_HEIGHT;
                    SDL_Point touchPt = { static_cast<int>(touchX), static_cast<int>(touchY) };
                    if (SDL_PointInRect(&touchPt, &btnBotCommands)) {
                        showBotCommands = !showBotCommands;
                        continue;
                    }
                    if (showBotCommands) {
                        for (int ci = 0; ci < 4; ++ci) {
                            SDL_Rect commandRect = bot_command_rect(ci);
                            if (SDL_PointInRect(&touchPt, &commandRect)) {
                                issue_bot_command(static_cast<BotCommand>(ci), currentTime);
                                showBotCommands = false;
                                break;
                            }
                        }
                        if (!showBotCommands) continue;
                    }

                    if (SDL_PointInRect(&touchPt, &vehicleInteractButton)) {
                        g_vehicleTouchInteractRequest = true;
                        continue;
                    }
                    if (in_weapon_zone(nx, ny)) {
                        int sector = radial_sector_at(touchPt.x - RADIAL_CX, touchPt.y - RADIAL_CY);
                        if (sector >= 0) {
                            if (weaponRadial[sector].type != WeaponType::COUNT) set_player_weapon(weaponRadial[sector].type, currentTime);
                        } else {
                            // Dead-zone tap - start tracking for a cycle-swipe instead.
                            weaponSwipeActive = true;
                            weaponSwipeFingerId = event.tfinger.fingerId;
                            weaponSwipeStartY = touchY;
                            weaponSwipeTriggered = false;
                        }
                    } else if (playerWeapon == WeaponType::PISTOL && SDL_PointInRect(&touchPt, &shieldButton)) {
                        try_activate_shield(currentTime);
                    } else if (selectedMode == GameMode::TACTICAL && tacticalBomb.planted && !tacticalBomb.defused &&
                               SDL_HasIntersection(&player, &tacticalBomb.rect) && SDL_PointInRect(&touchPt, &defuseButton)) {
                        defuseHeld = true;
                        if (defuseStartTime == 0) defuseStartTime = currentTime;
                    } else {
                        if (in_joystick_zone(nx, ny) && moveFingerId == -1) {
                            moveFingerId = event.tfinger.fingerId;
                            isTouchingDock = true;
                            joystickMagnitude = 0.0f;
                            joystickHoldTimer = 0.0f;
                            dockCenterX = touchPt.x; dockCenterY = touchPt.y;
                            dockBase.x = dockCenterX - dockBase.w / 2; dockBase.y = dockCenterY - dockBase.h / 2;
                            dockHandle.x = dockCenterX - dockHandle.w / 2; dockHandle.y = dockCenterY - dockHandle.h / 2;
                        }

                        if (touchX >= SCREEN_WIDTH / 2.0f) {
                            if (SDL_PointInRect(&touchPt, &padUpLeft)    && padFingerId[0] == -1) { dpadUpLeftPressed = true;    padFingerId[0] = event.tfinger.fingerId; }
                            if (SDL_PointInRect(&touchPt, &padUp)        && padFingerId[1] == -1) { dpadUpPressed = true;        padFingerId[1] = event.tfinger.fingerId; }
                            if (SDL_PointInRect(&touchPt, &padUpRight)   && padFingerId[2] == -1) { dpadUpRightPressed = true;   padFingerId[2] = event.tfinger.fingerId; }
                            if (SDL_PointInRect(&touchPt, &padLeft)      && padFingerId[3] == -1) { dpadLeftPressed = true;      padFingerId[3] = event.tfinger.fingerId; }
                            if (SDL_PointInRect(&touchPt, &padRight)     && padFingerId[4] == -1) { dpadRightPressed = true;     padFingerId[4] = event.tfinger.fingerId; }
                            if (SDL_PointInRect(&touchPt, &padDownLeft) && padFingerId[5] == -1) { dpadDownLeftPressed = true; padFingerId[5] = event.tfinger.fingerId; }
                            if (SDL_PointInRect(&touchPt, &padDown)     && padFingerId[6] == -1) { dpadDownPressed = true;     padFingerId[6] = event.tfinger.fingerId; }
                            if (SDL_PointInRect(&touchPt, &padDownRight)&& padFingerId[7] == -1) { dpadDownRightPressed = true;padFingerId[7] = event.tfinger.fingerId; }
                        }
                    }
                } else if (event.type == SDL_FINGERMOTION) {
                    if (event.tfinger.fingerId == weaponSwipeFingerId && weaponSwipeActive && !weaponSwipeTriggered) {
                        float touchY = event.tfinger.y * SCREEN_HEIGHT;
                        float dy = touchY - weaponSwipeStartY;
                        constexpr float SWIPE_THRESHOLD = 45.0f;
                        if (dy <= -SWIPE_THRESHOLD) { // swiped up -> next weapon
                            set_player_weapon(cycle_weapon(playerWeapon, 1), currentTime);
                            weaponSwipeFeedbackDir = 1;
                            weaponSwipeTriggered = true;
                        } else if (dy >= SWIPE_THRESHOLD) { // swiped down -> previous weapon
                            set_player_weapon(cycle_weapon(playerWeapon, -1), currentTime);
                            weaponSwipeFeedbackDir = -1;
                            weaponSwipeTriggered = true;
                        }
                    }
                    if (event.tfinger.fingerId == moveFingerId && isTouchingDock) {
                        float touchX = event.tfinger.x * SCREEN_WIDTH;
                        float touchY = event.tfinger.y * SCREEN_HEIGHT;
                        float dx = touchX - dockCenterX, dy = touchY - dockCenterY;
                        float dist = std::sqrt(dx * dx + dy * dy);

                        if (dist > 0) {
                            moveVecX = dx / dist; moveVecY = dy / dist;
                            float clampDist = std::min(dist, dockBase.w / 2.0f);
                            joystickMagnitude = clampDist / (dockBase.w / 2.0f);
                            dockHandle.x = dockCenterX + static_cast<int>((dx / dist) * clampDist) - dockHandle.w / 2;
                            dockHandle.y = dockCenterY + static_cast<int>((dy / dist) * clampDist) - dockHandle.h / 2;
                        }
                    }
                } else if (event.type == SDL_FINGERUP) {
                    if (event.tfinger.fingerId == weaponSwipeFingerId) {
                        weaponSwipeActive = false;
                        weaponSwipeFingerId = -1;
                    }
                    if (selectedMode == GameMode::TACTICAL) {
                        float touchX = event.tfinger.x * SCREEN_WIDTH;
                        float touchY = event.tfinger.y * SCREEN_HEIGHT;
                        SDL_Point touchPt = {static_cast<int>(touchX), static_cast<int>(touchY)};
                        if (SDL_PointInRect(&touchPt, &defuseButton)) {
                            defuseHeld = false;
                            defuseStartTime = 0;
                        }
                    }
                    if (event.tfinger.fingerId == moveFingerId) {
                        moveFingerId = -1; isTouchingDock = false; moveVecX = 0.0f; moveVecY = 0.0f;
                        joystickMagnitude = 0.0f; joystickHoldTimer = 0.0f; // release resets the long-press charge
                    }

                    // Release by fingerId, not by current touch position - a finger that
                    // drags off the button (or lifts elsewhere on screen) still releases
                    // whichever pad button it originally pressed, instead of leaving that
                    // direction stuck "pressed" forever.
                    SDL_FingerID upFinger = event.tfinger.fingerId;
                    if (padFingerId[0] == upFinger) { dpadUpLeftPressed = false; padFingerId[0] = -1; }
                    if (padFingerId[1] == upFinger) { dpadUpPressed = false; padFingerId[1] = -1; }
                    if (padFingerId[2] == upFinger) { dpadUpRightPressed = false; padFingerId[2] = -1; }
                    if (padFingerId[3] == upFinger) { dpadLeftPressed = false; padFingerId[3] = -1; }
                    if (padFingerId[4] == upFinger) { dpadRightPressed = false; padFingerId[4] = -1; }
                    if (padFingerId[5] == upFinger) { dpadDownLeftPressed = false; padFingerId[5] = -1; }
                    if (padFingerId[6] == upFinger) { dpadDownPressed = false; padFingerId[6] = -1; }
                    if (padFingerId[7] == upFinger) { dpadDownRightPressed = false; padFingerId[7] = -1; }
                }

                if (event.type == SDL_MOUSEBUTTONDOWN) {
                    SDL_Point clickPt = mouse_to_logical(renderer, event.button.x, event.button.y);
                    if (lanNetwork.hosting || lanNetwork.connected || lanNetwork.joining) {
                        const int netBoxW = std::min(360, SCREEN_WIDTH - 24);
                        const int netBoxX = SCREEN_WIDTH - netBoxW - 12;
                        SDL_Rect netBtn{netBoxX + netBoxW - 118, 78 + 66, 108, 22};
                        if (SDL_PointInRect(&clickPt, &netBtn)) {
                            Game59NetTogglePanel();
                            continue;
                        }
                    }
                    if (SDL_PointInRect(&clickPt, &btnPlayingBack)) {
                        currentGameState = GameState::MODE_SELECTION;
                        mapDropdownOpen = false;
                        moveFingerId = -1;
                        isTouchingDock = false;
                        joystickMagnitude = 0.0f;
                        defuseHeld = false;
                        defuseStartTime = 0;
                    } else if (SDL_PointInRect(&clickPt, &btnLeaderboard)) {
                        showLeaderboardPanel = !showLeaderboardPanel;
                    } else if (SDL_PointInRect(&clickPt, &btnBotCommands)) {
                        showBotCommands = !showBotCommands;
                    } else if (showBotCommands) {
                        for (int ci = 0; ci < 4; ++ci) {
                            SDL_Rect commandRect = bot_command_rect(ci);
                            if (SDL_PointInRect(&clickPt, &commandRect)) {
                                issue_bot_command(static_cast<BotCommand>(ci), currentTime);
                                showBotCommands = false;
                                break;
                            }
                        }
                    } else if (SDL_PointInRect(&clickPt, &vehicleInteractButton)) {
                        g_vehicleTouchInteractRequest = true;
                    } else if (in_weapon_zone(static_cast<float>(clickPt.x) / SCREEN_WIDTH, static_cast<float>(clickPt.y) / SCREEN_HEIGHT)) {
                        int sector = radial_sector_at(clickPt.x - RADIAL_CX, clickPt.y - RADIAL_CY);
                        if (sector >= 0) if (weaponRadial[sector].type != WeaponType::COUNT) set_player_weapon(weaponRadial[sector].type, currentTime);
                    } else if (playerWeapon == WeaponType::PISTOL && SDL_PointInRect(&clickPt, &shieldButton)) {
                        try_activate_shield(currentTime);
                    } else if (selectedMode == GameMode::TACTICAL && tacticalBomb.planted && !tacticalBomb.defused &&
                               SDL_HasIntersection(&player, &tacticalBomb.rect) && SDL_PointInRect(&clickPt, &defuseButton)) {
                        defuseHeld = true;
                        if (defuseStartTime == 0) defuseStartTime = currentTime;
                    } else if (moveFingerId == -1) {
                        if (SDL_PointInRect(&clickPt, &padUpLeft))    dpadUpLeftPressed = true;
                        if (SDL_PointInRect(&clickPt, &padUp))        dpadUpPressed = true;
                        if (SDL_PointInRect(&clickPt, &padUpRight))  dpadUpRightPressed = true;
                        if (SDL_PointInRect(&clickPt, &padLeft))     dpadLeftPressed = true;
                        if (SDL_PointInRect(&clickPt, &padRight))    dpadRightPressed = true;
                        if (SDL_PointInRect(&clickPt, &padDownLeft)) dpadDownLeftPressed = true;
                        if (SDL_PointInRect(&clickPt, &padDown))     dpadDownPressed = true;
                        if (SDL_PointInRect(&clickPt, &padDownRight))dpadDownRightPressed = true;
                    }
                }
                if (event.type == SDL_MOUSEBUTTONUP && moveFingerId == -1) {
                    dpadUpPressed = dpadDownPressed = dpadLeftPressed = dpadRightPressed = false;
                    dpadUpLeftPressed = dpadUpRightPressed = dpadDownLeftPressed = dpadDownRightPressed = false;
                    defuseHeld = false;
                    defuseStartTime = 0;
                }
            }
        }

        if (currentGameState == GameState::TACTICAL_CONFIG) {
            SDL_SetRenderDrawColor(renderer, 15, 18, 25, 255);
            SDL_RenderClear(renderer);
            render_tactical_config(renderer);
            render_badge_popup(renderer);
            draw_multiplayer_scoreboard(renderer);

    int scoreboard_screen_w = 1280;
    int scoreboard_screen_h = 720;
    SDL_GetRendererOutputSize(renderer, &scoreboard_screen_w, &scoreboard_screen_h);
    update_scoreboard_touch_button(scoreboard_screen_w, scoreboard_screen_h);
    draw_scoreboard_touch_button(renderer);

    SDL_RenderPresent(renderer);
            SDL_Delay(16);
            continue;
        }

        if (currentGameState == GameState::MAP_EDITOR) {
            SDL_SetRenderDrawColor(renderer, 20, 20, 25, 255);
            SDL_RenderClear(renderer);
            render_map_editor(renderer, currentTime);
            render_badge_popup(renderer);
            SDL_RenderPresent(renderer);
            SDL_Delay(16);
            continue;
        }

        if (currentGameState == GameState::WEAPON_MENU) {
            render_weapon_menu(renderer);
            render_badge_popup(renderer);
            SDL_RenderPresent(renderer);
            SDL_Delay(16);
            continue;
        }

        if (currentGameState == GameState::MULTIPLAYER_WIFI) {
            render_multiplayer_wifi(renderer);
            render_badge_popup(renderer);
            SDL_RenderPresent(renderer);
            SDL_Delay(16);
            continue;
        }

        if (currentGameState == GameState::MODE_SELECTION) {
            // Keep the menu background solid dark black so no previous game/menu
            // frame or Help overlay can remain visible behind the controls.
            SDL_SetRenderDrawColor(renderer, 0, 0, 0, 255);
            SDL_RenderClear(renderer);
            render_mode_selection(renderer);
            if (showFirstRunTutorial) render_first_run_tutorial(renderer);
            render_badge_popup(renderer);
            SDL_RenderPresent(renderer);
            SDL_Delay(16);
            continue;
        }

        if (currentGameState == GameState::PLAYING) {
            // STEP 17.36: weather is part of the active map/gameplay loop.
            // It only advances while the player is actually playing.
            weather_update(currentTime, deltaTime);

            const Uint8* state = SDL_GetKeyboardState(nullptr);
            // STEP 17.39: vehicle driving/entry/exit uses the same authoritative map collision.
            const bool vehicleTouchInteract = g_vehicleTouchInteractRequest;
            g_vehicleTouchInteractRequest = false;
            UpdateAllGameplayVisuals(deltaTime);

            VehicleUpdate(deltaTime, state,
                          moveVecX * joystickMagnitude,
                          moveVecY * joystickMagnitude,
                          vehicleTouchInteract,
                          playerPosX, playerPosY, player, playerHp,
                          (lanNetwork.hosting || lanNetwork.connected) ? lanNetwork.localPlayerId : 0);
            const bool drivingVehicle = g_activeVehicle >= 0;
            // VehicleUpdate temporarily disables infantry firing while the player is
            // driving. Restore it immediately after exiting the vehicle so the
            // player can shoot again; otherwise canShoot could remain false forever.
            if (!drivingVehicle && !isDashing) canShoot = true;
            const bool lanWaitingForGo = (lanNetwork.hosting || lanNetwork.connected) &&
                                         lanMatchStarted && lanMatchPhase != 2;
            const float countdownHoldX = playerPosX;
            const float countdownHoldY = playerPosY;

            if (playerShieldActive && currentTime - playerShieldActivatedAt >= SHIELD_DURATION_MS) {
                playerShieldActive = false;
                playerShieldReadyAt = currentTime + SHIELD_COOLDOWN_MS;
            }
            // Switching off pistol drops the shield immediately - it's a pistol-exclusive ability.
            if (playerShieldActive && playerWeapon != WeaponType::PISTOL) {
                playerShieldActive = false;
                playerShieldReadyAt = currentTime + SHIELD_COOLDOWN_MS;
            }


            if (selectedMode == GameMode::TACTICAL && state[SDL_SCANCODE_SPACE]) {
                defuseHeld = true;
            } else if (selectedMode == GameMode::TACTICAL && !defuseHeld) {
                defuseStartTime = 0;
            }

            // A driver is controlled exclusively by VehicleUpdate. Do not let
            // the infantry controller, dash, or weapon system move/fire the
            // player again after the vehicle has updated its position.
            if (drivingVehicle) {
                playerController.velocityX = playerController.velocityY = 0.0f;
                isDashing = false;
                canShoot = false;
            }

            // Dash/roll cooldown ticks down every frame using real delta time.
            if (!drivingVehicle && dashCooldown > 0.0f) dashCooldown = std::max(0.0f, dashCooldown - deltaTime);

            if (!drivingVehicle) {
            // --- Optional long-press joystick dodge roll: accumulate hold time while the stick
            // is deflected past the deadzone threshold; auto-trigger once it crosses
            // LONG_PRESS_DURATION (frame-rate independent via deltaTime). ---
            bool joystickDeflected = isTouchingDock && joystickMagnitude >= JOYSTICK_DEFLECT_THRESHOLD;
            if (dodgeRollEnabled && joystickDeflected && !isDashing) {
                joystickHoldTimer += deltaTime;
                if (joystickHoldTimer >= LONG_PRESS_DURATION && dashCooldown <= 0.0f) {
                    // Lock roll direction to the exact stick vector at the instant threshold is met.
                    dashDirX = moveVecX; dashDirY = moveVecY;
                    dashDurationSetting = JOYSTICK_ROLL_DURATION;
                    isDashing = true; playerIsInvulnerable = true; canShoot = false;
                    dashStartedAt = currentTime; lastDashTriggeredAt = currentTime;
                    dashGhostCount = 0; lastGhostSpawnAt = 0;
                    joystickHoldTimer = 0.0f;
                }
            } else if (!isDashing) {
                joystickHoldTimer = 0.0f; // released or returned to deadzone - charge resets
            }

            // --- Resolve dash end / cooldown start ---
            if (isDashing) {
                float dashElapsed = static_cast<float>(currentTime - dashStartedAt) / 1000.0f;
                if (dashElapsed >= dashDurationSetting) {
                    isDashing = false;
                    playerIsInvulnerable = false;
                    canShoot = true;
                    dashCooldown = DASH_COOLDOWN;
                }
            }

            float vx, vy;
            if (isDashing) {
                // Burst movement at 2.5x walk speed along the locked roll/dash direction.
                vx = dashDirX * WALK_SPEED * DASH_SPEED_MULT;
                vy = dashDirY * WALK_SPEED * DASH_SPEED_MULT;

                // Afterimage ghost trail: sample the player's position a few times per roll.
                if (currentTime - lastGhostSpawnAt >= 30 && dashGhostCount < static_cast<int>(dashGhosts.size())) {
                    dashGhosts[dashGhostCount++] = { playerPosX, playerPosY, currentTime };
                    lastGhostSpawnAt = currentTime;
                }
            } else {
                // Polished controller: unified keyboard/touch input, normalized
                // diagonals, gentle acceleration and responsive deceleration.
                float desiredMoveX = 0.0f, desiredMoveY = 0.0f;
                controller_build_move_input(state, moveVecX, moveVecY, desiredMoveX, desiredMoveY);
                controller_update_velocity(desiredMoveX, desiredMoveY, false, vx, vy);
            }

            // Tile-map collision checks apply during the roll/dash too - the player
            // cannot phase through solid walls even at burst speed.
            SDL_Rect nPx = player; nPx.x += static_cast<int>(vx);
            if (!check_wall_collision(nPx)) { playerPosX += vx; player.x = static_cast<int>(playerPosX); }
            else if (isDashing) { isDashing = false; playerIsInvulnerable = false; canShoot = true; dashCooldown = DASH_COOLDOWN; } // roll into a wall ends it early
            SDL_Rect nPy = player; nPy.y += static_cast<int>(vy);
            if (!check_wall_collision(nPy)) { playerPosY += vy; player.y = static_cast<int>(playerPosY); }

            // During the synchronized countdown, freeze the local player exactly
            // where the host/client snapshot last placed them.
            if (lanWaitingForGo) {
                playerPosX = countdownHoldX;
                playerPosY = countdownHoldY;
                player.x = static_cast<int>(playerPosX);
                player.y = static_cast<int>(playerPosY);
                playerController.velocityX = playerController.velocityY = 0.0f;
            }

            // Multiplayer: exchange player inputs and authoritative positions.
            // The host simulates remote players; clients receive snapshots.
            if (lanNetwork.hosting || lanNetwork.connected) {
                float netInputX = 0.0f, netInputY = 0.0f;
                controller_build_move_input(state, moveVecX, moveVecY, netInputX, netInputY);
                lan_multiplayer_tick(currentTime, deltaTime, playerPosX, playerPosY,
                                     playerHp, playerName, netInputX, netInputY);
                VehicleHostApplyRemotePlayerCollisions(currentTime);
                VehicleHostResolveDestroyed(playerPosX, playerPosY, player, playerHp, currentTime);
                // Blend toward the host's last authoritative position instead of the
                // hard-snap lan_multiplayer_tick used to apply directly (client only;
                // no-ops while hosting, since the host's own simulation is truth).
                Game59SmoothCorrectLocalPlayer(playerPosX, playerPosY, player, deltaTime);
                player.x = static_cast<int>(playerPosX);
                player.y = static_cast<int>(playerPosY);
            }

            }

            float pCx = playerPosX + player.w / 2.0f;
            float pCy = playerPosY + player.h / 2.0f;
            Uint32 curCooldown = WEAPON_PROPS[static_cast<int>(playerWeapon)].cooldownMs;

            // Tick ammo/reload state every frame (not just on frames where the
            // player is actively trying to fire) so an empty magazine actually
            // auto-reloads instead of permanently blocking the weapon.
            if (!drivingVehicle && playerHp > 0) combat_tick_player_weapon(playerWeapon, currentTime);

            // Firing is disabled entirely while dashing/rolling.
            if (!drivingVehicle && !lanWaitingForGo && canShoot && playerHp > 0 && combat_can_fire(playerWeapon) && currentTime - lastShootTime >= curCooldown) {
                bool shootUp    = state[SDL_SCANCODE_UP]    || dpadUpPressed || dpadUpLeftPressed || dpadUpRightPressed;
                bool shootDown  = state[SDL_SCANCODE_DOWN]  || dpadDownPressed || dpadDownLeftPressed || dpadDownRightPressed;
                bool shootLeft  = state[SDL_SCANCODE_LEFT]  || dpadLeftPressed || dpadUpLeftPressed || dpadDownLeftPressed;
                bool shootRight = state[SDL_SCANCODE_RIGHT] || dpadRightPressed || dpadUpRightPressed || dpadDownRightPressed;

                // 8-directional aiming: combine held direction keys into a single
                // (possibly diagonal) vector, e.g. UP+RIGHT -> up-right at 45 degrees.
                float aimX = 0.0f, aimY = 0.0f;
                if (shootUp)    aimY -= 1.0f;
                if (shootDown)  aimY += 1.0f;
                if (shootLeft)  aimX -= 1.0f;
                if (shootRight) aimX += 1.0f;

                if (aimX != 0.0f || aimY != 0.0f) {
                    float alen = std::sqrt(aimX * aimX + aimY * aimY);
                    lastPlayerAimX = aimX / alen;
                    lastPlayerAimY = aimY / alen;
                    {
                        if (lanNetwork.hosting) {
                            float al = std::sqrt(aimX*aimX + aimY*aimY);
                            lan_host_spawn_shot(1, pCx, pCy, static_cast<int>(playerWeapon), aimX/al, aimY/al);
                            lan_host_send_shot_event(1, static_cast<int>(playerWeapon), pCx, pCy, aimX/al, aimY/al);
                        } else if (lanNetwork.connected) {
                            lan_multiplayer_request_shot(playerWeapon, aimX, aimY);
                        } else {
                            spawn_vector_bullet(pCx, pCy, aimX, aimY, true, playerWeapon);
                        }
                        lastPlayerFireAt = currentTime;
                    }
                    combat_commit_player_shot(playerWeapon, currentTime);
                    WeaponVisual_OnFire(renderer, static_cast<int>(pCx + aimX * 34.0f - cameraX),
                                        static_cast<int>(pCy + aimY * 34.0f - cameraY));
                    // Player shots do not spawn the vehicle tracer.
                    // Weapon-specific projectile/laser visuals remain unchanged.
                    lastShootTime = currentTime;
                }
            }

            for (auto& hp : healthPacks) {
                if (hp.active && SDL_HasIntersection(&player, &hp.rect)) {
                    hp.active = false; 
                    playerHp = playerMaxHp;
                }
            }

            for (auto& coin : coins) {
                if (!coin.active) continue;

                // COIN MAGNET: attract only coins inside the local pickup field.
                // Coins elsewhere stay on the map until the player gets close.
                if (playerWeapon == WeaponType::COIN_MAGNET) {
                    float ccx = coin.rect.x + coin.rect.w * 0.5f;
                    float ccy = coin.rect.y + coin.rect.h * 0.5f;
                    float dx = pCx - ccx;
                    float dy = pCy - ccy;
                    float dist = std::sqrt(dx * dx + dy * dy);
                    if (dist > 0.5f && dist <= COIN_MAGNET_RADIUS) {
                        float pull = std::min(34.0f, 10.0f + 1800.0f / std::max(60.0f, dist));
                        float step = std::min(pull, dist);
                        coin.rect.x += static_cast<int>(std::round(dx / dist * step));
                        coin.rect.y += static_cast<int>(std::round(dy / dist * step));
                    }
                }

                if (SDL_HasIntersection(&player, &coin.rect)) {
                    coin.active = false;
                    coinBalance += COIN_VALUE;
                    play_coin_sound();
                    progressSavePending = true;
                }
            }

            if (selectedMode == GameMode::TACTICAL) {
                if (tacticalBomb.planted && !tacticalBomb.defused) {
                    bool nearBomb = SDL_HasIntersection(&player, &tacticalBomb.rect);
                    if (defuseHeld && nearBomb) {
                        if (defuseStartTime == 0) defuseStartTime = currentTime;
                        if (currentTime - defuseStartTime >= DEFUSE_TIME_MS) {
                            tacticalBomb.defused = true;
                            botDefuserIndex = -1;
                            playerBombDefuses++;
                            lifetimeBombDefuses++;
                            check_badge_unlocks();
                            defuseHeld = false;
                            defuseStartTime = 0;
                            score += 100;
                            currentGameState = GameState::GAME_WON;
                        }
                    } else {
                        // Leaving the bomb or releasing the button resets the hold timer.
                        defuseStartTime = 0;
                    }

                    // Fuse tick: beep interval and pitch both scale with remaining time
                    // percentage (not a fixed second count), so a longer fuse from a
                    // bigger enemy squad still sounds calm early and urgent late.
                    Uint32 fuseElapsed = currentTime - tacticalBomb.plantTime;
                    if (fuseElapsed < tacticalBomb.fuseDuration) {
                        float remainingFrac = 1.0f - static_cast<float>(fuseElapsed) / static_cast<float>(tacticalBomb.fuseDuration);
                        Uint32 beepInterval = static_cast<Uint32>(120 + remainingFrac * remainingFrac * 680); // ~800ms -> ~120ms
                        if (currentTime - lastFuseBeepTime >= beepInterval) {
                            float beepFreq = 600.0f + (1.0f - remainingFrac) * (1.0f - remainingFrac) * 700.0f; // 600Hz -> 1300Hz
                            play_fuse_beep(beepFreq, 0.6f);
                            lastFuseBeepTime = currentTime;
                        }
                    }

                    if (!tacticalBomb.defused && currentTime - tacticalBomb.plantTime >= tacticalBomb.fuseDuration) {
                        trigger_explosion(tacticalBomb.x, tacticalBomb.y, 500.0f, 200, player, playerHp);
                        if (selectedMode == GameMode::ENDLESS) playerDiedThisEndlessRun = true;
                        currentGameState = GameState::GAME_OVER;
                    }
                }
            }

            bool allEnemiesDefeated = true;
            for (int i = 0; i < activeEnemyCount; ++i) {
                if (enemies[i].active && enemies[i].hp > 0) {
                    allEnemiesDefeated = false;
                    break;
                }
            }

            // TACTICAL: if every enemy is eliminated before the bomb is ever planted,
            // there's no one left to plant it - mission accomplished by attrition.
            // (Once the bomb IS planted, the mission is won only by defusing it, even
            // if the last enemy standing dies to the fuse or a stray shot.)
            // activeEnemyCount can be configured down to 0 Raiders. With no enemies,
            // the loop above never runs and allEnemiesDefeated stays true by vacuous
            // truth from the very first frame of PLAYING - guard against treating
            // "nobody to eliminate" as an instant attrition win.
            if (selectedMode == GameMode::TACTICAL && activeEnemyCount > 0 && allEnemiesDefeated && !tacticalBomb.planted && !tacticalBomb.defused) {
                currentGameState = GameState::GAME_WON;
            }

            // Wave progression only applies to ENDLESS mode. In TACTICAL mode, if all enemies
            // are a one-time fixed squad chosen at mission config - once they're dead,
            // they stay dead; the mission is won by defusing the bomb, not by attrition.
            if (allEnemiesDefeated && selectedMode == GameMode::ENDLESS) {
                currentLevel++;
                highestEndlessWave = std::max(highestEndlessWave, currentLevel);
                check_badge_unlocks();
                activeEnemyCount = std::min(3 + currentLevel, MAX_ENEMIES);

                for (int i = 0; i < activeEnemyCount; ++i) {
                    spawn_single_enemy(enemies[i], i);
                }
                
                highScore = std::max(highScore, score);
            }

            // FIRE GUN ground hazard: an impact zone stays lit for a while after
            // the hit, so any enemy that walks into it gets ignited too - not just
            // whoever was standing there the instant the round landed. Lets one
            // fire gun shot punish a whole group as they move through the area.
            for (auto& fi : fireImpacts) {
                if (!fi.active) continue;
                if (currentTime - fi.spawnTime >= fi.duration) { fi.active = false; continue; }
                for (int fei = 0; fei < activeEnemyCount; ++fei) {
                    auto& fireVictim = enemies[fei];
                    if (!fireVictim.active || fireVictim.hp <= 0) continue;
                    float vx = fireVictim.x + fireVictim.rect.w * 0.5f;
                    float vy = fireVictim.y + fireVictim.rect.h * 0.5f;
                    float fdx = vx - fi.x, fdy = vy - fi.y;
                    if (fdx * fdx + fdy * fdy <= fi.radius * fi.radius) {
                        fireVictim.burningUntil = std::max(fireVictim.burningUntil, currentTime + 400);
                        fireVictim.nextBurnTick = std::min(fireVictim.nextBurnTick, currentTime + 250);
                    }
                }
            }

            for (int i = 0; i < activeEnemyCount; ++i) {
                auto& enemy = enemies[i];
                if (!enemy.active) continue;

                recover_enemy_from_wall(enemy);

                // Ice Gun freeze: a frozen enemy cannot move or fire until the
                // freeze timer expires. The visual frost overlay is rendered below.
                // WIND GUN: after the knockback lands, a hit pins the enemy in
                // place and spins it around its own center axis - no orbiting
                // around a distant point - while heavy DOT tears through it.
                if (enemy.windTornadoActive) {
                    if (currentTime < enemy.cycloneUntil) {
                        float elapsed = static_cast<float>(currentTime - enemy.cycloneStartTime);
                        float spinT = std::min(1.0f, elapsed / static_cast<float>(WIND_TORNADO_DURATION_MS));
                        // The vortex winds up - slow at first, whipping faster
                        // as it tightens toward the kill.
                        float angularSpeed = 0.28f + spinT * 1.05f;
                        enemy.cycloneAngle += angularSpeed;
                        // Rooted in place: only the rotation changes, position doesn't.
                        enemy.rect.x = static_cast<int>(enemy.cycloneCenterX);
                        enemy.rect.y = static_cast<int>(enemy.cycloneCenterY);
                        enemy.x = enemy.cycloneCenterX;
                        enemy.y = enemy.cycloneCenterY;
                        enemy.windPushX = enemy.windPushY = 0.0f;
                        // Spinning victims are fully disoriented and cannot shoot.
                        enemy.shootCooldown = std::max(enemy.shootCooldown, currentTime + 250);

                        if (currentTime >= enemy.nextWindTick) {
                            enemy.hp -= WIND_TORNADO_TICK_DAMAGE;
                            enemy.nextWindTick = currentTime + WIND_TORNADO_TICK_INTERVAL_MS;
                            if (enemy.hp <= 0) {
                                enemy.windTornadoActive = false;
                                enemy.active = false;
                                enemy.deaths = 1;
                                score += 10;
                                highScore = std::max(highScore, score);
                                playerKills++;
                                lifetimeKills++;
                                ++weaponKills[static_cast<int>(WeaponType::WIND_GUN)];
                                check_badge_unlocks();
                                continue;
                            }
                        }
                    } else {
                        // Survived the spin-up - the tornado finishes what it
                        // started. A sustained Wind Gun hit is meant to kill.
                        enemy.windTornadoActive = false;
                        enemy.hp = 0;
                        enemy.active = false;
                        enemy.deaths = 1;
                        score += 10;
                        highScore = std::max(highScore, score);
                        playerKills++;
                        lifetimeKills++;
                        ++weaponKills[static_cast<int>(WeaponType::WIND_GUN)];
                        check_badge_unlocks();
                        continue;
                    }
                } else if (currentTime < enemy.windPushUntil) {
                    float damp = WIND_PUSH_DAMPING;
                    float nx = enemy.x + enemy.windPushX;
                    float ny = enemy.y + enemy.windPushY;
                    SDL_Rect nr = enemy.rect; nr.x=(int)nx; nr.y=(int)ny;
                    if (!check_wall_collision(nr)) {
                        enemy.x=nx; enemy.y=ny; enemy.rect=nr;
                    } else if (!enemy.windSlamApplied) {
                        // Slammed into a wall mid-push: a solid bonus hit that rewards
                        // knocking enemies into cover instead of open space.
                        enemy.windSlamApplied = true;
                        enemy.hp -= WIND_SLAM_DAMAGE;
                        if (enemy.hp <= 0) {
                            enemy.active = false;
                            enemy.deaths = 1;
                            score += 10;
                            highScore = std::max(highScore, score);
                            playerKills++;
                            lifetimeKills++;
                            ++weaponKills[static_cast<int>(WeaponType::WIND_GUN)];
                            check_badge_unlocks();
                            continue;
                        }
                    }
                    enemy.windPushX*=damp; enemy.windPushY*=damp;

                    // Chip damage while airborne - puts WIND_DAMAGE_PER_TICK to use so
                    // the knockback itself hurts, not just the shoot lockout.
                    if (currentTime >= enemy.nextWindTick) {
                        enemy.hp -= WIND_DAMAGE_PER_TICK;
                        enemy.nextWindTick = currentTime + WIND_TICK_INTERVAL_MS;
                        if (enemy.hp <= 0) {
                            enemy.active = false;
                            enemy.deaths = 1;
                            score += 10;
                            highScore = std::max(highScore, score);
                            playerKills++;
                            lifetimeKills++;
                            ++weaponKills[static_cast<int>(WeaponType::WIND_GUN)];
                            check_badge_unlocks();
                            continue;
                        }
                    }
                } else if (enemy.windTornadoPending) {
                    // WIND GUN tornado follow-up: the knockback just finished -
                    // pin the enemy in place and start spinning it around its
                    // own center axis, right where it landed, so a single hit
                    // delivers both the push and the (lethal) tornado.
                    enemy.windTornadoPending = false;
                    enemy.windTornadoActive = true;
                    enemy.cycloneCenterX = enemy.x;
                    enemy.cycloneCenterY = enemy.y;
                    enemy.cycloneAngle = 0.0f;
                    enemy.cycloneRadius = WIND_TORNADO_RADIUS;
                    enemy.cycloneStartTime = currentTime;
                    enemy.cycloneUntil = currentTime + WIND_TORNADO_DURATION_MS;
                    enemy.nextWindTick = currentTime + WIND_TORNADO_TICK_INTERVAL_MS;
                }
                bool enemyFrozen = currentTime < enemy.iceSlowUntil;

                // FIRE GUN burn-over-time. Burning is deliberately separate from the
                // impact damage so the target continues taking small flame damage.
                if (enemy.burningUntil > currentTime && enemy.hp > 0 && currentTime >= enemy.nextBurnTick) {
                    enemy.hp -= std::max(2, WEAPON_PROPS[static_cast<int>(WeaponType::FIRE_GUN)].damage / 3);
                    enemy.nextBurnTick = currentTime + 250;
                    enemy.lastFlameBurstAt = currentTime;
                    if (enemy.hp <= 0) {
                        enemy.active = false;
                        enemy.deaths = 1;
                        score += 10;
                        highScore = std::max(highScore, score);
                        playerKills++;
                        lifetimeKills++;
                        ++weaponKills[static_cast<int>(WeaponType::FIRE_GUN)];
                        check_badge_unlocks();
                        continue;
                    }
                }

                // Electric shield: any enemy that touches the player while it's up is instantly fried.
                if (playerShieldActive && SDL_HasIntersection(&enemy.rect, &player)) {
                    enemy.hp = 0;
                    enemy.active = false;
                    enemy.deaths = 1;
                    score += 10;
                    highScore = std::max(highScore, score);
                    continue;
                }

                // Any living enemy can plant the bomb. There is no dedicated carrier.
                if (selectedMode == GameMode::TACTICAL && !tacticalBomb.planted) {
                    Point enemyTile{static_cast<int>(enemy.x + enemy.rect.w / 2) / TILE_SIZE,
                                    static_cast<int>(enemy.y + enemy.rect.h / 2) / TILE_SIZE};
                    Point chosenSite = selectedBombSite;
                    tacticalBomb.x = chosenSite.x * TILE_SIZE + 8;
                    tacticalBomb.y = chosenSite.y * TILE_SIZE + 8;
                    tacticalBomb.rect = {static_cast<int>(tacticalBomb.x), static_cast<int>(tacticalBomb.y), 35, 35};
                    // Plant as soon as the bomber is close enough.  A single
                    // surviving RED enemy must never wait for the rest of the
                    // squad or get stuck trying to stand on the exact site tile.
                    // The 2-tile fallback also makes narrow/cornered custom maps
                    // playable when the enemy can reach the site area but not its
                    // exact 60x60 tile footprint.
                    int plantRange = (count_active_enemies() <= 1) ? 2 : 1;
                    if (std::abs(enemyTile.x-chosenSite.x) <= plantRange &&
                        std::abs(enemyTile.y-chosenSite.y) <= plantRange) {
                        trigger_bomb_plant(tacticalBomb, currentTime, i);
                    }
                }

                // While the player is actively holding the defuse, every living enemy
                // goes on high alert: they path straight for the bomb site instead of
                // the player's general position, move faster, and fire more often and
                // with relaxed aim - so they'll actually rush in and try to stop the
                // defuse rather than sit back waiting for a lucky alignment.
                bool defuseInProgress = selectedMode == GameMode::TACTICAL && tacticalBomb.planted &&
                                        !tacticalBomb.defused && defuseHeld;

                if (currentTime - enemy.lastPathCalc >= AI_PATH_INTERVAL_MS) {
                    Point aiTile{ static_cast<int>(enemy.x + enemy.rect.w / 2) / TILE_SIZE, static_cast<int>(enemy.y + enemy.rect.h / 2) / TILE_SIZE };
                    Point targetTile;
                    if (selectedMode == GameMode::TACTICAL && !tacticalBomb.planted) {
                        // Every enemy is a potential planter, so the squad converges on the selected site.
                        targetTile = selectedBombSite;
                    } else if (defuseInProgress) {
                        // Bomb is planted and being defused right now - converge on it.
                        targetTile = selectedBombSite;
                    } else {
                        targetTile = Point{ static_cast<int>(playerPosX + player.w / 2) / TILE_SIZE,
                                            static_cast<int>(playerPosY + player.h / 2) / TILE_SIZE };
                    }
                    enemy.nextTile = get_next_ai_step(aiTile, targetTile);
                    enemy.lastPathCalc = currentTime;
                }

                float aiSpeed = enemyFrozen ? 0.0f : tactical_enemy_speed(defuseInProgress);
                // Aim for the centre of the next tile.  More importantly, move
                // one axis at a time and test the complete 60x60 hitbox before
                // committing the move.  This lets the AI slide around walls
                // instead of freezing when one component of a diagonal move is
                // blocked.
                float aiDx = (enemy.nextTile.x * TILE_SIZE + 5) - enemy.x;
                float aiDy = (enemy.nextTile.y * TILE_SIZE + 5) - enemy.y;
                float dist = std::sqrt(aiDx * aiDx + aiDy * aiDy);
                if (dist > 1.0f) {
                    // Clamp the final step to the target; this prevents Endless enemies
                     // from overshooting and vibrating between adjacent positions.
                     float aiStep = std::min(aiSpeed, dist);
                     float aiVx = (aiDx / dist) * aiStep, aiVy = (aiDy / dist) * aiStep;
                    SDL_Rect nAiX = enemy.rect; nAiX.x += static_cast<int>(aiVx);
                    bool blockedX = check_wall_collision(nAiX);
                    if (!blockedX) { enemy.x += aiVx; enemy.rect.x = static_cast<int>(enemy.x); }
                    else { enemy.lastPathCalc = 0; }
                    SDL_Rect nAiY = enemy.rect; nAiY.y += static_cast<int>(aiVy);
                    bool blockedY = check_wall_collision(nAiY);
                    if (!blockedY) { enemy.y += aiVy; enemy.rect.y = static_cast<int>(enemy.y); }
                    else { enemy.lastPathCalc = 0; }

                    // If the chosen step is blocked, immediately invalidate it so
                    // the next path calculation can choose a different route.
                    // Without this, the AI could keep the same bad nextTile for
                    // 250ms at a time and look frozen against a wall.
                    if (blockedX && blockedY) enemy.lastPathCalc = 0;

                    // Glass now blocks movement, but pathing doesn't route around every
                    // pane - if the blocker directly ahead is glass, shoot it open instead
                    // of stalling in place. Without this an enemy can get permanently
                    // stuck behind glass between it and the bomb site or the player.
                    if ((blockedX || blockedY) && currentTime - enemy.lastGlassBreakTime >= 260) {
                        int gc = -1, gr = -1;
                        bool blockedByGlass = (blockedX && rect_hits_glass(nAiX, &gc, &gr)) ||
                                              (blockedY && rect_hits_glass(nAiY, &gc, &gr));
                        if (blockedByGlass) {
                            float ecx = enemy.x + enemy.rect.w / 2.0f, ecy = enemy.y + enemy.rect.h / 2.0f;
                            float gdx = blockedX ? (aiVx > 0.0f ? 1.0f : -1.0f) : 0.0f;
                            float gdy = blockedY ? (aiVy > 0.0f ? 1.0f : -1.0f) : 0.0f;
                            spawn_vector_bullet(ecx, ecy, gdx, gdy, false, enemy.weaponType, &player, enemy.enemyType, i);
                            enemy.lastGlassBreakTime = currentTime;
                        }
                    }
                }

                Uint32 enemyShootCooldown = enemyFrozen ? 0xFFFFFFFFu : std::max(180U, WEAPON_PROPS[static_cast<int>(enemy.weaponType)].cooldownMs * tactical_enemy_shoot_multiplier(defuseInProgress));
                if (selectedMode == GameMode::ENDLESS) {
                    enemyShootCooldown = std::max(enemyShootCooldown, 850U);
                }
                if (currentTime >= enemy.shootCooldown &&
                    currentTime - enemy.lastShootTime >= enemyShootCooldown) {
                    float aiCx = enemy.x + enemy.rect.w / 2.0f, aiCy = enemy.y + enemy.rect.h / 2.0f;
                    float dx = pCx - aiCx, dy = pCy - aiCy;

                    bool cardinalAligned = std::abs(dx) <= CARDINAL_ALIGN_TOLERANCE || std::abs(dy) <= CARDINAL_ALIGN_TOLERANCE;
                    // Diagonal alignment: |dx| and |dy| within tolerance of each other (both nonzero).
                    float largerAxis = std::max(std::abs(dx), std::abs(dy));
                    bool diagonalAligned = largerAxis > 0.0001f &&
                        std::abs(std::abs(dx) - std::abs(dy)) <= largerAxis * DIAGONAL_ALIGN_TOLERANCE;

                    // Difficulty-aware aiming. RED/cardinal enemies must always fire in
                    // only the 4 cardinal directions (up/down/left/right) - no true
                    // free-aim angle, ever. But a RED enemy holding a rifle still needs
                    // to actually engage: requiring pixel-perfect row/column alignment
                    // (cardinalAligned, an 18px window) before it's even allowed to fire
                    // left it barely shooting at all during normal movement. redRifleTrack
                    // restores that engagement - it can fire whenever the player is in
                    // range, same as before - but the shot is still snapped to the nearest
                    // of the 4 cardinal directions via spawn_cardinal_bullet below, never
                    // a true angled vector shot. Only PINK enemies get actual free-aim
                    // (diagonal/rifle-track/defuse-interrupt vector shots).
                    bool normalMode = (selectedMode == GameMode::TACTICAL &&
                                       tacticalEnemyDifficulty == EnemyDifficulty::NORMAL);
                    bool isPink = (enemy.enemyType == EnemyType::PINK);
                    bool redRifleTrack = !isPink && (enemy.weaponType == WeaponType::RIFLE) && !normalMode;
                    bool rifleAim = isPink && (enemy.weaponType == WeaponType::RIFLE) && !normalMode;
                    bool defuseFreeAim = isPink && defuseInProgress && !normalMode;
                    bool canFire = cardinalAligned || redRifleTrack ||
                                   (isPink && (diagonalAligned || rifleAim || defuseFreeAim));

                    if (canFire) {
                        bool trueFreeAim = isPink && !cardinalAligned && (diagonalAligned || rifleAim || defuseFreeAim);
                        if (!trueFreeAim) {
                            // Cardinal shot, snapped to whichever axis has the larger
                            // displacement - used whenever actually aligned, and always
                            // for RED (including its rifle-track engagement above).
                            Direction sDir = (std::abs(dx) > std::abs(dy)) ? ((dx > 0) ? Direction::DIR_RIGHT : Direction::DIR_LEFT)
                                                                           : ((dy > 0) ? Direction::DIR_DOWN : Direction::DIR_UP);
                            spawn_cardinal_bullet(aiCx, aiCy, sDir, false, enemy.weaponType, &player, enemy.enemyType, i);
                        } else {
                            // Pink enemy diagonal shot, rifle track, or defuse-interrupt shot:
                            // continuous normalized 2D velocity vector straight at the player.
                            spawn_vector_bullet(aiCx, aiCy, dx, dy, false, enemy.weaponType, &player, enemy.enemyType, i);
                        }
                        enemy.lastShootTime = currentTime;
                    }
                }
            }

            // --- Ally Sentinel squad AI -------------------------------------------------
            // Sentinels behave like a team now instead of independent turret-like bots:
            //   * when there is no immediate threat, they accompany the player;
            //   * when Raiders are nearby, they spread out and engage them;
            //   * after a bomb is planted, the nearest surviving Sentinel becomes the
            //     designated defuser while the others protect the bomb/defuser;
            //   * a bot holds the bomb for the same 3 seconds as the player;
            //   * bot bomb defuses are recorded on the Sentinel leaderboard.
            {
                std::array<int, MAX_ENEMIES> targetClaims{};
                targetClaims.fill(0);

                const bool bombActive = selectedMode == GameMode::TACTICAL &&
                                        tacticalBomb.planted && !tacticalBomb.defused;

                // Only one Sentinel should actively work the bomb. If the player is
                // already defusing it, the bots become the security team instead.
                int designatedDefuser = -1;
                if (bombActive && !defuseHeld) {
                    // Keep the same bot assigned while it is alive. This prevents the
                    // defuse timer from constantly resetting because another bot walks
                    // slightly closer to the bomb. If the assigned bot dies, choose a
                    // replacement once.
                    if (botDefuserIndex >= 0 && botDefuserIndex < activeBotCount &&
                        bots[botDefuserIndex].active && bots[botDefuserIndex].hp > 0) {
                        designatedDefuser = botDefuserIndex;
                    } else {
                        float bestBombDist = 1e18f;
                        float bcx = tacticalBomb.x + tacticalBomb.rect.w / 2.0f;
                        float bcy = tacticalBomb.y + tacticalBomb.rect.h / 2.0f;
                        for (int bi = 0; bi < activeBotCount; ++bi) {
                            const Bot& bot = bots[bi];
                            if (!bot.active || bot.hp <= 0) continue;
                            float dx = bcx - (bot.x + bot.rect.w / 2.0f);
                            float dy = bcy - (bot.y + bot.rect.h / 2.0f);
                            float d2 = dx * dx + dy * dy;
                            if (d2 < bestBombDist) {
                                bestBombDist = d2;
                                designatedDefuser = bi;
                            }
                        }
                        botDefuserIndex = designatedDefuser;
                    }
                }

                auto move_bot_toward = [&](Bot& bot, int botIndex, Point destination, float stopDistance) {
                    Point botTile{ static_cast<int>(bot.x + bot.rect.w / 2) / TILE_SIZE,
                                   static_cast<int>(bot.y + bot.rect.h / 2) / TILE_SIZE };
                    if (currentTime - bot.lastPathCalc >= AI_PATH_INTERVAL_MS) {
                        bot.nextTile = get_next_ai_step(botTile, destination);
                        bot.lastPathCalc = currentTime;
                    }

                    float dx = (bot.nextTile.x * TILE_SIZE + 5) - bot.x;
                    float dy = (bot.nextTile.y * TILE_SIZE + 5) - bot.y;
                    float dist = std::sqrt(dx * dx + dy * dy);
                    if (dist <= 1.0f) {
                        // The bot reached its current waypoint tile before the
                        // periodic AI_PATH_INTERVAL_MS timer fired again (this
                        // is the normal case at every tier's speed). Re-plan
                        // right now instead of idling here until the next
                        // scheduled tick - that idle gap was the stutter that
                        // made bots look slower than their actual bot_speed().
                        // Difficulty speeds themselves are untouched.
                        bot.nextTile = get_next_ai_step(botTile, destination);
                        bot.lastPathCalc = currentTime;
                        dx = (bot.nextTile.x * TILE_SIZE + 5) - bot.x;
                        dy = (bot.nextTile.y * TILE_SIZE + 5) - bot.y;
                        dist = std::sqrt(dx * dx + dy * dy);
                        if (dist <= 1.0f) return; // truly at the destination tile
                    }

                    // Keep formation/fighting distances from the destination. For the
                    // actual bomb defuser this is effectively disabled by passing 0.
                    if (stopDistance > 0.0f) {
                        float destCx = destination.x * TILE_SIZE + TILE_SIZE / 2.0f;
                        float destCy = destination.y * TILE_SIZE + TILE_SIZE / 2.0f;
                        float curCx = bot.x + bot.rect.w / 2.0f;
                        float curCy = bot.y + bot.rect.h / 2.0f;
                        float realDist = std::sqrt((destCx-curCx)*(destCx-curCx) + (destCy-curCy)*(destCy-curCy));
                        if (realDist <= stopDistance) return;
                    }

                    float spd = bot_speed(bot.tier) * bot.speedJitter;
                    float bvx = (dx / dist) * spd, bvy = (dy / dist) * spd;
                    SDL_Rect nBx = bot.rect; nBx.x += static_cast<int>(bvx);
                    bool blockedX = check_wall_collision(nBx);
                    if (!blockedX) { bot.x += bvx; bot.rect.x = static_cast<int>(bot.x); }
                    else bot.lastPathCalc = 0;
                    SDL_Rect nBy = bot.rect; nBy.y += static_cast<int>(bvy);
                    bool blockedY = check_wall_collision(nBy);
                    if (!blockedY) { bot.y += bvy; bot.rect.y = static_cast<int>(bot.y); }
                    else bot.lastPathCalc = 0;

                    // Break a glass pane directly blocking a Sentinel's route rather
                    // than repeatedly walking into it.
                    if ((blockedX || blockedY) && currentTime - bot.lastGlassBreakTime >= 260) {
                        int gc = -1, gr = -1;
                        bool blockedByGlass = (blockedX && rect_hits_glass(nBx, &gc, &gr)) ||
                                              (blockedY && rect_hits_glass(nBy, &gc, &gr));
                        if (blockedByGlass) {
                            float bcx = bot.x + bot.rect.w / 2.0f, bcy = bot.y + bot.rect.h / 2.0f;
                            float gdx = blockedX ? (bvx > 0.0f ? 1.0f : -1.0f) : 0.0f;
                            float gdy = blockedY ? (bvy > 0.0f ? 1.0f : -1.0f) : 0.0f;
                            spawn_vector_bullet(bcx, bcy, gdx, gdy, true, bot.weaponType, nullptr, EnemyType::RED, botIndex);
                            bot.lastGlassBreakTime = currentTime;
                        }
                    }
                };

                // Find nearby Raiders once for target selection. Bots still de-conflict
                // their targets so the whole squad does not pile onto one Raider.
                for (int bi = 0; bi < activeBotCount; ++bi) {
                    Bot& bot = bots[bi];
                    if (!bot.active || bot.hp <= 0) continue;

                    float botCx = bot.x + bot.rect.w / 2.0f;
                    float botCy = bot.y + bot.rect.h / 2.0f;

                    // Before the bomb is planted, a Sentinel reports an empty
                    // site when it checks that area. The cooldown prevents a
                    // squad standing together from flooding the audio channel.
                    if (selectedMode == GameMode::TACTICAL && !bombActive &&
                        currentTime - bot.lastCalloutTime >= 4000) {
                        auto near_site = [&](Point site) {
                            if (site.x < 0 || site.y < 0) return false;
                            float siteCx = site.x * TILE_SIZE + TILE_SIZE * 0.5f;
                            float siteCy = site.y * TILE_SIZE + TILE_SIZE * 0.5f;
                            float sx = botCx - siteCx, sy = botCy - siteCy;
                            return sx * sx + sy * sy <= 105.0f * 105.0f;
                        };
                        if (near_site(bombSiteA)) {
                            play_bombsite_callout_sound(true);
                            bot.lastCalloutTime = currentTime;
                        } else if (near_site(bombSiteB)) {
                            play_bombsite_callout_sound(false);
                            bot.lastCalloutTime = currentTime;
                        }
                    }

                    int nearestEnemy = -1;
                    float nearestEnemyDist = 1e18f;
                    for (int ei = 0; ei < activeEnemyCount; ++ei) {
                        const Enemy& enemy = enemies[ei];
                        if (!enemy.active || enemy.hp <= 0) continue;
                        float ecx = enemy.x + enemy.rect.w / 2.0f;
                        float ecy = enemy.y + enemy.rect.h / 2.0f;
                        float d = std::sqrt((ecx-botCx)*(ecx-botCx) + (ecy-botCy)*(ecy-botCy));
                        float weighted = d + targetClaims[ei] * static_cast<float>(TILE_SIZE) * 3.0f;
                        if (weighted < nearestEnemyDist) {
                            nearestEnemyDist = weighted;
                            nearestEnemy = ei;
                        }
                    }
                    if (nearestEnemy >= 0) targetClaims[nearestEnemy]++;

                    const bool isDefuser = bombActive && !defuseHeld && bi == designatedDefuser;
                    Point movementTarget{ static_cast<int>(playerPosX + player.w / 2) / TILE_SIZE,
                                          static_cast<int>(playerPosY + player.h / 2) / TILE_SIZE };
                    float stopDistance = 150.0f;
                    int combatTarget = -1;

                    if (isDefuser) {
                        // The designated Sentinel has a clear, overriding objective:
                        // reach the bomb and defuse it.
                        Point bombTile{ static_cast<int>(tacticalBomb.x + tacticalBomb.rect.w / 2) / TILE_SIZE,
                                        static_cast<int>(tacticalBomb.y + tacticalBomb.rect.h / 2) / TILE_SIZE };
                        movementTarget = bombTile;
                        stopDistance = 0.0f;
                    } else if (currentBotCommand == BotCommand::FOLLOW_PLAYER) {
                        // Keep the whole squad with the player and support them
                        // by engaging nearby Raiders without breaking formation.
                        if (nearestEnemy >= 0 && nearestEnemyDist < 760.0f)
                            combatTarget = nearestEnemy;
                        stopDistance = 150.0f;
                    } else if (currentBotCommand == BotCommand::HOLD_POSITION) {
                        // Capture the position once per bot. Recomputing the
                        // destination every frame made bots oscillate around
                        // the centre of their tile.
                        if (!bot.holdTileValid) {
                            bot.holdTile = Point{
                                static_cast<int>(botCx) / TILE_SIZE,
                                static_cast<int>(botCy) / TILE_SIZE
                            };
                            bot.holdTileValid = true;
                        }
                        movementTarget = bot.holdTile;
                        stopDistance = 0.0f;
                    } else if (currentBotCommand == BotCommand::REACH_SITE_A && bombSiteAValid) {
                        // A reach-site order is a squad-wide movement order:
                        // every non-defuser Sentinel uses the same bombsite target
                        // instead of selecting an individual Raider to pursue.
                        movementTarget = bombSiteA;
                        stopDistance = 0.0f;
                    } else if (currentBotCommand == BotCommand::REACH_SITE_B && bombSiteBValid) {
                        // Apply the Bombsite B order to every non-defuser Sentinel.
                        movementTarget = bombSiteB;
                        stopDistance = 0.0f;
                    } else if (nearestEnemy >= 0 && nearestEnemyDist < 760.0f) {
                        // Immediate combat takes priority over following formation.
                        combatTarget = nearestEnemy;
                        const Enemy& target = enemies[nearestEnemy];
                        Point targetTile{ static_cast<int>(target.x + target.rect.w / 2) / TILE_SIZE,
                                          static_cast<int>(target.y + target.rect.h / 2) / TILE_SIZE };
                        movementTarget = nearest_free_tile({
                            targetTile.x + static_cast<int>(std::cos(bot.flankAngle) * 3),
                            targetTile.y + static_cast<int>(std::sin(bot.flankAngle) * 3)
                        });
                        stopDistance = 260.0f;
                    } else if (bombActive) {
                        // No nearby Raider: remain around the bomb/player instead of
                        // wandering off to random map locations.
                        Point bombTile{ static_cast<int>(tacticalBomb.x + tacticalBomb.rect.w / 2) / TILE_SIZE,
                                        static_cast<int>(tacticalBomb.y + tacticalBomb.rect.h / 2) / TILE_SIZE };
                        movementTarget = nearest_free_tile({
                            bombTile.x + static_cast<int>(std::cos(bot.flankAngle) * 3),
                            bombTile.y + static_cast<int>(std::sin(bot.flankAngle) * 3)
                        });
                        stopDistance = 180.0f;
                    } else {
                        // No immediate threat: accompany the player in a loose formation.
                        // The golden-angle offset gives each Sentinel its own slot.
                        int radius = 2 + (bi % 3);
                        movementTarget = nearest_free_tile({
                            static_cast<int>(playerPosX + player.w / 2) / TILE_SIZE + static_cast<int>(std::cos(bot.flankAngle) * radius),
                            static_cast<int>(playerPosY + player.h / 2) / TILE_SIZE + static_cast<int>(std::sin(bot.flankAngle) * radius)
                        });
                        stopDistance = 130.0f;
                    }

                    // Once a Sentinel reaches the bomb, stop its movement completely
                    // while defusing. This prevents the old frame-to-frame collision
                    // correction from making the bot visibly jitter/vibrate in place.
                    bool botAlreadyAtBomb = false;
                    if (isDefuser && bombActive && !defuseHeld) {
                        botAlreadyAtBomb = SDL_HasIntersection(&bot.rect, &tacticalBomb.rect);
                    }
                    bool isHoldingPosition = currentBotCommand == BotCommand::HOLD_POSITION && !isDefuser;
                    if (!botAlreadyAtBomb && !isHoldingPosition) {
                        move_bot_toward(bot, bi, movementTarget, stopDistance);
                    }

                    // --- Bot bomb defuse -------------------------------------------------
                    if (isDefuser && bombActive && !defuseHeld) {
                        bool nearBomb = SDL_HasIntersection(&bot.rect, &tacticalBomb.rect);
                        if (nearBomb) {
                            if (!bot.defusingBomb) {
                                // Radio signal: this Sentinel has reached the bomb
                                // and has started the defuse.
                                play_fuse_beep(820.0f, 0.68f);
                            }
                            bot.defusingBomb = true;
                            if (bot.defuseStartTime == 0) bot.defuseStartTime = currentTime;
                            if (currentTime - bot.defuseStartTime >= DEFUSE_TIME_MS) {
                                tacticalBomb.defused = true;
                                botDefuserIndex = -1;
                                bot.bombDefuses++;
                                bot.defusingBomb = false;
                                bot.defuseStartTime = 0;
                                score += 100;
                                highScore = std::max(highScore, score);
                                currentGameState = GameState::GAME_WON;
                                for (int bj = 0; bj < activeBotCount; ++bj) {
                                    bots[bj].defusingBomb = false;
                                    bots[bj].defuseStartTime = 0;
                                }
                            }
                        } else {
                            bot.defusingBomb = false;
                            bot.defuseStartTime = 0;
                        }
                    } else if (!isDefuser) {
                        bot.defusingBomb = false;
                        bot.defuseStartTime = 0;
                    }

                    // --- Combat ----------------------------------------------------------
                    if (combatTarget >= 0 && enemies[combatTarget].active && enemies[combatTarget].hp > 0) {
                        const Enemy& target = enemies[combatTarget];
                        float ecx = target.x + target.rect.w / 2.0f;
                        float ecy = target.y + target.rect.h / 2.0f;
                        float engageDx = ecx - botCx;
                        float engageDy = ecy - botCy;
                        float engageDist = std::sqrt(engageDx*engageDx + engageDy*engageDy);
                        Uint32 botShootCooldown = std::max(180U,
                            WEAPON_PROPS[static_cast<int>(bot.weaponType)].cooldownMs * bot_shoot_multiplier(bot.tier));
                        if (currentTime - bot.lastShootTime >= botShootCooldown && engageDist < 700.0f) {
                            spawn_vector_bullet(botCx, botCy, engageDx, engageDy, true,
                                                bot.weaponType, nullptr, EnemyType::RED, bi);
                            bot.lastShootTime = currentTime;
                        }

                        // --- Electric Shield (pistol bots only) --------------------------
                        // Mirrors the player's try_activate_shield: a pistol-carrying
                        // Sentinel that's taking a beating from a nearby Raider pops its
                        // own shield rather than just tanking hits, using the same
                        // duration/cooldown constants as the player's ability.
                        if (bot.weaponType == WeaponType::PISTOL && !bot.shieldActive &&
                            currentTime >= bot.shieldReadyAt &&
                            bot.hp <= bot.maxHp / 2 && engageDist < 260.0f) {
                            bot.shieldActive = true;
                            bot.shieldActivatedAt = currentTime;
                            play_voice_line(VoiceLine::SHIELD_ACTIVATE);
                        }
                    }

                    // Shield duration expiry - ticks every frame regardless of combat
                    // state, same as the player's handling, so it always drops on time.
                    if (bot.shieldActive && currentTime - bot.shieldActivatedAt >= SHIELD_DURATION_MS) {
                        bot.shieldActive = false;
                        bot.shieldReadyAt = currentTime + SHIELD_COOLDOWN_MS;
                    }
                }
            }

            for (auto& b : bullets) {
                if (!b.active) continue;
                b.x += b.vx; b.y += b.vy;
                b.rect.x = static_cast<int>(b.x) - b.rect.w / 2;
                b.rect.y = static_cast<int>(b.y) - b.rect.h / 2;

                int glassCol = -1, glassRow = -1;
                bool hitGlass = rect_hits_glass(b.rect, &glassCol, &glassRow);

                // GLASS IS A BREAKABLE OBSTACLE, NOT A PERMANENT WALL.
                // Any projectile that strikes it shatters the glass immediately.
                // The glass tile is removed, so the position becomes passable.
                if (hitGlass) {
                    gameMap[glassRow][glassCol] = 0;

                    for (auto& gs : glassShatters) {
                        if (!gs.active) {
                            gs.x = glassCol * TILE_SIZE + TILE_SIZE / 2.0f;
                            gs.y = glassRow * TILE_SIZE + TILE_SIZE / 2.0f;
                            gs.spawnTime = currentTime;
                            gs.duration = 420;
                            gs.active = true;
                            break;
                        }
                    }

                    play_glass_shatter_sound();
                }

                // Glass is intentionally excluded from wall collision. Once struck,
                // it disappears and does not reflect Vector-Reflect bullets.
                bool hitWall = check_wall_collision(b.rect);
                bool hitPlayer = (!b.isPlayerBullet && SDL_HasIntersection(&b.rect, &player));
                
                bool hitEnemy = false;
                if (b.isPlayerBullet) {
                    for (int i = 0; i < activeEnemyCount; ++i) {
                        auto& enemy = enemies[i];
                        if (enemy.active && enemy.hp > 0 && SDL_HasIntersection(&b.rect, &enemy.rect)) {
                            hitEnemy = true;
                            
                            int baseDamage = WEAPON_PROPS[static_cast<int>(b.type)].damage;
                            if (b.type == WeaponType::VECTOR_REFLECT) {
                                baseDamage = std::max(10, static_cast<int>(baseDamage * std::pow(0.85f, static_cast<float>(b.bounceCount))));
                            }
                            int scaledDamage = baseDamage + (currentLevel * 3);
                            enemy.hp -= scaledDamage;
                            if (b.type == WeaponType::ICE_GUN) {
                                enemy.iceSlowUntil = currentTime + 5000;

                                // Large ice projectile: the impact freezes and damages
                                // every enemy caught in the surrounding frost burst.
                                const float iceSplashRadius = 105.0f;
                                const int iceSplashDamage =
                                    std::max(6, WEAPON_PROPS[static_cast<int>(WeaponType::ICE_GUN)].damage / 2);
                                const float impactX = enemy.x + enemy.rect.w * 0.5f;
                                const float impactY = enemy.y + enemy.rect.h * 0.5f;

                                for (int ni = 0; ni < activeEnemyCount; ++ni) {
                                    if (ni == i) continue;
                                    auto& nearby = enemies[ni];
                                    if (!nearby.active || nearby.hp <= 0) continue;

                                    float nx = nearby.x + nearby.rect.w * 0.5f;
                                    float ny = nearby.y + nearby.rect.h * 0.5f;
                                    float dx = nx - impactX;
                                    float dy = ny - impactY;
                                    if (std::sqrt(dx * dx + dy * dy) <= iceSplashRadius) {
                                        nearby.hp -= iceSplashDamage;
                                        nearby.iceSlowUntil = std::max(nearby.iceSlowUntil,
                                                                          currentTime + 5000);
                                    }
                                }
                            }
                            if (b.type == WeaponType::FIRE_GUN) {
                                enemy.burningUntil = currentTime + 2200;
                                enemy.nextBurnTick = currentTime + 250;
                                enemy.lastFlameBurstAt = currentTime;

                                // The projectile ignites the impact area, so nearby
                                // enemies are caught by the spreading fire too.
                                float impactX = enemy.x + enemy.rect.w * 0.5f;
                                float impactY = enemy.y + enemy.rect.h * 0.5f;

                                for (auto& fi : fireImpacts) {
                                    if (!fi.active) {
                                        fi.x = impactX;
                                        fi.y = impactY;
                                        fi.radius = 95.0f;
                                        fi.spawnTime = currentTime;
                                        fi.duration = 1600;
                                        fi.active = true;
                                        break;
                                    }
                                }

                                const float fireSplashRadius = 95.0f;
                                const int nearbyIgniteDamage =
                                    std::max(3, WEAPON_PROPS[static_cast<int>(WeaponType::FIRE_GUN)].damage / 4);

                                for (int ni = 0; ni < activeEnemyCount; ++ni) {
                                    if (ni == i) continue;
                                    auto& nearby = enemies[ni];
                                    if (!nearby.active || nearby.hp <= 0) continue;

                                    float nx = nearby.x + nearby.rect.w * 0.5f;
                                    float ny = nearby.y + nearby.rect.h * 0.5f;
                                    float dx = nx - impactX;
                                    float dy = ny - impactY;
                                    float dist = std::sqrt(dx * dx + dy * dy);

                                    if (dist <= fireSplashRadius) {
                                        nearby.burningUntil = std::max(nearby.burningUntil,
                                                                         currentTime + 1500);
                                        nearby.nextBurnTick = std::min(nearby.nextBurnTick,
                                                                       currentTime + 300);
                                        nearby.lastFlameBurstAt = currentTime;
                                        nearby.hp -= nearbyIgniteDamage;
                                    }
                                }
                                // Fire applies a short damage-over-time effect to
                                // the primary target while nearby targets are engulfed.
                            }
                            if (b.type == WeaponType::WIND_GUN) {
                                // WIND GUN launches the enemy backward with a
                                // strong initial impulse plus damping for a long
                                // knockback, THEN - once that knockback finishes -
                                // catches it in a brief spinning tornado right
                                // where it landed. Push and tornado are combined
                                // effects from a single hit, not an either/or.
                                float d = std::sqrt(b.vx * b.vx + b.vy * b.vy);
                                if (d > 0.01f) {
                                    // Scale slightly with projectile speed, while
                                    // keeping a hard ceiling for reliable balance.
                                    float pushStrength = WIND_PUSH_STRENGTH +
                                                         std::min(8.0f, d * 0.14f);
                                    enemy.windPushX = (b.vx / d) * pushStrength;
                                    enemy.windPushY = (b.vy / d) * pushStrength;
                                } else {
                                    enemy.windPushX = enemy.windPushY = 0.0f;
                                }
                                enemy.windPushUntil = currentTime + WIND_PUSH_DURATION_MS;
                                enemy.cycloneUntil = 0;
                                enemy.windTornadoActive = false;
                                enemy.windTornadoPending = true;
                                enemy.shootCooldown = currentTime + WIND_PUSH_DURATION_MS;
                                enemy.windSlamApplied = false;
                                enemy.nextWindTick = currentTime + WIND_TICK_INTERVAL_MS;
                            }

                            if (enemy.hp <= 0) {
                                enemy.active = false;
                                enemy.deaths = 1;
                                score += 10;
                                highScore = std::max(highScore, score);
                                if (b.ownerBotIndex >= 0 && b.ownerBotIndex < activeBotCount) {
                                    bots[b.ownerBotIndex].kills++;
                                } else {
                                    playerKills++;
                                    lifetimeKills++;
                                    ++weaponKills[static_cast<int>(b.type)];
                                    check_badge_unlocks();
                                }
                            }
                            // Ice and Wind are impact projectiles: consume the shot
                            // after the hit so one projectile creates its intended
                            // area/control effect without repeatedly re-hitting.
                            if (b.type == WeaponType::ICE_GUN || b.type == WeaponType::WIND_GUN)
                                b.active = false;
                            break;
                        }
                    }
                }

                // Raider bullets can strike an ally Sentinel bot the same way they
                // strike the player - bots are real targets, not just decoration.
                int hitBotIndex = -1;
                if (!b.isPlayerBullet) {
                    for (int bi = 0; bi < activeBotCount; ++bi) {
                        if (bots[bi].active && bots[bi].hp > 0 && SDL_HasIntersection(&b.rect, &bots[bi].rect)) {
                            hitBotIndex = bi;
                            break;
                        }
                    }
                }
                bool hitBot = (hitBotIndex >= 0);

                // Vehicles are solid combat objects: both player and enemy/bot
                // projectiles damage their armor and can eventually destroy them
                // (a parked car is fair game for either side, not just the
                // player). This is resolved on the authoritative host, while
                // clients only receive the resulting VSTATE.
                int hitVehicleIndex = VehicleProjectileHitIndex(b.rect);
                if (hitVehicleIndex >= 0) {
                    VehicleEntity& hitVehicle = g_vehicles[hitVehicleIndex];
                    VehicleApplyProjectileDamage(hitVehicle, b.type, currentTime, b.x + b.rect.w*0.5f, b.y + b.rect.h*0.5f);
                    b.active = false;
                    if (b.type == WeaponType::ROCKET) {
                        trigger_explosion(b.x, b.y, 160.0f, WEAPON_PROPS[static_cast<int>(WeaponType::ROCKET)].damage,
                                          player, playerHp, b.isPlayerBullet, b.ownerBotIndex, WeaponType::ROCKET);
                    }
                    continue;
                }

                // check_wall_collision() converts pixels to tiles with integer
                // division, which truncates toward zero rather than flooring -
                // a rocket that exits near the negative (left/top) map edge can
                // therefore have hitWall come back false even though it's really
                // out of bounds. Catch that case explicitly here too, otherwise
                // such a rocket gets silently deactivated by the generic bounds
                // cleanup further down without ever detonating.
                bool rocketOutOfBounds = (b.rect.x < 0 || b.rect.x > currentMapCols * TILE_SIZE ||
                                           b.rect.y < 0 || b.rect.y > currentMapRows * TILE_SIZE);
                if (b.type == WeaponType::ROCKET && (hitWall || hitGlass || hitPlayer || hitEnemy || hitBot || rocketOutOfBounds)) {
                    b.active = false;
                    // Pass the rocket's shooter through so a splash kill (not just a
                    // direct hit) is credited on the leaderboard the same way.
                    trigger_explosion(b.x, b.y, 160.0f, WEAPON_PROPS[static_cast<int>(WeaponType::ROCKET)].damage, player, playerHp,
                                       b.isPlayerBullet, b.ownerBotIndex, WeaponType::ROCKET);
                    highScore = std::max(highScore, score);
                    if (playerHp <= 0) {
                        if (selectedMode == GameMode::ENDLESS) playerDiedThisEndlessRun = true;
                        currentGameState = GameState::GAME_OVER;
                    }
                    continue;
                }

                if (b.type == WeaponType::VECTOR_REFLECT && hitWall && !hitGlass) {
                    SDL_Rect prevRect = b.rect;
                    prevRect.x = static_cast<int>(b.x - b.vx) - b.rect.w / 2;
                    prevRect.y = static_cast<int>(b.y - b.vy) - b.rect.h / 2;
                    bool hitX = check_wall_collision(SDL_Rect{prevRect.x + static_cast<int>(b.vx), prevRect.y, prevRect.w, prevRect.h});
                    bool hitY = check_wall_collision(SDL_Rect{prevRect.x, prevRect.y + static_cast<int>(b.vy), prevRect.w, prevRect.h});
                    if (hitX) b.vx = -b.vx;
                    if (hitY) b.vy = -b.vy;
                    if (!hitX && !hitY) { b.vx = -b.vx; b.vy = -b.vy; }
                    b.bounceCount++;
                    b.x = static_cast<float>(prevRect.x + prevRect.w / 2);
                    b.y = static_cast<float>(prevRect.y + prevRect.h / 2);
                    b.rect.x = static_cast<int>(b.x) - b.rect.w / 2;
                    b.rect.y = static_cast<int>(b.y) - b.rect.h / 2;
                    if (b.bounceCount >= 3) b.active = false;
                    continue;
                }

                if (b.type == WeaponType::FIRE_GUN && b.isPlayerBullet && hitWall) {
                    // Fire Gun should ignite wherever it lands, not only on a
                    // direct enemy hit - a shot into a wall or doorway leaves
                    // a wall of fire stretched across the impact point, so it
                    // reads as a barrier blocking that doorway/corridor rather
                    // than a single burning patch.
                    spawn_fire_wall(b.x, b.y, b.vx, b.vy, currentTime);
                }

                if (b.rect.x < 0 || b.rect.x > currentMapCols * TILE_SIZE || b.rect.y < 0 || b.rect.y > currentMapRows * TILE_SIZE || hitWall) {
                    b.active = false; continue;
                }
                if (!b.isPlayerBullet && hitPlayer) {
                    b.active = false; // bullet is stopped either way - shield/I-Frames don't let it through
                    if (!playerShieldActive && !playerIsInvulnerable) {
                        playerHp -= static_cast<int>(WEAPON_PROPS[static_cast<int>(b.type)].damage * tactical_enemy_damage_multiplier());
                        highScore = std::max(highScore, score);
                        if (playerHp <= 0) {
                            currentGameState = GameState::GAME_OVER;
                            playerDeaths++;
                            // b.ownerBotIndex holds the shooting Raider's index for
                            // enemy-fired bullets (same field bots use for their own
                            // kill attribution on player-team shots).
                            if (b.ownerBotIndex >= 0 && b.ownerBotIndex < activeEnemyCount) {
                                enemies[b.ownerBotIndex].kills++;
                            }
                        }
                        // Getting hit while defusing breaks concentration - the timer
                        // resets, so an enemy that lands a shot genuinely stops the defuse
                        // rather than the player being able to tank it and finish anyway.
                        if (defuseHeld) {
                            defuseHeld = false;
                            defuseStartTime = 0;
                        }
                    }
                }
                if (!b.isPlayerBullet && hitBot) {
                    b.active = false; // bullet is stopped either way - a shielded bot still blocks it
                    Bot& bot = bots[hitBotIndex];
                    if (!bot.shieldActive) {
                        bot.hp -= static_cast<int>(WEAPON_PROPS[static_cast<int>(b.type)].damage * tactical_enemy_damage_multiplier());
                        if (bot.defusingBomb) {
                            // Radio signal: incoming fire interrupted the defuse.
                            play_fuse_beep(360.0f, 0.68f);
                            bot.defusingBomb = false;
                            bot.defuseStartTime = 0;
                        }
                        if (bot.hp <= 0) {
                            // Radio signal: a Sentinel is down.
                            play_fuse_beep(220.0f, 0.78f);
                            bot.active = false;
                            bot.deaths++;
                            bot.defusingBomb = false;
                            bot.defuseStartTime = 0;
                            if (botDefuserIndex == hitBotIndex) botDefuserIndex = -1;
                            if (b.ownerBotIndex >= 0 && b.ownerBotIndex < activeEnemyCount) {
                                enemies[b.ownerBotIndex].kills++;
                            }
                        }
                    }
                }
                if (b.isPlayerBullet && hitEnemy) {
                    b.active = false;
                }
            }
        }

        update_camera(playerPosX, playerPosY);

        SDL_SetRenderDrawColor(renderer, 20, 20, 25, 255);
        SDL_RenderClear(renderer);

        int firstCol = std::max(0, cameraX / TILE_SIZE);
        int firstRow = std::max(0, cameraY / TILE_SIZE);
        int lastCol = std::min(currentMapCols - 1, (cameraX + SCREEN_WIDTH) / TILE_SIZE + 1);
        int lastRow = std::min(currentMapRows - 1, (cameraY + SCREEN_HEIGHT) / TILE_SIZE + 1);

SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);
for (int r = firstRow; r <= lastRow; ++r) {
    for (int c = firstCol; c <= lastCol; ++c) { 
        SDL_Rect tile = {c * TILE_SIZE - cameraX, r * TILE_SIZE - cameraY, TILE_SIZE, TILE_SIZE};
        const int val = gameMap[r][c];
        if (val == 1)      SDL_SetRenderDrawColor(renderer, 50, 55, 65, 255);
        else if (val == 8 || val == 9) {
            SDL_Color paletteColor = editor_palette_color(val);
            SDL_SetRenderDrawColor(renderer, paletteColor.r, paletteColor.g, paletteColor.b, paletteColor.a);
        }
        else if (val == 10) SDL_SetRenderDrawColor(renderer, 120, 210, 240, 95);
        else               SDL_SetRenderDrawColor(renderer, 15, 18, 22, 255);
        SDL_RenderFillRect(renderer, &tile);
        if (val == 10) {
            SDL_SetRenderDrawColor(renderer, 190, 240, 255, 220);
            draw_rect_outline(renderer, tile);
            SDL_RenderDrawLine(renderer, tile.x + 5, tile.y + 5, tile.x + TILE_SIZE - 5, tile.y + TILE_SIZE - 5);
            SDL_RenderDrawLine(renderer, tile.x + TILE_SIZE - 5, tile.y + 5, tile.x + 5, tile.y + TILE_SIZE - 5);
        }
    }
}

        // World objects are rendered in world coordinates through the camera.
        SDL_RenderSetViewport(renderer, nullptr);
        // Keep the renderer's 2000x1200 logical coordinate system for all HUD
        // and editor controls.
        // Draw world-space objects manually offset by camera.
        if (selectedMode == GameMode::TACTICAL && !tacticalBomb.defused) {
            SDL_Rect bombScreen = tacticalBomb.rect;
            bombScreen.x -= cameraX; bombScreen.y -= cameraY;
            render_bomb_entity(renderer, tacticalBomb, bombScreen, currentTime);
        }

        if (selectedMode == GameMode::TACTICAL) {
            auto draw_site = [&](Point site, char label, SDL_Color col) {
                if (site.x < 0 || site.y < 0) return;
                SDL_Rect sr{site.x*TILE_SIZE-cameraX+5,site.y*TILE_SIZE-cameraY+5,TILE_SIZE-10,TILE_SIZE-10};
                SDL_SetRenderDrawColor(renderer,col.r,col.g,col.b,150); SDL_RenderFillRect(renderer,&sr);
                SDL_SetRenderDrawColor(renderer,255,255,255,255); draw_rect_outline(renderer, sr);
                draw_text(renderer,std::string(1,label),sr.x+18,sr.y+13,2,{255,255,255,255});
            };
            if (bombSiteAValid) draw_site(bombSiteA,'A',{255,150,70,255});
            if (bombSiteBValid) draw_site(bombSiteB,'B',{255,150,70,255});
        }
        for (const auto& hp : healthPacks) render_health_pack(renderer, hp);
        for (const auto& coin : coins) render_coin(renderer, coin, currentTime);
        for (const auto& b : bullets) if (b.active) render_bullet(renderer, b);

        // Render Raiders.  The previous icon patch accidentally left a fragment
        // of an old enemy-effect block outside the enemy loop; keep all enemy
        // rendering local to this loop so every variable is in scope.
        for (int i = 0; i < activeEnemyCount; ++i) {
            const auto& enemy = enemies[i];
            if (!enemy.active || enemy.hp <= 0) continue;

            SDL_Color eColor = (enemy.enemyType == EnemyType::PINK)
                ? SDL_Color{245, 90, 150, 255}
                : SDL_Color{230, 60, 60, 255};
            SDL_Rect enemyScreen = enemy.rect;
            enemyScreen.x -= cameraX;
            enemyScreen.y -= cameraY;

            SDL_SetRenderDrawColor(renderer, eColor.r, eColor.g, eColor.b, 255);
            SDL_RenderFillRect(renderer, &enemyScreen);
            SDL_SetRenderDrawColor(renderer, 255, 255, 255, 255);
            draw_rect_outline(renderer, enemyScreen);
            render_health_bar(renderer, enemyScreen.x, enemyScreen.y - 12,
                              enemyScreen.w, 8, enemy.hp, enemy.maxHp, eColor);
            draw_text(renderer, enemy.name,
                      centered_text_x(enemy.name, 1, enemyScreen.x, enemyScreen.w),
                      enemyScreen.y - 24, 1, eColor);

            // WIND GUN tornado follow-up feedback: the enemy is rooted in
            // place and visibly spins around its own center axis (not
            // orbiting some distant point) while the lethal DOT ramps up
            // toward the kill - color and spin speed intensify together.
            if (currentTime < enemy.cycloneUntil) {
                SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);
                float elapsed = static_cast<float>(currentTime - enemy.cycloneStartTime);
                float spinT = std::min(1.0f, elapsed / static_cast<float>(WIND_TORNADO_DURATION_MS));
                int ecx = enemyScreen.x + enemyScreen.w / 2;
                int ecy = enemyScreen.y + enemyScreen.h / 2;
                float halfDiag = std::sqrt(static_cast<float>(enemyScreen.w * enemyScreen.w +
                                            enemyScreen.h * enemyScreen.h)) * 0.5f;

                // Color ramps from cool blue-white toward a hot red-orange as
                // the spin tightens and the kill approaches.
                Uint8 rC = static_cast<Uint8>(190 + spinT * 65);
                Uint8 gC = static_cast<Uint8>(235 - spinT * 150);
                Uint8 bC = static_cast<Uint8>(255 - spinT * 205);

                // Rotated outline around the enemy's own center - four
                // corners spun by cycloneAngle - reads as the body itself
                // whipping around in place, not drifting through the world.
                SDL_SetRenderDrawColor(renderer, rC, gC, bC, 230);
                SDL_Point corners[5];
                for (int c = 0; c < 4; ++c) {
                    float a = enemy.cycloneAngle + c * (static_cast<float>(M_PI) / 2.0f) +
                              static_cast<float>(M_PI) / 4.0f;
                    corners[c].x = ecx + static_cast<int>(std::cos(a) * halfDiag);
                    corners[c].y = ecy + static_cast<int>(std::sin(a) * halfDiag);
                }
                corners[4] = corners[0];
                SDL_RenderDrawLines(renderer, corners, 5);

                // Tight speed-line streaks hugging the body, spinning with it.
                for (int k = 0; k < 6; ++k) {
                    float a = enemy.cycloneAngle * 1.6f + k * (2.0f * static_cast<float>(M_PI) / 6.0f);
                    float rInner = halfDiag + 4.0f;
                    float rOuter = halfDiag + 16.0f + spinT * 10.0f;
                    int x1 = ecx + static_cast<int>(std::cos(a) * rInner);
                    int y1 = ecy + static_cast<int>(std::sin(a) * rInner);
                    int x2 = ecx + static_cast<int>(std::cos(a) * rOuter);
                    int y2 = ecy + static_cast<int>(std::sin(a) * rOuter);
                    SDL_SetRenderDrawColor(renderer, rC, gC, bC, static_cast<Uint8>(210 - spinT * 40));
                    SDL_RenderDrawLine(renderer, x1, y1, x2, y2);
                }

                // Faint pressure halo, tightening as the spin accelerates.
                SDL_SetRenderDrawColor(renderer, rC, gC, bC, 60);
                draw_circle_outline(renderer, ecx, ecy,
                                    static_cast<int>(halfDiag) + 20 - static_cast<int>(spinT * 6.0f), 2);
                SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_NONE);
            }

            // Premium strong-wind feedback: directional pressure streaks and
            // dust/air particles for the initial knockback phase.
            if (currentTime < enemy.windPushUntil) {
                SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);
                float wt = currentTime * 0.02f;
                float pushLen = std::sqrt(enemy.windPushX * enemy.windPushX + enemy.windPushY * enemy.windPushY);
                float wdx = pushLen > 0.01f ? enemy.windPushX / pushLen : 1.0f;
                float wdy = pushLen > 0.01f ? enemy.windPushY / pushLen : 0.0f;
                float wpx = -wdy, wpy = wdx;
                int ecx = enemyScreen.x + enemyScreen.w / 2;
                int ecy = enemyScreen.y + enemyScreen.h / 2;
                for (int g = 0; g < 10; ++g) {
                    float phase = wt * (1.5f + g * 0.07f) + g * 1.37f;
                    float side = std::sin(phase) * (5.0f + g * 0.7f);
                    float back = 12.0f + std::fmod(wt * 48.0f + g * 23.0f, 95.0f);
                    int gx = ecx - static_cast<int>(wdx * back + wpx * side);
                    int gy = ecy - static_cast<int>(wdy * back + wpy * side);
                    int gl = 14 + (g % 4) * 7;
                    SDL_SetRenderDrawColor(renderer, 175, 238, 255,
                                           static_cast<Uint8>(190 - g * 13));
                    SDL_RenderDrawLine(renderer, gx, gy,
                                       gx + static_cast<int>(wdx * gl),
                                       gy + static_cast<int>(wdy * gl));
                }
                // Pressure halo around the enemy being blasted.
                SDL_SetRenderDrawColor(renderer, 190, 242, 255, 80);
                draw_circle_outline(renderer, ecx, ecy, 24 + static_cast<int>(4.0f * std::sin(wt * 5.0f)), 2);
                SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_NONE);
            }

            // Fire Gun premium burn: a large ring of fire wraps fully around the
            // burning enemy - flames at the feet, the sides, and over the head -
            // plus rising embers and smoke while the damage-over-time effect runs.
            if (enemy.burningUntil > currentTime) {
                SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);
                float bt = currentTime * 0.018f + enemy.x * 0.013f + enemy.y * 0.009f;
                float remain = static_cast<float>(enemy.burningUntil - currentTime);
                float fade = std::min(1.0f, remain / 450.0f);
                int ecx = enemyScreen.x + enemyScreen.w / 2;
                int baseY = enemyScreen.y + enemyScreen.h - 2;
                float bodyR = std::max(enemyScreen.w, enemyScreen.h) * 0.62f;

                // A fan of tapered flame tongues spreading up and outward from the
                // base - tall near the center, lower and wider toward the edges -
                // so the fire reads as a single spreading blaze rather than a
                // cluster of round particles.
                const int tongueCount = 7;
                for (int f = 0; f < tongueCount; ++f) {
                    float spreadT = tongueCount > 1 ? static_cast<float>(f) / (tongueCount - 1) : 0.5f;
                    float lean = (spreadT - 0.5f) * 2.0f; // -1 (left edge) .. 1 (right edge)
                    float flick = std::sin(bt * (3.0f + f * 0.4f) + f * 1.8f);
                    float flick2 = std::cos(bt * 2.1f + f * 0.9f);
                    float jetLen = bodyR * (0.55f + 0.85f * (0.5f + 0.5f * flick));

                    float baseX = ecx + lean * bodyR * 0.55f;
                    float flameH = jetLen * (0.5f + 0.3f * (1.0f - std::abs(lean)));
                    float tipX = baseX + lean * bodyR * 0.35f + flick2 * 4.0f;
                    float tipY = baseY - flameH;

                    draw_flame_tongue(renderer, baseX, static_cast<float>(baseY), tipX, tipY,
                                      14.0f - std::abs(lean) * 5.0f,
                                      static_cast<Uint8>(215 * fade));
                }
                // A taller central plume rising straight up from the enemy, so the
                // fire clearly towers over them rather than just spreading at the
                // base.
                for (int p = 0; p < 2; ++p) {
                    float plick = std::sin(bt * (2.4f + p * 0.5f) + p * 2.2f);
                    float px = ecx + plick * 6.0f;
                    float plumeH = 34.0f + (plick * 0.5f + 0.5f) * 28.0f;
                    draw_flame_tongue(renderer, px, static_cast<float>(baseY),
                                      px + plick * 5.0f, baseY - plumeH,
                                      10.0f - p * 2.0f,
                                      static_cast<Uint8>(190 * fade));
                }
                // Rising embers, spread wider to match the larger fire.
                for (int e = 0; e < 9; ++e) {
                    float ep = std::fmod(bt * (0.7f + e * 0.08f) + e * 1.41f, 2.8f);
                    int ex = ecx + static_cast<int>(std::sin(bt * 2.0f + e) * (bodyR * 0.5f + e * 2));
                    int ey = baseY - static_cast<int>(ep * 30.0f) - e * 4;
                    SDL_SetRenderDrawColor(renderer, 255, 190, 45, static_cast<Uint8>(170 * fade));
                    draw_filled_circle(renderer, ex, ey, 1 + (e % 2));
                }
                // Thicker smoke above the burning target.
                for (int s = 0; s < 4; ++s) {
                    float sp = bt * 0.8f + s * 2.0f;
                    int sx = ecx + static_cast<int>(std::sin(sp) * (8 + s * 4));
                    int sy = enemyScreen.y - 6 - s * 9 + static_cast<int>(std::fmod(bt * 8.0f + s * 4.0f, 6.0f));
                    SDL_SetRenderDrawColor(renderer, 105, 105, 105, static_cast<Uint8>(60 * fade));
                    draw_filled_circle(renderer, sx, sy, 4 + s);
                }
                SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_NONE);
            }

            if (currentTime < enemy.iceSlowUntil) {
                SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);
                SDL_SetRenderDrawColor(renderer, 170, 245, 255, 170);
                draw_rect_outline(renderer, SDL_Rect{enemyScreen.x - 5, enemyScreen.y - 5,
                                                     enemyScreen.w + 10, enemyScreen.h + 10}, 4);
                SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_NONE);
            }
        }

        // Ally Sentinel bots use the same green visual identity as the player.
        // This makes every friendly combatant immediately readable as Sentinel.
        for (int i = 0; i < activeBotCount; ++i) {
            const auto& bot = bots[i];
            if (bot.active && bot.hp > 0) {
                SDL_Color bColor{60, 220, 100, 255};
                SDL_SetRenderDrawColor(renderer, bColor.r, bColor.g, bColor.b, 255);
                SDL_Rect botScreen = bot.rect;
                botScreen.x -= cameraX; botScreen.y -= cameraY;
                SDL_RenderFillRect(renderer, &botScreen);
                SDL_SetRenderDrawColor(renderer, 255, 255, 255, 255);
                draw_rect_outline(renderer, botScreen);
                render_health_bar(renderer, botScreen.x, botScreen.y - 12, botScreen.w, 8, bot.hp, bot.maxHp, bColor);
                draw_text(renderer, bot.name, centered_text_x(bot.name, 1, botScreen.x, botScreen.w),
                          botScreen.y - 24, 1, bColor);
                // This bot's own reply floats above its own name tag, not the
                // player's, so each bot reads as its own voice answering.
                if (!bot.replyMessage.empty() && currentTime < bot.replyMessageUntil) {
                    draw_text(renderer, bot.replyMessage,
                              centered_text_x(bot.replyMessage, 1, botScreen.x, botScreen.w),
                              botScreen.y - 40, 1, {255, 225, 105, 255});
                }
                if (bot.defusingBomb) {
                    draw_text(renderer, "DEFUSING", centered_text_x("DEFUSING", 1, botScreen.x, botScreen.w),
                              botScreen.y + botScreen.h + 4, 1, {255, 220, 80, 255});
                }
                if (bot.shieldActive) {
                    // Same pulsing ring look as the player's shield, scaled to the bot.
                    SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);
                    Uint32 shieldElapsed = currentTime - bot.shieldActivatedAt;
                    float pulse = 0.6f + 0.4f * std::sin(static_cast<float>(shieldElapsed) * 0.02f);
                    for (int ring = 0; ring < 3; ++ring) {
                        int pad = 10 + ring * 6;
                        SDL_Rect glow = { botScreen.x - pad, botScreen.y - pad, botScreen.w + pad * 2, botScreen.h + pad * 2 };
                        Uint8 alpha = static_cast<Uint8>(std::max(0.0f, (150 - ring * 45) * pulse));
                        SDL_SetRenderDrawColor(renderer, 90, 200, 255, alpha);
                        draw_rect_outline(renderer, glow);
                    }
                    SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_NONE);
                }
            }
        }

        // Afterimage ghost trail: fading silhouettes along the roll/dash path,
        // confirming the long-press/double-tap threshold was met.
        if (dashGhostCount > 0) {
            SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);
            for (int i = 0; i < dashGhostCount; ++i) {
                Uint32 age = currentTime - dashGhosts[i].t;
                if (age > 220) continue;
                float fade = 1.0f - static_cast<float>(age) / 220.0f;
                SDL_Rect ghost = { static_cast<int>(dashGhosts[i].x) - cameraX, static_cast<int>(dashGhosts[i].y) - cameraY, player.w, player.h };
                SDL_SetRenderDrawColor(renderer, 140, 220, 255, static_cast<Uint8>(140 * fade));
                SDL_RenderFillRect(renderer, &ghost);
            }
        }

        // STEP 17.36: weather is rendered after world actors so rain/fog/cloud cover
        // reads as an environmental layer without hiding critical HUD controls.
        render_weather(renderer, currentTime);

        // Host-authoritative round/match result overlays. These are driven only
        // by ROUND_RESULT/MATCH_RESULT messages, so every device sees the same result.
        if ((lanNetwork.hosting || lanNetwork.connected) && lanRoundResultVisible && lanMatchPhase == 3) {
            SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);
            SDL_SetRenderDrawColor(renderer, 0, 0, 0, 175);
            SDL_Rect overlay{0, 0, SCREEN_WIDTH, SCREEN_HEIGHT};
            SDL_RenderFillRect(renderer, &overlay);
            std::string title = "ROUND " + std::to_string(lanRoundNumber) + " OVER";
            std::string who = lanRoundWinningTeam < 0 ? "DRAW" :
                              (lanRoundWinningTeam == (lanNetwork.localTeam == Team::RED_BOMBER ? 1 : 0) ? "YOUR TEAM WINS" :
                               std::string(lanRoundWinningTeam == 1 ? "RAIDERS" : "SENTINELS") + " WIN");
            draw_text(renderer, title, centered_text_x(title, 3), SCREEN_HEIGHT/2 - 110, 3, {235,240,245,255});
            draw_text(renderer, who, centered_text_x(who, 5), SCREEN_HEIGHT/2 - 25, 5, {100,220,255,255});
            std::string score = "TEAM SCORE: SENTINELS=" + std::to_string(lanTeamRoundScore[0]) + "  RAIDERS=" + std::to_string(lanTeamRoundScore[1]);
            draw_text(renderer, score, centered_text_x(score, 2), SCREEN_HEIGHT/2 + 70, 2, {255,220,100,255});
            SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_NONE);
        }
        if ((lanNetwork.hosting || lanNetwork.connected) && lanMatchResultVisible && lanMatchPhase == 4) {
            SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);
            SDL_SetRenderDrawColor(renderer, 0, 0, 0, 190);
            SDL_Rect overlay{0, 0, SCREEN_WIDTH, SCREEN_HEIGHT};
            SDL_RenderFillRect(renderer, &overlay);
            std::string title = "MATCH OVER";
            std::string who = lanMatchWinningTeam < 0 ? "MATCH DRAW" :
                              (lanMatchWinningTeam == (lanNetwork.localTeam == Team::RED_BOMBER ? 1 : 0) ? "YOUR TEAM WINS THE MATCH" :
                               std::string(lanMatchWinningTeam == 1 ? "RAIDERS" : "SENTINELS") + " WIN THE MATCH");
            std::string score = "FINAL TEAM SCORE: SENTINELS=" + std::to_string(lanTeamRoundScore[0]) + "  RAIDERS=" + std::to_string(lanTeamRoundScore[1]);
            draw_text(renderer, title, centered_text_x(title, 4), SCREEN_HEIGHT/2 - 130, 4, {255,255,255,255});
            draw_text(renderer, who, centered_text_x(who, 3), SCREEN_HEIGHT/2 - 30, 3, {100,220,255,255});
            draw_text(renderer, score, centered_text_x(score, 2), SCREEN_HEIGHT/2 + 60, 2, {255,220,100,255});
            SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_NONE);
        }

        // Synchronized pre-round countdown overlay. Input is also gated by lanMatchPhase.
        if ((lanNetwork.hosting || lanNetwork.connected) && lanMatchStarted && lanMatchPhase == 1) {
            SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);
            SDL_SetRenderDrawColor(renderer, 0, 0, 0, 150);
            SDL_Rect overlay{0, 0, SCREEN_WIDTH, SCREEN_HEIGHT};
            SDL_RenderFillRect(renderer, &overlay);
            std::string cd = lanCountdownValue > 0 ? std::to_string(lanCountdownValue) : "GO!";
            draw_text(renderer, cd, centered_text_x(cd, 8), SCREEN_HEIGHT / 2 - 90, 8,
                      {100, 220, 255, 255});
            draw_text(renderer, "GET READY", centered_text_x("GET READY", 2), SCREEN_HEIGHT / 2 + 20, 2,
                      {235, 240, 245, 255});
            SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_NONE);
        }

        // Authoritative multiplayer projectiles are rendered from host snapshots.
        if (lanNetwork.hosting || lanNetwork.connected) {
            for (const auto& nb : lanNetwork.bullets) {
                if (!nb.active) continue;
                SDL_Rect br{static_cast<int>(nb.renderX) - cameraX - 5, static_cast<int>(nb.renderY) - cameraY - 5, 10, 10};
                const auto& wp = WEAPON_PROPS[std::clamp(nb.weapon, 0, static_cast<int>(WeaponType::COIN_MAGNET))];
                SDL_SetRenderDrawColor(renderer, wp.color.r, wp.color.g, wp.color.b, 255);
                SDL_RenderFillRect(renderer, &br);
            }
        }

        // STEP 17.39: render tire effects behind world-space vehicles, then vehicles.
        VehicleRenderTireEffects(renderer, cameraX, cameraY);
        for (int vehicleIndex = 0; vehicleIndex < MAX_AMBIENT_VEHICLES; ++vehicleIndex) {
            if (g_vehicles[vehicleIndex].active) {
                const auto& vv = g_vehicles[vehicleIndex];
                SDL_Texture* tex = VehicleTextureFor(vv.type);
                if (tex) DrawVehicleSpriteLayer(renderer, tex, vv, cameraX, cameraY);
                else VehicleRender(renderer, vv, cameraX, cameraY);
            }
        }
        DrawVehicleEffects(renderer, cameraX, cameraY);
    DrawAllGameplayVisuals(renderer, cameraX, cameraY);
        DrawVisualTracers(renderer, cameraX, cameraY);

        // Draw network players before the local player so the local character remains visually primary.
        if (lanNetwork.hosting || lanNetwork.connected) {
            for (const auto& rp : lanNetwork.remotePlayers) {
                if (rp.id == lanNetwork.localPlayerId) continue;
                SDL_Rect other{static_cast<int>(rp.x) - cameraX, static_cast<int>(rp.y) - cameraY, 60, 60};
                SDL_SetRenderDrawColor(renderer, rp.dead ? 100 : 70, rp.dead ? 100 : 150, rp.dead ? 100 : 255, rp.dead ? 120 : 255);
                SDL_RenderFillRect(renderer, &other);
                SDL_SetRenderDrawColor(renderer, 220, 245, 255, 255);
                draw_rect_outline(renderer, other);
                std::string label = rp.name.empty() ? ("PLAYER_" + std::to_string(rp.id)) : rp.name;
                draw_text(renderer, label, centered_text_x(label, 1, other.x, other.w),
                          other.y - 24, 1, {150, 220, 255, 255});
                render_health_bar(renderer, other.x, other.y - 12, other.w, 8, rp.hp, 100,
                                  {70, 160, 255, 255});
                if (rp.dead) draw_text(renderer, "DEAD", other.x + 12, other.y + 24, 1, {255, 100, 100, 255});
            }
        }

        // Screen-space player rectangle is also used by HUD/effects below.
        // Keep it in scope even when the player is hidden inside a vehicle.
        SDL_Rect playerScreen = player;
        playerScreen.x -= cameraX;
        playerScreen.y -= cameraY;

        // The local player is physically inside the vehicle while driving.
        // Do NOT render the infantry/player rectangle or player name on top of
        // the vehicle. The vehicle itself is the only visible representation
        // of the driver.
        if (g_activeVehicle < 0) {
            SDL_Color playerTint{60, 220, 100, 255};
            if (isDashing || (currentTime - lastDashTriggeredAt < 180)) {
                float flash = isDashing ? 1.0f : (1.0f - static_cast<float>(currentTime - lastDashTriggeredAt) / 180.0f);
                playerTint.r = static_cast<Uint8>(60 + (255 - 60) * flash);
                playerTint.g = static_cast<Uint8>(220 + (255 - 220) * flash);
                playerTint.b = static_cast<Uint8>(100 + (255 - 100) * flash);
            }
            SDL_SetRenderDrawColor(renderer, playerTint.r, playerTint.g, playerTint.b, playerTint.a);
            SDL_RenderFillRect(renderer, &playerScreen);
            if (!playerName.empty()) {
                draw_text(renderer, playerName,
                          centered_text_x(playerName, 1, playerScreen.x, playerScreen.w),
                          playerScreen.y - 24, 1, {235, 255, 245, 255});
            }
        }

        // Premium weapon muzzle FX: short, bright bursts that make Fire Gun and
        // Ice Gun feel distinct even before their projectiles reach a target.
        if (lastPlayerFireAt != 0 && currentTime - lastPlayerFireAt < 140 &&
            (playerWeapon == WeaponType::FIRE_GUN || playerWeapon == WeaponType::ICE_GUN)) {
            float age = static_cast<float>(currentTime - lastPlayerFireAt) / 140.0f;
            float fade = 1.0f - age;
            int fx = playerScreen.x + playerScreen.w/2 + static_cast<int>(lastPlayerAimX * 55.0f);
            int fy = playerScreen.y + playerScreen.h/2 + static_cast<int>(lastPlayerAimY * 55.0f);
            SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);
            if (playerWeapon == WeaponType::FIRE_GUN) {
                SDL_SetRenderDrawColor(renderer,255,90,20,static_cast<Uint8>(220*fade));
                draw_filled_circle(renderer,fx,fy,static_cast<int>(30+18*fade));
                SDL_SetRenderDrawColor(renderer,255,220,70,static_cast<Uint8>(240*fade));
                draw_filled_circle(renderer,fx,fy,static_cast<int>(14+10*fade));
            } else {
                SDL_SetRenderDrawColor(renderer,100,220,255,static_cast<Uint8>(220*fade));
                draw_filled_circle(renderer,fx,fy,static_cast<int>(24+12*fade));
                SDL_SetRenderDrawColor(renderer,235,252,255,static_cast<Uint8>(240*fade));
                for (int shard=0; shard<6; ++shard) {
                    float a = shard * 1.0472f + age * 2.0f;
                    int ex = fx + static_cast<int>(std::cos(a) * (28+35*age));
                    int ey = fy + static_cast<int>(std::sin(a) * (28+35*age));
                    SDL_RenderDrawLine(renderer,fx,fy,ex,ey);
                }
            }
            SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_NONE);
        }

        if (playerShieldActive) {
            SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);
            Uint32 shieldElapsed = currentTime - playerShieldActivatedAt;
            // Fast pulse so the shield reads as "electric" rather than a static outline.
            float pulse = 0.6f + 0.4f * std::sin(static_cast<float>(shieldElapsed) * 0.02f);
            for (int ring = 0; ring < 3; ++ring) {
                int pad = 10 + ring * 6;
                SDL_Rect glow = { playerScreen.x - pad, playerScreen.y - pad, playerScreen.w + pad * 2, playerScreen.h + pad * 2 };
                Uint8 alpha = static_cast<Uint8>(std::max(0.0f, (150 - ring * 45) * pulse));
                SDL_SetRenderDrawColor(renderer, 90, 200, 255, alpha);
                draw_rect_outline(renderer, glow);
            }
        }

        // --- Unified top title bar ------------------------------------------------
        // Clean order:
        // [Health] [Weapon] [Bomb Fuse] [Mode] [Round] [Score] [High Score] [RANKS] [X]
        SDL_Rect titleBar{15, 10, SCREEN_WIDTH - 30, 62};
        SDL_SetRenderDrawColor(renderer, 7, 15, 28, 245);
        SDL_RenderFillRect(renderer, &titleBar);
        SDL_SetRenderDrawColor(renderer, 55, 150, 205, 255);
        draw_rect_outline(renderer, titleBar, 2);

        // 1. HEALTH
        render_health_bar(renderer, 25, 29, 220, 22, playerHp, playerMaxHp,
                          {60, 220, 120, 255});

        // 2. WEAPON
        draw_text(renderer, WEAPON_PROPS[static_cast<int>(playerWeapon)].name,
                  265, 31, 2, WEAPON_PROPS[static_cast<int>(playerWeapon)].color);

        // 3. BOMB FUSE
        // Keep the fuse beside the weapon so the round-critical state is easy
        // to scan without searching the rest of the title bar.
        SDL_Rect fuseBox{475, 20, 170, 42};
        std::string fuseText = "FUSE: --.-S";
        Uint32 remainingMs = 0;
        float fuseFrac = 0.0f;
        bool fuseActive = selectedMode == GameMode::TACTICAL &&
                          tacticalBomb.planted && !tacticalBomb.defused;
        if (fuseActive) {
            Uint32 fuseElapsed = currentTime - tacticalBomb.plantTime;
            remainingMs = (fuseElapsed < tacticalBomb.fuseDuration)
                ? (tacticalBomb.fuseDuration - fuseElapsed) : 0;
            int wholeSec = static_cast<int>(remainingMs / 1000);
            int tenths = static_cast<int>((remainingMs % 1000) / 100);
            fuseText = "FUSE: " + std::to_string(wholeSec) + "." +
                       std::to_string(tenths) + "S";
            fuseFrac = static_cast<float>(remainingMs) /
                       static_cast<float>(std::max<Uint32>(1, tacticalBomb.fuseDuration));
        }

        if (selectedMode == GameMode::TACTICAL) {
            SDL_SetRenderDrawColor(renderer, fuseActive ? 65 : 25,
                                   fuseActive ? 25 : 35,
                                   fuseActive ? 30 : 45, 235);
            SDL_RenderFillRect(renderer, &fuseBox);
            SDL_SetRenderDrawColor(renderer, fuseActive ? 255 : 90,
                                   fuseActive ? 70 : 170,
                                   fuseActive ? 70 : 210, 255);
            draw_rect_outline(renderer, fuseBox, 2);

            SDL_Rect fuseBarBg{fuseBox.x + 8, fuseBox.y + 31, fuseBox.w - 16, 5};
            SDL_SetRenderDrawColor(renderer, 35, 35, 40, 255);
            SDL_RenderFillRect(renderer, &fuseBarBg);
            if (fuseActive) {
                SDL_Rect fuseBar{fuseBarBg.x + 1, fuseBarBg.y + 1,
                                 std::max(1, static_cast<int>((fuseBarBg.w - 2) * fuseFrac)), 3};
                SDL_SetRenderDrawColor(renderer, 255, 70, 70, 255);
                SDL_RenderFillRect(renderer, &fuseBar);
            }

            draw_text(renderer, fuseText,
                      centered_text_x(fuseText, 2, fuseBox.x, fuseBox.w),
                      fuseBox.y + 7, 2,
                      fuseActive ? SDL_Color{255, 110, 110, 255} : SDL_Color{130, 180, 210, 255});
        }

        // 4-7. Compact, evenly spaced title-bar statistics. Every field has
        // its own fixed zone so text never touches its neighbor.
        const int textY = titleBar.y + 24;
        auto drawTitleField = [&](const std::string& text, int x, int w,
                                  SDL_Color color, int preferredScale = 2) {
            const int scale = fit_text_scale(text, w - 12, preferredScale);
            draw_text(renderer, text, centered_text_x(text, scale, x, w),
                      textY, scale, color);
        };

        drawTitleField("MODE: " + std::string(selectedMode == GameMode::ENDLESS ? "ENDLESS" : "TACTICAL"),
                       660, 180, {100, 220, 255, 255}, 2);

        if (selectedMode == GameMode::ENDLESS) {
            drawTitleField("WAVE: " + std::to_string(currentLevel),
                           840, 135, {100, 220, 255, 255}, 2);
            drawTitleField("KILLS: " + std::to_string(playerKills),
                           975, 145, {120, 235, 150, 255}, 2);
            drawTitleField("SCORE: " + std::to_string(score),
                           1120, 140, {240, 200, 80, 255}, 2);
        } else {
            drawTitleField("ROUND: " + std::to_string(currentRound) + "/" +
                           std::to_string(MAX_TACTICAL_ROUNDS),
                           840, 190, {100, 220, 255, 255}, 2);
            // Keep HIGH SCORE directly after SCORE, but use the available
            // right-side space instead of shrinking the font.
            // The 250px HIGH SCORE zone fits five digits at the normal scale 2.
            // Give SCORE, HIGH SCORE and COINS enough fixed room for six digits.
            // Keep the normal font size; use the available right-side space instead.
            drawTitleField("SCORE: " + std::to_string(score),
                           1030, 150, {240, 200, 80, 255}, 2);
            drawTitleField("HIGH SCORE: " + std::to_string(highScore),
                           1180, 330, {255, 190, 70, 255}, 2);
            // Extra room keeps COINS at normal font size for very large balances.
            drawTitleField("COINS: " + std::to_string(coinBalance),
                           1510, 190, {240, 200, 80, 255}, 2);
        }

        if (selectedMode == GameMode::ENDLESS) {
            drawTitleField("HIGH SCORE: " + std::to_string(highScore),
                           1260, 190, {255, 190, 70, 255}, 2);
            drawTitleField("COINS: " + std::to_string(coinBalance),
                           1450, 155, {240, 200, 80, 255}, 2);
        }

        // Blueprint-style separators.
        SDL_SetRenderDrawColor(renderer, 45, 95, 125, 180);
        if (selectedMode == GameMode::ENDLESS) {
            for (int x : {250, 465, 660, 840, 975, 1120, 1260, 1450, 1605, 1805})
                SDL_RenderDrawLine(renderer, x, titleBar.y + 10,
                                   x, titleBar.y + titleBar.h - 10);
        } else {
            // Tactical mode: SCORE -> wide HIGH SCORE -> COINS.
            // Use the side space before RANKS instead of shrinking HIGH SCORE.
            for (int x : {250, 465, 660, 840, 1030, 1180, 1510, 1700, 1815, 1835})
                SDL_RenderDrawLine(renderer, x, titleBar.y + 10,
                                   x, titleBar.y + titleBar.h - 10);
        }

        // 8. RANKS
        SDL_SetRenderDrawColor(renderer,
                               showLeaderboardPanel ? 40 : 55,
                               showLeaderboardPanel ? 150 : 80,
                               showLeaderboardPanel ? 210 : 100, 235);
        SDL_RenderFillRect(renderer, &btnLeaderboard);
        SDL_SetRenderDrawColor(renderer, 255, 255, 255, 255);
        draw_rect_outline(renderer, btnLeaderboard);
        draw_text(renderer, "RANKS",
                  centered_text_x("RANKS", 2, btnLeaderboard.x, btnLeaderboard.w),
                  btnLeaderboard.y + 8, 2, {255, 255, 255, 255});

        // Squad command menu on the right side. It is available to mouse and
        // touch input, while the number keys remain useful on desktop.
        SDL_SetRenderDrawColor(renderer, showBotCommands ? 45 : 55,
                               showBotCommands ? 145 : 85,
                               showBotCommands ? 190 : 105, 235);
        SDL_RenderFillRect(renderer, &btnBotCommands);
        SDL_SetRenderDrawColor(renderer, 255, 255, 255, 255);
        draw_rect_outline(renderer, btnBotCommands);
        draw_text(renderer, "BOT COMMANDS",
                  centered_text_x("BOT COMMANDS", 1, btnBotCommands.x, btnBotCommands.w),
                  btnBotCommands.y + 15, 1, {255, 255, 255, 255});
        if (showBotCommands) {
            const char* commandLabels[] = {
                "5  EVERYONE, STAY TOGETHER AND MOVE WITH ME!",
                "6  SQUAD, HOLD THIS POSITION!",
                "8  SQUAD, MOVE TO BOMBSITE A!",
                "9  SQUAD, MOVE TO BOMBSITE B!"
            };
            for (int ci = 0; ci < 4; ++ci) {
                SDL_Rect commandRect = bot_command_rect(ci);
                bool selected = static_cast<int>(currentBotCommand) == ci;
                SDL_SetRenderDrawColor(renderer, selected ? 45 : 35,
                                       selected ? 145 : 55,
                                       selected ? 110 : 75, 245);
                SDL_RenderFillRect(renderer, &commandRect);
                SDL_SetRenderDrawColor(renderer, 230, 240, 245, 255);
                draw_rect_outline(renderer, commandRect);
                draw_text(renderer, commandLabels[ci], commandRect.x + 12,
                          commandRect.y + 14, 1, {255, 255, 255, 255});
            }
        }

        // 9. CLOSE — small square X in the title bar.
        render_back_button(renderer, btnPlayingBack);

        // Fixed left-side map box.  The weapon wheel begins far below it.
        if (currentGameState == GameState::PLAYING && !showLeaderboardPanel) {
            render_live_minimap(renderer, SDL_Rect{20, 95, 320, 255}, playerPosX, playerPosY, moveVecX, moveVecY);
        }

        if (selectedMode == GameMode::TACTICAL && tacticalBomb.planted && !tacticalBomb.defused) {
            bool nearBomb = SDL_HasIntersection(&player, &tacticalBomb.rect);
            if (nearBomb) {
                SDL_SetRenderDrawColor(renderer, defuseHeld ? 40 : 55, defuseHeld ? 170 : 80, defuseHeld ? 80 : 100, 235);
                SDL_RenderFillRect(renderer, &defuseButton);
                SDL_SetRenderDrawColor(renderer, 255, 255, 255, 255);
                draw_rect_outline(renderer, defuseButton);

                int progress = defuseHeld && defuseStartTime
                    ? static_cast<int>(std::min<Uint32>(100, (currentTime - defuseStartTime) * 100 / DEFUSE_TIME_MS))
                    : 0;
                SDL_Rect bar = {defuseButton.x + 12, defuseButton.y + 40,
                                (defuseButton.w - 24) * progress / 100, 16};
                SDL_SetRenderDrawColor(renderer, 80, 230, 120, 255);
                SDL_RenderFillRect(renderer, &bar);
                draw_text(renderer, "HOLD TO DEFUSE",
                          centered_text_x("HOLD TO DEFUSE", 2, defuseButton.x, defuseButton.w),
                          defuseButton.y + 8, 2, {255,255,255,255});
            }
        }

        if (playerWeapon == WeaponType::PISTOL) {
            std::string shieldLabel;
            SDL_Color shieldFill{60, 65, 80, 220};
            if (playerShieldActive) {
                int secsLeft = static_cast<int>((SHIELD_DURATION_MS - (currentTime - playerShieldActivatedAt)) / 1000) + 1;
                shieldLabel = "SHIELD: " + std::to_string(std::max(0, secsLeft)) + "S";
                shieldFill = {40, 150, 220, 235};
            } else if (currentTime < playerShieldReadyAt) {
                int secsLeft = static_cast<int>((playerShieldReadyAt - currentTime) / 1000) + 1;
                shieldLabel = "SHIELD: " + std::to_string(std::max(0, secsLeft)) + "S";
                shieldFill = {90, 90, 60, 200};
            } else {
                shieldLabel = "SHIELD [Q]";
                shieldFill = {40, 170, 90, 235};
            }
            SDL_SetRenderDrawColor(renderer, shieldFill.r, shieldFill.g, shieldFill.b, shieldFill.a);
            SDL_RenderFillRect(renderer, &shieldButton);
            SDL_SetRenderDrawColor(renderer, 255, 255, 255, 255);
            draw_rect_outline(renderer, shieldButton);
            int shieldTextX = shieldButton.x + (shieldButton.w - static_cast<int>(shieldLabel.length()) * 6 * 2) / 2;
            draw_text(renderer, shieldLabel, shieldTextX, shieldButton.y + (shieldButton.h - 14) / 2, 2, {255, 255, 255, 255});
        }

        // Vehicle enter/exit control. Visible only near a vehicle or while driving.
        if (VehicleFindNearbyPlayer(playerPosX + player.w * 0.5f, playerPosY + player.h * 0.5f) >= 0 || g_activeVehicle >= 0) {
            SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);
            SDL_SetRenderDrawColor(renderer, g_activeVehicle >= 0 ? 220 : 60,
                                   g_activeVehicle >= 0 ? 90 : 190,
                                   g_activeVehicle >= 0 ? 70 : 120, 225);
            SDL_RenderFillRect(renderer, &vehicleInteractButton);
            SDL_SetRenderDrawColor(renderer, 255, 255, 255, 255);
            draw_rect_outline(renderer, vehicleInteractButton);
            const char* vehicleAction = g_activeVehicle >= 0 ? "EXIT VEHICLE" : "ENTER VEHICLE";
            int vehicleTextX = vehicleInteractButton.x +
                (vehicleInteractButton.w - static_cast<int>(std::strlen(vehicleAction)) * 12) / 2;
            draw_text(renderer, vehicleAction, vehicleTextX,
                      vehicleInteractButton.y + 24, 2, {255, 255, 255, 255});
            SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_NONE);
        }

        render_arrow_pad(renderer);
if (isTouchingDock) {
            SDL_SetRenderDrawColor(renderer, 255, 255, 255, 60);
            SDL_RenderFillRect(renderer, &dockBase);
            SDL_SetRenderDrawColor(renderer, 255, 255, 255, 180);
            SDL_RenderFillRect(renderer, &dockHandle);

            // Long-press charge indicator: a radial ring around the joystick knob that
            // fills up as joystickHoldTimer approaches LONG_PRESS_DURATION, so the player
            // gets visual feedback before the roll auto-triggers.
            if (joystickHoldTimer > 0.0f) {
                float chargeFrac = std::min(1.0f, joystickHoldTimer / LONG_PRESS_DURATION);
                int knobCx = dockHandle.x + dockHandle.w / 2;
                int knobCy = dockHandle.y + dockHandle.h / 2;
                int ringRadius = dockHandle.w / 2 + 14;
                constexpr int ringSegments = 40;
                int filledSegments = static_cast<int>(chargeFrac * ringSegments);
                SDL_SetRenderDrawColor(renderer, 140, 230, 255, 230);
                for (int s = 0; s < filledSegments; ++s) {
                    float a0 = -static_cast<float>(M_PI) / 2.0f + (static_cast<float>(s) / ringSegments) * 2.0f * static_cast<float>(M_PI);
                    float a1 = -static_cast<float>(M_PI) / 2.0f + (static_cast<float>(s + 1) / ringSegments) * 2.0f * static_cast<float>(M_PI);
                    int x0 = knobCx + static_cast<int>(std::cos(a0) * ringRadius), y0 = knobCy + static_cast<int>(std::sin(a0) * ringRadius);
                    int x1 = knobCx + static_cast<int>(std::cos(a1) * ringRadius), y1 = knobCy + static_cast<int>(std::sin(a1) * ringRadius);
                    SDL_RenderDrawLine(renderer, x0, y0, x1, y1);
                }
            }
        }

        if (playerWeapon == WeaponType::COIN_MAGNET) {
            SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);
            int mcx = player.x + player.w/2 - cameraX, mcy = player.y + player.h/2 - cameraY;
            float pulse = 0.5f + 0.5f * std::sin(currentTime * 0.007f);
            // Bright, clearly visible concentric magnetic field rings.
            for (int rr = 70; rr <= 420; rr += 70) {
                float phase = std::fmod(currentTime * 0.09f + rr, 70.0f);
                int radius = rr + static_cast<int>(phase * 0.22f);
                Uint8 a = static_cast<Uint8>(55 + 70 * pulse);
                SDL_SetRenderDrawColor(renderer, 255, 205, 45, a);
                draw_circle_outline(renderer, mcx, mcy, radius, 3);
            }
            // Rotating magnetic field ticks make the rings read as an active pull,
            // rather than decorative circles.
            for (int k = 0; k < 12; ++k) {
                float a = currentTime * 0.0025f + k * (2.0f * static_cast<float>(M_PI) / 12.0f);
                float r1 = 330.0f, r2 = 410.0f;
                int x1 = mcx + static_cast<int>(std::cos(a) * r1);
                int y1 = mcy + static_cast<int>(std::sin(a) * r1);
                int x2 = mcx + static_cast<int>(std::cos(a) * r2);
                int y2 = mcy + static_cast<int>(std::sin(a) * r2);
                SDL_SetRenderDrawColor(renderer, 255, 235, 100, static_cast<Uint8>(90 + 100*pulse));
                SDL_RenderDrawLine(renderer, x1, y1, x2, y2);
            }
            SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_NONE);
        }
        render_weapon_radial(renderer, currentTime);

        // Manual leaderboard toggle - only reachable mid-match via the RANKS button.
        if (currentGameState == GameState::PLAYING && showLeaderboardPanel) {
            render_leaderboard_panel(renderer, leaderboardPanelBox, "LEADERBOARD");
        }

        if (currentGameState == GameState::GAME_OVER) {
            SDL_SetRenderDrawColor(renderer, 180, 0, 0, 150);
            SDL_Rect overlay = {0, 0, SCREEN_WIDTH, SCREEN_HEIGHT};
            SDL_RenderFillRect(renderer, &overlay);
            bool hasNextRound = selectedMode == GameMode::TACTICAL && currentRound < MAX_TACTICAL_ROUNDS;
            std::string goLine1 = hasNextRound ? "SQUAD DOWN - ROUND FAILED" : "GAME OVER - TAP TO MAIN MENU";
            std::string goLine2 = hasNextRound
                ? "TAP ANYWHERE FOR ROUND " + std::to_string(currentRound + 1) + "/" + std::to_string(MAX_TACTICAL_ROUNDS)
                : "FINAL SCORE: " + std::to_string(score) + "   HIGH SCORE: " + std::to_string(highScore);
            draw_text(renderer, goLine1, centered_text_x(goLine1, 3), SCREEN_HEIGHT / 2 - 40, 3, {255, 255, 255, 255});
            draw_text(renderer, goLine2, centered_text_x(goLine2, 2), SCREEN_HEIGHT / 2 + 15, 2, {255, 220, 100, 255});
            // Auto-flash: the match-end leaderboard pops on top once, right as the
            // result lands, so the squad's final standing is the last thing seen.
            if (showMatchEndLeaderboard) {
                render_leaderboard_panel(renderer, leaderboardPanelBox, "MATCH RESULTS");
            }
        } else if (currentGameState == GameState::GAME_WON) {
            SDL_SetRenderDrawColor(renderer, 0, 180, 60, 150);
            SDL_Rect overlay = {0, 0, SCREEN_WIDTH, SCREEN_HEIGHT};
            SDL_RenderFillRect(renderer, &overlay);
            std::string wonLine1 = tacticalBomb.planted ? "BOMB DEFUSED! MISSION ACCOMPLISHED" : "ALL ENEMIES ELIMINATED! MISSION ACCOMPLISHED";
            bool hasNextRound = selectedMode == GameMode::TACTICAL && currentRound < MAX_TACTICAL_ROUNDS;
            std::string wonLine2 = hasNextRound
                ? "TAP ANYWHERE FOR ROUND " + std::to_string(currentRound + 1) + "/" + std::to_string(MAX_TACTICAL_ROUNDS)
                : "TAP ANYWHERE TO RETURN TO MENU";
            draw_text(renderer, wonLine1, centered_text_x(wonLine1, 3), SCREEN_HEIGHT / 2 - 40, 3, {255, 255, 255, 255});
            draw_text(renderer, wonLine2, centered_text_x(wonLine2, 2), SCREEN_HEIGHT / 2 + 15, 2, {255, 255, 255, 255});
            if (showMatchEndLeaderboard) {
                render_leaderboard_panel(renderer, leaderboardPanelBox, "MATCH RESULTS");
            }
        }

        // Draw the rocket/C4 square blast LAST so enemies, bots, player, weapon effects,
        // and HUD-world effects cannot cover it. This matches the working game57 layering.
        if (lanNetwork.hosting || lanNetwork.connected || lanNetwork.joining) {
            if (lanNetwork.statsWindowAt == 0) lanNetwork.statsWindowAt = currentTime;
            Uint32 elapsed = currentTime - lanNetwork.statsWindowAt;
            if (elapsed >= 1000) {
                float sec = elapsed / 1000.0f;
                lanNetwork.packetsPerSecondOut = lanNetwork.windowPacketsSent / sec;
                lanNetwork.packetsPerSecondIn = lanNetwork.windowPacketsReceived / sec;
                lanNetwork.windowPacketsSent = lanNetwork.windowPacketsReceived = 0;
                lanNetwork.statsWindowAt = currentTime;
            }
            int boxW = std::min(360, SCREEN_WIDTH - 24), boxH = 92;
            int boxX = SCREEN_WIDTH - boxW - 12, boxY = 78;
            SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);
            SDL_SetRenderDrawColor(renderer, 8, 18, 28, 215);
            SDL_Rect r{boxX, boxY, boxW, boxH}; SDL_RenderFillRect(renderer, &r);
            SDL_SetRenderDrawColor(renderer, 70, 150, 190, 230); draw_rect_outline(renderer, r, 2);
            std::string a = "NET PING " + std::to_string(lanNetwork.lastPingMs) + "ms IN " + std::to_string((int)lanNetwork.packetsPerSecondIn) + "/s OUT " + std::to_string((int)lanNetwork.packetsPerSecondOut) + "/s";
            std::string b = "PKT " + std::to_string(lanNetwork.lastPacketSize) + "B MAX " + std::to_string(lanNetwork.maxPacketSize) + "B TOTAL " + std::to_string(lanNetwork.packetsSent + lanNetwork.packetsReceived);
            std::string c = "SNAP " + std::to_string(lanNetwork.snapshotPacketsSent) + " DELTA " + std::to_string(lanNetwork.deltaSnapshotsSent) + " FULL " + std::to_string(lanNetwork.fullSnapshotsSent);
            draw_text(renderer, a, boxX + 10, boxY + 10, 1, {170,235,255,255});
            draw_text(renderer, b, boxX + 10, boxY + 35, 1, {220,230,235,255});
            draw_text(renderer, c, boxX + 10, boxY + 60, 1, {150,220,170,255});
            SDL_Rect netBtn{boxX + boxW - 118, boxY + 66, 108, 22};
            SDL_SetRenderDrawColor(renderer, 25, 70, 95, 235);
            SDL_RenderFillRect(renderer, &netBtn);
            draw_rect_outline(renderer, netBtn, 1);
            draw_text(renderer, "NET TEST [N]", netBtn.x + 8, netBtn.y + 5, 1, {220,240,250,255});
            SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_NONE);
        }
        // Connection-lost overlay: gameplay remains visible but local simulation is
        // paused until an authoritative snapshot arrives after reconnect.
        if (networkReconnect.connectionLost || networkReconnect.status == ReconnectStatus::MIGRATING || networkReconnect.status == ReconnectStatus::RESUMED) {
            SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);
            SDL_SetRenderDrawColor(renderer, 0, 0, 0, 185);
            SDL_Rect shade{0, 0, SCREEN_WIDTH, SCREEN_HEIGHT}; SDL_RenderFillRect(renderer, &shade);
            SDL_SetRenderDrawColor(renderer, 12, 28, 42, 245);
            SDL_Rect card{SCREEN_WIDTH/2-360, SCREEN_HEIGHT/2-125, 720, 250}; SDL_RenderFillRect(renderer, &card);
            SDL_SetRenderDrawColor(renderer, 100,220,255,255); draw_rect_outline(renderer, card, 3);
            const char* title = networkReconnect.status == ReconnectStatus::MIGRATING ? "HOST MIGRATION" :
                                (networkReconnect.status == ReconnectStatus::RESUMED ? "CONNECTION RESTORED" : "CONNECTION LOST");
            draw_text(renderer, title, centered_text_x(title, 3), card.y+28, 3, {100,220,255,255});
            draw_text(renderer, networkReconnect.message, centered_text_x(networkReconnect.message, 1), card.y+100, 1, {230,240,245,255});
            if (networkReconnect.status == ReconnectStatus::RECONNECTING)
                draw_text(renderer, "Automatic reconnect in progress - match will resume from server state", centered_text_x("Automatic reconnect in progress - match will resume from server state", 1), card.y+145, 1, {160,225,185,255});
            if (networkReconnect.status == ReconnectStatus::MIGRATING)
                draw_text(renderer, "Migration candidate: Player " + std::to_string(networkReconnect.migrationCandidateId), centered_text_x("Migration candidate: Player " + std::to_string(networkReconnect.migrationCandidateId), 1), card.y+145, 1, {255,220,120,255});
            SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_NONE);
        }
        Game59NetUpdateDiagnostics(currentTime);
        Game59DrawNetworkTestPanel(renderer);
        render_explosions(renderer, currentTime);
        render_badge_popup(renderer);
        render_fire_impacts(renderer, currentTime);
        SDL_RenderPresent(renderer);
        SDL_Delay(16);
    }

    // Never lose pickups collected during the final save interval.
    if (progressSavePending) save_progress();
    lan_shutdown_network();
    if (playerPortraitTexture) SDL_DestroyTexture(playerPortraitTexture);
    if (audioDevice != 0) {
        // Closing the device first guarantees the audio callback cannot
        // dereference voice buffers while they are being released.
        SDL_CloseAudioDevice(audioDevice);
        audioDevice = 0;
    }
    free_all_voice_clips();
    if (SDL_WasInit(SDL_INIT_AUDIO) != 0) SDL_QuitSubSystem(SDL_INIT_AUDIO);
    if (g_carVehicleTexture) SDL_DestroyTexture(g_carVehicleTexture);
    if (g_truckVehicleTexture) SDL_DestroyTexture(g_truckVehicleTexture);
    if (g_buggyVehicleTexture) SDL_DestroyTexture(g_buggyVehicleTexture);
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    IMG_Quit();
    SDL_Quit();
    return 0;
}


