// ============================================================
// STEP 15: DISCONNECT / RECONNECT FOUNDATION
// ============================================================
// Network integration hook for the existing authoritative host.
// This keeps a player's slot/state reserved for a grace period instead
// of immediately deleting the player when their socket disappears.

#ifndef GAME59_RECONNECT_GRACE_SECONDS
#define GAME59_RECONNECT_GRACE_SECONDS 20.0
#endif

struct Game59ReconnectSlot {
    bool occupied = false;
    bool connected = false;
    bool reconnecting = false;
    int playerId = -1;
    int team = 0;
    double disconnectedAt = 0.0;
};

// Call this when the authoritative host detects a client disconnect.
// The player's gameplay state should remain in the normal player array;
// this slot only tracks the connection lifecycle.
static inline void Game59MarkPlayerDisconnected(Game59ReconnectSlot& slot, double nowSeconds) {
    if (!slot.occupied) return;
    slot.connected = false;
    slot.reconnecting = true;
    slot.disconnectedAt = nowSeconds;
}

// Returns true while the player is still inside the reconnect grace period.
static inline bool Game59ReconnectWindowOpen(const Game59ReconnectSlot& slot, double nowSeconds) {
    return slot.occupied && slot.reconnecting &&
           (nowSeconds - slot.disconnectedAt) <= GAME59_RECONNECT_GRACE_SECONDS;
}

// Call this after a reconnect has been authenticated as the same player.
// Keep the existing player/team/spawn state; only restore connectivity.
static inline bool Game59RestorePlayerConnection(Game59ReconnectSlot& slot, int reconnectingPlayerId) {
    if (!slot.occupied || slot.playerId != reconnectingPlayerId) return false;
    slot.connected = true;
    slot.reconnecting = false;
    slot.disconnectedAt = 0.0;
    return true;
}

// Host-side cleanup after the grace period expires.
static inline bool Game59ReconnectExpired(const Game59ReconnectSlot& slot, double nowSeconds) {
    return slot.occupied && slot.reconnecting &&
           (nowSeconds - slot.disconnectedAt) > GAME59_RECONNECT_GRACE_SECONDS;
}

#include <cstdint>
#include <random>
#include <unordered_set>
#include <deque>

// Reliable delivery metadata for important multiplayer events.
struct NetReliabilityHeader {
    uint32_t messageId = 0;
    uint32_t sequence = 0;
    uint8_t reliable = 0;
};

class NetReliabilityTracker {
public:
    uint32_t nextMessageId() { return nextId++; }
    uint32_t nextSequence() { return ++sendSequence; }

    bool acceptSequence(uint32_t seq) {
        if (seq <= highestSequence) return false;
        highestSequence = seq;
        return true;
    }

    bool seenMessage(uint32_t id) const { return received.count(id) != 0; }

    void markReceived(uint32_t id) {
        if (!received.insert(id).second) return;
        receivedOrder.push_back(id);
        if (receivedOrder.size() > 1024) {
            received.erase(receivedOrder.front());
            receivedOrder.pop_front();
        }
    }

private:
    uint32_t nextId = 1;
    uint32_t sendSequence = 0;
    uint32_t highestSequence = 0;
    std::unordered_set<uint32_t> received;
    std::deque<uint32_t> receivedOrder;
};

// Use reliable=true for JOIN/READY/START/ACTION/ROUND_RESULT/RESYNC.
// Snapshot sequence numbers let clients discard stale state updates.
static NetReliabilityTracker gNetReliability;


// ================================================================
// STEP 17.6 - DESYNC DETECTION + AUTOMATIC FULL-STATE RECOVERY
// ================================================================
// This layer is intentionally transport-agnostic. Hook the helpers below
// into the existing packet send/receive paths. The server remains authoritative.

#include <cstdint>
#include <random>
#include <deque>
#include <string>
#include <algorithm>

namespace net_sync_recovery {

static constexpr std::uint32_t kProtocolStateVersion = 176;
static constexpr std::uint32_t kRecoveryCooldownTicks = 180; // 3s @ 60Hz
static constexpr std::uint32_t kChecksumMismatchThreshold = 2;

struct RecoveryTracker {
    std::uint32_t lastAuthoritativeTick = 0;
    std::uint32_t lastAuthoritativeChecksum = 0;
    std::uint32_t lastRecoveryRequestTick = 0;
    std::uint32_t mismatchCount = 0;
    bool awaitingFullState = false;

    bool observeAuthoritativeState(std::uint32_t tick,
                                   std::uint32_t checksum,
                                   std::uint32_t localChecksum) {
        if (tick < lastAuthoritativeTick) return false;
        lastAuthoritativeTick = tick;
        lastAuthoritativeChecksum = checksum;

        if (checksum != localChecksum) {
            ++mismatchCount;
            return mismatchCount >= kChecksumMismatchThreshold;
        }
        mismatchCount = 0;
        return false;
    }

    bool canRequestRecovery(std::uint32_t currentTick) const {
        return !awaitingFullState &&
               currentTick >= lastRecoveryRequestTick + kRecoveryCooldownTicks;
    }

    void markRecoveryRequested(std::uint32_t currentTick) {
        lastRecoveryRequestTick = currentTick;
        awaitingFullState = true;
    }

    void markRecoveryApplied(std::uint32_t tick) {
        lastAuthoritativeTick = tick;
        mismatchCount = 0;
        awaitingFullState = false;
    }
};

// Stable FNV-1a checksum helper for deterministic replicated fields.
inline std::uint32_t fnv1a(const void* data, std::size_t size,
                           std::uint32_t hash = 2166136261u) {
    const auto* bytes = static_cast<const std::uint8_t*>(data);
    for (std::size_t i = 0; i < size; ++i) {
        hash ^= bytes[i];
        hash *= 16777619u;
    }
    return hash;
}

template <typename T>
inline void checksumValue(std::uint32_t& hash, const T& value) {
    hash = fnv1a(&value, sizeof(T), hash);
}

// Packet tags to add to the existing protocol switch.
static constexpr const char* MSG_STATE_CHECKSUM = "STATE_CHECKSUM";
static constexpr const char* MSG_RESYNC_REQUEST  = "RESYNC_REQUEST";
static constexpr const char* MSG_FULL_STATE      = "FULL_STATE";

} // namespace net_sync_recovery

// ============================================================
// STEP 17.19 - MULTIPLAYER SYNCHRONIZATION
// Player state, movement, actions, world snapshots, and
// reliable/unreliable message lanes. The transport layer owns sockets;
// this layer owns packet intent, sequencing, interpolation, and authority.
// ============================================================

enum class Game59SyncMessageKind : uint8_t {
    PLAYER_INPUT,
    PLAYER_ACTION,
    PLAYER_STATE,
    WORLD_SNAPSHOT,
    WORLD_EVENT,
    ACK
};

enum class Game59DeliveryLane : uint8_t { UNRELIABLE, RELIABLE };

struct Game59PlayerSyncState {
    int playerId = -1;
    float x = 0.0f, y = 0.0f;
    float velocityX = 0.0f, velocityY = 0.0f;
    float aimX = 0.0f, aimY = 0.0f;
    int health = 100;
    uint32_t animationFlags = 0;
    uint32_t lastInputSequence = 0;
    uint32_t lastServerTick = 0;
};

struct Game59PlayerInputCommand {
    uint32_t sequence = 0;
    uint32_t clientTick = 0;
    float moveX = 0.0f, moveY = 0.0f;
    float aimX = 0.0f, aimY = 0.0f;
};

struct Game59ActionEvent {
    uint32_t eventId = 0;
    int playerId = -1;
    uint32_t actionFlags = 0; // fire, reload, interact, plant, defuse, ability
    float targetX = 0.0f, targetY = 0.0f;
    uint32_t clientTick = 0;
};

struct Game59WorldState {
    uint32_t serverTick = 0;
    int score = 0;
    int round = 0;
    bool bombPlanted = false;
    bool roundEnded = false;
    std::vector<Game59PlayerSyncState> players;
};

struct Game59SyncEnvelope {
    Game59SyncMessageKind kind = Game59SyncMessageKind::PLAYER_INPUT;
    Game59DeliveryLane lane = Game59DeliveryLane::UNRELIABLE;
    uint32_t sequence = 0;
    uint32_t messageId = 0;
    uint32_t serverTick = 0;
};

// Snapshot interpolation keeps remote movement smooth without allowing the
// receiving client to author gameplay state. Snapshots are intentionally
// best-effort: a newer state supersedes a lost older state.
struct Game59SnapshotInterpolator {
    Game59PlayerSyncState previous{};
    Game59PlayerSyncState current{};
    Uint32 receivedAt = 0;
    bool hasPrevious = false;
    bool hasCurrent = false;

    void push(const Game59PlayerSyncState& state, Uint32 now) {
        if (hasCurrent && state.lastServerTick <= current.lastServerTick) return;
        previous = current;
        hasPrevious = hasCurrent;
        current = state;
        hasCurrent = true;
        receivedAt = now;
    }

    Game59PlayerSyncState sample(float alpha) const {
        if (!hasCurrent || !hasPrevious) return current;
        alpha = std::max(0.0f, std::min(1.0f, alpha));
        Game59PlayerSyncState out = current;
        out.x = previous.x + (current.x - previous.x) * alpha;
        out.y = previous.y + (current.y - previous.y) * alpha;
        out.velocityX = previous.velocityX + (current.velocityX - previous.velocityX) * alpha;
        out.velocityY = previous.velocityY + (current.velocityY - previous.velocityY) * alpha;
        return out;
    }
};

class Game59MultiplayerSynchronizer {
public:
    // Movement/input and high-frequency snapshots use UNRELIABLE delivery.
    // Important actions/world events use RELIABLE delivery with the existing
    // NetReliabilityTracker below handling acknowledgement/retransmission.
    static Game59DeliveryLane laneFor(Game59SyncMessageKind kind) {
        switch (kind) {
            case Game59SyncMessageKind::PLAYER_INPUT:
            case Game59SyncMessageKind::PLAYER_STATE:
            case Game59SyncMessageKind::WORLD_SNAPSHOT:
                return Game59DeliveryLane::UNRELIABLE;
            default:
                return Game59DeliveryLane::RELIABLE;
        }
    }

    Game59SyncEnvelope makeEnvelope(Game59SyncMessageKind kind, uint32_t tick) {
        Game59SyncEnvelope packet;
        packet.kind = kind;
        packet.lane = laneFor(kind);
        packet.sequence = ++nextSequence;
        packet.serverTick = tick;
        if (packet.lane == Game59DeliveryLane::RELIABLE) packet.messageId = ++nextReliableId;
        return packet;
    }

    bool acceptUnreliable(uint32_t sequence) {
        if (sequence <= highestUnreliableSequence) return false;
        highestUnreliableSequence = sequence;
        return true;
    }

    // Host-authoritative movement: apply validated input, not a client position.
    bool submitMovement(int playerId, const Game59PlayerInputCommand& input, float dt) {
        auto it = players.find(playerId);
        if (it == players.end()) return false;
        if (input.sequence <= it->second.lastInputSequence) return false;
        const float dx = input.moveX * dt;
        const float dy = input.moveY * dt;
        if (!ServerValidateMove(dx, dy, dt)) return false;
        it->second.lastInputSequence = input.sequence;
        it->second.velocityX = input.moveX;
        it->second.velocityY = input.moveY;
        it->second.x += dx;
        it->second.y += dy;
        return true;
    }

    // Actions are queued for authoritative validation/application. The caller
    // should use ServerAllowAction/weapon-specific checks before changing world state.
    void queueAction(const Game59ActionEvent& event) { reliableActions.push_back(event); }

    void applyAuthoritativeSnapshot(const Game59WorldState& snapshot, Uint32 now) {
        if (snapshot.serverTick <= world.serverTick) return;
        world = snapshot;
        for (const auto& p : snapshot.players) {
            players[p.playerId] = p;
            interpolators[p.playerId].push(p, now);
        }
    }

    const Game59WorldState& worldState() const { return world; }
    const std::unordered_map<int, Game59PlayerSyncState>& playerStates() const { return players; }
    std::deque<Game59ActionEvent>& pendingReliableActions() { return reliableActions; }
    Game59SnapshotInterpolator* interpolator(int playerId) {
        auto it = interpolators.find(playerId);
        return it == interpolators.end() ? nullptr : &it->second;
    }

private:
    uint32_t nextSequence = 0;
    uint32_t nextReliableId = 0;
    uint32_t highestUnreliableSequence = 0;
    Game59WorldState world{};
    std::unordered_map<int, Game59PlayerSyncState> players;
    std::unordered_map<int, Game59SnapshotInterpolator> interpolators;
    std::deque<Game59ActionEvent> reliableActions;
};

static Game59MultiplayerSynchronizer g_multiplayerSync;

// Integration contract for the existing LAN transport:
// 1) Each local frame sends PLAYER_INPUT on the unreliable lane.
// 2) FIRE/RELOAD/INTERACT/BOMB actions are reliable and deduplicated by eventId.
// 3) The host advances authoritative state and emits WORLD_SNAPSHOT packets at
//    a fixed cadence; clients interpolate remote PLAYER_STATE values.
// 4) Reliable WORLD_EVENT packets carry irreversible state changes such as
//    kills, pickups, bomb state, round transitions, reconnect restoration, and
//    host migration commits. A snapshot always remains the recovery source of truth.

// ============================================================
// STEP 17.20 - SERVER AUTHORITY
// Server validation, anti-cheat checks, state correction, and
// client-side prediction/reconciliation. Client input is intent;
// only the server publishes authoritative state.
// ============================================================

#include <algorithm>
#include <unordered_map>
#include <vector>

struct AuthorityVec3 { float x=0, y=0, z=0; };
static inline AuthorityVec3 operator+(AuthorityVec3 a, AuthorityVec3 b) { return {a.x+b.x,a.y+b.y,a.z+b.z}; }
static inline AuthorityVec3 operator*(AuthorityVec3 a, float s) { return {a.x*s,a.y*s,a.z*s}; }
static inline float AuthorityLenSq(AuthorityVec3 a) { return a.x*a.x+a.y*a.y+a.z*a.z; }

struct ClientInputCommand {
    uint32_t sequence = 0;
    uint32_t clientTick = 0;
    float moveX = 0, moveY = 0;
    float aimYaw = 0, aimPitch = 0;
    uint32_t buttons = 0;
};

struct AuthoritativePlayerState {
    AuthorityVec3 position;
    AuthorityVec3 velocity;
    float health = 100.0f;
    uint32_t serverTick = 0;
    uint32_t lastProcessedInput = 0;
    bool alive = true;
};

struct AuthorityValidationResult {
    bool accepted = false;
    bool correctionRequired = false;
    const char* reason = "";
};

static constexpr float AUTH_MAX_INPUT_MAGNITUDE = 1.05f;
static constexpr float AUTH_MAX_SPEED = 900.0f;
static constexpr float AUTH_MAX_CORRECTION_DISTANCE = 64.0f;
static constexpr uint32_t AUTH_MAX_FUTURE_TICKS = 8;

static AuthorityValidationResult ValidateClientInput(
    const ClientInputCommand& input,
    const AuthoritativePlayerState& current,
    uint32_t serverTick)
{
    if (!current.alive) return {false, true, "player is not alive"};
    if (input.sequence <= current.lastProcessedInput) return {false, false, "duplicate or stale input"};
    if (input.clientTick > serverTick + AUTH_MAX_FUTURE_TICKS)
        return {false, true, "future tick rejected"};
    if (input.moveX != input.moveX || input.moveY != input.moveY ||
        input.aimYaw != input.aimYaw || input.aimPitch != input.aimPitch)
        return {false, true, "invalid numeric input"};
    if (input.moveX*input.moveX + input.moveY*input.moveY > AUTH_MAX_INPUT_MAGNITUDE*AUTH_MAX_INPUT_MAGNITUDE)
        return {false, true, "movement input exceeds limits"};
    return {true, false, ""};
}

// Server simulation uses intent only; clients never submit positions as authority.
static void SimulateAuthoritativeMovement(
    AuthoritativePlayerState& state,
    const ClientInputCommand& input,
    float dt)
{
    AuthorityVec3 wish{input.moveX, 0.0f, input.moveY};
    float lenSq = AuthorityLenSq(wish);
    if (lenSq > 1.0f) {
        float invLen = 1.0f / std::sqrt(lenSq);
        wish = wish * invLen;
    }
    state.velocity = wish * AUTH_MAX_SPEED;
    state.position = state.position + state.velocity * dt;
    state.lastProcessedInput = input.sequence;
}

// Minimal server-side anti-cheat accounting. Escalation policy is deliberately
// separated from gameplay so a backend can log, warn, kick, or review players.
struct AntiCheatState {
    uint32_t rejectedInputs = 0;
    uint32_t suspiciousEvents = 0;
    uint64_t lastRejectMs = 0;
};
static std::unordered_map<int, AntiCheatState> g_authorityAntiCheat;

static void RecordAuthorityViolation(int playerId, uint64_t nowMs) {
    AntiCheatState& s = g_authorityAntiCheat[playerId];
    ++s.rejectedInputs;
    ++s.suspiciousEvents;
    s.lastRejectMs = nowMs;
}

// Client prediction: apply local input immediately for responsiveness and keep
// an input history. When a server snapshot arrives, rewind and replay inputs
// after the last server-acknowledged sequence.
struct PredictedClientState {
    AuthoritativePlayerState predicted;
    std::deque<ClientInputCommand> pendingInputs;
};

static void ClientPredict(PredictedClientState& client, const ClientInputCommand& input, float dt) {
    client.pendingInputs.push_back(input);
    SimulateAuthoritativeMovement(client.predicted, input, dt);
}

static bool ClientReconcile(
    PredictedClientState& client,
    const AuthoritativePlayerState& serverState,
    float dt)
{
    AuthorityVec3 delta{
        client.predicted.position.x - serverState.position.x,
        client.predicted.position.y - serverState.position.y,
        client.predicted.position.z - serverState.position.z
    };
    bool corrected = AuthorityLenSq(delta) > AUTH_MAX_CORRECTION_DISTANCE * AUTH_MAX_CORRECTION_DISTANCE;

    while (!client.pendingInputs.empty() &&
           client.pendingInputs.front().sequence <= serverState.lastProcessedInput)
        client.pendingInputs.pop_front();

    // The authoritative snapshot is always the baseline, even for small errors.
    client.predicted = serverState;
    for (const ClientInputCommand& input : client.pendingInputs)
        SimulateAuthoritativeMovement(client.predicted, input, dt);
    return corrected;
}

// Example authoritative packet handler entry point. Integrate this with the
// transport layer from Steps 17.19 and earlier.
static AuthorityValidationResult ServerProcessClientInput(
    int playerId,
    AuthoritativePlayerState& state,
    const ClientInputCommand& input,
    uint32_t serverTick,
    float dt,
    uint64_t nowMs)
{
    AuthorityValidationResult result = ValidateClientInput(input, state, serverTick);
    if (!result.accepted) {
        if (result.correctionRequired) RecordAuthorityViolation(playerId, nowMs);
        return result;
    }
    SimulateAuthoritativeMovement(state, input, dt);
    state.serverTick = serverTick;
    return result;
}

