// ============================================================
// VEHICLE DESTRUCTION FEEL LAYER - VISUAL PASS 25
// Explosions, debris, wreck smoke and stronger combat feedback.
// ============================================================

struct VehicleDebrisPiece {
    float x{0}, y{0};
    float vx{0}, vy{0};
    float life{0};
    float spin{0};
};

static std::vector<VehicleDebrisPiece> vehicleDebris;

static void SpawnVehicleDebris(float x, float y, int amount = 10) {
    for (int i = 0; i < amount && vehicleDebris.size() < 220; ++i) {
        VehicleDebrisPiece d;
        d.x = x;
        d.y = y;
        d.vx = static_cast<float>((std::rand() % 200) - 100) * 0.05f;
        d.vy = static_cast<float>((std::rand() % 200) - 160) * 0.05f;
        d.life = 0.8f + static_cast<float>(std::rand() % 60) * 0.01f;
        d.spin = static_cast<float>((std::rand() % 100) - 50) * 0.1f;
        if (vehicleDebris.size() < MAX_VEHICLE_DEBRIS_PIECES) {
            vehicleDebris.push_back(d);
        }
    }
}

static void SpawnVehicleExplosionImpact(float x, float y, bool destroyed) {
    if (destroyed && vehicleDebris.size() > MAX_VEHICLE_DEBRIS_PIECES - 32) {
        return;
    }
    SpawnVehicleDebris(x, y, destroyed ? 28 : 8);
    SpawnVehicleSmoke(x, y, destroyed);
    if (destroyed) {
        SpawnVehicleSmoke(x - 12, y - 10, true);
        SpawnVehicleSmoke(x + 14, y + 8, true);
    }
}

static void UpdateVehicleDestructionEffects(float dt) {
    if (dt <= 0.0f) return;
    for (auto& d : vehicleDebris) {
        d.x += d.vx * 60.0f * dt;
        d.y += d.vy * 60.0f * dt;
        d.vy += 0.8f * dt;
        d.life -= dt;
    }
    vehicleDebris.erase(std::remove_if(vehicleDebris.begin(), vehicleDebris.end(),
        [](const VehicleDebrisPiece& d){ return d.life <= 0.0f; }),
        vehicleDebris.end());
}

static void DrawVehicleDestructionEffects(SDL_Renderer* renderer, int cameraX, int cameraY) {
    if (!renderer) return;
    SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);
    for (const auto& d : vehicleDebris) {
        Uint8 a = static_cast<Uint8>(std::clamp(d.life, 0.0f, 1.0f) * 220.0f);
        SDL_SetRenderDrawColor(renderer, 150, 150, 150, a);
        SDL_Rect r{static_cast<int>(d.x) - cameraX, static_cast<int>(d.y) - cameraY, 5, 5};
        SDL_RenderFillRect(renderer, &r);
    }
    SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_NONE);
}

