// ============================================================
// VEHICLE COMBAT EFFECTS LAYER - VISUAL PASS 24
// ============================================================

struct TireMark {
    float x;
    float y;
    float life;
};

struct ImpactSpark {
    float x;
    float y;
    float life;
};

static std::vector<TireMark> vehicleTireMarks;
static std::vector<ImpactSpark> vehicleImpactSparks;

static void AddVehicleTireMark(float x, float y)
{
    vehicleTireMarks.push_back({x, y, 1.0f});
}

static void AddVehicleImpactSpark(float x, float y)
{
    vehicleImpactSparks.push_back({x, y, 1.0f});
}

static void UpdateVehicleCombatEffects(float dt)
{
    for (auto& t : vehicleTireMarks)
        t.life -= dt;

    for (auto& s : vehicleImpactSparks)
        s.life -= dt;

    vehicleTireMarks.erase(
        std::remove_if(vehicleTireMarks.begin(),
                       vehicleTireMarks.end(),
                       [](const TireMark& t){ return t.life <= 0; }),
        vehicleTireMarks.end());

    vehicleImpactSparks.erase(
        std::remove_if(vehicleImpactSparks.begin(),
                       vehicleImpactSparks.end(),
                       [](const ImpactSpark& s){ return s.life <= 0; }),
        vehicleImpactSparks.end());
}

static void DrawVehicleCombatEffects(SDL_Renderer* renderer)
{
    for (const auto& t : vehicleTireMarks)
    {
        SDL_Rect mark = {
            static_cast<int>(t.x),
            static_cast<int>(t.y),
            18,
            4
        };

        SDL_SetRenderDrawColor(renderer, 40, 40, 40,
                               static_cast<Uint8>(120 * t.life));
        SDL_RenderFillRect(renderer, &mark);
    }

    for (const auto& s : vehicleImpactSparks)
    {
        SDL_Rect spark = {
            static_cast<int>(s.x),
            static_cast<int>(s.y),
            6,
            6
        };

        SDL_SetRenderDrawColor(renderer, 255, 200, 50,
                               static_cast<Uint8>(220 * s.life));
        SDL_RenderFillRect(renderer, &spark);
    }
}


// ============================================================
// VISUAL PASS 26 - REFERENCE COMBAT FEEDBACK LAYER
// Screen shake, shockwave rings, wreck states and directional hits.
// ============================================================

struct CombatShakeState {
    float intensity = 0.0f;
    float timer = 0.0f;
    float offsetX = 0.0f;
    float offsetY = 0.0f;
};

static CombatShakeState g_combatShake;

static void TriggerCombatShake(float strength)
{
    g_combatShake.intensity = std::max(g_combatShake.intensity, strength);
    g_combatShake.timer = std::max(g_combatShake.timer, 0.18f);
}

static void UpdateCombatShake(float dt)
{
    if (g_combatShake.timer > 0.0f) {
        g_combatShake.timer -= dt;
        float force = g_combatShake.intensity * (g_combatShake.timer / 0.18f);
        g_combatShake.offsetX = std::sin(SDL_GetTicks() * 0.08f) * force;
        g_combatShake.offsetY = std::cos(SDL_GetTicks() * 0.11f) * force;
    } else {
        g_combatShake.offsetX = 0.0f;
        g_combatShake.offsetY = 0.0f;
        g_combatShake.intensity = 0.0f;
    }
}

struct ShockwaveRing {
    float x;
    float y;
    float radius;
    float life;
    float maxRadius;
};

static std::vector<ShockwaveRing> g_shockwaves;

static void SpawnShockwave(float x, float y, float size)
{
    g_shockwaves.push_back({x, y, 8.0f, 0.35f, size});
}

static void UpdateShockwaves(float dt)
{
    for (auto& s : g_shockwaves) {
        s.life -= dt;
        s.radius += (s.maxRadius / 0.35f) * dt;
    }

    g_shockwaves.erase(
        std::remove_if(g_shockwaves.begin(), g_shockwaves.end(),
            [](const ShockwaveRing& s){ return s.life <= 0.0f; }),
        g_shockwaves.end());
}

static void DrawShockwaves(SDL_Renderer* renderer, int cameraX, int cameraY)
{
    for (const auto& s : g_shockwaves) {
        SDL_Rect r{
            static_cast<int>(s.x - s.radius - cameraX),
            static_cast<int>(s.y - s.radius - cameraY),
            static_cast<int>(s.radius * 2),
            static_cast<int>(s.radius * 2)
        };
        SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);
        SDL_SetRenderDrawColor(renderer, 255, 170, 80,
            static_cast<Uint8>(180 * (s.life / 0.35f)));
        SDL_RenderDrawRect(renderer, &r);
    }
}

struct VehicleWreckState {
    bool wrecked = false;
    float wreckTimer = 0.0f;
    float firePulse = 0.0f;
    float rotation = 0.0f;
};

static VehicleWreckState g_vehicleWreck;

static void SetVehicleWreckedState(float x, float y)
{
    g_vehicleWreck.wrecked = true;
    g_vehicleWreck.wreckTimer = 12.0f;
    g_vehicleWreck.rotation += 7.0f;
    SpawnShockwave(x, y, 150.0f);
    TriggerCombatShake(14.0f);
}

static void UpdateVehicleWreckState(float dt)
{
    if (!g_vehicleWreck.wrecked) return;
    g_vehicleWreck.wreckTimer -= dt;
    g_vehicleWreck.firePulse += dt * 8.0f;
    if (g_vehicleWreck.wreckTimer <= 0.0f)
        g_vehicleWreck.wrecked = false;
}

struct DirectionalHitFeedback {
    float x;
    float y;
    float nx;
    float ny;
    float life;
};

static std::vector<DirectionalHitFeedback> g_directionHits;

static void AddDirectionalVehicleHit(float x, float y, float hitX, float hitY)
{
    float len = std::sqrt(hitX * hitX + hitY * hitY);
    if (len < 0.001f) len = 1.0f;
    g_directionHits.push_back({x, y, hitX / len, hitY / len, 0.22f});
    SpawnShockwave(x, y, 45.0f);
    TriggerCombatShake(5.0f);
}

static void UpdateDirectionalHits(float dt)
{
    for (auto& h : g_directionHits)
        h.life -= dt;

    g_directionHits.erase(
        std::remove_if(g_directionHits.begin(), g_directionHits.end(),
            [](const DirectionalHitFeedback& h){ return h.life <= 0.0f; }),
        g_directionHits.end());
}

static void DrawDirectionalHits(SDL_Renderer* renderer, int cameraX, int cameraY)
{
    for (const auto& h : g_directionHits) {
        SDL_RenderDrawLine(renderer,
            static_cast<int>(h.x - cameraX),
            static_cast<int>(h.y - cameraY),
            static_cast<int>(h.x + h.nx * 42 - cameraX),
            static_cast<int>(h.y + h.ny * 42 - cameraY));
    }
}


// -----------------------------------------------------------------------------
// Unified combat/visual update + render integration.
// Keep these calls in one place so implemented visual systems cannot silently
// become "dead" functions when the main loop changes.
// -----------------------------------------------------------------------------
static void UpdateAllGameplayVisuals(float dt)
{
    UpdateCombatShake(dt);
    UpdateShockwaves(dt);
    UpdateVehicleWreckState(dt);
    UpdateDirectionalHits(dt);
    UpdateVehicleCombatEffects(dt);
    DayNightUpdate(dt);
}

static void DrawAllGameplayVisuals(SDL_Renderer* renderer, int cameraX, int cameraY)
{
    DrawVehicleCombatEffects(renderer);
    DrawShockwaves(renderer, cameraX, cameraY);
    DrawDirectionalHits(renderer, cameraX, cameraY);
    DrawVehicleDestructionEffects(renderer, cameraX, cameraY);
    DayNightRenderOverlay(renderer);
}

