// PASS 28: Cinematic destruction polish layer
// Adds persistent burning wreck behavior, deformation stages, and timing hooks.

struct VehicleWreckVisualState {
    float x{0};
    float y{0};
    float burnTime{0};
    float smokePulse{0};
    float deformation{0};
    bool active{false};
};

static std::vector<VehicleWreckVisualState> g_vehicleWreckVisuals;

static void StartCinematicVehicleWreck(float x, float y)
{
    VehicleWreckVisualState wreck;
    wreck.x = x;
    wreck.y = y;
    wreck.burnTime = 18.0f;
    wreck.smokePulse = 0.0f;
    wreck.deformation = 1.0f;
    wreck.active = true;
    g_vehicleWreckVisuals.push_back(wreck);

    SpawnShockwave(x, y, 90.0f);
    TriggerCombatShake(12.0f);
}

static void UpdateCinematicVehicleWrecks(float dt)
{
    for (auto& wreck : g_vehicleWreckVisuals) {
        if (!wreck.active) continue;
        wreck.burnTime -= dt;
        wreck.smokePulse -= dt;

        if (wreck.smokePulse <= 0.0f) {
            wreck.smokePulse = 0.55f;
            // Hook smoke particle burst here.
        }

        if (wreck.burnTime <= 0.0f)
            wreck.active = false;
    }

    g_vehicleWreckVisuals.erase(
        std::remove_if(g_vehicleWreckVisuals.begin(), g_vehicleWreckVisuals.end(),
            [](const VehicleWreckVisualState& w){ return !w.active; }),
        g_vehicleWreckVisuals.end());
}

static void ApplyVehicleDeformationFeedback(float hitX, float hitY, float force)
{
    // Hook for mesh/sprite deformation or damage-state swapping.
    SpawnShockwave(hitX, hitY, 30.0f + force);
    TriggerCombatShake(force * 0.5f);
}

