// PASS 29: AAA combat presentation polish layer
// Presentation-only hooks: audio timing, hit-stop, camera impulses, environmental reactions.

struct CombatCameraImpulse {
    float shake{0.0f};
    float recoilKick{0.0f};
    float duration{0.0f};
};

struct CombatHitStopEvent {
    float freezeTime{0.0f};
    float intensity{0.0f};
};

struct DestructionAudioCue {
    int phase{0}; // 0 impact, 1 secondary burst, 2 wreck ambience
    float delay{0.0f};
};

struct EnvironmentalBlastReaction {
    float radius{0.0f};
    float impulse{0.0f};
};

static CombatCameraImpulse BuildVehicleImpactCameraImpulse(float damage)
{
    CombatCameraImpulse out;
    out.shake = std::clamp(damage * 0.08f, 0.0f, 12.0f);
    out.recoilKick = std::clamp(damage * 0.04f, 0.0f, 6.0f);
    out.duration = std::clamp(0.12f + damage * 0.001f, 0.05f, 0.25f);
    return out;
}

static CombatHitStopEvent BuildHeavyHitStop(float damage)
{
    CombatHitStopEvent out;
    out.freezeTime = damage > 80.0f ? 0.045f : 0.018f;
    out.intensity = damage * 0.01f;
    return out;
}

static EnvironmentalBlastReaction BuildExplosionReaction(float radius)
{
    EnvironmentalBlastReaction out;
    out.radius = radius;
    out.impulse = radius * 0.5f;
    return out;
}
